//0x8D4
Text_8B4:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_CHAP|$F3$FCL_BOLE|$F1$P어이쿠야$MC……$MD$K\n"
.stringn "졌다 졌어, $w2항복이여.$w4\n"
.stringn "$FS후우,$w2 역시\n"
.stringn "보레한테는 못 이기겠구마.$K\n"
.stringn "$F3$P$FS그래도 지금은 아까웠어.$w4\n"
.stringn "아저씨도 강해졌고.$w4\n"
.stringn "슬슬 특훈도 끝나가네.$K\n"
.stringn "$F1$P그려?$w4\n"
.stringn "나도 조금은 나아진 건가?$K\n"
.stringn "$F3$P어디에 내놓아도 부끄럽지 않은\n"
.stringn "어엿한 병사라는 느낌이야.$K\n"
.stringn "$F1$P그것참 다행이구먼.$w4\n"
.stringn "모두의 짐이 되지 않으면$w2\n"
.stringn "그걸로 충분하데이.$K\n"
.stringn "$F3$P무슨 소리야.$w4\n"
.stringn "이 정도면 종전 후에$w2\n"
.stringn "왕궁 병사로 들어갈 수도 있을걸?$K\n"
.stringn "$F1$P$FA$MC…$MD나는 싸움이 지긋지긋혀.$w2\n"
.stringn "이 전쟁이 끝나면$w2\n"
.stringn "바로 제대해서 농민으로 돌아갈 거여.$K\n"
.stringn "$F3$P$FA$MC…………$MD$K$P저기 아저씨.$w2\n"
.stringn "솔직히 $w2아저씨가 보기에$w3\n"
.stringn "우리 용병은 어떻게 보여?$K\n"
.stringn "$F1$P응?$K\n"
.stringn "$F3$P이 세상에 용병은 널려 있지만,$w2\n"
.stringn "대부분은 먹고 살기도 힘든 $w2불량배들이야.$K$P게다가 용병은 $w2전쟁이 끝나면\n"
.stringn "변변한 일거리가 없어져서 몰락하지.$K$P그 대부분의 말로는 $w3마을 사람들로부터\n"
.stringn "돈을 빼앗는 도적들과 다를 바가 없어.$K\n"
.stringn "$F1$P$MC……$MD보레.$K\n"
.stringn "$F3$P우리는 그런 놈들과 달라.$w4\n"
.stringn "하지만$MC…$MD$w4 그건$w2\n"
.stringn "겉으로만 봐서는 모르지.$K$P가끔 $w2거리를 돌아다니다 보면 자주 들어.$K\n"
.stringn "또 용병 놈들이 $w2등쳐 먹으러 왔다$MC…$MD$w1고.$w4\n"
.stringn "나에 대해선 어떻게 말하든지 상관없지만,$w2\n"
.stringn "동료들에게 그러는 건$MC……$MD 조금 $w2그래서.$K\n"
.stringn "$F1$P$MC……$MD저기, $w2보레.$K$P아무리 깨끗한 삶을 살려고 해도\n"
.stringn "누군가에게는 원망을 사 버린다. $w2그런 악의는\n"
.stringn "피할 수 없다고 생각혀.$K$P하지만 $w2나는 보레나 모두를\n"
.stringn "좋아하고, $w2존경도 하고, $w2감사하고 있데이.$w4\n"
.stringn "그걸로 $w3충분하지 않나.$K\n"
.stringn "$F3$P$MC…………$MD$w4$K\n"
.stringn "미안, $w2아저씨. $w4$MC……$MD고마워.$w4\n"
.stringn "그걸로$MC……$MD$w2 충분하지.$K$P$FS영차, $w2그럼 다시 한번 힘내 볼까$MC!$MD$w4\n"
.stringn "가자고$MC!$MD$K$F3$FD\n"
.stringn "$F1$P엥$MC!?$MD$w4 또, 또 하는 겨?$w4\n"
.stringn "자, $w2잠깐만 기다리라, $w2보레$MC!$MD$K\n"
.stringn "후우$w2 후우$w2 후우$K"
db 0
.align 4
//MYELL_BOLE_CHAP_A

//0x3A8
Text_388:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_BOLE|$F1$FCL_CHAP|$F1$P후우$w2 후우$w2 후우$w2\n"
.stringn "후우우$MC……$MD$K$P미안하구먼, $w2보레.$w4\n"
.stringn "늦어 버려서.$K\n"
.stringn "$F3$P$FS뭐, $w2발이 느린 건 어쩔 수 없으니까.$w4\n"
.stringn "처음이라 어떨까 싶었는데,$w2\n"
.stringn "아저씨, $w2의외로 잘 따라오네.$K\n"
.stringn "$F1$P$FS그려?$w4\n"
.stringn "확실히 $w2끈기만큼은\n"
.stringn "다른 사람보다 강할지도 모르겠구먼.$K$P안 그래도 $w2농사는 1년이 걸리니께.$w4\n"
.stringn "끈기가 없다고 하면 섭섭혀.$K\n"
.stringn "$F3$P$FA흐~음$MC……$MD$w4\n"
.stringn "저기, $w2밭일은 재밌어?$K\n"
.stringn "$F1$P그야 $w2재미있제.$w4\n"
.stringn "날씨라든가 해충이라든가 $w2여러 고충이 있지만,$w2\n"
.stringn "수확할 때의 기쁨은 이루 말할 수가 없어.$K\n"
.stringn "$F3$P그렇구나$MC……$MD$K\n"
.stringn "$F1$P$FA?$w4 왜 그러는 겨?$K\n"
.stringn "$F3$P아니,$w2\n"
.stringn "용병 일과는$w2\n"
.stringn "정반대구나 싶어서.$K$P농민이 하는 일은 뭔가를 만드는 거잖아?$K$P하지만 $w2우리가 하는 일은 $w2적을 쓰러뜨리는$MC……$MD$w4\n"
.stringn "파괴적인 일들뿐이지. $w4그 뒤엔 남는 게 없어.$K\n"
.stringn "$F1$P그런 식으로 말하지 말어$MC……$MD$w4\n"
.stringn "사람들을 지키려고 싸우는 일이잖어.$w4\n"
.stringn "나는 $w2훌륭한 일이라고 생각하는디.$K\n"
.stringn "$F3$P아, $w2착각하지 마.$w2\n"
.stringn "난 이 일이 좋아서 하는 거니까.$w4\n"
.stringn "그레일 용병단 말고 있을 곳이 없기도 하고.$K$P그런데$MC……$MD$w4 말야.$K\n"
.stringn "$F1$P응?$K\n"
.stringn "$F3$P$FS$MC……$MD$w2너무 많이 쉬었는걸.$K$P특훈 재개야. $w2다음으로 가자$MC!$MD$K$F3$FD\n"
.stringn "$F1$P그, 그렇게 갑자기$MC…$MD$w4\n"
.stringn "잠깐만 기다리래이~$w4 후우$w2 후우$K"
db 0
.align 4
//MYELL_BOLE_CHAP_B

//0x20
Text_0:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_CHAP|$F3$FCL_BOLE|$F1$P이야, $w2반갑구먼.$K\n"
.stringn "난 채프라고 혀.$w4\n"
.stringn "너, $w2용병단 사람인 겨?$K\n"
.stringn "$F3$P응?$w2 당신은 분명\n"
.stringn "포로였던 $w2아저씨 맞지?$K$P$FS난 보레야.$w4\n"
.stringn "그레일 용병단 최고의 전사지.$K\n"
.stringn "$F1$P호오~ $w2그려?$w4\n"
.stringn "젊은 데도 $w2대단하구먼.$K\n"
.stringn "$F3$P뭐, $w2진짜 그 정도로 대단하진 않아.$K$P$FA근데 아저씨.$w4\n"
.stringn "당신$MC…$MD$w4 포로였던 것치고는$w2\n"
.stringn "왠지 $w2뚱뚱한걸.$K$P그런 몸으로 제대로 싸울 수는 있어?$K\n"
.stringn "$F1$P$FA아니, $w2잘 싸우지도\n"
.stringn "못하제.$K$P밭을 가는 건\n"
.stringn "문제 없었지마는.$K\n"
.stringn "$F3$P아저씨, $w2농민이었어?$K\n"
.stringn "$F1$P그려.$K$P그나저나 이 상태로는$MC…$MD$w3\n"
.stringn "모두에게 짐이 될 것 같아서\n"
.stringn "미안하구먼.$K\n"
.stringn "$F3$P$FS그럼 특훈하면 되지.$w4\n"
.stringn "내가 $w2같이 해 줄게.$K\n"
.stringn "$F1$P$FS차, 참말로?$w4\n"
.stringn "그럼 미안하지만\n"
.stringn "잘 부탁혀.$K"
db 0
.align 4
//MYELL_BOLE_CHAP_C

