Text_1A88:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_BOLE|$F3$P오, $w2미스트.$K\n"
.stringn "$F1$FCL_MISTs|$F1$P$MC…$MD보레.$K\n"
.stringn "$F3$P어, $w2야.$K$P왜 그러고 있어, $w2괜찮아?$w4\n"
.stringn "요즘 $w2너답지 않다고.$w4\n"
.stringn "무슨 일 있어?$K\n"
.stringn "$F1$P$Fh보레에$MC…$MD$w4\n"
.stringn "$MC…$MD흑$w3$Fc $MC………$MD$K\n"
.stringn "$F3$P우왁$MC!$MD$w4 왜 그래$MC!?$MD$K\n"
.stringn "$F1$P$MC………$MD많이$MC…$MD$w3 있었어$MC…$MD$MC…$MD$w4\n"
.stringn "여러 가지$MC…$MD$w3 잔뜩$MC…$MD$w5\n"
.stringn "$MC……$MD나$MC……$MD$w4 나$MC……$MD$K\n"
.stringn "$F3$P아$MC…$MD$w4 $MC……$MD그래.$w4\n"
.stringn "$MC…$MD뭔지는 잘 모르겠지만$MC……$MD$w3\n"
.stringn "울고 싶을 때는 울어도 돼.$K\n"
.stringn "$F1$P$MC……$MD흑$w4 $MC………$MD으흑$w4\n"
.stringn "$MC……………$MD$K\n"
.stringn "$F3$P$FS진정되면$w3\n"
.stringn "내가 얘기 $w2들어줄 테니까.$K$P마음껏 울고$w4\n"
.stringn "마음껏 털어 놔.$w4\n"
.stringn "그리고 $w2편해지면 돼.$w4 그렇지?$K\n"
.stringn "$F1$P$MC………$MD$w3응$MC……$MD$w4 $MC……$MD$w4\n"
.stringn "$MC………$MD고$MC…$MD$w2마워$MC……$MD$K\n"
.stringn "$F3$P괜찮을 거야.$w4\n"
.stringn "나$MC…$MD하고, $w2모두가 있으니까.$w4\n"
.stringn "$MC…$MD괜찮아.$K\n"
.stringn "$F1$P$MC………$MD$w2응$MC……$MD$K"
db 0
.align 4
//MYELL_BOLE_MIST_A

//0x1544
Text_1524:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_MIST|$F1$P어라?$w4\n"
.stringn "어디 있지?$K$F1$FD\n"
.stringn "$F3$FCL_BOLE|$F3$P나 참, $w2어디로 간 거야$MC……$MD$K\n"
.stringn "$F1$FCL_MIST|$F1$P아, $w2보레.$K\n"
.stringn "$F3$P오, $w2미스트.$w4\n"
.stringn "아이크 어디 있는지 알아?$K\n"
.stringn "$F1$P아니, $w2나도 찾던 중이었어.$K\n"
.stringn "$F3$P그러냐.$w4\n"
.stringn "그 녀석 요즘\n"
.stringn "되게 바쁜가 보네.$K$P그럼 $w2포기하고\n"
.stringn "다른 녀석이나 찾아볼까.$K\n"
.stringn "$F1$P훈련 상대?$K\n"
.stringn "$F3$P그래. $w4역시 난$w2\n"
.stringn "상대가 없으면 진심으로 못 하겠어.$K\n"
.stringn "$F1$P나랑은$MC…$MD$w2 안 되겠지?$K\n"
.stringn "$F3$P응?$K\n"
.stringn "$F1$P그, $w3상대가 안 된다는 건\n"
.stringn "알고 있어$MC!$MD$K$P그치만$MC…$MD$w3 나도\n"
.stringn "강해져야 된다고 생각해.$w4\n"
.stringn "전장에서 살아남기 위해서$MC…$MD$w4 그러니까$MC…$MD$K\n"
.stringn "$F3$P그럼 $w2부탁할게.$K\n"
.stringn "$F1$P$FS정말?$K\n"
.stringn "$F3$P$FS막대만 쥐고 있어도\n"
.stringn "허수아비보단 $w2낫겠지.$K\n"
.stringn "$F1$P$FA너무해$MC!$MD$w4\n"
.stringn "그래도 $w2나는$MC…$MD$K\n"
.stringn "$F3$P아빠의 딸인데, $w2맞지?$K\n"
.stringn "$F1$P$MC……$MD우$MC……$MD$K\n"
.stringn "$F3$P저번엔 미안했어.$w4\n"
.stringn "말이 너무 심했지.$K\n"
.stringn "$F1$P아냐$MC…$MD$w4 내가\n"
.stringn "너무 들떠 있었던 건 사실이고.$K$P듣고 나서 정신도 차렸어.$w4$FS\n"
.stringn "고마워, 보레.$K\n"
.stringn "$F3$P$FA$MC………$MD머$w3\n"
.stringn "멍청아$MC…$MD$MC!$MD$w4\n"
.stringn "갑자기 뭐라는 거야$MC……$MD$K\n"
.stringn "$F1$P뭐라니 고맙다고$MC…$MD$w5$FA\n"
.stringn "아, $w2뭐야.$w4\n"
.stringn "보레 왜 얼굴 빨개진 건데?$K\n"
.stringn "$F3$P시끄러워$MC!$MD$K$F3$FD\n"
.stringn "$F1$P아, 잠깐$MC!$MD$K$P어디 가는 거야?$w4\n"
.stringn "훈련해야지$MC!?$MD$K"
db 0
.align 4
//MYELL_BOLE_MIST_B

//0x1094
Text_1074:
.stringn "$R背景会話|$B支援背景|$<$F6$FCL_BOLE|$F6$P얍$MC!$MD$w4\n"
.stringn "핫$MC!$MD$w4\n"
.stringn "으랴앗$MC!$MD $w4$MC……$MD영차.$K$P후우$MC……$MD$w4 오늘은 이 정도면 되겠지.$w4\n"
.stringn "요즘은 할 마음도 안 들고,$w2\n"
.stringn "훈련은 여기까지$MC……$MD$K\n"
.stringn "$F7$FCDUMMY|$F7$P보레$MC!$MD$w4\n"
.stringn "똑바로 안 해$MC!$MD$K\n"
.stringn "$F6$FD$F3$FCL_BOLE|$F3$P켁$MC!?$MD$w4\n"
.stringn "제, $w2제대로 하고 있다고\n"
.stringn "티아마트씨$MC……$MD$w4 어라?$K\n"
.stringn "$F1$FS$F1$FCL_MIST|$F1$P큭 큭$K$F1$FD\n"
.stringn "$F3$P야$MC!$MD$K\n"
.stringn "얌마, $w2거기 서 미스트$MC!$MD$K\n"
.stringn "$F0$FS$F0$FCL_MIST|$F0$P훈련을 빼먹으려던$w2\n"
.stringn "보레 잘못이지.$K$P그렇게 땡땡이치다간$w3\n"
.stringn "조만간 $w2내가 더\n"
.stringn "강해지게 될걸.$K\n"
.stringn "$F3$P$Fh그럴 리가 없잖아.$w2\n"
.stringn "뻔뻔한 것도 정도가 있지.$K\n"
.stringn "$F0$P그치만, 나$w2\n"
.stringn "우리 아빠의 딸인데?$w4\n"
.stringn "싸우는 재능은 $w2있을 거라고 생각해.$K\n"
.stringn "$F3$P$Fd$MC……$MD웃기시네.$K\n"
.stringn "전장에서 살아남을 수 있을지 없을지는$w2\n"
.stringn "실전 경험이 얼마나 있느냐에 달렸어.$K$P재능이 있다고\n"
.stringn "자만하다간 $w3죽을걸.$K\n"
.stringn "$F0$P왜 그래$MC…$MD$w2 평소처럼 장난친 거잖아.$w4$FA\n"
.stringn "그렇게 무서운 얼굴 하지 마.$K\n"
.stringn "$F3$P우리는 장난으로 싸우고 있는 게 아니야$MC!$MD$K$P알았으면 저리 가.$w4\n"
.stringn "훈련에 방해돼.$K\n"
.stringn "$F0$P$MC………$MD미안.$K$F0$FD\n"
.stringn "$F3$P$MC………………$MD$K"
db 0
.align 4
//MYELL_BOLE_MIST_C

//0x2824
Text_2804:
.stringn "$R背景会話|$B支援背景|$<$F3$FS$F3$FCL_BOLE|$F3$P티아마트씨$MC!$MD$K\n"
.stringn "겨우 찾았다$MC……$MD$w3\n"
.stringn "티아마트씨는 최근 $w2군사 회의 같은 데에만 있고\n"
.stringn "좀처럼 혼자 있지 않으니까$MC……$MD$K\n"
.stringn "$F1$FS$F1$FCL_TIAMAT|$F1$P뭐니, $w2보레.$w4\n"
.stringn "오늘은 화낼 만한 일도 없는데.$K\n"
.stringn "$F3$P$FA아니, 별로 혼나고 싶은 게 아니고요.$w4\n"
.stringn "$MC……$MD$K$FS\n"
.stringn "티아마트씨, $w2지금 뭔가\n"
.stringn "갖고 싶은 거 있어요?$K\n"
.stringn "$F1$P딱히 생각이 안 나는데$MC…$MD$w3\n"
.stringn "왜?$K\n"
.stringn "$F3$P저번에 받은 보수가 $w2꽤 많거든요.$w4\n"
.stringn "항상 신세를 지고 있는 티아마트 씨에게$w2\n"
.stringn "뭐라도 사 드릴까 해서요.$K\n"
.stringn "$F1$P후후,$w3 한 사람 몫을 하게 됐다고 인정했더니$w2\n"
.stringn "생각하는 것도 어른스러워졌는걸?$K\n"
.stringn "$F3$P헤헤,$w3 그러니까 뭐든지 말만 해 주세요.$w4\n"
.stringn "새로운 어깨 보호대라든지, $w2무릎 보호대라든지,$w2\n"
.stringn "굉장히 좋은 도끼라든지$MC…?$MD$K\n"
.stringn "$F1$P마음만 받아 둘게.$w4\n"
.stringn "자기가 번 돈이니까$w4\n"
.stringn "자신을 위해서 사용하면 돼.$K\n"
.stringn "$F3$P$FA그러니까$MC!$MD$w4 저는,$w3\n"
.stringn "티아마트씨에게 뭔가를 해 주고 싶어요.$K\n"
.stringn "$F1$P$FA보레$MC…$MD$w4 너, 설마$MC……$MD$K\n"
.stringn "$F3$P저$MC…$MD$K$P티아마트씨를 보면서\n"
.stringn "항상 생각했어요.$w4\n"
.stringn "이렇게 아름다운 사람은 $w2처음이라고.$K\n"
.stringn "$F1$P보레, $w2마음은 고맙지만$MC…$MD$w3\n"
.stringn "나는$MC……$MD$K\n"
.stringn "$F3$P$FS엄마라는 건$w2\n"
.stringn "이런 느낌이구나 했죠.$K\n"
.stringn "$F1$P$MC………$MD$K\n"
.stringn "$F3$P$FA으아$MC!$MD$w3 쑥쓰러워 죽겠네$MC!!$MD$w4\n"
.stringn "아, $w3진짜 $w2부끄럽다.$K\n"
.stringn "$F1$P$Fh$MC……$MD보레.$K\n"
.stringn "$F3$P$FS네?$K\n"
.stringn "$F1$P너, 대체$MC…$MD$w3\n"
.stringn "나를 몇 살이라고 생각하는 거야?$K\n"
.stringn "$F3$P$MC…………………$MD\n"
.stringn "$MC………$MD음$MC……$MD$w3\n"
.stringn "돌아가신 우리 엄마보다는$MC…$MD$w4 아래?$K\n"
.stringn "$F1$P$Fc$MC…………$MD$K\n"
.stringn "$F3$P$MC……$MD$K$P그건 그렇고 $w2훈련해야지 훈련$MC!$MD$K$F3$FD\n"
.stringn "$F1$P$Fh보레에$MC!$MD$w4\n"
.stringn "거기 서어$MC!!$MD$K"
db 0
.align 4
//MYELL_BOLE_TIAMAT_A

//0x2374
Text_2354:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_TIAMAT|$F1$P보레.$K\n"
.stringn "$F3$FCL_BOLE|$F3$P티, $w2티아마트씨$MC!?$MD$w4\n"
.stringn "아니, $w2땡땡이 안 쳤어요$MC!$MD$w4\n"
.stringn "오늘도 제대로 기초 훈련 했는데$MC!$MD$K\n"
.stringn "$F1$P아직 아무 말도 안 했어.$K\n"
.stringn "$F3$P아, $w2그렇구나.$w4\n"
.stringn "이젠 그런 흐름이\n"
.stringn "몸에 착 달라붙어서$MC……$MD$K\n"
.stringn "$F1$P오늘은 화내러 온 게 아니야.$K$P이젠 $w2너도 잘 알고 있을 테니까.$w4\n"
.stringn "싸움이 점점 치열해지는 와중에\n"
.stringn "늘어질 틈 따위는 없다는 걸.$K\n"
.stringn "$F3$P$MC……$MD네.$K\n"
.stringn "$F1$P얼마나 기술을 갈고닦았는가$MC……$MD$w2\n"
.stringn "얼마나 육체를 단련했는가$MC……$MD$w2\n"
.stringn "그것이 전장에서 목숨을 좌우하지$MC……$MD$K$P$FS$MC……$MD넌 이제 괜찮겠네, $w2보레.$w4\n"
.stringn "그 무게를 제대로 알고 있을 테니까.$K\n"
.stringn "$F3$P으에엑$MC!?$MD$K\n"
.stringn "$F1$P$FA뭐, $w2뭐야?$w4\n"
.stringn "내가 뭐 이상한 말이라도 했어?$K\n"
.stringn "$F3$P그야 이상하죠 티아마트씨.$w4\n"
.stringn "그건 마치$MC…$MD$w3 절\n"
.stringn "칭찬하는 것처럼 들리는데요?$K\n"
.stringn "$F1$P칭찬하는 거 맞아.$w4\n"
.stringn "이제야 한 사람 몫을 $w2하게 됐잖아.$K\n"
.stringn "$F3$P우와~$MC…$MD$w3\n"
.stringn "왠지 불길한걸요$MC…$MD$w4\n"
.stringn "혼나는 것보다 더 무서운데.$K\n"
.stringn "$F1$P$MC……$MD그래. $w4그렇게나 혼나는 게\n"
.stringn "좋은 거구나$MC……$MD$w3\n"
.stringn "$FS그럼 $w2앞으로도 사양 않고 화내도록 할게.$K$F1$FD\n"
.stringn "$F3$P$FA켁$MC……$MD$MC!$MD$w4\n"
.stringn "아, $w2아니에요 $w2티아마트씨$MC!$MD$K"
db 0
.align 4
//MYELL_BOLE_TIAMAT_B

//0x1EAC
Text_1E8C:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_BOLE|$F3$P53, $w254, $w255$MC……$MD$w4$K$P후우$MC…$MD$w2 이런 운동은\n"
.stringn "혼자서 해 봤자$MC…$MD$w4\n"
.stringn "상대가 없으면 의미가 없단 말이지.$K$P그래, 아이크 녀석이라도 꼬셔서$MC……$MD$K\n"
.stringn "$F1$FCL_TIAMAT|$F1$P보레$MC!$MD$K\n"
.stringn "$F3$P켁, $w2티아마트씨$MC!$MD$K\n"
.stringn "$F1$P또 기초 훈련을 빼먹고\n"
.stringn "어디 갈 셈이야?$K\n"
.stringn "$F3$P아니, $w2땡땡이가 아니라,$w4\n"
.stringn "아이크랑 대련이라도\n"
.stringn "할까 하던 참이었어요.$K\n"
.stringn "실전으로 단련해야 된다고 생각하니까.$K\n"
.stringn "$F1$P확실히, $w2우리들의 검술은\n"
.stringn "배운 수준에도 못 미쳐.$w4\n"
.stringn "하지만 $w2기초를 소홀히 하면 $w2죽게 될 거야.$K$P피폐해져서 제대로 판단이 안 설 때$w2\n"
.stringn "몸에 배인 순간적인 몸놀림이\n"
.stringn "목숨을 좌우하는 일도 있는 법이니까.$K\n"
.stringn "$F3$P하지만 $w2상대가 없으면\n"
.stringn "별로 안 내킨다고나 할까$MC……$MD$K\n"
.stringn "$F1$P$Fc곤란하네$MC……$MD$w4\n"
.stringn "또 옛날처럼 진심으로\n"
.stringn "화내야 되는 걸까.$K\n"
.stringn "$F1$P$Fd$F3$P$FS아, $w2아뇨 농담입니다$MC!$MD$w4\n"
.stringn "지금까지 다 농담이었어요$MC!$MD$K$P아아, $w2갑자기 엄청\n"
.stringn "훈련하고 싶은걸$MC!$MD$K$P기초 훈련은 정말 재미있어요$MC!$MD$w4\n"
.stringn "그쵸, $w2티아마트씨$MC!$MD$K\n"
.stringn "$F1$P$FS그래, 그거면 됐어.$K$P보레, $w2넌 체격도 \n"
.stringn "타고났으니까.$K$P그럴 마음만 먹으면\n"
.stringn "나보다 우수한 전사가 될 수 있을 거야.$w4\n"
.stringn "아무튼 $w2열심히 하렴.$K"
db 0
.align 4
//MYELL_BOLE_TIAMAT_C

//0x37CC
Text_37AC:
.stringn "$R背景会話|$B支援背景|$<$F5$FCL_VULCI|$F3$FCL_BOLE|$F3$P찾았다$MC!$MD$w4\n"
.stringn "기다려 봐 $w2우르키$MC!$MD$K\n"
.stringn "$F5$P$MC………$MD$K\n"
.stringn "$F3$P왜 $w2날 피하는 거야?$K$P내가 뭔가 잘못한 게 있으면$w2\n"
.stringn "확실하게 말해도$MC…$MD$w4\n"
.stringn "난 $w2전혀 상관없어.$K\n"
.stringn "$F5$FD$F1$FCL_VULCI|$F1$P$MC…$MD보레$MC……$MD$K\n"
.stringn "$F3$P모처럼 $w2라구즈인 너하고\n"
.stringn "친구가 될 수 있다고 생각했는데$MC…$MD$K$P역시 $w2내가 베오크라서\n"
.stringn "친해질 수 없다고$MC…$MD$w3 생각하는 거야?$K\n"
.stringn "$F1$P$MC……$MD아니$MC…$MD$w3\n"
.stringn "$MC…$MD너는 좋은 녀석이다.$w4\n"
.stringn "내가$MC…$MD$w2 최악일 뿐이다$MC……$MD$K\n"
.stringn "$F3$P그 『최악』이란 거$w2\n"
.stringn "저번에도 말했었지?$w4\n"
.stringn "대체 $w2무슨 뜻이야?$K\n"
.stringn "$F1$P$MC………………$MD$K$P$MC…$MD네가 처음으로$MC…$MD$w3\n"
.stringn "나한테 말을 걸어왔을 때,$w4\n"
.stringn "나는$MC…$MD 너를 의심하고 있었다.$K$P베오크가 $w2라구즈인 나에게\n"
.stringn "친근하게 말을 걸며 $w3다가오니$MC…$MD\n"
.stringn "뭔가 꾸미고 있는 게 틀림없다고$MC……$MD$K\n"
.stringn "$F3$P응$MC…?$MD$w4 그치만$w2 우르키는\n"
.stringn "처음에 날 칭찬했었잖아?$w5\n"
.stringn "그거$MC…$MD$w3 거짓말이었어?$K\n"
.stringn "$F1$P상대를 칭찬하는 것이$w3\n"
.stringn "베오크의 인사법이라고 생각했다$MC…$MD$K$P보레도 $w2나에게 어울리지 않는\n"
.stringn "미사여구를 늘어놓았으니까.$K\n"
.stringn "$F3$P그$MC……$MD$w3\n"
.stringn "그건$MC……$MD$K\n"
.stringn "$F1$P난 너랑 헤어지자마자$MC…$MD$w3\n"
.stringn "너에 대해 조사했다.$K$P이름은 무엇이고 $w2어디 태생인지.$w4\n"
.stringn "모든 것을 빈틈없이.$K\n"
.stringn "$F3$P$MC…………$MD\n"
.stringn "그래서, $w3뭔가 찾았어?$K\n"
.stringn "$F1$P그레일 용병단의 보레.$w4\n"
.stringn "보이는 대로$MC…$MD$w2 표리가 같은\n"
.stringn "쾌활한 전사였다.$K\n"
.stringn "$F3$P$MC………………$MD$K\n"
.stringn "$F1$P$MC…$MD너는 $w2처음부터\n"
.stringn "호의를 보였지만$MC…$MD$K$P나는 $w2믿지 않았다.$w4\n"
.stringn "의심하고 경계했지.$K$P그래서 『최악』이라고 한 것이다.$w4\n"
.stringn "넌 나와 우호를 다질 필요가 없어.$K\n"
.stringn "$F3$P$MC……$MD베오크와 라구즈$w2인가.$K\n"
.stringn "$F1$P?$K\n"
.stringn "$F3$P난 말이지, 처음에는$MC…$MD$w2\n"
.stringn "우르키하고 친구가 될 수 있을지\n"
.stringn "완전 자신이 없었다고.$K$P아이크처럼 자연스럽게$MC…$MD$w3\n"
.stringn "라구즈랑 친해질 수 있을까 했지.$K$P$FS근데$MC…$MD$w2 우연히 너하고$w3\n"
.stringn "얘기를 해 보니$w3\n"
.stringn "생각보다 별거 아니었다는 걸 안 거야.$K$P그래서 $w2기뻤어.$w4\n"
.stringn "전장에서 $w2널 찾아내서\n"
.stringn "일부러 $w3가까이서 싸우고 있었지.$K\n"
.stringn "$F1$P$MC…$MD보레.$K\n"
.stringn "$F3$P$FA베오크는 계속 라구즈와 적대해 왔어.$w4\n"
.stringn "그러니까 우르키가 날 경계하고$MC…$MD$w3\n"
.stringn "신상을 조사해 보는 건 어쩔 수 없겠지.$K$P$FS하지만 $w2나한테 꿍꿍이가 없다는 걸 안 후에도\n"
.stringn "그렇게 벽을 치는 건 이해가 안 돼.$K$P그래서는 $w2평생 베오크와\n"
.stringn "라구즈가 서로 알아갈 수 없을 거야.$K$P나는 그렇게 생각해$MC…$MD$w4\n"
.stringn "우르키는 그래도 아직$w3\n"
.stringn "날 피할 생각이야?$K\n"
.stringn "$F1$P$MC………$MD아니.$K$P보레, $w2정말로 미안했다.$w4\n"
.stringn "네가 용서해 준다면$w3$FS\n"
.stringn "난 네 친구가 되고 싶다.$K\n"
.stringn "$F3$P용서하고 자시고$MC…$MD$w4\n"
.stringn "나는 $w2처음부터\n"
.stringn "그럴 생각이었다고$MC!$MD$K"
db 0
.align 4
//MYELL_BOLE_VULCI_A

//0x32F0
Text_32D0:
.stringn "$R背景会話|$B支援背景|$<$F3$FS$F3$FCL_BOLE|$F3$P어~이$MC!$MD$w4\n"
.stringn "매 형씨!$K\n"
.stringn "$F1$FCL_VULCI|$F1$P$MC…$MD너였나.$w4\n"
.stringn "전장 밖에서 만나는 건 오랜만이군.$K\n"
.stringn "$F3$P그래.$K\n"
.stringn "아, $w2난 보레라고 해.$w4\n"
.stringn "동료기도 하고, 『너』가 아니라\n"
.stringn "이름으로 불러 달라고?$K\n"
.stringn "$F1$P알았다.$w4$MC…$MD 난 우르키.$w4\n"
.stringn "나도 『매 형씨』가 아니라$w3\n"
.stringn "이름으로 불러 줬으면 좋겠군.$K\n"
.stringn "$F3$P알았어.$K$P그래서 우르키.$w4\n"
.stringn "이런 곳에서 $w2뭐 하고 있었어?$K\n"
.stringn "$F1$P$MC……$MD작은 새들의 소리에 귀를 기울이고 있었다.$w4\n"
.stringn "듣고 있으면 $w2마음이 편해지지.$K\n"
.stringn "$F3$P그래?$K$P$MC………………$MD\n"
.stringn "안 되겠다. $w4나한테는 아무것도 안 들려.$w4\n"
.stringn "너 정말 귀가 밝구나.$K\n"
.stringn "$F1$P$MC………$MD$K\n"
.stringn "$F3$P그나저나 $w2조익족은 좋겠네~$w4\n"
.stringn "하늘을 날 수 있다니 최강이잖아$MC!$MD$K$P우르키가 싸우는 걸 가까이서$w3\n"
.stringn "보고 있으면 굉장하다고.$w4\n"
.stringn "라구즈의 강함을 느꼈어.$K$P왜 베오크에게는 날개가 없는 걸까?$w2\n"
.stringn "화신하기 전에는 $w2비슷하게 생겼는데.$K\n"
.stringn "$F1$P$MC………$MD$K\n"
.stringn "$F3$P아, 미안. $w4왠지\n"
.stringn "나 혼자만 떠들고 있었네.$w4\n"
.stringn "방해되면 $w2그렇다고 말을$MC…$MD$K\n"
.stringn "$F1$P$MC……$MD$Fc미안하다$MC…$MD$K\n"
.stringn "$F3$P$FA왜 그래, 갑자기?$K\n"
.stringn "$F1$P$Fd나는$MC…$MD 최악이다.$K$F1$FD\n"
.stringn "$F3$P자, $w2잠깐$MC!$MD$w4\n"
.stringn "$MC………$MD뭐야 $w2갑자기$MC…$MD$K"
db 0
.align 4
//MYELL_BOLE_VULCI_B

//0x2EB4
Text_2E94:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_BOLE|$F3$P오$MC…?$MD$w4\n"
.stringn "저 녀석은 $w2우리 군의\n"
.stringn "매 라구즈잖아$MC……$MD$K\n"
.stringn "$F1$FCL_VULCI|$F1$P$MC…………$MD$K\n"
.stringn "$F3$P우왓$MC!?$MD$K\n"
.stringn "$F1$P$MC……$MD뭔가 볼일이 있나.$K\n"
.stringn "$F3$P어?$K\n"
.stringn "$F1$P부른 것 같아서 왔다.$w4\n"
.stringn "아닌가?$K\n"
.stringn "$F3$P뭐? $w2아,$w2\n"
.stringn "설마$MC…$MD 아까 혼잣말한 거?$w4\n"
.stringn "그만큼 떨어져 있었는데도 들은 거야?$K\n"
.stringn "$F1$P선명하게.$K\n"
.stringn "$F3$P괴, $w2굉장한데.$K\n"
.stringn "$F1$P그래서$MC…$MD$w3\n"
.stringn "나한테 무슨 볼일이지?$K\n"
.stringn "$F3$P아니$MC……$MD$w3 뭐냐,$w4\n"
.stringn "음$MC……$MD$w3 그게$MC…$MD$w4\n"
.stringn "$MC……$MD$w3기합이 들어간 얼굴이구나 해서$MC……$MD$K\n"
.stringn "$F1$P?$w4\n"
.stringn "$MC……$MD내 얼굴에 문제라도 있는 건가?$w4\n"
.stringn "지극히 평범한 얼굴이다만.$K\n"
.stringn "$F3$P$FS아냐 아냐. $w4전혀 $w2문제없어$MC!$MD$w4\n"
.stringn "완전 세 보이고, $w3남자다워. $w3최고야$MC!$MD$K\n"
.stringn "$F1$P$MC………$MD$K\n"
.stringn "$F3$P$MC…………$MD$K\n"
.stringn "$F1$P$MC………$MD너야말로, $w3\n"
.stringn "건강하고 $w2좋은 빛깔의 두발을 가지고 있군.$w4\n"
.stringn "팔도 굵고 $w3제법 강해 보여서 좋다.$K\n"
.stringn "$F3$P$FA응?$K\n"
.stringn "$F1$P그럼, $w2오늘은 볼일이 있으니$MC…$MD$w3 다음에 보지.$K$F1$FD\n"
.stringn "$F3$P$MC………………$MD$w4\n"
.stringn "나, 의외로$w2\n"
.stringn "라구즈랑 잘 지낼 수 있을 것 같아, $w3응.$K"
db 0
.align 4
//MYELL_BOLE_VULCI_C

