//0x4ED0
Text_4EB0:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_CALILL|$F3$FCL_GEOFFRAY|$F1$P흐음, $w2그래서?$K\n"
.stringn "$F3$P$MC……$MD그런 사정이 있어서,$w2\n"
.stringn "공주님의 존재는 공표되지 않고$MC…$MD$w3\n"
.stringn "왕궁 안쪽의 별궁에서 $w2조용히 자라오셨던 거다.$K\n"
.stringn "$F1$P우리 같은 평민 입장에서 보면$w2\n"
.stringn "참 복잡한 이야기네.$K$P모처럼 태어난 딸을$w2\n"
.stringn "세간에 비밀로 하고 키워야 했다니$MC…$MD$K\n"
.stringn "$F3$P하지만 $w2공주님께선 결코 불행하지 않으셨다.$K$P국왕 폐하 내외, 레닝님의\n"
.stringn "사랑을 한 몸에 받으셨고$MC…$MD$K$P왕위를 이을 필요가 없다고 해도$w3\n"
.stringn "기죽지 않으시며 $w2지방 귀족의 영애처럼$w3\n"
.stringn "평온하게 살고 계셨지.$K\n"
.stringn "$F1$P그날, 데인이 쳐들어오지만 않았다면\n"
.stringn "지금까지도 그 행복은 계속됐겠지.$K\n"
.stringn "$F3$P$MC…………$MD$K\n"
.stringn "$F1$P아, $w2미안. $w4말이 심했어.$K\n"
.stringn "$F3$P아니, 괜찮다.$K\n"
.stringn "$F1$P$FS으음, $w3지금 이야기로\n"
.stringn "공주님이 어떻게 자라오셨는지는 잘 알았어.$K\n"
.stringn "제프리는 공주님의 유모의 아들이었고,$w3\n"
.stringn "어렸을 때부터 같이 놀던 친구라는 거지.$K\n"
.stringn "$F3$P$MC…$MD지금 생각해 보면, $w2내 인생에서\n"
.stringn "가장 행복한 날들이었다.$K$P크리미아는 평화롭고,$w3\n"
.stringn "밝은 빛으로 가득 차 있었지.$K$P공주님께서 계시고, $w2루키노 누나가 있고,$w2\n"
.stringn "나는 두 사람의 뒤를 쫓아가고$MC…$MD$K\n"
.stringn "$F1$P$FA안 된다구. $w4그런 식으로\n"
.stringn "과거의 추억에 매달리지 마.$w4\n"
.stringn "우린 아직 살아 있잖아?$K$P이렇게 전쟁을 하면서$w4\n"
.stringn "피땀 흘리는 나날들뿐이지만$MC…$MD$K$P희망과 $w2삶을 즐기는 마음은$MC…$MD$w4\n"
.stringn "어떤 때라도 잊어선 안 돼.$K\n"
.stringn "$F3$P$MC…$MD카릴 공.$w4\n"
.stringn "미안하다, $w2나약한 소리를 한 거 같군.$K\n"
.stringn "$F1$P$FS딱히 상관없어.$K\n"
.stringn "난 완벽한 사람보다$w3\n"
.stringn "어딘가 부족한 부분도 있는 사람이$w2\n"
.stringn "인간미 있어서 좋으니까.$K\n"
.stringn "$F3$P$FS고맙다.$K$FA$P아무튼, 지금은 그저$MC…$MD$w3\n"
.stringn "크리미아 부흥에 전력을 다할 뿐.$K$P공주님에 대해선$MC…$MD$w3 아무리 깊이 생각해 봤자$w2\n"
.stringn "신분의 차는 넘을 수 없겠지.$K$P그렇다면 적어도$MC…$MD$w3 평생 곁에서 모시며,$w2\n"
.stringn "가까이에서 공주님의 행복을 지켜보고 싶다.$w4\n"
.stringn "그것만이$MC…$MD$w2 내 소원이다.$K\n"
.stringn "$F1$P그냥$w2\n"
.stringn "낚아채서 도망가면 될 텐데.$K$P$MC……$MD라고 해도$w2\n"
.stringn "제프리 같은 고지식한 사람한테는 무리겠지.$w4\n"
.stringn "알고 있어.$K$FA$P하지만$MC…$MD$w3 왠지 안타깝네.$w4\n"
.stringn "남의 일인데. $w4정말$MC…$MD$K\n"
.stringn "$F3$P$MC…………$MD$K$FS\n"
.stringn "카릴 공, $w2너는 좋은 사람이군.$K\n"
.stringn "$F1$P$FS뭐야, $w2이제야 눈치챘어?$w4\n"
.stringn "나같이 좋은 여자,$w3\n"
.stringn "요즘에는 $w2좀처럼 없다구?$K\n"
.stringn "$F3$P인정하지.$w4\n"
.stringn "너는 훌륭한 여자야.$K\n"
.stringn "$F1$P그, $w2그렇게 말해도$w2\n"
.stringn "이미 늦었거든.$K$P나는 나만을 바라봐 주고$MC…$MD$w2\n"
.stringn "사랑해 주는 남자한테만 관심이 있으니까.$K\n"
.stringn "$F3$P그렇군$MC…$MD$w2 그거 아쉽게 됐어.$K\n"
.stringn "$F1$P아하하,$w3 우린$w2\n"
.stringn "좋은 친구잖아?$w4\n"
.stringn "뭐든지 상담해 줘, $w2힘이 되어 줄 테니까.$K"
db 0
.align 4
//MYELL_CALILL_GEOFFRAY_A

//0x462C
Text_460C:
.stringn "$R背景会話|$B支援背景|$<$F3$FS$F3$FCL_CALILL|$F3$P아, $w2찾았다$MC!$MD$w4\n"
.stringn "제프리님~$MC!$MD$K\n"
.stringn "$F1$FS$F1$FCL_GEOFFRAY|$F1$P응?$w4 아아$MC…$MD 카릴 공.$w4\n"
.stringn "무슨 일 있나?$K\n"
.stringn "$F3$P우후후,$w2 제대로\n"
.stringn "나를 $w2기억해 주다니$MC……$MD$w4\n"
.stringn "이거 가능성 있다고 $w3봐도 되는 거겠지?$K\n"
.stringn "$F1$P뭐라 얘기했었나?$K\n"
.stringn "$F3$P아~뇨, $w2아무것도 아니에요.$K$P저기, $w2제프리님은\n"
.stringn "크리미아 왕녀님의 기사라면서요?$K$P그런 분과 가까워질 수 있다니,$w3\n"
.stringn "저 $w2무척 영광이에요$MC!$MD$K\n"
.stringn "$F1$P그렇게 대단한 건 아니야.$K\n"
.stringn "카릴 공도 나와 같은 동료다,$w2\n"
.stringn "신분 같은 걸로 구별하지 말고$w3\n"
.stringn "평범하게 대해 주었으면 좋겠어.$K\n"
.stringn "$F3$P네$MC!?$MD$w4 그렇게 말하셔도$MC…$MD$w2 아니지.$K\n"
.stringn "크흠$w3 저야말로\n"
.stringn "잘 부탁드려요.$w4 우후후후$K\n"
.stringn "$F1$P그래.$K\n"
.stringn "$F3$P그런데 $w2제프리님.$K\n"
.stringn "저는 $w2엘린시아 공주님에 대해$MC…$MD\n"
.stringn "잘 모르거든요$MC……$MD$w4\n"
.stringn "도대체 어떤 분이신가요?$K\n"
.stringn "$F1$P$FA공주님께 흥미가 있는 건가?$K\n"
.stringn "$F3$P네.$w4\n"
.stringn "$MC…$MD그야, 연적이 될지도 모르니까.$K\n"
.stringn "$F1$P지금 뭐라고 했$MC…$MD$K\n"
.stringn "$F3$P아~뇨, $w3아무것도 얘기 안 했어요.$K$P우리가 지켜야 할 소중한 분이시니$w2\n"
.stringn "알아 두고 싶은 것은 당연하죠.$w4\n"
.stringn "얘기$w2해 주실 수 있나요?$K\n"
.stringn "$F1$P$FS물론이다. $w4$FA$MC…$MD다만$w3\n"
.stringn "어떤 분이냐고 물어보니$w2\n"
.stringn "뭐라고 대답해야 할지 모르겠군$MC……$MD$K\n"
.stringn "$F3$P어째서인가요?$K\n"
.stringn "$F1$P$MC…$MD어떤 말로도$w2\n"
.stringn "공주님을 정확히 표현하는 것은 힘들다.$w4\n"
.stringn "$MC……$MD어쨌든$MC…$MD$K\n"
.stringn "$F3$P어쨌든?$K\n"
.stringn "$F1$P$FS모든 것이 훌륭하신 분이다.$w2\n"
.stringn "가신이니까 그렇게 보는 거라고들 하지만,$w2\n"
.stringn "결코 그렇지 않다.$K$P무엇과도 바꿀 수 없는$MC…$MD$w2\n"
.stringn "크리미아의 보물 그 자체로$MC……$MD$K\n"
.stringn "$F3$P$FA$Fh$MC…………$MD$w2뭐야$MC……$MD$w4\n"
.stringn "제프리님은 $w2공주님께 푹 빠진 거야?$K$P아~ 진짜$MC!$MD$w4 어째서 이렇게$w2\n"
.stringn "좋은 남자하고는 인연이 없는 건데$MC!!$MD$K\n"
.stringn "$F1$P$FA뭐$MC……$MD$w3뭐라고$MC!$MD$MC!?$MD$K\n"
.stringn "기다려, $w2카릴 공$MC!$MD$w4\n"
.stringn "오해야$MC!$MD$w4 나는 그런$MC…………$MD$K\n"
.stringn "$F3$P$FS$Fd아~아$MC…$MD$w3\n"
.stringn "강하신 기사님께서 당황하시기는$MC…$MD$w4\n"
.stringn "정말이지 귀여워 $w2죽겠네.$K$P그래$w2그래.$w4\n"
.stringn "내 것이 될 수 없다는 건 유감이지만,$w3\n"
.stringn "연애 얘기라면 $w2또 카릴님의 특기 분야지.$K$P순진한 기사님과 공주님이 이어지도록$w3\n"
.stringn "발 벗고 나서 보실까.$K"
db 0
.align 4
//MYELL_CALILL_GEOFFRAY_B

//0x425C
Text_423C:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_CALILL|$F1$P으~음$MC…$MD$w2 어쩌지$MC……$MD$w5\n"
.stringn "$MC…………$MD$w2꺄악$MC!?$MD$K$F1$FD\n"
.stringn "$F2$FCL_GEOFFRAY|$F2$P$MC!$MD$w4 위험해$MC!$MD$K\n"
.stringn "$F1$FCL_CALILL|$F1$P$Fo$MC!$MD$w2 $MC!$MD$w2 $MC!$MD$K\n"
.stringn "$F2$FD$F3$FS$F3$FCL_GEOFFRAY|$F3$P괜찮나, $w2아가씨?$K\n"
.stringn "$F1$P어, $w2어머$MC……$MD$w3\n"
.stringn "아가씨$w2라니$MC……$MD$K$FS$P$Fd괘, $w2괜찮아요.$w4\n"
.stringn "성기사님 덕분에\n"
.stringn "아무래도 다치진 않은 것 같네요.$K\n"
.stringn "$F3$P그런가. $w4다행이야.$w4\n"
.stringn "생각하는 것도 좋지만, $w2발밑을\n"
.stringn "아무쪼록 조심하도록 해.$K$F3$FD\n"
.stringn "$F1$P$FA자, $w2잠깐$MC!$MD 잠깐만요$MC!$MD$K\n"
.stringn "$F4$FS$F4$FCL_GEOFFRAY|$F4$P왜 그러지?$K\n"
.stringn "$F1$P$FS나는$MC…$MD$w2 아니, $w3저는\n"
.stringn "카릴이라고 합니다만$MC……$MD$w4\n"
.stringn "성기사님의 존함은 어떻게 되시나요?$K\n"
.stringn "$F4$P제프리다.$w4\n"
.stringn "그럼, $w2이만.$K$F4$FD\n"
.stringn "$F1$P제프리님$MC……$MD$K$P좋은데.$w4\n"
.stringn "저런 고급스러운 남자야말로$w2\n"
.stringn "이 카릴님에게 어울리는 상대지.$K$P아아$MC…$MD$w4 사랑은 정말\n"
.stringn "불쑥 찾아온다니까.$K"
db 0
.align 4
//MYELL_CALILL_GEOFFRAY_C

//0x61AC
Text_618C:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_CALILL|$F1$FCL_NEPENEE|$F3$P음?$w4 네페니, $w2자루를 잔뜩 가져왔네.\n"
.stringn "어디 나갔다 온 거야?$K\n"
.stringn "$F1$P근처에, $w2로슈 열매가$MC……$MD$w4\n"
.stringn "열려서$MC……$MD$K\n"
.stringn "$F3$P흐음$MC……$MD$w2 그래서,$w2\n"
.stringn "그 로슈 열매라는 건$MC…$MD 뭔데?$K\n"
.stringn "$F1$P벌레 물린 데 쓰는$MC……$MD$w2 약이에유.$K\n"
.stringn "$F3$P흐~음, $w2그런 열매도 있구나.$w4\n"
.stringn "시골의 지혜라는 건가?$w4\n"
.stringn "나는 왕도에서 자라서 잘 모르지만.$K\n"
.stringn "뭐 $w2됐어, $w2하나 줘 봐.$K\n"
.stringn "$F1$P근디$MC……$MD$w4\n"
.stringn "생것을 맨손으로 잘못 만지면$MC……$MD$w4\n"
.stringn "피부가 까져유.$K\n"
.stringn "$F3$P아아, $w2알고 있어.$w4\n"
.stringn "이렇게 드는 거 맞지?$K\n"
.stringn "$F1$P$MC……$MD어떻게 아는 거예유?$K\n"
.stringn "$F3$P$MC…………$MD$K\n"
.stringn "$F1$P왕도에서 자랐다고$MC…$MD$w2 계속 그렇게 말했으면서$MC……$MD$K\n"
.stringn "$F3$P시, $w2시끄러워$MC!$MD$K$P네페니, $w2지금 건 비밀이다?$w4\n"
.stringn "나는 세련된 도시 여자니까$MC!$MD$w4\n"
.stringn "알았지$MC!?$MD$K\n"
.stringn "$F1$P$MC…………$MD$K\n"
.stringn "$F3$P$Fc뭐, $w2뭐 어때서.$w4\n"
.stringn "시골뜨기 취급을 받기 싫은 건$MC……$MD$w4\n"
.stringn "나도 마찬가지라는 거야.$K$P$Fd그러니까 네 기분은$MC…$MD$w2 잘 알고 있어$MC…$MD$K\n"
.stringn "$F1$P$MC…………$MD알았어$MC……$MD$K$P$FS$MC……$MD하지만$MC……$MD$w2 그렇구나.$w4\n"
.stringn "노력하면$MC……$MD$w2 카릴씨처럼\n"
.stringn "될 수 있데이$MC……$MD$w3 다행이다.$K$P저$MC……$MD$w2 힘낼게유.$K\n"
.stringn "$F3$P$FS그래, $w2그 마음가짐이야.$w4\n"
.stringn "좋은 남자 찾아서 $w2마을로 돌아가자고$MC!$MD$w4\n"
.stringn "힘내래이$MC!$MD$K"
db 0
.align 4
//MYELL_CALILL_NEPENEE_A

//0x5CC0
Text_5CA0:
.stringn "$R背景会話|$B支援背景|$<$F3$FS$F3$FCL_CALILL|$F1$FCL_NEPENEE|$F3$P어머, $w2네페니.$w4\n"
.stringn "요즘은 $w2어때?$K\n"
.stringn "$F1$P$MC……$MD카릴씨.$K\n"
.stringn "$F3$P$FA이리 와서 $w2잠깐 얼굴 좀 들어 봐.$w4\n"
.stringn "$MC…$MD으~음, $w2역시 그 투구가 안 된다니까.$w4\n"
.stringn "모처럼 화장까지 해 줬는데. $w4연하긴 하지만.$K\n"
.stringn "$F1$P괜찮아요$MC……$MD$w4\n"
.stringn "들면$MC……$MD$w2 힐끔힐끔 볼 수 있고$MC……$MD$K\n"
.stringn "$F3$P$MC…$MD은근슬쩍 $w2자기가 귀엽다고\n"
.stringn "티 내는 거야?$K\n"
.stringn "$F1$P네?$K\n"
.stringn "$F3$P$MC……$MD자각이 없나 $w2보네.$w4\n"
.stringn "좋겠다$MC……$MD 넌.$K$P가슴도 큰 편이면서$MC……$MD$w4\n"
.stringn "전부 숨기고 말이야$MC……$MD$w4\n"
.stringn "왠지 좀 $w2열받기 시작했어$MC……$MD$K\n"
.stringn "$F1$P그, $w2그래도$MC……$MD 난$MC……$MD$w3\n"
.stringn "카릴씨처럼, $w2당당하게$MC……$MD$w3 못 산다.$w4\n"
.stringn "시골뜨기$MC……$MD$w3니까$MC……$MD$K\n"
.stringn "$F3$P그렇겠지~$w4\n"
.stringn "남의 시선을 신경 쓰면, $w2꽤나\n"
.stringn "자신을 꾸미기 힘들어져$MC…$MD$K$P그래도 $w2도시 사람들은 쌀쌀맞으니까 괜찮아.$w4\n"
.stringn "남의 일 같은 건 신경 안 써.$K\n"
.stringn "$F1$P$MC……$MD그래도$MC……$MD$w4\n"
.stringn "카릴씨는, $w2친절한데$MC……?$MD$K\n"
.stringn "$F3$P$MC!$MD$w4\n"
.stringn "$FS아, $w2아아, $w2그런가?$w4\n"
.stringn "나는 도시 태생이지만, $w2상식인이니까$MC!$MD$K$P어쨌든, $w2포기하지 마 $w2네페니$MC!$MD$w4\n"
.stringn "너는 귀여우니까, $w2알겠지?$K\n"
.stringn "$F1$P$MC…………$MD네$MC……$MD$K"
db 0
.align 4
//MYELL_CALILL_NEPENEE_B

//0x5898
Text_5878:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_CALILL|$F3$P음?$w4 거기 너,$w2\n"
.stringn "잠깐 기다려 봐.$K\n"
.stringn "$F1$FCL_NEPENEE|$F1$P$MC……?$MD$K\n"
.stringn "$F3$P뭐야 $w1뭐야,$w3\n"
.stringn "젊은 아가씨가 $w2그런 투구로 얼굴을 가려서야 되겠어.$K$P화장이라도 하는 게 어때?$K\n"
.stringn "$F1$P$MC……$MD딱히, $w2그런 건$MC……$MD$w4\n"
.stringn "아무래도 좋아요$MC……$MD$K\n"
.stringn "$F3$P$MC…………$MD$w4\n"
.stringn "너, $w2태어난 곳은 어디야?$K\n"
.stringn "$F1$P$MC……$MD어디든 $w2상관없$MC…$MD$w3잖아요.$K\n"
.stringn "$F3$P붙임성 없는 아가씨네.$w4\n"
.stringn "뭐어, $w2왜 그렇게\n"
.stringn "말하기 싫어하는지는 알겠어.$K$P시골 사투리가 무심코\n"
.stringn "나올까 봐 그러는 거지?$K\n"
.stringn "$F1$P$MC!$MD$w4 어, $w2어떻게$MC……$MD$K\n"
.stringn "$F3$P어떻게 알았냐고?$w4\n"
.stringn "내 옛날 친구가$MC…$MD$w3\n"
.stringn "너랑 똑같은 고민을 $w2가지고 있었거든.$K\n"
.stringn "$F1$P$MC…………$MD$K\n"
.stringn "$F3$P$FS그래, $w2\n"
.stringn "내가 발벗고 나서 줄게.$K$P너같이 촌스러운 애가 있으면$w3\n"
.stringn "나까지 기운이 빠지니까.$w4\n"
.stringn "기분 전환으로 $w2화장하는 법을 가르쳐 줄게.$K\n"
.stringn "$F1$P$MC……$MD피, $w2필요 없다$MC…$MD$w3요.$K\n"
.stringn "$F3$P자자, $w3이상한 말투 쓰지 말고.$w4\n"
.stringn "이 카릴씨한테 $w2전~부 맡겨 줘.$w4\n"
.stringn "나쁜 짓은 안 할 테니까.$K\n"
.stringn "$F1$P$MC…………$MD$K"
db 0
.align 4
//MYELL_CALILL_NEPENEE_C

//0x6FCC
Text_6FAC:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_CALILL|$F3$FCL_TOPUCK|$F3$P저기, $w2카릴 선생님$MC…$MD$w4\n"
.stringn "내 마도, $w2어땠어?$K\n"
.stringn "$F1$P$MC…$MD음.$K\n"
.stringn "$F3$P$MC……$MD$K\n"
.stringn "$F1$P$FS열심히 했구나.$w4\n"
.stringn "이제 $w2내가 가르칠 건 없어.$K\n"
.stringn "$F3$P$FS해냈다$MC!$MD$w4\n"
.stringn "이걸로 나도 제 몫을 하겠어$MC!$MD$K\n"
.stringn "$F1$P후후,$w2 네 덕분에\n"
.stringn "나도 자극받았어.$K$P한 번 더 $w2마도를 공부해 볼까\n"
.stringn "생각도 했었거든.$K\n"
.stringn "$F3$P$FA음$MC…?$MD$w4 선생님도\n"
.stringn "아직 공부할 게 있는 거야?$K\n"
.stringn "$F1$P$FA무슨 소리야.$w4\n"
.stringn "내가 알려 준 건$w2\n"
.stringn "마도의 아주 작은 일부분이라고.$K$P여기까진 $w2수행을 거듭하면\n"
.stringn "누구나 습득할 수 있어.$K$P앞으로 더 나아갈지 말지는$MC…$MD$w4\n"
.stringn "자신의 자질에 달려 있지.$K\n"
.stringn "$F3$P자질이라니$MC…?$MD$K\n"
.stringn "$F1$P타고난 재능 $w2말하는 거야.$w4\n"
.stringn "마도의 극에 달하려면\n"
.stringn "그게 있느냐 없느냐가 중요해.$K\n"
.stringn "$F3$P$FS나, $w2나는 있어$MC!?$MD$w4\n"
.stringn "내 마도의 자질은 어때$MC…?$MD$K\n"
.stringn "$F1$P$MC……$MD유감이지만,$w2\n"
.stringn "너도 나처럼 평범해.$w4\n"
.stringn "대단한 자질은 없는 것 같네.$K\n"
.stringn "$F3$P$FA$MC…$MD그럼,$w2\n"
.stringn "나는 $w2여기까지인 거야?$K\n"
.stringn "아무리 노력해도$w2\n"
.stringn "최강의 마도사가 될 순 없어?$K\n"
.stringn "$F1$P$MC……$MD어떤 방법을 사용해서\n"
.stringn "마력을 높일 순 있지만$w2\n"
.stringn "그것도 한계가 있고.$K\n"
.stringn "$F3$P어, $w2어떤 방법인데$MC!?$MD$K\n"
.stringn "$F1$P자기 몸에 정령을 새기는 거야.$w4\n"
.stringn "소위 【정령의 부적】이라고 하지.$K\n"
.stringn "$F3$P정령의$MC…$MD$w4 부적?$K\n"
.stringn "$F1$P그래.$w4\n"
.stringn "마도의 근원은\n"
.stringn "대자연을 관장하는 정령의 힘.$K$P그걸 몸속에 집어넣어서,$w2\n"
.stringn "빠르게 자신의 마력을 올리는 방법이야.$K$P간단히 말하면 $w2자기 자신을 미끼로 삼아서\n"
.stringn "정령을 기르는 거라고 할 수 있지.$K\n"
.stringn "$F3$P자, $w2잡아먹히는 거야?$K\n"
.stringn "$F1$P영혼을 갉아먹힌다는 것 같아$MC…$MD$w4\n"
.stringn "마력의 대가로 말이지.$K$P그러니까 $w2상당한 각오가 없다면\n"
.stringn "하지 않는 편이 좋아.$K\n"
.stringn "$F3$P$MC…$MD그렇게 위험한 짓을\n"
.stringn "하는 녀석이 있어?$K\n"
.stringn "$F1$P사실 $w2꽤 많이들 해.$w4\n"
.stringn "이 군의 참모 공도 아마 그럴 거고.$K\n"
.stringn "$F3$P세네리오라는 녀석?$K\n"
.stringn "$F1$P이마에 문양이 새겨져 있잖아.$w4\n"
.stringn "정령과 계약하면\n"
.stringn "그런 증표가 나타나.$K\n"
.stringn "$F3$P아, 그거구나$MC…$MD$MC!$MD$K$P그거라면 나도 본 적 있어.$w5\n"
.stringn "나한테 마도를 가르쳐 준$w2\n"
.stringn "사막의 할아버지 손바닥에도 있었거든.$K\n"
.stringn "$F1$P$MC…$MD베그니온이나 데인에서는,$w4\n"
.stringn "【인붙이】라고 오해받는다는 이유로\n"
.stringn "꺼리는 사람도 많이 봤지만.$K\n"
.stringn "$F3$P응?$w4\n"
.stringn "뭐라고?$K\n"
.stringn "$F1$P뭐, $w2아무튼$w3\n"
.stringn "정령과의 계약은 하지 말라는 소리야.$K\n"
.stringn "$F3$P그래도 말야$MC…$MD$w4\n"
.stringn "나, $w2강해지고 싶은데$MC…$MD$K\n"
.stringn "$F1$P$FS계약을 하지 않아도$w2\n"
.stringn "아직 노력할 여지는 있어.$K\n"
.stringn "평범한 사람들끼리$w2\n"
.stringn "서로 돕는 거지.$K\n"
.stringn "$F3$P$FS그, $w2그렇구나.$K\n"
.stringn "좋아$MC!$MD$w4\n"
.stringn "나, $w2최강의 평범한 마도사가 될 거야$MC!!$MD$K\n"
.stringn "$F1$P아하하,$w2 그 기세야.$K"
db 0
.align 4
//MYELL_CALILL_TOPUCK_A

//0x6A68
Text_6A48:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_CALILL|$F3$FCL_TOPUCK|$F1$P토팍$MC!$MD$w4\n"
.stringn "적당히 좀 하라니까$MC!!$MD$K\n"
.stringn "$F3$P상관없잖아.$w4\n"
.stringn "빨리 다음 마법 $w2알려 줘.$K\n"
.stringn "$F1$P안 돼.$K\n"
.stringn "$F3$P나 $w2잘하고 있잖아$MC!$MD$w4\n"
.stringn "화염도, $w2번개도, $w2바람도$MC!$MD$K\n"
.stringn "$F1$P네 배우는 속도가 빠르다는 건 인정할게.$w4\n"
.stringn "솔직히 $w2대단하다고 생각해.$K\n"
.stringn "$F3$P그치?$K\n"
.stringn "$F1$P하지만, $w2알맹이가 없어.$K$P한 번에 머리에 욱여넣어 봤자$w3\n"
.stringn "하나하나 제대로 사용하지 못하면$w2\n"
.stringn "습득했다고 할 순 없다고.$K\n"
.stringn "$F3$P말은 그렇게 해 놓고$w4\n"
.stringn "카릴은 $w2내가 더\n"
.stringn "재능이 있는 게 부러운 거지$MC!$MD$K\n"
.stringn "추월당하는 게 싫어서 그런 거 아냐$MC!?$MD$K\n"
.stringn "$F1$P$Fc$MC…$MD후우$w3\n"
.stringn "$Fd알겠니?$w4 잘 들어.$K$P어설프게 주문을 외우다간,$w2\n"
.stringn "언젠가 사고 난다?$K\n"
.stringn "$F3$P사고?$K\n"
.stringn "$F1$P마도를 오발시키는 사고.$w4\n"
.stringn "손가락이 날아가거나$MC…$MD$w4\n"
.stringn "아, $w2손가락뿐이면 다행이지.$K$P팔이 사라지는 경우도 있고,$w2\n"
.stringn "잘못하면 $w2목숨을 잃는 경우도 있어.$K\n"
.stringn "$F3$P가, $w2각오는 하고 있거든$MC…$MD$K\n"
.stringn "$F1$P자기 목숨이라곤 $w2한 적 없다.$K\n"
.stringn "$F3$P뭐?$K\n"
.stringn "$F1$P적을 맞히려고 했는데$w2\n"
.stringn "아군에게 직격$MC…$MD$w4\n"
.stringn "그렇게 $w2소중한 사람을 잃는다$MC……$MD$K\n"
.stringn "$F3$P$MC……$MD$K\n"
.stringn "$F1$P마도는 말이지,$w2\n"
.stringn "다른 무기하곤 달라.$K$P사용자의 능력이 부족하면$w2\n"
.stringn "큰 사고가 날 수도 있어.$w4\n"
.stringn "이건 그냥 하는 말이 아니야.$K\n"
.stringn "$F3$P$MC……$MD알았어.$K\n"
.stringn "$F1$P그럼, $w2제대로 기초부터 해.$w4\n"
.stringn "전장에서 아군의 발목을$w2\n"
.stringn "잡고 싶진 않지?$K\n"
.stringn "$F3$P응$MC…$MD$MC!$MD$K"
db 0
.align 4
//MYELL_CALILL_TOPUCK_B

//0x6710
Text_66F0:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_CALILL|$F3$FS$F3$FCL_TOPUCK|$F3$P저기 저기,$w2\n"
.stringn "예쁜 아줌마$MC!$MD$K\n"
.stringn "$F1$P$MC……$MD$K\n"
.stringn "$F3$P$FA어라?$w4\n"
.stringn "화려한 누나였던가?$K\n"
.stringn "$F1$P예쁜$MC!$MD$w4\n"
.stringn "누나$MC!!$MD$w4\n"
.stringn "$MC…$MD라고 안 하면 대답 안 할 거야.$K\n"
.stringn "$F3$P쳇$w2\n"
.stringn "귀찮아.$K\n"
.stringn "$F1$P그럼 $w2관둬도 상관없는데?$K$P나도$w3\n"
.stringn "너 같은 꼬맹이한테\n"
.stringn "마도를 가르치는 건 사양$MC…$MD$K\n"
.stringn "$F3$P$FS예쁜 누나$MC!$MD$w4\n"
.stringn "카릴씨$MC!$MD$K$P부탁이니까$w3\n"
.stringn "저한테 마도를 $w2가르쳐 주세요$MC!$MD$K\n"
.stringn "$F1$P$MC…$MD나 참.$w4\n"
.stringn "계산적인 꼬맹이라니까.$K$P그래서, $w2저번에 알려준 곳까지는\n"
.stringn "어떻게 됐어?$K$P제대로 습득하지 않았다면$w2\n"
.stringn "새로운 건 안 알려 줄 거야.$K\n"
.stringn "$F3$P당연히 완벽하게 했지$MC!$MD$w4\n"
.stringn "애초에 $w2나,$w2\n"
.stringn "이 책에 있는 건 전부 익혔거든.$K\n"
.stringn "$F1$P정말이야?$K\n"
.stringn "$F3$P지금부터 보여 줄게.$w4\n"
.stringn "제대로 한 건지 확인해 줘?$K\n"
.stringn "$F1$P네네.$K"
db 0
.align 4
//MYELL_CALILL_TOPUCK_C

