//0x8310
Text_82F0:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_CHAP|$F1$P어~이, $w2네페니.$K\n"
.stringn "$F3$FS$F3$FCL_NEPENEE|$F3$P아, $w2채프씨.$K\n"
.stringn "$F1$P아까 $w2젊은 애들한테서 들었다.$K$P너 $w2너무\n"
.stringn "다른 사람에게 $w2입을 안 여는 거 아녀?$K\n"
.stringn "$F3$P$FA그, $w2그치만$MC……$MD$w3\n"
.stringn "난 시골뜨기잖여,$w2\n"
.stringn "부끄럽다 아이가$MC……$MD$K\n"
.stringn "$F1$P뭐가 부끄럽단 기가,$w2\n"
.stringn "시골이 얼마나 좋은디.$K\n"
.stringn "$F3$P내 말투는$w2\n"
.stringn "너무 사투리가 세다.$w4\n"
.stringn "바보 취급 당할 기다$MC……$MD$K$P채프씨처럼\n"
.stringn "평범하게 말도 잘 못 꺼내구$MC……$MD$K\n"
.stringn "$F1$P$FS무슨 말 하나 니, $w2이 단에는\n"
.stringn "그렇게 나쁜 사람 없다.$K$P그렇게 딱딱하게 굴지 말고,$w2\n"
.stringn "마을에 있을 때처럼\n"
.stringn "평범하게 하면 된데이.$K\n"
.stringn "$F3$P$MC…………$MD$K\n"
.stringn "$F1$P니는 나랑 얘기할 때는$w3\n"
.stringn "환하게 잘 웃으면서.$K$P그렇게 예쁜 미소를$w2\n"
.stringn "숨기면 아깝제.$w4\n"
.stringn "자, $w2시험 삼아 여기서 웃어 보는 건 어뗘?$K\n"
.stringn "$F3$P뭐, $w2뭐꼬$MC……?$MD$K\n"
.stringn "$F1$P자, $w2웃어라 웃어.$K\n"
.stringn "$F3$P부, $w2부끄럽다 안 카나$MC……$MD$w4 정말.$K\n"
.stringn "$FS이, $w2이렇게?$K\n"
.stringn "$F1$P그래그래, $w2그거여.$w4\n"
.stringn "그 미소여.$K$P니는 얼굴이 이쁘장하니께\n"
.stringn "그러고 있으면$w2\n"
.stringn "단의 젊은 남자들이 가만두지 않을 기다.$K$P여기서 좋은 사람 찾아가지고$w2\n"
.stringn "마을에 함께 돌아가는 건 어뗘?$K\n"
.stringn "$F3$P저, $w2정말$MC……$MD$w4\n"
.stringn "무슨 말 하는 겨, $w2채프씨$MC!$MD$K"
db 0
.align 4
//MYELL_CHAP_NEPENEE_A

//0x7D00
Text_7CE0:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_NEPENEE|$F1$FCL_CHAP|$F1$P우리 병영은$w2\n"
.stringn "대체 어디 있는 겨?$K\n"
.stringn "$F3$P글쎄$MC……?$MD$K\n"
.stringn "$F1$P다들 용케 안 헤매고\n"
.stringn "제대로 찾아가는구마.$K$P매일매일 숙소가 바뀌니까\n"
.stringn "나는 왠지 안정되지가 않어.$K\n"
.stringn "$F3$P어쩔 수 없다 아이가, $w2전쟁이다.$w4\n"
.stringn "우리도\n"
.stringn "익숙해질 수밖에 없는 기라.$K\n"
.stringn "$F1$P그렇구먼$MC……$MD$K$P나도 니도\n"
.stringn "지금까지는 전쟁이랑\n"
.stringn "인연이 없었제.$K\n"
.stringn "$F3$P맞다.$w4\n"
.stringn "그래서 군에서 당연하다고 카는 게\n"
.stringn "잘 이해가 안 간데이.$K\n"
.stringn "$F1$P$FS그러고 보니 $w2지원했을 때는\n"
.stringn "큰일이었제.$K\n"
.stringn "어찌 됐든 우린 그냥 민병이니께\n"
.stringn "사실상 마을 사람들 모임에 불과했지 않나.$K$P이상은 있어도 힘과 기술이 없어서 곤란혀.$K\n"
.stringn "$F3$P$FS맞다 맞다.$K$P장비도 수도 부족하다꼬 해서\n"
.stringn "나랑 채프씨 둘이서$w2\n"
.stringn "활 하나만 쓰라카고.$K$P게다가 둘 다 활 쓸 줄 모르는데, $w2참.$K\n"
.stringn "$F1$P이번 전쟁은$w2\n"
.stringn "정말로 갑작스러웠으니께.$K$P우리가 제대로 한 훈련은$w3\n"
.stringn "점호가 다고$MC…$MD$K$P행군할 때마다 다들 도망치거나 뒤처져서$w2\n"
.stringn "막상 싸우기 전부터 점점\n"
.stringn "사람이 줄고 있었데이.$K$P그러니 져서 잡혀가는 것도 무리가 아녀.$w4\n"
.stringn "그에 비하면 $w2이 군은\n"
.stringn "엄청 우수하다 아이가.$K\n"
.stringn "$F3$P그야 $w2왕녀님의 군이니까 그러제.$K\n"
.stringn "$FA그나저나 $w2진짜로 어딘지 모르겠다.$K\n"
.stringn "$F1$P뭐 괜찮다, $w2어쨌든 근처에 있는\n"
.stringn "누군가에게 물어보면 되니.$K\n"
.stringn "$F3$P으, $w2응$MC……$MD$K\n"
.stringn "$F1$P$FA음?$w4 왜 그려?$K\n"
.stringn "$F3$P나$MC……$MD$w4 그다지\n"
.stringn "도시 사람하고 얘기하는 게 익숙지 않다.$K\n"
.stringn "$F1$P무슨 말 $w2하나 니.$w4\n"
.stringn "언제나처럼$w2\n"
.stringn "평범하게 말하면 되지 않나.$K\n"
.stringn "$F3$P그, $w2그치만$MC……$MD$w4\n"
.stringn "난 시골뜨기다$MC……$MD$K"
db 0
.align 4
//MYELL_CHAP_NEPENEE_B

//0x79AC
Text_798C:
.stringn "$R背景会話|$B支援背景|$<$F3$FS$F3$FCL_NEPENEE|$F1$FS$F1$FCL_CHAP|$F1$P오늘은 날씨가 좋구먼,$w2\n"
.stringn "네페니.$K\n"
.stringn "$F3$P응응, $w2증말로.$K\n"
.stringn "$F1$P네페니,$w2\n"
.stringn "너네 집은 어뗘?$w4\n"
.stringn "지금쯤이면 $w3밭 수확에 힘쓸 때인가?$K\n"
.stringn "$F3$P응응, $w2그렇데이.$w4\n"
.stringn "여동생과 남동생들이 $w2어무이 일손으로 불려가서$w2\n"
.stringn "분명 $w2불평하고 있을 기다.$K\n"
.stringn "$F1$P하하하,$w2 그야 한창 놀고 싶을 때니께.$w4\n"
.stringn "네페니네 집은 $w4가족이 몇 명이었제?$K\n"
.stringn "$F3$P여동생 둘에 남동생 셋.$w4\n"
.stringn "남동생들은 세쌍둥이라,$w2\n"
.stringn "아직 여섯 살밖에 안 된다.$K\n"
.stringn "$F1$P딱 장난기 많을 나이구먼.$w4\n"
.stringn "분명 집안이 북적거리겠구마.$K\n"
.stringn "$F3$P응, $w2매일 어무이한테\n"
.stringn "야단맞고 있을 기다.$w4\n"
.stringn "채프씨네는?$K\n"
.stringn "$F1$P우리 집 애들은 좀 더 크대이.$w4\n"
.stringn "제대로 애엄마를 도와주면\n"
.stringn "좋을 텐데 말여$MC……$MD$K\n"
.stringn "$F3$P괜찮을 기다, $w2\n"
.stringn "분명 $w2잘하고 있겄제.$K"
db 0
.align 4
//MYELL_CHAP_NEPENEE_C

//0x94A0
Text_9480:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_ZIHARK|$F3$FS$F3$FCL_CHAP|$F3$P$MC…$MD그래서 말이여.$K$P첫째 딸은 나처럼 이렇게$MC…$MD$w2\n"
.stringn "덩치가 크데이.$w4\n"
.stringn "밭일도 사내놈만큼 하는 $w2착한 아가씨라구.$K$P너도 $w2분명 마음에 들 거여.$K\n"
.stringn "$F1$P아$MC…$MD$w4 네.$K\n"
.stringn "$F3$P$FA그렇게 건성으로 대답하면 못 쓴데이.$w3\n"
.stringn "제~대로 들어야제.$K$P아내가 될지도 모르는\n"
.stringn "딸아이에 대한 일이니께.$K\n"
.stringn "$F1$P채프씨$MC……$MD$w4\n"
.stringn "지난번에도 말씀드렸지만,$w2\n"
.stringn "저는 아직 $w2가정을 가질 생각이 없어요.$K\n"
.stringn "$F3$P얼레$MC…$MD$w4 우째서?$K\n"
.stringn "$F1$P$MC……$MD옛날에$MC…$MD$w4 소중한 애인이 있었습니다.$K$P사정이 있어서\n"
.stringn "함께하지 못했는데$MC……$MD$w4\n"
.stringn "전 아직도 $w3그 애한테 미련이 남았거든요.$K$P잊을 수가 없어요.$K$P그러니까, $w2$FS채프씨의 마음은\n"
.stringn "기쁘지만$MC…$MD$w3 죄송해요.$K\n"
.stringn "$F3$P그랬구먼.$K$P아쉬우이$MC…$MD$K\n"
.stringn "$F1$P채프씨네 가족이\n"
.stringn "된다는 건$MC…$MD$w3\n"
.stringn "꽤나 매력적이지만요.$K\n"
.stringn "$F3$P$MC……$MD$K$FS$P그럼 둘째 딸은 어떤가?$w4\n"
.stringn "나이 차가 조금 나긴 하지만,$w2\n"
.stringn "뭐 신경 쓰지 말어.$K$P얘가 또 마음씨가 $w2그렇게 좋거든.$w4\n"
.stringn "웃으면 이렇게, $w2통통하게 볼에 보조개가$MC……$MD$K\n"
.stringn "$F1$P$FA아니,$w3\n"
.stringn "그런 게 아니라니까요.$w4\n"
.stringn "곤란하게 됐네$MC……$MD$K"
db 0
.align 4
//MYELL_CHAP_ZIHARK_A

//0x8DBC
Text_8D9C:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_ZIHARK|$F3$FS$F3$FCL_CHAP|$F3$P이야, $w2지하크.$w4\n"
.stringn "전에는 즐거웠데이.$K\n"
.stringn "$F1$P맞아요.$K$P채프씨는 말을 잘 하시니까$w3\n"
.stringn "식사하는 내내 $w2웃기만 했어요.$w4\n"
.stringn "그렇게 즐거운 식사는 오랜만이었습니다.$K\n"
.stringn "$F3$P그리 말해 주니 같이 가자고$w3\n"
.stringn "말한 보람이 있구먼.$K\n"
.stringn "$F1$P아, $w2그러고 보니 여기요.$w4\n"
.stringn "제 몫입니다.$K\n"
.stringn "$F3$P아이, 괜찮어.$w4\n"
.stringn "내가 가자고 했으니께.$w4\n"
.stringn "신경 쓰지 말어.$K\n"
.stringn "$F1$P그럴 수는 없습니다.$K\n"
.stringn "갑작스러운 권유여서 돈을 못 드렸지만$w2\n"
.stringn "오늘은 제대로 있거든요.$w4\n"
.stringn "제대로 반만큼 $w2내겠습니다.$K\n"
.stringn "$F3$P$FA그런 말을 들어도 말이지$MC…$MD$w4\n"
.stringn "얼마 받았는지 $w2기억도 안 난데이.$K\n"
.stringn "$F1$P합쳐서 4하고 반 골드였습니다.$w4\n"
.stringn "그러니까 2하고 4분의 1 골드를\n"
.stringn "드리면 $w3빚은 남지 않죠.$K\n"
.stringn "$F3$P허어~$w3 젊은데도\n"
.stringn "착실하구먼.$w4\n"
.stringn "기억력도 좋고, $w2계산도 빠르구.$K\n"
.stringn "$F1$P똑 부러진 것 천성입니다.$w4\n"
.stringn "느긋한 용병 동료들은$w3\n"
.stringn "꽤나 $w2싫어하지만요.$K\n"
.stringn "$F3$P$FS아녀. $w3그거면 됐지.\n"
.stringn "잘생기고 성실하면 충분혀.$K$P젊은 아가씨들에게$w3\n"
.stringn "인기 있지 않어?$K\n"
.stringn "$F1$P그렇지도 않습니다.$K$P저 같은 녀석을 좋아해 주는\n"
.stringn "마음씨 착한 여성은$MC…$MD$w2\n"
.stringn "좀처럼 없거든요.$K\n"
.stringn "$F3$P$FA허어어,$w3 세상 일은 아무도 모르는 법이여.$w4\n"
.stringn "나처럼 멍한 남자도$w3\n"
.stringn "살림을 차리는데 말이제.$K\n"
.stringn "$F1$P하하하,$w4 채프씨는\n"
.stringn "좋은 남자예요. $w4제가 보장합니다.$K\n"
.stringn "$F3$P$FS아 맞다$MC!$MD$w4 우리 딸을 데려가면 되겠데이.$K\n"
.stringn "$F1$P$FA네?$w4\n"
.stringn "갑자기 무슨 말씀을 하시는 거죠?$K\n"
.stringn "$F3$P자랑은 아니지먼,$w2\n"
.stringn "착한 아이들 뿐이여.$K$P나는 지하크가 마음에 들었으니,$w2\n"
.stringn "딸내미들도 $w2분명 마음에 들어할 겨.$K\n"
.stringn "$F1$P채프씨, $w2농담은 그만$MC…$MD$K\n"
.stringn "$F3$P어떤가,$w2\n"
.stringn "첫째 딸이라면 $w2나이도 딱\n"
.stringn "맞을 것 같은디?$K\n"
.stringn "$F1$P아니$MC…$MD$w3 곤란합니다.$w4\n"
.stringn "전 그럴 생각은$MC……$MD$K"
db 0
.align 4
//MYELL_CHAP_ZIHARK_B

//0x87F4
Text_87D4:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_ZIHARK|$F1$FCL_CHAP|$F1$P얼레$MC……$MD$w4\n"
.stringn "너, $w2그런 데서\n"
.stringn "뭐 하는 거여?$K\n"
.stringn "$F3$P$FS아, $w2채프씨.$w4\n"
.stringn "잠깐 $w2어깨 보호대를 수리하고 있었어요.$w4\n"
.stringn "보세요, $w2여기가 찢어졌거든요.$K\n"
.stringn "$F1$P정말이구먼. $w2이 상태로\n"
.stringn "싸우거나 하면 위험하제$MC……$MD$K$P가 아니라$MC…$MD$w3 으음?$w4\n"
.stringn "우째 내 이름을 알고 있는 겨?$K\n"
.stringn "$F3$P아아$MC…$MD$w4 저는 직업 때문에$w2\n"
.stringn "사람의 얼굴과 이름을 잘 기억합니다.$K$P인사도 하지 않았는데 $w2\n"
.stringn "놀래켜서 죄송해요.$K$P저는 지하크.$w4\n"
.stringn "앞으로도 잘 부탁합니다, $w4채프씨.$K\n"
.stringn "$F1$P$FS그래, $w2나도$MC……$MD$w4\n"
.stringn "반가우이.$K$P어깨 보호대를 고치는 $w2직업이라면$MC…$MD$w4\n"
.stringn "너는 $w2가죽 장인이라도 되는 겨?$K\n"
.stringn "$F3$P아닙니다. $w4저는 $w2검사예요.$w4\n"
.stringn "용병으로 아이크에게 고용되어 있죠.$K\n"
.stringn "$F1$P흐음$MC…$MD$w4 검사가 용케 이런 것도\n"
.stringn "수리할 수 있구먼. $w4참말로 재주가 좋아.$K\n"
.stringn "$F3$P이 정도는 스스로 해야죠.$w4\n"
.stringn "용병은 가난하니까요.$K$P좋아, $w3이제 됐다.$K\n"
.stringn "$F1$P호오$MC…$MD$w4 훌륭하데이.$K\n"
.stringn "우리 둘째 아들도$w2\n"
.stringn "본받으면 좋을 텐디.$K\n"
.stringn "$F3$P채프씨네 아이는$w2\n"
.stringn "모두 몇 명인가요?$K\n"
.stringn "$F1$P아들 다섯에 $w2딸 셋.$w4\n"
.stringn "제일 큰 놈이 $w2딱\n"
.stringn "너 정도 될 거여.$K\n"
.stringn "$F3$P역시 아이가 많으시군요.$w4\n"
.stringn "그럴 거 같은 느낌이 들었어요.$K\n"
.stringn "$F1$P그건 $w2대체 무슨 느낌이여?$K\n"
.stringn "$F3$P마음씨 좋은 아버지요.$w4\n"
.stringn "채프씨한테는 $w2딱 맞지 않나요?$K\n"
.stringn "$F1$P그, $w2그려?$w4\n"
.stringn "그렇게 말해 주니$w3\n"
.stringn "왠지 쑥스럽구먼.$K"
db 0
.align 4
//MYELL_CHAP_ZIHARK_C

//0xA678
Text_A658:
.stringn "$R背景会話|$B支援背景|$<$F5$FCL_GATRIE|$F5$P$MC…………$MD$K\n"
.stringn "$F3$FCL_CHINON|$F3$P응?$K\n"
.stringn "$F5$P$MC…………$MD$K\n"
.stringn "$F3$P야, $w2뭘 멍하게\n"
.stringn "서 있냐 가트리?$K\n"
.stringn "$F5$FD$F1$FS$F1$FCL_GATRIE|$F1$P아, $w2시논씨$K\n"
.stringn "저, $w2그녀를 기다리고 있슴다.$K\n"
.stringn "$F3$P$FS아아, $w2예의 여자인가.$w4\n"
.stringn "그럼 $w2잘된 거냐?$K\n"
.stringn "$F1$P당연하죠$MC!$MD$K$P시논씨가 골라 준\n"
.stringn "선물을 가지고 만나러 갔더니$w3\n"
.stringn "그 애가 $w2정말 기뻐했어요$MC…$MD$K$P게다가 실은 말이죠,$w2\n"
.stringn "곧 결혼하기로 했거든요.$K\n"
.stringn "$F3$P$FA그건 또$MC…$MD$w4\n"
.stringn "급전개구만.$K\n"
.stringn "$F1$P$FA그런데 그 애, $w2무슨\n"
.stringn "불치병에 걸린 것 같아서$K$P치료비로 쓸 골드를 지불하지 못하면$w2\n"
.stringn "여생이 며칠 남지 않았다고 해요.$K$P그래서, $w2지금은 제가\n"
.stringn "돈을 쓸 때라고 생각했기에$MC……$MD$K\n"
.stringn "$F3$P돈을 건네줬다고?$K\n"
.stringn "$F1$P$FS네, $w2있는 거 전부요.$K$P그랬더니 $w2그 액수가\n"
.stringn "치료비하고 딱 맞는다고 하지 뭡니까$MC!$MD$K$P이건 역시 운명이죠?$w4\n"
.stringn "여신님께서 $w3저와 그 애가 맺어지도록\n"
.stringn "도와주신 거라구요$MC!$MD$K$P$F3$P$MC……$MD그래서?$K\n"
.stringn "$F1$P이런 때지만$MC…$MD$w4\n"
.stringn "아니, $w2이런 때니까\n"
.stringn "바로 식을 올리기로 했슴다.$K$P$FA사실은 그 애가 오고 나서$w2\n"
.stringn "모두에게 성대하게 발표하려고\n"
.stringn "했는데$MC……$MD$K$P아직도 안 오네요.$w4\n"
.stringn "$MC……$MD걱정입니다.$K$P집에도 찾아가 봤는데,$w2\n"
.stringn "제가 $w2길을 잘못 든 건지\n"
.stringn "빈집들 뿐이었어요.$K$P$FS그래도 $w2괜찮습니다.$w4\n"
.stringn "그녀는 제가 이 군에 있다는 걸\n"
.stringn "알고 있으니까요.$K\n"
.stringn "$F3$P$MC…$MD가트리$MC……$MD$w4\n"
.stringn "너, $w2속은 거야.$K\n"
.stringn "$F1$P$FA네에$MC!?$MD$w4\n"
.stringn "그럴 리가 없지 않슴까$MC!?$MD$w5\n"
.stringn "그런 청순한 아이가$MC!$MD$K\n"
.stringn "$F3$P어떻게 여생이 며칠 안 남은 사람이$w2\n"
.stringn "거리를 어슬렁거리고 있냐?$K\n"
.stringn "$F1$P그, $w2그건$MC……$MD$w4\n"
.stringn "저를 만나기 위해서죠$MC!$MD$K\n"
.stringn "$F3$P그럼 $w2왜 안 나타나는데?$K\n"
.stringn "$F1$P그건$MC……$MD$w4 그건 말이죠$MC……$MD$K\n"
.stringn "$F3$P가트리$MC…$MD$K\n"
.stringn "$F1$P$FS$MC……$MD아하하하$MC…$MD$w4\n"
.stringn "$MC…$MD역시, $w2저$MC…$MD$K$P또 속은 거군요$MC…$MD$K\n"
.stringn "$F3$P$MC…$MD그 여자의 인상이라든가 $w2알려 줘 봐.$K\n"
.stringn "$F1$P$FA네?$w4 그치만$MC…$MD$K\n"
.stringn "$F3$P있는 돈을 전부 뜯어갔다니$w2\n"
.stringn "보통 악질이 아니잖냐.$K$P내가 붙잡아서\n"
.stringn "돈 되찾아 줄게.$K\n"
.stringn "$F1$P$MC……$MD$w4\n"
.stringn "$FS으~음, $w2역시 괜찮슴다.$w4\n"
.stringn "제가 준 돈이고요$MC……$MD$K\n"
.stringn "$F3$P괜찮은 거냐?$w4\n"
.stringn "그 여자, $w2지금쯤 널 비웃고 있을 텐데.$K\n"
.stringn "$F1$P뭐, $w2그 애는 웃는 얼굴이 귀여웠으니까요.$K\n"
.stringn "$F3$P$Fc하아$MC…$MD$w4$Fd 얼마나 더\n"
.stringn "속아야 직성이 풀릴 거냐, $w2넌?$K\n"
.stringn "$F1$P괜찮슴다$MC…$MD$w4\n"
.stringn "그게 제 $w2유일한 장점이니까요.$K\n"
.stringn "$F3$P$MC…$MD뭐, $w2이걸로\n"
.stringn "돈을 어디에 쓸지는 고민 안 해도 되겠구만.$K\n"
.stringn "$F1$P그렇네요, $w2그렇게 생각하면\n"
.stringn "오히려 다행임다$MC!$MD$K\n"
.stringn "$F3$P$MC…$MD나 참.$w4\n"
.stringn "술이나 마시지 않으면\n"
.stringn "못 해먹겠네.$K\n"
.stringn "$F1$P아, $w2그럼$MC!$MD$w4 저도 저도$MC!$MD$K$P$FA아$MC…$MD$w4 맞다 돈이 없었지$MC……$MD$w4\n"
.stringn "역시 전 됐슴다.$K\n"
.stringn "$F3$P이리 와.$w4\n"
.stringn "내가 한잔 사 줄게.$K\n"
.stringn "$F1$P엇, $w2정말요?$K\n"
.stringn "$F3$P그래.$K\n"
.stringn "$F1$P$FS$MC…$MD헤헤헤$K\n"
.stringn "$F3$P뭘 그렇게 웃냐?$K\n"
.stringn "$F1$P시논씨가 사 주는 술을 마실 수 있다니,$w3\n"
.stringn "오늘은 $w2운이 좋은 것 같아서요.$K\n"
.stringn "$F3$P$FS$MC……$MD뭐래.$w4\n"
.stringn "태평한 놈이구만.$K"
db 0
.align 4
//MYELL_CHINON_GATRIE_A

//0xA0D0
Text_A0B0:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_GATRIE|$F5$FCL_CHINON|$F3$P저기, $w2시논씨~이$MC!$MD$K\n"
.stringn "$F5$P지금은 바빠.$w4\n"
.stringn "나중에 오라고 말했잖아.$K\n"
.stringn "$F3$P무슨 일이 있더라도\n"
.stringn "바로 대답해 주셨으면 $w2하는 게 있슴다.$K\n"
.stringn "$F5$P안 돼.$K\n"
.stringn "$F3$P오늘 $w2술값도 제가 낼 테니까요.$K\n"
.stringn "$F5$P시끄러워.$K\n"
.stringn "$F3$P평소보다 비싼 술로 $w2마셔도 돼요.$K\n"
.stringn "$F5$P$MC…$MD안주는?$K\n"
.stringn "$F3$P비장의 훈제 고기$MC!$MD$w4\n"
.stringn "어떠$w2심까$MC!$MD$K\n"
.stringn "$F5$FD$F1$FS$F1$FCL_CHINON|$F1$P어쩔 수 없지.$w4\n"
.stringn "귀여운 동생 얼굴을 봐서라도$w4\n"
.stringn "잠깐 시간 좀 내 볼까.$K\n"
.stringn "$F3$P$FS이 은혜는 꼭 갚겠슴다$MC!$MD$K\n"
.stringn "$F1$P$FA그래서, $w2뭔데?$K\n"
.stringn "$F3$P뭐랄까, $w2이야아~\n"
.stringn "곤란해서 말이죠.$K\n"
.stringn "$F1$P뭐가?$K\n"
.stringn "$F3$P곤란하단 말이죠~\n"
.stringn "어떻게 할까나~$MC…$MD$w4\n"
.stringn "그렇게 듣고 싶으세요?$K\n"
.stringn "$F1$P켁,$w2 죽을 때까지 그러고 있어라.$K$F1$FD\n"
.stringn "$F3$P$FA자, $w2잠깐만요$MC!$MD$w4\n"
.stringn "기다려 주세요$MC!$MD$w4\n"
.stringn "지금부터 이야기할 거라고요$MC!!$MD$K\n"
.stringn "$F1$FCL_CHINON|$F1$P나 참.$w4\n"
.stringn "빨리 말해.$K\n"
.stringn "$F3$P$FS저$MC…$MD$w4\n"
.stringn "여, $w2여, $w2여자친구가 생겼슴다$MC!$MD$K\n"
.stringn "$F1$P호오?$w4 그것참\n"
.stringn "별난 여자도 다 있구만.$K\n"
.stringn "$F3$P저번에 $w2마을에 나갔을 때 $w2만났슴다$MC!$MD$w4\n"
.stringn "엄청 귀여운 아이임다$MC!$MD$w4\n"
.stringn "이번엔 정말로 운명의 빨간 실이라고요$MC!$MD$K\n"
.stringn "$F1$P$FS잘됐네.$w4\n"
.stringn "그렇구만, $w2뭔지 알겠다.$K$P그 여자에게 줄 선물을 $w3나한테\n"
.stringn "상담하고 싶은 거지?$K\n"
.stringn "$F3$P헤헤헤헤,$w3\n"
.stringn "어떤 게 좋슴까?$K\n"
.stringn "$F1$P그런 거라면 $w2맡겨 달라고.$w4\n"
.stringn "술 마시면서$w2\n"
.stringn "차근차근 가르쳐 주지.$K\n"
.stringn "$F3$P넵$MC!$MD$w4 스승님$MC!$MD$K"
db 0
.align 4
//MYELL_CHINON_GATRIE_B

//0x993C
Text_991C:
.stringn "$R背景会話|$B支援背景|$<$F5$Fh$F5$FCL_GATRIE|$F5$P$MC…$MD하아$K$w5\n"
.stringn "$F5$P$MC……$MD후우$MC…$MD$K$w5\n"
.stringn "$F5$P$Fd아니, 그래도$MC…$MD$w5\n"
.stringn "~~~$w4 역시 안 되겠어$MC!!$MD$K\n"
.stringn "$F4$FCL_CHINON|$F4$P야$MC!$MD$K\n"
.stringn "$F5$FD$F1$Fh$F1$FCL_GATRIE|$F1$P아?$K$Fd\n"
.stringn "$MC…$MD아, $w2시논씨.$K\n"
.stringn "$F4$P『$MC…$MD아, $w2시논씨』 같은 소리 하네.$w4\n"
.stringn "뭐야, $w2아까부터\n"
.stringn "정신 사납게.$K\n"
.stringn "$F1$P$MC……$MD아무것도 아님다.$K\n"
.stringn "$F4$P아, $w2그러셔.$w4\n"
.stringn "그럼 난 간다.$K$F4$FD\n"
.stringn "$F1$P기, $w2기다려 주세요$MC!$MD$w4 거짓말이라구요$MC!$MD$w4\n"
.stringn "심술부리지 말고\n"
.stringn "상담해 주세요~$MC!!$MD$K\n"
.stringn "$F3$FCL_CHINON|$F3$P오늘 술값은 $w2네가 내는 거다?$K\n"
.stringn "$F1$P으으$MC…$MD$w4 알겠습니다.$K\n"
.stringn "$F3$P$FS좋~아.$w4\n"
.stringn "그럼 얘기해 봐.$K\n"
.stringn "$F1$P이번 보수를 어디에 쓸지 $w2말인데요$MC…$MD$w4\n"
.stringn "어떻게 할지 망설여집니다.$K\n"
.stringn "$F3$P$FA그런 건 사람마다 제각각이지.$w4\n"
.stringn "마음대로 쓰면 되잖아.$K\n"
.stringn "$F1$P마음대로 쓰고 나면$w3\n"
.stringn "시논씨가\n"
.stringn "일일이 트집을 잡지 않습니까$MC!$MD$K\n"
.stringn "$F3$P내가?$w4\n"
.stringn "언제?$K\n"
.stringn "$F1$P지난번에 산 『궁극의 방패』 때도$MC…$MD$K\n"
.stringn "$F3$P아아, $w2그 요새 대문에서?$w4\n"
.stringn "위병이 너를 도둑으로 봤었지.$w4\n"
.stringn "제대로 돌려놨냐?$K\n"
.stringn "$F1$P몸에 뿌리기만 해도\n"
.stringn "움직임이 빨라지는 비약$w3\n"
.stringn "『대시 한 방$MC!$MD』 때도$MC…$MD$K\n"
.stringn "$F3$P그 썩은 육즙?$w4\n"
.stringn "너, $w2냄새 확인도 안 하고\n"
.stringn "자기 몸에 끼얹었지?$K\n"
.stringn "$F1$P저, $w2그걸로 조금은\n"
.stringn "움직임이 빨라졌거든요$MC!$MD$K\n"
.stringn "$F3$P들개 30마리한테\n"
.stringn "쫓기면서 말이지.$K\n"
.stringn "$F1$P보세요$MC!$MD$w4 트집 잡기만 하잖아요$MC!!$MD$K\n"
.stringn "$F3$P아, $w2그거 때문에 상처 준 거구만, $w2내가.$w4\n"
.stringn "사실대로 알려 주고\n"
.stringn "불평하지 않으면 $w2성에 안 차긴 하지.$K\n"
.stringn "$F1$P$MC!!$MD$w4 저, 전\n"
.stringn "그렇게까지 말할 생각은$MC…$MD$w4\n"
.stringn "저기$MC…$MD$w4 죄송합니다$MC…$MD$K\n"
.stringn "$F3$P$FS너의 그 솔직한 점,$w2\n"
.stringn "나는 제법 $w2마음에 들어.$K\n"
.stringn "$F1$P$FS헤헤헤,$w2 수줍어하시기는.$K\n"
.stringn "$F3$P좋아, $w2마시러 가자고$MC!$MD$w4\n"
.stringn "네 돈을 유용하게 쓰고 싶다며.$K$F3$FD\n"
.stringn "$F1$P$FA엇, $w2아니, $w2잠깐만요\n"
.stringn "시논씨$MC!$MD$w4\n"
.stringn "그건 $w2뭔가 다르잖아요$MC!!$MD$K"
db 0
.align 4
//MYELL_CHINON_GATRIE_C

//0xBA38
Text_BA18:
.stringn "$R背景会話|$B支援背景|$<$F0$FCL_CHINON|$F3$FS$F3$FCL_JANAFF|$F3$P오, $w2있다.$K\n"
.stringn "$F0$P$MC………$MD$K\n"
.stringn "$F3$P너,$w2\n"
.stringn "시논이라고 했었지?$w4\n"
.stringn "잠깐 얘기 좀 할까?$K\n"
.stringn "$F0$P$MC…$MD뭐어?$K\n"
.stringn "신분 높은 반수분께서\n"
.stringn "일부러 지명해 주시다니$w2\n"
.stringn "살다 보니 $w2별일이 다 있구만.$K\n"
.stringn "$F3$P기어오르지 마.$w4\n"
.stringn "지난번에는, 미안했다.$K\n"
.stringn "$F0$P$MC………$MD$K\n"
.stringn "$F3$P나는 $w2베오크를\n"
.stringn "오해하고 있었던 것 같아.$K$P살육을 좋아하는 야만적인 종족이라고,$w2\n"
.stringn "우리들 라구즈와는\n"
.stringn "서로 이해할 수 없는 존재라고 말이지.$K\n"
.stringn "$F0$P$MC…$MD그런 것치고는$w2\n"
.stringn "아이크 쪽이랑 잘 어울리시던데.$w4\n"
.stringn "주인의 명령이라서 그런 거냐?$K\n"
.stringn "$F3$P$FA아냐. $w4우리하고 왕의 관계는\n"
.stringn "그렇게 일방적이지 않아.$K$P우린 왕의 의견이 잘못되었다고 여기면\n"
.stringn "절대로 명령을 듣지 않거든.$K\n"
.stringn "$F0$P그럼 $w2어째선데?$K\n"
.stringn "$F3$P$FS그 녀석은 $w2셀리노스의 동료를 구해줬어.$K$P은혜에는 은혜로$MC…$MD$w4\n"
.stringn "뤼시온 왕자의 호위로서\n"
.stringn "이 군에 가담했지만,$K$P나 스스로도 $w2그 녀석을 신뢰하고 있지.$K\n"
.stringn "$F0$P$MC……$MD마음에 안 들어.$K\n"
.stringn "$F3$P$FA응?$K\n"
.stringn "$F0$P나는 $w2옛날부터 아이크가 싫었거든.$w4\n"
.stringn "그놈은 $w2뭐든지 가지고 있어.$w4\n"
.stringn "$MC…$MD그리고 그게 당연하다고 생각하고 있지.$K\n"
.stringn "$F3$P하지만 $w2그건\n"
.stringn "그 녀석 잘못이 아니잖아?$K\n"
.stringn "$F0$P알아.$w4\n"
.stringn "하지만 $w2열받는 것도\n"
.stringn "내 자유란 거지.$K\n"
.stringn "$F3$P$FS그건 그렇지만.$K\n"
.stringn "$F0$P$MC……$MD그건 그렇고$w2\n"
.stringn "내가 왜\n"
.stringn "너랑 이런 얘기를 하고 있냐.$K\n"
.stringn "$F3$P$MC…$MD어쩌다 보니?$w4\n"
.stringn "너, $w2젊었을 때의 나랑\n"
.stringn "비슷한 느낌이 들어.$K\n"
.stringn "$F0$P뭐어?$K\n"
.stringn "$F3$P나도 날개가 다 자랄 때까지는\n"
.stringn "심술쟁이었거든.$w4\n"
.stringn "이것도 저것도 다 마음에 안 들었지.$K\n"
.stringn "$F0$P$MC……$MD너, $w2몇 살인데?$K\n"
.stringn "$F3$P$FA110살 조금 넘었나.$K\n"
.stringn "$F0$P$MC…$MD우리랑 나이 세는 법이$w2\n"
.stringn "다르기라도 한 거냐?$K\n"
.stringn "$F3$P봄, $w2여름, $w2가을, $w2겨울로 1년이라는 건\n"
.stringn "라구즈나 베오크나 마찬가지잖아.$K\n"
.stringn "$F0$P$MC……$MD내가 27살이니까$MC…$MD$w4\n"
.stringn "나보다 최소\n"
.stringn "85살$MC…$MD$w4 정도는 연상인 $w2건가?$K\n"
.stringn "$F3$P그래, $w2우러러보라고.$w4\n"
.stringn "애송아.$K$P$FS앞으로 무슨 일이 생기면$w2\n"
.stringn "나한테 의지하도록 해.$w4\n"
.stringn "연상만이 할 수 있는 조언들을 해 줄 테니까.$K$F3$FD\n"
.stringn "$F0$P$MC…$MD야, $w2야$MC!$MD$w4\n"
.stringn "잠깐 기다려$MC!$MD$w4\n"
.stringn "너희들 대체 수명이$MC…$MD$K"
db 0
.align 4
//MYELL_CHINON_JANAFF_A

//0xB564
Text_B544:
.stringn "$R背景会話|$B支援背景|$<$F4$FCL_JANAFF|$F0$FCL_CHINON|$F0$P오, $w2또 만났구만.$w4\n"
.stringn "꼬맹이 반수 놈.$K\n"
.stringn "$F4$P뻔뻔하게 말 걸지 마시지.$w4\n"
.stringn "애송이 인간 자식.$K\n"
.stringn "$F0$P너, $w2페니키스 왕의 측근이라면서?$w4\n"
.stringn "체격은 왜소한 주제에 $w2팔자가 좋은데?$K\n"
.stringn "$F4$P너는 베오크 대장과 오래 지낸 사이라던데.$w4\n"
.stringn "용병단 동료들을 배신하고 데인에 붙었다가,$w2\n"
.stringn "거기서 또 배신하고 크리미아에 붙었다며?$K\n"
.stringn "$F0$P그게 뭐 어때서?$w4\n"
.stringn "비겁하다고 말하고 싶은 거냐?$K$P공교롭게도 $w2나는 완전 용병 체질이거든.$w4\n"
.stringn "동료 같은 거에 얽매일 생각은 없어.$K\n"
.stringn "$F4$P동료도 안 두고, $w2주인도 따로 없고$MC…$MD$w4\n"
.stringn "넌 $w2대체\n"
.stringn "뭐 때문에 싸우는 거냐?$K\n"
.stringn "$F0$P$MC……$MD살기 위해서지.$w4\n"
.stringn "누구라도 그렇잖아.$K$P그게 아니라면,$w2\n"
.stringn "누가 좋아서 서로 죽이고 있겠냐고$MC…$MD$K\n"
.stringn "$F4$P너$MC…$MD$K\n"
.stringn "$F0$P왜?$K\n"
.stringn "$F4$P넌 $w2살육이 싫은 거야?$K\n"
.stringn "$F0$P좋아하는 놈이 $w2있겠냐?$K\n"
.stringn "$F4$P$MC…$MD인간은 $w2살육을 좋아하는 종족이잖아?$w4\n"
.stringn "그래서 무기를 만들고,$w4\n"
.stringn "먹지도 않는 동물을 사냥하지.$K\n"
.stringn "$F0$P웃기지 마$MC!$MD$w4\n"
.stringn "무기를 만드는 건, $w2너희들\n"
.stringn "반수로부터 몸을 지키기 위해서다$MC!$MD$K$P사냥을 취미로 삼고 있는 건$w2\n"
.stringn "시간이 썩어 남아도는 귀족들뿐이라고$MC!!$MD$K\n"
.stringn "$F4$P$MC………$MD$K\n"
.stringn "$F0$P켁$w2\n"
.stringn "기분 더럽네.$K$F0$FD\n"
.stringn "$F4$P야$MC!$MD$w4\n"
.stringn "아직 얘기가$MC……$MD$w4\n"
.stringn "칫,$w2 어떻게 된 거야.$K"
db 0
.align 4
//MYELL_CHINON_JANAFF_B

//0xB22C
Text_B20C:
.stringn "$R背景会話|$B支援背景|$<$F0$FCL_JANAFF|$F0$P이봐$MC!$MD$w4\n"
.stringn "거기 있는 놈, $w2멈춰$MC!$MD$K\n"
.stringn "$F6$FCL_CHINON|$F6$P$MC……$MD$K$F6$FD\n"
.stringn "$F0$P야, $w2듣고 있냐?$K\n"
.stringn "$F4$FCL_CHINON|$F4$P음?$w4\n"
.stringn "뭐냐 $w2넌?$K\n"
.stringn "$F0$P그건 내가 할 말이야.$w4\n"
.stringn "너, $w2이 군에서는 본 적 없는데.$K$P$MC…$MD신입인가?$w4 이름은?$w4\n"
.stringn "어느 부대 소속이야?$K\n"
.stringn "$F4$P$MC……$MD반수 꼬맹이한테\n"
.stringn "대답할 이유는 없어.$K\n"
.stringn "$F0$P뭐라고, $w2이 자식$MC!?$MD$K\n"
.stringn "$F4$P어이쿠.$w4$FS\n"
.stringn "날 그런 태도로 대하다간\n"
.stringn "나중에 곤란해질걸?$K\n"
.stringn "$F0$P$FS너야말로$w2\n"
.stringn "내가 누군지 알고 나서\n"
.stringn "후회해도 늦을 텐데?$K\n"
.stringn "$F4$P$FA$MC………$MD$K\n"
.stringn "$F0$P$FA$MC………$MD$K\n"
.stringn "$F4$P$MC…$MD켁$w2\n"
.stringn "오늘은 봐주지.$K\n"
.stringn "$F0$P웃기지 마, $w2인간$MC!$MD$K$P잘 들어, $w2내가\n"
.stringn "널 봐주는 거야.$w4\n"
.stringn "착각하지 마라$MC!!$MD$K"
db 0
.align 4
//MYELL_CHINON_JANAFF_C

//0xC9C4
Text_C9A4:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_CHINON|$F6$FCL_LOFA2|$F1$P어~이, $w3이제 그만\n"
.stringn "기분 풀어.$w4 나 참.$K\n"
.stringn "$F6$P$MC……$MD$K\n"
.stringn "$F1$P그러니까, 나는$w2\n"
.stringn "널 위해서 그런 거라고.$w4\n"
.stringn "알잖아 $w2그 정도는.$K\n"
.stringn "$F6$P$MC……$MD$K\n"
.stringn "$F1$P칫$w4\n"
.stringn "고집불통 꼬맹이구만.$K$P계속 그러고 있으면$w2\n"
.stringn "나 이제 갈 거다?$w4\n"
.stringn "괜찮지?$K\n"
.stringn "$F6$P$MC……$MD그치만$MC…$MD$w4\n"
.stringn "시논씨가 $w2내가 만든 활$MC…$MD$w4\n"
.stringn "$MC………………$MD버렸잖아.$K\n"
.stringn "$F1$P야, $w3그런 걸 들고\n"
.stringn "전장에 나가 봐라.$w4\n"
.stringn "한 방에 당할걸.$K$P그걸 미리 막아 준 거잖아.$w4\n"
.stringn "말하자면 생명의 은인인 거지.$w3\n"
.stringn "오히려 감사해야 할 판이라고.$K\n"
.stringn "$F6$FD$F3$FCL_LOFA|$F3$P$MC………$MD그건 그렇지만.$K$P그치만$MC…$MD$w2 시논씨를\n"
.stringn "기쁘게 해 주고 싶어서$MC…$MD$w4\n"
.stringn "정성을 들여서 만든 건데.$K$P나$MC…$MD$w2 처음 싸울 때,$w3\n"
.stringn "너무 무서워서 $w2다리가$MC…$MD$w2 떨렸지만$MC……$MD$K$P시논씨가 준 활을\n"
.stringn "꽉$w2 쥐니까$MC…$MD$w4 용기가 났어.$K\n"
.stringn "난 할 수 있어, $w3실패하지 않을 거야, 라고.$K$P왜냐면 시논씨가$w2\n"
.stringn "가르쳐 줬으니까.$K$P그러니까 지금까지 $w2살아남아서\n"
.stringn "이거였구나$MC…$MD$w3 했으니까$MC……$MD$K\n"
.stringn "$F1$P$MC……$MD$w4\n"
.stringn "뭘 그렇게까지$MC…$MD$w3\n"
.stringn "나 같은 놈한테 기대고 있냐.$K$P네게 활을 가르친 것도,$w2\n"
.stringn "활을 만들어 준 것도$w3\n"
.stringn "그냥 한가해서 그런 것뿐이야.$K\n"
.stringn "$F3$P$FS그래도, $w2기뻤어.$K$FA$P다른 형들은$MC…$MD$w3\n"
.stringn "내가 아직 어린애라고$w2\n"
.stringn "아무것도 시키지 않았거든.$K$P시논씨가 활을 안 알려 줬다면$MC…$MD$w3\n"
.stringn "지금도 계속 뒤에서 기다리고만 있었을 거야.$K$P모두가 목숨을 걸고 싸우고 있는데$MC…$MD$w3\n"
.stringn "그걸 가만히$MC…$MD$w2 기다렸겠지.$w4\n"
.stringn "어제는 살아 돌아왔어.$K$P하지만$MC…$MD$w2 오늘은?$w4 내일은?$w4\n"
.stringn "불안에 짓눌리면서$w2\n"
.stringn "그저 기다릴 수밖에 없었어.$K\n"
.stringn "$F1$P$MC……$MD어떻게 생각하든\n"
.stringn "네 마음이지만 말이야.$K$P어른들은$MC…$MD$w3 가능하면\n"
.stringn "꼬맹이들을 전장에 내보내려고 하지 않아.$K$P어지간히 정신 나간 놈이 아니라면$w3\n"
.stringn "다른 사람의 죽음에 관여하려고도 안 하지.$K$P그게 꼬맹이라면$MC…$MD$w4\n"
.stringn "더더욱.$K$P이건 꼬맹이들을 위해서라기보단,$w3\n"
.stringn "어른 쪽의 자부심이야.$K$P자신들의 죄책감을 $w2조금이라도\n"
.stringn "줄이려고 항상$w2\n"
.stringn "머리를 $w2쥐어짜고 있지.$K$P사람은$MC…$MD$w2 타인의 고통을 느낄 수 있는 생물이야.$w4\n"
.stringn "그걸 무의식적으로 무시하려고 해도$MC…$MD$w4\n"
.stringn "눈치채고 나면$MC…$MD$w3 괴롭지.$K\n"
.stringn "$F3$P$MC……$MD어려워.$K\n"
.stringn "$F1$P$MC…$MD그래.$w4\n"
.stringn "뭐, $w2어쨌든.$K$P나도 어른의 자부심이라는 게$w3\n"
.stringn "구역질 날 정도로 싫거든.$K$P어린애들도 훌륭하게 잘 살 수 있어.$w4\n"
.stringn "살아남는 법은$w2\n"
.stringn "빨리 터득할수록 좋지.$K\n"
.stringn "$F3$P$FS그래서 나한테\n"
.stringn "활을 알려 준 거구나?$w4\n"
.stringn "한가했던 게 아니라$MC…$MD$K\n"
.stringn "$F1$P$MC……$MD$w4 칫$w5\n"
.stringn "마음대로 생각하셔.$K$FS$Fc$P그래도 뭐, $Fd그걸로 기분이 나아졌다면$MC…$MD$w2\n"
.stringn "상관없나.$K"
db 0
.align 4
//MYELL_CHINON_LOFA_A

//0xC6D8
Text_C6B8:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_LOFA|$F3$FCL_CHINON|$F1$P봐봐, $w2시논씨$MC!$MD$w4\n"
.stringn "이건 $w2제대로 만든 활 같지?$K\n"
.stringn "$F3$P일단 『활』이라고 할 순 있겠네.$K\n"
.stringn "$F1$P그럼, $w2시논씨가 써$MC…$MD$K\n"
.stringn "$F3$P싫거든$MC!$MD$w4\n"
.stringn "난 $w2아직 죽고 싶지 않아.$K\n"
.stringn "$F1$P$FA흥!$w3\n"
.stringn "$MC…$MD됐어.$w4\n"
.stringn "내가 $w2쓸 거야 그럼.$K$F1$FD\n"
.stringn "$F3$P$MC……$MD잠깐$MC!$MD$K\n"
.stringn "$F1$FCL_LOFA|$F1$P왜?$K\n"
.stringn "$F3$P$MC…$MD그 활 $w3이리 줘 봐.$K\n"
.stringn "$F1$P$FS역시 갖고 싶어졌지?$K\n"
.stringn "$F3$P그래.$w4\n"
.stringn "갑자기 엄청 갖고 싶어졌어.$K\n"
.stringn "$F1$P와~!$w4\n"
.stringn "그럼, $w2여기$MC!$MD$K\n"
.stringn "$F3$P고맙다.$K$P그럼 이만.$K$F3$FD\n"
.stringn "$F1$P$MC……$MD내가 만든 활을\n"
.stringn "시논씨가 쓰면$w3\n"
.stringn "어떤 식을 보일까~$K$P신경 쓰이는걸~$MC…$MD$w4$MC……$MD\n"
.stringn "$MC………$MD따라가 봐야지.$w4\n"
.stringn "에헤헤$K"
db 0
.align 4
//MYELL_CHINON_LOFA_B

//0xC218
Text_C1F8:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_LOFA|$F1$P시논씨$MC!$MD$w4 잠깐 잠깐$MC!$MD$K\n"
.stringn "$F3$FCL_CHINON|$F3$P음?$w4\n"
.stringn "왜, $w2요파.$K\n"
.stringn "$F1$P에헤헤$MC…$MD$w4 여기$MC!$MD$K\n"
.stringn "$F3$P뭐야 $w2이건?$w4\n"
.stringn "엄청 휘어지고 $w2뒤틀린 막대기잖아$MC……$MD$K\n"
.stringn "$F1$P$FA활이야$MC!$MD$K$FS$P언젠가 시논씨랑 만나면$w3\n"
.stringn "꼭 갚으려고 $w2생각했거든.$w4\n"
.stringn "그래서 조금씩 만들고 있었어.$K$P모양은 별로지만$w2\n"
.stringn "열심히 만들었으니까 써 줘$MC!$MD$K\n"
.stringn "$F3$P$MC……$MD백번 양보해서 $w3이게\n"
.stringn "활이라고 $w2치자.$K$P이렇게 약한 건 $w2한 번 쓰면\n"
.stringn "부숴질 게 뻔하다고.$w4\n"
.stringn "나보고 그렇게 $w2전장에서 무방비하게 있으란 거냐?$K\n"
.stringn "$F1$P$FA아, $w2아니야$MC!$MD$K\n"
.stringn "$F3$P애초에$w3\n"
.stringn "선택한 나무부터 잘못됐어.$w4\n"
.stringn "이런 딱딱한 나무로는 안 되지.$K$P내가 널 위해 만들어 준 활은$w2\n"
.stringn "이런 게 아니었잖아?$K\n"
.stringn "$F1$P제대로 연구했어.$w4\n"
.stringn "똑같이 생겼잖아$MC!$MD$K\n"
.stringn "$F3$P하나도 안 똑같거든.$K\n"
.stringn "$F1$P윽$MC…$MD$K\n"
.stringn "$F3$P칫,$w3 어쩔 수 없지.$w4\n"
.stringn "다음에 $w2좀 가르쳐 줄게.$K\n"
.stringn "$F1$P$FS정말$MC!?$MD$w4\n"
.stringn "완전 $w2좋아$MC!$MD$w3\n"
.stringn "약속했으니까 $w3꼭 지켜야 돼?$K\n"
.stringn "$F3$P그래, $w3알았으니까$w4\n"
.stringn "그렇게 강아지마냥$w2\n"
.stringn "착 달라붙지 좀 마, $w4$FS나 참.$K"
db 0
.align 4
//MYELL_CHINON_LOFA_C

//0xD420
Text_D400:
.stringn ""
db 0
.align 4
//MYELL_CHINON_MIST_A

//0xD41C
Text_D3FC:
.stringn ""
db 0
.align 4
//MYELL_CHINON_MIST_B

//0xD418
Text_D3F8:
.stringn ""
db 0
.align 4
//MYELL_CHINON_MIST_C

//0xDC1C
Text_DBFC:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_LARGO|$F3$P다라하우, $w2잠깐 괜찮을까?$K\n"
.stringn "$F1$FS$F1$FCL_DALAHOWE|$F1$P물론 $w2전혀 상관없어~$K\n"
.stringn "$F3$P그때는 $w2겁이 나서\n"
.stringn "도망쳤지만$MC……$MD$w4\n"
.stringn "정말 미안했어, 다라하우.$K$P말도 안 되는 짓을 해 버렸어,$w2\n"
.stringn "어떻게 용서를 빌지 쭉 생각해 봤는데$MC…$MD$w2\n"
.stringn "사과하는 것밖에 생각이 안 나.$K\n"
.stringn "미안해, $w2다라하우$MC……$MD$w3 우하라다도.$K\n"
.stringn "$F1$P아아~ 그렇게나 신경 써 준 거야~?$w4\n"
.stringn "미안해 라르고, $w2우하라다는 괜찮아$MC!$MD$K\n"
.stringn "$F3$P저, $w2정말이야$MC!?$MD$K\n"
.stringn "$F1$P우하라다는 언제나 다라하우의 친구$MC!$MD$w4\n"
.stringn "친구는 언제든지 곁에 있어야지~$MC!$MD$K$P그러니까 이렇게 종이에 그려서$MC…$MD$w3\n"
.stringn "$Fc중얼중얼중얼중얼~$K$P$Fd짜~잔, $w2우하라다야$MC!$MD$K\n"
.stringn "$F7$FCDUMMY|$F7$P오랜만이야, $w2라르고.$K\n"
.stringn "$F3$P$FS오오$MC!$MD$w4 정말이네$MC!$MD$K\n"
.stringn "$FA미안해 우하라다~$MC!!$MD$w4\n"
.stringn "내가 그만 화를 내는 바람에\n"
.stringn "널 아프게$MC……$MD$K\n"
.stringn "$F7$P괜찮아 라르고.$K\n"
.stringn "$F1$P그래그래, $w2괜찮아 라르고~$MC!$MD$w4\n"
.stringn "라르고는 다라하우의 친구니까$w2\n"
.stringn "우하라다랑도 친구잖아~$MC!$MD$K\n"
.stringn "친구끼리 그런 거 신경 쓰지 마~$MC!$MD$K\n"
.stringn "$F3$P$FS다행이다$MC……$MD$w2 둘 다 고마워$MC!$MD$w4\n"
.stringn "너희들 좋은 녀석들이구나$MC!$MD$w4 와하하하하$MC!$MD$K\n"
.stringn "$F1$P아냐아냐~ $w2라르고가 제일 착한 사람이야~$w4\n"
.stringn "상냥한 라르고를 $w3다라하우는 무척 좋아해~$w4\n"
.stringn "앞으로도 잘 부탁해, $w2라르고~$MC!$MD$K\n"
.stringn "$F3$P그래, $w2물론이지$MC!$MD$K"
db 0
.align 4
//MYELL_DALAHOWE_LARGO_A

//0xD7E8
Text_D7C8:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_LARGO|$F1$P좋아, $w2오늘도 힘내 볼까$MC!$MD$K$P$FA응?$w4 이건$MC……$MD$w4\n"
.stringn "다라하우의 친구인 $w2우하라다잖아.$w4\n"
.stringn "이런 데 떨어져 있어도 되는 거야?$K\n"
.stringn "이봐, $w2괜찮아?$K\n"
.stringn "$F7$FCDUMMY|$F7$P$MC…………$MD$K\n"
.stringn "$F1$P$MC……$MD역시나.$w4\n"
.stringn "이런 종이 쪼가리랑 대화할 수 있을 리 없나.$K$P$MC…………$MD좀 열받는데$MC……$MD$w3\n"
.stringn "돌돌 말아서 버려야지$MC!$MD$K\n"
.stringn "$F7$P아, $w2아$MC……$MD$w3파$MC……$MD$K\n"
.stringn "$F1$P$MC!$MD$MC!?$MD$K$P자, 잠깐$MC!$MD$w4 진짜냐$MC!?$MD$w4\n"
.stringn "지금 분명히 목소리가$MC…………$MD$w3\n"
.stringn "미안해, 괜찮아 $w2우하라다$MC!?$MD$K\n"
.stringn "$F7$P$MC……………………$MD$K\n"
.stringn "$F1$P이럴 수가$MC……$MD$w4\n"
.stringn "난 $w2대체 무슨 짓을$MC……$MD$K\n"
.stringn "$F3$FS$F3$FCL_DALAHOWE|$F3$P라르고~$MC!$MD$w4\n"
.stringn "거기서 뭐 해~?$K\n"
.stringn "$F1$P우와앗$MC!!$MD$w4\n"
.stringn "요, $w2용서해 줘~$MC!!$MD$K$F1$FD\n"
.stringn "$F3$P$FA$MC……$MD도망가 버렸네~$w4\n"
.stringn "미안해 라르고~ $w2나쁜 건\n"
.stringn "깜빡 소재를 떨어뜨려 버린 다라하우야~$K$P하지만 일족의 비기니까$w2\n"
.stringn "절대로 들키면 안 되거든~$MC…$MD$w4\n"
.stringn "죄책감이 드는걸~ $MC……$MD$w3하아.$K"
db 0
.align 4
//MYELL_DALAHOWE_LARGO_B

//0xD424
Text_D404:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_DALAHOWE|$F1$P지금부터 비장의 재주를 보여 줄 거야~$MC!$MD$w4\n"
.stringn "모두 보러 와~ $w2보고 가는 거야~$MC!$MD$K\n"
.stringn "$F3$FS$F3$FCL_LARGO|$F3$P오, $w2거리 공연이냐. $w4재밌겠는데.$w4\n"
.stringn "구경꾼은 나밖에 없는 것 같은데,$w2\n"
.stringn "하나 부탁해도 되냐?$K\n"
.stringn "$F1$P물론이지~$MC!$MD$w4\n"
.stringn "양피지에 이렇게 그림을 그려서~$MC…$MD$w4\n"
.stringn "$Fc중얼중얼중얼중얼~$K$P$Fd여~기, $w2다 됐다$MC!$MD$w4\n"
.stringn "이 애는 다라하우의 친구인$w2\n"
.stringn "우하라다야~$K\n"
.stringn "$F3$P$FA우하라다?$w4\n"
.stringn "이건 그냥 낙서잖아.$K\n"
.stringn "$F1$P아니야~$w4\n"
.stringn "자, $w2귀를 기울여 봐~$K\n"
.stringn "$F3$P귀를?$K\n"
.stringn "$F7$FCDUMMY|$F7$P안녕.$K\n"
.stringn "$F3$P오오$MC!?$MD$w4 뭐, $w2뭐야?$K\n"
.stringn "넌 말하지 않았는데$w2\n"
.stringn "지금 어디선가 소리가 났어.$w4\n"
.stringn "대체 $w2어떻게 된 거지?$K\n"
.stringn "$F1$P이 우하라다가 말하고 있는 거야~$w4\n"
.stringn "우하라다, $w2인사~$MC!$MD$K\n"
.stringn "$F7$P안녕 라르고.$K\n"
.stringn "$F3$P$FS와하하하하$MC!$MD$w4 대단한데$MC!$MD$w4\n"
.stringn "또 다른 건 없어?$K\n"
.stringn "$F1$P물론 있지~$MC!$MD$w4\n"
.stringn "자~ 다음은$MC…………$MD$K"
db 0
.align 4
//MYELL_DALAHOWE_LARGO_C

