//0xE900
Text_E8E0:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_NEPENEE|$F3$P다라하우씨.$K\n"
.stringn "$F1$FS$F1$FCL_DALAHOWE|$F1$P어라, $w2네페니가 먼저\n"
.stringn "말을 걸어오다니 별일도 다 있네~$w4\n"
.stringn "다라하우 $w2기뻐~$K\n"
.stringn "$F3$P$MC……$MD다라하우씨는, $w2언제나 웃는 얼굴이네유$MC…$MD$K$P싸움이라든가$MC……$MD 힘들지 않나유?$w4\n"
.stringn "$FS지는 $w2가끔씩$MC……$MD$w3\n"
.stringn "울고 싶어지기도$MC…$MD 하는디$MC……$MD$K\n"
.stringn "$F1$P$FA$MC………………$MD$w5\n"
.stringn "으~음$MC……$MD$w3 그렇지~$MC…$MD$K$P확실히 싸우는 건 괴롭지만~$MC…$MD$w3\n"
.stringn "그런 말을 하는 네페니를 보는 게\n"
.stringn "다라하우는 더 괴로워~$MC…$MD$K\n"
.stringn "$F3$P$FA다라하우씨$MC……$MD$K\n"
.stringn "$F1$P$FS다라하우, $w2사람의 웃는 얼굴을 정말 좋아해~$w4\n"
.stringn "그래서 $w2다라하우도 웃는 거야~$K$P$FA하지만, 괴로운데도 웃는 얼굴은 슬프지~$K$P다라하우가 말했으니까$w2\n"
.stringn "네페니도 $w2열심히 웃어 주고 있는데\n"
.stringn "힘들어 보여~$K$P전에 말한 $w2죽은 아이를\n"
.stringn "떠올리게 돼~$MC…$MD$K$P미안해, $w2네페니. $w4힘든 일을\n"
.stringn "시킨 모양이네~$K\n"
.stringn "$F3$P죄송해유, $w2저$MC……$MD$w3\n"
.stringn "마을 밖 사람들과 $w2얘기하는 게 힘들어서$MC…$MD$w4\n"
.stringn "사이좋은 사람도 별로 없거든유$MC……$MD$K\n"
.stringn "$F1$P그랬구나~$MC…$MD$K\n"
.stringn "$F3$P하지만 $w2저$MC……$MD$w2 너무 안 좋은 일들만\n"
.stringn "생각한 것 같아유$MC……$MD$K$P$FS다라하우씨처럼 $w2잔뜩 웃으면$MC…$MD$w3\n"
.stringn "좋은 생각들을 할 수 $w2있게 될까유$MC……?$MD$K\n"
.stringn "$F1$P$FS그야 당연하지~$MC!$MD$w4\n"
.stringn "웃는 얼굴은 웃는 사람도, $w2보는 상대도 구하거든~$MC!$MD$K\n"
.stringn "$F3$P$MC……$MD응, $w2그렇지유$MC……$MD$w4\n"
.stringn "다라하우씨의 웃는 얼굴은 $w2엄청 좋습니데이$MC……$MD$w4\n"
.stringn "고마워유, $w2다라하우씨$MC……$MD$K"
db 0
.align 4
//MYELL_DALAHOWE_NEPENEE_A

//0xE468
Text_E448:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_DALAHOWE|$F3$FCL_NEPENEE|$F1$P네페니,$w2\n"
.stringn "할 얘기가 있는데~$K\n"
.stringn "$F3$P다라하우씨$MC……$MD$w4\n"
.stringn "할 얘기가 뭔, $w2가요$MC……?$MD$K\n"
.stringn "$F1$P역시 얼굴이 무서워~$w2\n"
.stringn "좀 더 웃는 게 어때~?$K$P의미없이 웃어도 된다고\n"
.stringn "다라하우가 지난번에 알려 줬잖아~?$K\n"
.stringn "$F3$P그치만$MC……$MD$w4\n"
.stringn "어려워$MC…$MD서$MC…$MD$K\n"
.stringn "$F1$P어렵다고?$w4 왜~?$w4\n"
.stringn "다라하우처럼\n"
.stringn "이렇게 웃기만 하면 되는 거야~$K\n"
.stringn "$F3$P즐겁지$MC…$MD 않아요$MC……$MD$w4\n"
.stringn "웃어도$MC……$MD$K\n"
.stringn "$F1$P$MC…$MD$w2네페니\n"
.stringn "또 그런다~$w4\n"
.stringn "목소리도 작고, $w2수다도 안 떨고~$K\n"
.stringn "$F3$P$MC…………$MD$K\n"
.stringn "$F1$P다라하우가 들렀던 마을에 있지~$w2\n"
.stringn "네페니 같은 아이가 있었거든~$K$P그 아이, $w2다라하우에게\n"
.stringn "엄청 잘해 줬어~$K$P$FA하지만 $w2그 아이, $w2마을을 덮친\n"
.stringn "산적들에게 죽었다~$MC…$MD$K\n"
.stringn "$F3$P$MC!$MD$K\n"
.stringn "$F1$P그 아이는 혼자서만 깊게 생각하는\n"
.stringn "성격이었던 거지~$K$P모두랑 같이 가만히 숨어 있으면\n"
.stringn "됐을 텐데~$K$P다라하우가 다른 산적들과 싸우고 있는 사이에\n"
.stringn "나가 버렸던 것 같아.$K$P자기가 어떻게든 해야만 한다$w2고\n"
.stringn "생각했던 거겠지~$MC…$MD$K$P$FS그러니까 네페니는\n"
.stringn "좀 더 다른 사람들과 수다를 떨고$w2\n"
.stringn "웃어 줬으면 좋겠어~$K\n"
.stringn "$F3$P$MC…………$MD$K"
db 0
.align 4
//MYELL_DALAHOWE_NEPENEE_B

//0xE1A8
Text_E188:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_DALAHOWE|$F1$P잠깐 잠깐, 거기 있는 사람~$w4\n"
.stringn "다라하우 $w2할 얘기가 있어~$K\n"
.stringn "$F3$FCL_NEPENEE|$F3$P$MC……$MD뭔, $w2가요?$K\n"
.stringn "$F1$P다라하우 $w2언제나 생각해~$w3\n"
.stringn "너, $w2얼굴이 무서워~$K\n"
.stringn "$F3$P$MC………$MD그렇, $w2습니까?$K\n"
.stringn "$F1$P보고 있으면 무섭다고~$w4\n"
.stringn "잔뜩, $w2잔뜩\n"
.stringn "웃는 편이 좋아~$K$P너무 진지한 건, $w2좋지 않아~$w4\n"
.stringn "오래 못 살게 되니까~$K\n"
.stringn "$F3$P진지한 건$MC……$MD$w2\n"
.stringn "아니라, $w2고$MC…$MD 생각하는데.$K\n"
.stringn "$F1$P$FA그래~?$w4\n"
.stringn "$FS그나저나 $w2너, $w3이름이 뭐야~?$K\n"
.stringn "$F3$P네페니$MC……$MD$K\n"
.stringn "$F1$P다라하우$w2 이제부터$w3\n"
.stringn "네페니에게 웃는 법을 알려 줄게~$w4\n"
.stringn "사양 안 해도 돼~$K\n"
.stringn "$F3$P네에$MC……$MD$K"
db 0
.align 4
//MYELL_DALAHOWE_NEPENEE_C

//0xF680
Text_F660:
.stringn "$R背景会話|$B支援背景|$<$F3$Fh$F3$FCL_TOPUCK|$F3$P$MC……$MD후우$K\n"
.stringn "$F1$FS$F1$FCL_DALAHOWE|$F1$P안 돼 토팍~$w4\n"
.stringn "한숨을 쉬면 행복이 날아간다구~$K\n"
.stringn "$F3$P$Fd$MC……$MD다라하우구나.$K\n"
.stringn "$F1$P$FA어라$w4\n"
.stringn "오늘은 안 놀라네~ $w4조금 아쉬운걸~$K\n"
.stringn "$F3$P다라하우는 $w2좋겠다$MC……$MD$w4\n"
.stringn "창술사가 되기 위해 태어났다는 느낌이야.$w4\n"
.stringn "엄청 강하고~$MC…$MD$w4 하아아$MC…$MD$K\n"
.stringn "$F1$P토팍도 강하잖아~$K\n"
.stringn "$F3$P$MC……$MD겉치레는 됐어.$w4\n"
.stringn "나 스스로도 알고 있다구.$w4\n"
.stringn "마도는 $w2나랑 안 맞을지도 모른다는 걸$MC……$MD$K\n"
.stringn "$F1$P누구나 $w2정체기는 있는 법이야~$K\n"
.stringn "$F3$P$MC……$MD내 경우는$w2\n"
.stringn "그거랑 다르다는 느낌이 들어.$K\n"
.stringn "$F1$P하나를 습득하기 위해서는~$w3\n"
.stringn "언제나 끈기가 필요한 거야~$K$P앞만 보고 서두르면~$w3\n"
.stringn "소중한 것들을 못 보게 돼~$K\n"
.stringn "$F3$P소중한 것들이라니?$K\n"
.stringn "$F1$P$FS예를 들면, 처음으로 마법을\n"
.stringn "사용했을 때의 기분이라든가~$w4\n"
.stringn "어떤 기분이었는지 기억나~?$K\n"
.stringn "$F3$P어땠냐니$MC……$MD$w4\n"
.stringn "그야, $w2기뻤지.$K\n"
.stringn "$F1$P조금씩 실력이 늘어갈 때는$w2\n"
.stringn "어땠어~?$K\n"
.stringn "$F3$P기쁘고$MC……$MD$w2 즐거웠어.$K\n"
.stringn "$F1$P$MC……$MD왜 마법을 사용하게 돼서\n"
.stringn "기뻤던 건지 기억해 내 봐~$K\n"
.stringn "$F3$P$MC………$MD그야 강해졌다고 생각했으니까.$w4\n"
.stringn "$MC…$MD모두를 지킬 수 있는 힘을 가지게 돼서$w3\n"
.stringn "굉장히 $w2기뻤어$MC……$MD$K\n"
.stringn "$F1$P그 기분을 잊으면 안 돼~$w4\n"
.stringn "그것만 잘 기억한다면~$w2\n"
.stringn "토팍은 더 성장할 수 있어~$K\n"
.stringn "$F3$P$MC…………$MD$K$FS$P고마워, 다라하우$MC!$MD$w4\n"
.stringn "뭔가$MC…$MD$w4 너한테는 항상\n"
.stringn "중요한 걸 배우는 것 같아.$K\n"
.stringn "$F1$P신경 쓰지 마~$w4\n"
.stringn "아이를 이끌어 주는 건 어른의 의무니까~$K$P그리고 말이지~ $w4다라하우도\n"
.stringn "답례를 받고 있거든~$K\n"
.stringn "$F3$P답례?$K\n"
.stringn "$F1$P토팍의 해맑은 미소야~$w4\n"
.stringn "다라하우는 언제나~$w2\n"
.stringn "아이들의 웃는 얼굴을 위해서 싸우고 있지~$K"
