.stringn "$R背景会話|$B支援背景|$<$F3$FCL_TOPUCK|$F3$P아~ $w2이제 그만할래$MC!$MD$w4\n"
.stringn "이런 건 못 한다고$MC……$MD$K\n"
.stringn "$F4$FCL_DALAHOWE|$F4$P중간에 포기하는 건 좋지 않아~$K\n"
.stringn "$F3$FD$F1$FCL_TOPUCK|$F1$P와아악$MC!$MD$w4\n"
.stringn "어, $w2어느새$MC……$MD$MC!$MD$K\n"
.stringn "$F4$FD$F3$FCL_DALAHOWE|$F3$P아까부터 보고 있었어~$w4\n"
.stringn "토팍은 $w2상처 치료를\n"
.stringn "너무 대충해~$K\n"
.stringn "$F1$P어쩔 수 없잖아.$w4\n"
.stringn "상처약을 발라서 $w2천으로 누르려고 해도$w3\n"
.stringn "미끄러지기만 하고.$K$P누가 와서 $w2지팡이를 쓰는 편이$w3\n"
.stringn "빠르고 확실하게 나아서 좋아.$K\n"
.stringn "$F3$P바보$MC!$MD$K\n"
.stringn "$F1$P응$MC……?$MD$K\n"
.stringn "$F3$P바로 다른 사람한테 기대면 안 돼~$K$P자기가 할 수 있는 일은\n"
.stringn "스스로 할 수 있게 되지 못하면~$w3\n"
.stringn "전장에서는 살아남을 수 없어~$K$P곤란할 때는 $w2항상\n"
.stringn "누군가가 도와줄 수 있는 게 아니거든~$K\n"
.stringn "$F1$P$MC…$MD그렇구나.$w4$FS\n"
.stringn "역시 너는 $w2말솜씨가 좋아.$K\n"
.stringn "$F3$P$FS기본 중의 기본이지~$K$P자아, $w2천을 빌려줘 봐~$w3\n"
.stringn "잘 감는 법을 $w2가르쳐 줄게~$K\n"
.stringn "$F1$P그래$MC!$MD$K"
