Text_EED4:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_TOPUCK|$F1$P나 참, $w2여기로 집합하라고\n"
.stringn "들었는데$MC……$MD$w3 아직도 안 온 건가?$K\n"
.stringn "$F3$FS$F3$FCL_DALAHOWE|$F3$P기다리게 해서 미안해~$MC!$MD$K\n"
.stringn "$F1$P우와아앗$MC!!$MD$K\n"
.stringn "$F3$P우와아앗$MC!$MD$K$P이라니, $w2뭘 보고 그렇게 놀란 거야~?$K\n"
.stringn "$F1$P당연히 너지, $w2너$MC!$MD$w4\n"
.stringn "갑자기 나타나면 $w3심장에 안 좋다고.$w4\n"
.stringn "아~$w3 내 수명 줄어들었을지도 몰라$MC…$MD$K\n"
.stringn "$F3$P토팍은 조금 과장이 심하네~$w4\n"
.stringn "그런 일로 수명이 줄어든다면~$w3\n"
.stringn "다들 진작에 $w2죽었을 거야~$K$P그것보다, 일하자 일~$MC!$MD$w4\n"
.stringn "참모씨에게 부탁받은 무기 손질을$w3\n"
.stringn "얼른 끝내 버리자~$MC!$MD$K\n"
.stringn "$F1$P하아아,$w4 왜 $w2이런 잡일을$MC…$MD$w4\n"
.stringn "우리가 할 일은 아니지 않아?$K\n"
.stringn "$F3$P좋은 경험이라고 생각해~$K$P자기가 쓰는 무기뿐만 아니라~$w2\n"
.stringn "다양한 무기를 알아 둔다면~$w3\n"
.stringn "싸울 때 도움이 될 거야~$K\n"
.stringn "$F1$P그렇긴 하지.$w4$FS\n"
.stringn "뭐야, $w2제법 말솜씨가 좋잖아.$K\n"
.stringn "$F3$P칭찬받아서 영광이야~$K\n"
.stringn "$F1$P그럼, 일단$w3\n"
.stringn "검부터 시작해 보실까$MC!$MD$K"
