.stringn "$R背景会話|$B支援背景|$<$F1$FCL_ELAICE|$F3$FS$F3$FCL_GATRIE|$F3$P안녕, $w2이레이스$MC!$MD$K$P얼마 전에 $w2좋은 걸 얻었어.$w4\n"
.stringn "봐봐, $w2이 조개껍데기$MC!$MD$w4\n"
