.stringn "$F1$P네에$MC……$MD$K\n"
.stringn "$F3$P$FA$MC……$MD관심$w2 없어?$K\n"
.stringn "$F1$P그런 게 아니고$MC……$MD$K\n"
.stringn "$F3$P$FS그럼, $w2관심 있어?$K\n"
.stringn "$F1$P그런 게 아니고$MC……$MD$K\n"
.stringn "$F3$P$FA후우, $w2역시 안 되는구나.$K$P뭔가 마음에 들어하면\n"
.stringn "그걸 계기로\n"
.stringn "식사에 초대하려고 했는데$MC…$MD$K\n"
.stringn "$F1$P$MC!!$MD$w4\n"
.stringn "아, $w2함께해도 좋아요$MC……$MD$K\n"
.stringn "$F3$P응?$K\n"
.stringn "$F1$P식사$MC……$MD$K\n"
.stringn "$F3$P$FS저, $w2정말이야$MC!?$MD$w4\n"
.stringn "좋았어$MC!$MD$w4 나한테 맡겨 줘$MC!$MD$K$P이 내가 $w2이레이스를 위해서\n"
.stringn "맛~~있는 음식을 만드는 곳을$w2\n"
.stringn "찾아올 테니까$MC!$MD$K\n"
.stringn "$F1$P$MC……$MD그렇군요.$w4\n"
.stringn "가트리씨구나$MC…$MD$K\n"
