.stringn "$F1$P아뇨, $w2아무것도$MC…$MD$K\n"
.stringn "$F3$P???$w4\n"
.stringn "$FS뭐어, $w2됐어.$w4\n"
.stringn "그럼, $w2다음에 보자$MC!$MD$K\n"
.stringn "$F3$FD$P$w5$F1$P가트리씨, $w2가트리씨$MC…$MD$w4\n"
