.stringn "$R背景会話|$B支援背景|$<$F1$FCL_ELAICE|$F3$FS$F3$FCL_GATRIE|$F3$P안녕, $w2이레이스$MC!$MD$K\n"
.stringn "$F1$P$MC……$MD안녕하세요.$K\n"
.stringn "$F3$P헤헤헤$MC…$MD$w4\n"
.stringn "어때, $w2이 꽃, $w2예쁘지?$K$P이렇게 귀엽고 $w2예쁜 꽃은\n"
.stringn "이레이스랑 잘 어울린다고 생각했거든.$K\n"
.stringn "$F1$P네에$MC……$MD$K\n"
