.stringn "$F1$P그런 게 아니고$MC……$MD$K\n"
.stringn "$F3$P$FA$MC…………$MD$K$P$FS그, $w2그럼, $w2이건 어때?$w4\n"
.stringn "이 브로치, $w2예쁘지?$w4\n"
