.stringn "$R背景会話|$B支援背景|$<$F5$FCL_ELAICE|$F3$Fc$F3$FCL_GATRIE|$F3$P크흠,$w2 거기 아가씨.$K\n"
.stringn "$F5$P$MC……$MD$K\n"
.stringn "$F3$P$Fd아, $w2거기 귀여운 아가씨.$K\n"
.stringn "$F5$P$MC……$MD$K\n"
.stringn "$F3$P$Fc아,$w2\n"
.stringn "거기 연보라색 양갈래 머리를 한\n"
.stringn "사랑스러운 아가씨.$K\n"
.stringn "$F5$FD$F1$FCL_ELAICE|$F1$P아$MC…$MD$w2 저$MC…$MD$w4인가요?$w4\n"
.stringn "설마$MC……$MD$K\n"
.stringn "$F3$P$Fd$FS후우, $w2겨우 눈치채 주었구나.$w4\n"
.stringn "자각이 없다니 $w2이리 고상할 수가$MC…$MD$MC!$MD$K$P이야아~$MC!$MD$w4 아가씨 같은\n"
.stringn "귀엽고 근사한 여성과 같은 군에 있다니\n"
.stringn "행복한걸~$MC!$MD$K\n"
.stringn "$F1$P네에$MC……$MD$K\n"
.stringn "$F3$P그래서, $w2그,$w2\n"
.stringn "아가씨는 이름이 뭐야?$K\n"
.stringn "$F1$P이름$MC……$MD$w4이요?$w4\n"
.stringn "이레이스입니다$MC……$MD$K\n"
.stringn "$F3$P이레이스라고 하는구나.$w4\n"
.stringn "이야아~ $w2외모하고 어울리는\n"
.stringn "귀여운 이름이네$MC!$MD$w4 진짜 최고야$MC!$MD$K\n"
.stringn "$F1$P네에$MC……$MD$K\n"
.stringn "$F3$P내 이름은 $w2가트리야.$w4\n"
.stringn "가트라고 불러도 좋아$MC!$MD$w4\n"
.stringn "아니, $w2오히려 환영한달까?$K\n"
.stringn "$F1$P네에$MC……$MD$K\n"
.stringn "$F3$P그럼, $w2그렇게 됐으니까$w2\n"
.stringn "앞으로도~ $w1잘 부탁해$MC!$MD$K\n"
.stringn "$F1$P네에$MC……$MD$w4\n"
.stringn "$MC……$MD실례할게요$MC……$MD$K\n"
.stringn "$F1$FD$P$w5$F3$P헤헤헤,$w2 이걸로 내 인상은 확실히 남았겠지$MC!$MD$w4\n"
.stringn "그렇구나, $w2이레이스라고 하는구나$MC…$MD$w4\n"
