Text_11584:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_LUCHINO|$F3$P이레이스?$w4 이상하네.$w4\n"
.stringn "여기서 기다리라고 했는데.$w4\n"
.stringn "대체 어디에$MC……$MD$K\n"
.stringn "$F7$FCL_ELAICE|$F7$P루키노$MC……$MD$w4씨$MC……$MD$K$F7$FD\n"
.stringn "$F3$P$MC!$MD$w4 이레이스$MC……$MD$MC!?$MD$K$P이레이스, 정신 차려$MC!$MD$w4\n"
.stringn "왜 그래, $w2무슨 일 있었어?$K\n"
.stringn "$F1$FCL_ELAICE|$F1$P아뇨$MC……$MD$w4 아무것도$MC……$MD$K$P그저$MC……$MD$w4 배가, 고파서$MC……$MD$K\n"
.stringn "$F3$P배, $w2배가 고프다니$MC……$MD$w4\n"
.stringn "너, $w2제대로\n"
.stringn "밥은 먹고 다니는 거지?$K\n"
.stringn "$F1$P아뇨$MC……$MD$w4 오늘은 아직$MC……$MD$K\n"
.stringn "겨우 3인분밖에$MC……$MD$K\n"
.stringn "$F3$P뭐?$K$P3인$MC……$MD$w4분?$K\n"
.stringn "$F1$P네$MC……$MD$K\n"
.stringn "$F3$P$MC……$MD너, $w2평소에는\n"
.stringn "얼마나 먹는데?$K\n"
.stringn "$F1$P최근에는 $w2거의 못 먹고 있어요$MC……$MD$K\n"
.stringn "평범하게 5인분$MC……$MD$w4 정도밖에$MC……$MD$K\n"
.stringn "$F3$P$MC…………$MD어 그게$MC……$MD$K$P너, $w2혹시 라구즈는 아니지?$K\n"
.stringn "$F1$P네$MC……$MD$K\n"
.stringn "$F3$P$MC……$MD저기, 이레이스.$w4\n"
.stringn "지난 며칠 동안, $w2나는 네게\n"
.stringn "여러 가지 훈련을 시켜 봤어.$K\n"
.stringn "그리고 생각을 해 봤는데$MC……$MD$K$P너는 몸이 약한 것보다$MC……$MD$w4\n"
.stringn "좀 더 근본적인 뭔가가 문제라고 생각해.$K$P그래도 $w2이대로 내버려 둘 수는 없지.$w4\n"
.stringn "이왕 시작한 일이니$MC……$MD$w4\n"
.stringn "같이 어떻게든 해 보자.$K\n"
.stringn "$F1$P$FS네$MC……$MD$w4 기뻐요.$w4\n"
.stringn "루키노씨는 맛있는 요리를\n"
.stringn "만들어 줘요$MC……$MD$K$P루키노씨는 예쁘고, $w2강하고,$w2\n"
.stringn "좋은 냄새가 납니다$MC……$MD$w4\n"
.stringn "루키노씨와 함께 있고 싶어요$MC……$MD$K\n"
.stringn "$F3$P그, $w2그래.$w4\n"
.stringn "그럼 어쨌든 먹을 걸$MC……$MD$K\n"
.stringn "$F1$P루키노씨의 요리$MC……$MD$K$P$Fc$MC……$MD 꿀꺽.$K\n"
.stringn "$F3$P$FS$MC…$MD후우,$w3 어쩔 수 없지.$w4\n"
.stringn "뭐든지 좋아하는 걸 만들어 줄 테니까,$w2\n"
.stringn "훈련도 열심히 해야 한다?$K\n"
.stringn "$F1$P$Fd네$MC!$MD$w2 기뻐요$MC…$MD$MC!$MD$K"
