.stringn "$R背景会話|$B支援背景|$<$F1$FCL_ELAICE|$F3$FCL_LUCHINO|$F3$P그럼 이레이스, $w2시작해 봐.$K\n"
.stringn "$F1$P네$MC……$MD$w4\n"
.stringn "그럼$MC……$MD$w4 해 볼게요$MC……$MD$K\n"
.stringn "$F1$FD$F3$P$MC………………$MD$K$w4$P기, $w2기다려 이레이스.$w4\n"
.stringn "잠깐 $w2이쪽으로 돌아와 볼래?$K\n"
.stringn "$F1$FCL_ELAICE|$F1$P네$MC……$MD$w4\n"
.stringn "왜 그러시나요$MC……?$MD$K\n"
.stringn "$F3$P이레이스, $w2네가\n"
.stringn "몸이 약하는 건 잘 알아.$K$P그래도 $w2조금만 달려 보자.$w4\n"
.stringn "천천히 해도 되니까.$K\n"
.stringn "$F1$P네$MC……$MD$w4\n"
.stringn "저, $w2열심히\n"
.stringn "달렸잖아요$MC……$MD$K\n"
.stringn "$F3$P응$MC……?$MD$K$P방금 그게$MC……$MD$w4 달린 거였니?$K\n"
.stringn "$F1$P네$MC……$MD$K\n"
.stringn "$F3$P$MC………………$MD$w4\n"
.stringn "$MC……$MD잘 들어, $w2이레이스.$K$P누구에게나 서투른 게 있는 법이야.$w4\n"
.stringn "그걸 극복하기 위해서는$w2\n"
.stringn "많은 시간과 노력이 필요해.$K$P그러니까$MC…$MD$w3 바로 결과가 나타나지 않아도$w2\n"
.stringn "결코 서두르면 안 돼. $w4알았지?$K\n"
.stringn "$F1$P네$MC……$MD$K\n"
.stringn "$F3$P$FS나도 함께할게.$w4\n"
.stringn "같이 힘내 보자!$K\n"
.stringn "$F1$P네$MC…$MD$w4 힘낼게요$MC……$MD$K\n"
.stringn "$F3$P그럼, 일단 휴식하자.$w4\n"
.stringn "뭔가 마실 거라도$MC…$MD$K\n"
.stringn "$F1$P$FS먹는 게 좋아요.$K\n"
.stringn "$F3$P그, $w2그래.$w4\n"
.stringn "그럼, 먹을 걸 가져올게$MC…$MD$w3\n"
.stringn "뭘 먹고 싶니?$K\n"
.stringn "$F1$P지난번에 $w2루키노씨가\n"
.stringn "만들어서 가져다주신 거$MC…$MD$w4\n"
.stringn "전부 $w3다시 먹고 싶어요.$K\n"
.stringn "$F3$P그렇게나 마음에 들었니?$w4\n"
.stringn "기쁘네.$K\n"
.stringn "그렇다면 $w2다시\n"
.stringn "팔을 걷어 볼까.$K\n"
.stringn "$F1$P네, $w2기뻐요$MC…$MD$MC!$MD$K"
db 0
.align 4
//MYELL_ELAICE_LUCHINO_B

//0x10A80
Text_10A60:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_ELAICE|$F3$FS$F3$FCL_LUCHINO|$F3$P안녕.$w4\n"
.stringn "제법 귀여운 아이가 있나 했더니$MC…$MD$w3\n"
.stringn "너는 마도사구나.$K$P나는 루키노야.$K\n"
.stringn "크리미아 왕국군의 일원으로서$w3\n"
.stringn "네가 $w2이 전투에\n"
.stringn "참가해 준 것에 대해 감사하고 있어.$K\n"
.stringn "$F1$P네$MC……$MD$K$P저는 이레이스라고 해요$MC……$MD$w4\n"
.stringn "그레일 용병단의$MC……$MD$w4\n"
.stringn "$Fc$MC…$MD$w4 $MC…$MD$w4 $MC…$MD$K\n"
.stringn "$F3$P$FA왜, $w2왜 그래?$w4\n"
.stringn "정신 차려 봐, $w2괜찮니?$K\n"
.stringn "$F1$P$Fh네$MC……$MD$K\n"
.stringn "$F3$P그건 그렇고$MC……$MD$w4\n"
.stringn "이레이스는 $w2무척 가냘프네.$w4\n"
.stringn "그 상태로는 행군하는 것도 힘들지 않아?$K\n"
.stringn "$F1$P$Fc네$MC……$MD$w4 행군 중에 자주$MC……$MD$w4\n"
.stringn "쓰러져요$MC……$MD$K\n"
.stringn "$F3$P그래선 안 돼.$w4\n"
.stringn "만약 $w3전장에서 그런 일이 생기면$w2\n"
.stringn "바로 목숨을 잃게 될 거야.$K$P조심해. $w4싸우는 중에는$w2\n"
.stringn "체력 등의 자기 관리도 $w2중요하니까.$K\n"
.stringn "$F1$P네, $w2네에$MC…$MD$K\n"
.stringn "$F3$P기어 들어갈 듯한 대답인걸.$w4\n"
.stringn "정신 차려, $w2금방이라도 쓰러질 것 같은데?$K$P일단 도와줄 테니까$w3\n"
.stringn "네 천막으로 돌아가자.$K\n"
.stringn "$F1$P$Fh$MC…$MD안 돼요. $w4배가 고파서$MC……$MD$w3\n"
.stringn "움직일 수가$MC…$MD 없어요$MC……$MD$K\n"
.stringn "$F3$P그렇게나 배고파?$w4\n"
.stringn "기다려 봐. $w2내가 지금\n"
.stringn "식량을 좀 가지고 올 테니까.$K\n"
.stringn "$F1$P$Fd$FS정말인가요$MC……?$MD$K\n"
.stringn "$F3$P$FS그래. $w4어떤 걸\n"
.stringn "좋아하니?$K\n"
.stringn "$F1$P$MC…$MD편식하진 않아요.$w4\n"
.stringn "입에 들어가는 거라면 $w2뭐든지 좋아요.$K\n"
.stringn "$F3$P$FA그, $w2그렇구나.$w4\n"
.stringn "그 정도로 위험한 상태라는 거지?$K$P알았어.$w4\n"
.stringn "내가 돌아올 때까지 얌전히 있어야 해?$K$F3$FD\n"
.stringn "$F1$P네, $w2기뻐요$MC……$MD$K"
db 0
.align 4
//MYELL_ELAICE_LUCHINO_C

//0x12590
Text_12570:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_MORDY|$F1$FS$F1$FCL_ELAICE|$F1$P모우디씨$MC……$MD$w4 저번에는\n"
.stringn "감사했습니다$MC……$MD$K$P엄청, $w2도움이 됐어요$MC……$MD$K\n"
.stringn "$F3$P그, $w2그래$MC……$MD$w4 신경 쓰지 마라.$K\n"
.stringn "그나저나 너, $w2많이 먹는다.$w4\n"
.stringn "모우디가 12명 있는 것 같았다.$K\n"
.stringn "$F1$P대접해 주신\n"
.stringn "요리는 $w2맛있었지만$MC……$MD$w4\n"
.stringn "양이 적어서 아쉬웠어요$MC……$MD$K\n"
.stringn "$F3$P모우디는 이제 돈이 없다.$w4\n"
.stringn "미안하지만 포기했으면 한다.$K$P그나저나 $w2이레이스는 정말 많이 먹는다.$w4\n"
.stringn "그 많은 음식이 모두 $w2어디로 가나?$K\n"
.stringn "$F1$P$FA배 안으로요$MC……$MD$K\n"
.stringn "$F3$P으으음$MC……$MD$K$P그러고 보니, $w2생각났다.$w4\n"
.stringn "모우디랑 같이 숲에 사는 다람쥐는,$w2\n"
.stringn "몸이 작은데도 항상 뭔가를 볼에 넣었다.$K$P이레이스는 베오크지만,$w2\n"
.stringn "분명 다람쥐랑 같은 부류일 거다.$K\n"
.stringn "$F1$P$FS그럴지도$MC……$MD$w2 모르겠네요$MC……$MD$w4\n"
.stringn "다람쥐라$MC…$MD$w2 귀여운 비유군요$MC……$MD$K\n"
.stringn "$F3$P$FS그래서$MC…$MD$w4\n"
.stringn "이레이스는 $w2언제 겨울잠을 자나?$K\n"
.stringn "$F1$P$FA겨울잠은 안 자요.$K"
db 0
.align 4
//MYELL_ELAICE_MORDY_A

//0x120EC
Text_120CC:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_MORDY|$F1$P으으으$MC!$MD$K\n"
.stringn "$F3$FS$F3$FCL_ELAICE|$F3$P안녕하세요, $w2모우디씨$MC……$MD$K\n"
.stringn "짐을 나르고\n"
.stringn "계신 건가요$MC……?$MD$K\n"
.stringn "$F1$P$FS그렇다. $w4모우디는 힘이 세니까$w2\n"
.stringn "이럴 때는 $w2도움이 된다.$K$P이제 이것만 나르면 끝이다.$K\n"
.stringn "$F3$P그렇게 많은 짐을\n"
.stringn "한 번에$MC……$MD$w4 대단해요.$K\n"
.stringn "$F1$P너도 $w2잔뜩 먹어서\n"
.stringn "살을 붙이는 편이 좋다.$w4\n"
.stringn "커지면 $w2맞아도 버틸 수 있다.$K\n"
.stringn "$F3$P$FA사실은 저도 $w2그렇게 되고 싶어요$MC……$MD$K\n"
.stringn "하지만 저는 돈이 없어서$MC……$MD$w2\n"
.stringn "만족스럽게 먹을 수가 없거든요$MC……$MD$K$P그러니까 $w2금방이라도 쓰러지게 돼서$MC……$MD$K\n"
.stringn "$F1$P$FA으음, $w2그랬던 건가$MC……$MD$K$P이레이스는, 먹고 싶은 걸 못 먹는다니$MC…$MD$w4\n"
.stringn "그건 불쌍하다.$K$P$FS알았다. $w4모우디가 대접한다.$w4\n"
.stringn "아무거나 먹고 싶은 대로 마음껏 먹어라.$K\n"
.stringn "$F3$P네$MC……?$MD$w4\n"
.stringn "그 말 정말$MC……$MD$w3이신가요?$K\n"
.stringn "$F1$P그래, $w2정말이다.$K\n"
.stringn "$F3$P정말로$MC……$MD$w3 정말로요?$K\n"
.stringn "$F1$P?$w4\n"
.stringn "그렇다, $w2모우디는 거짓말 안 한다.$K\n"
.stringn "$F3$P$FS감사합니다$MC……$MD$w4\n"
.stringn "당신은 마치$MC…$MD$w2 여신님처럼\n"
.stringn "굉장한 분이시군요$MC……$MD$K\n"
.stringn "$F1$P그런가?$w4\n"
.stringn "그렇게 칭찬받으니 $w2부끄럽다.$K"
db 0
.align 4
//MYELL_ELAICE_MORDY_B

//0x11C4C
Text_11C2C:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_ELAICE|$F1$P아$MC…$MD$K\n"
.stringn "$F1$FD$F3$FCL_MORDY|$F3$P크, $w2큰일이다$MC…$MD$MC!$MD$w4\n"
.stringn "괜찮나?$w4 정신 차려라$MC!$MD$K\n"
.stringn "$F1$FCL_ELAICE|$F1$P$MC……$MD아$MC…$MD$w4\n"
.stringn "당신은$MC…$MD$w3 확실히$MC……$MD$K\n"
.stringn "$F3$P모우디다.$w4\n"
.stringn "너는 분명$MC…$MD$w3 이레이스?$w4\n"
.stringn "얘기하는 거, $w2처음이다.$K\n"
.stringn "$F1$P그렇네요$MC…$MD$w3\n"
.stringn "같은 동료인데도$MC……$MD$K$P저$MC…$MD$w2 존재감이 없어서$MC……$MD$w3\n"
.stringn "$MC……$MD자주 잊히거든요$MC……$MD$w4\n"
.stringn "$Fc아$MC……$MD$w2윽$MC……$MD$K\n"
.stringn "$F3$P왜 그러나?$K\n"
.stringn "$F1$P죄송합니다, $w2잠깐\n"
.stringn "발밑이 휘청거려서$MC……$MD$K$Fd$P자주 있는 일이니까$MC……$MD$w4\n"
.stringn "신경 쓰지 않으셔도 돼요$MC……$MD$K\n"
.stringn "$F3$P으음$MC…………$MD$K$P베오크 중에서도,$w2\n"
.stringn "너는 무척 가늘어 보인다.$w4\n"
.stringn "그런 가는 몸으로 $w2싸울 수 있나?$K\n"
.stringn "$F1$P네$MC……$MD$w3 어떻게든요.$K\n"
.stringn "$F3$P하지만 $w2그런 상태로는$MC…$MD$w3\n"
.stringn "적이랑 부딪치기만 해도$w2\n"
.stringn "쓰러져 버리지 않나?$K\n"
.stringn "$F1$P그때는 $w2어쩔 수 없죠$MC……$MD$w4\n"
.stringn "그렇게 될 각오는 되어 있으니까요$MC……$MD$K\n"
.stringn "$F3$P으으음$MC……$MD$w4 걱정이다$MC……$MD$K$FS$P알았다. $w4모우디가 너의 앞을 지킨다.$w4\n"
.stringn "모우디가 벽이 돼서 적을 막을 테니까,$w2\n"
.stringn "이레이스는 무리하지 마라.$K\n"
.stringn "$F1$P$FS아$MC……$MD$w4\n"
.stringn "감사합니다$MC……$MD$K"
db 0
.align 4
//MYELL_ELAICE_MORDY_C

//0x12FC8
Text_12FA8:
.stringn "$R背景会話|$B支援背景|$<$F6$FCL_WAYU|$F6$P으~음, $w2오늘은 상태가 별로네.$w4\n"
.stringn "이래선 강적에게 웃음거리가 될 거야.$w4\n"
.stringn "더 집중해야지$MC!$MD$K$P$MC……$MD그러고 보니 이레이스, $w2요즘 안 보이네.$w4\n"
.stringn "건강했으면 좋겠는데 $w2왠지 걱정된다.$K$P뭐, $w2생각해 봤자 소용없지$MC!$MD$w4\n"
.stringn "$FS그것보다 수행하자 $w2수행$MC……$MD$w4\n"
.stringn "$FA어라?$K\n"
.stringn "$F6$FD$F1$FCL_WAYU|$F1$P뭐, $w2뭔가를 밟아 버렸는데?$K\n"
.stringn "$F3$Fc$F3$FCL_ELAICE|$F3$P$MC……$MD$K\n"
.stringn "$F1$P우왓$MC!?$MD$w4\n"
.stringn "왜 이런 데 쓰러져 있는 거야$MC!$MD$w4\n"
.stringn "괜찮아$MC!?$MD$K\n"
.stringn "$F3$P배가$MC……$MD$K\n"
.stringn "$F1$P왜, $w2왜 그래?$w4\n"
.stringn "배$w4 아파?$K\n"
.stringn "$F3$P$MC……$MD고파요.$K\n"
.stringn "$F1$P응$MC……?$MD$K\n"
.stringn "$F3$P$Fd뭔가$MC……$MD$w3 먹을 $w2걸$MC……$MD$K\n"
.stringn "$F1$P저기$MC……$MD$w4\n"
.stringn "너 계속 휘청휘청거리던 게\n"
.stringn "설마 $w2배고파서 그런 거였어?$K\n"
.stringn "$F3$P네$MC……$MD$w4\n"
.stringn "저, $w2먹어도 먹어도 바로 배가 고파져서$MC……$MD$K\n"
.stringn "쓰러져 버렸$MC……$MD$w4 $MC……$MD$K\n"
.stringn "$F3$FD$F1$P엇, $w2자, $w2잠깐만$MC!$MD$w4\n"
.stringn "나 $w2지금 먹을 거 없는데$MC!$MD$K$P이, $w2일단 다른 사람 불러올 테니까――$w4\n"
.stringn "윽히에엑$MC!?$MD$K\n"
.stringn "$F8$FCL_ELAICE|$F8$P가$MC……$MD$w3가지 마세$MC……$MD$w2요$MC……$MD$K\n"
.stringn "$F1$P아, $w2다리$MC!$MD$w4\n"
.stringn "다리 잡혀 버렸다$MC!$MD$w4\n"
.stringn "힘 엄청 세잖아$MC!$MD$K\n"
.stringn "$F8$FD$F2$FCL_ELAICE|$F2$P뭔가, $w2먹을 $w2걸$MC……$MD$K\n"
.stringn "$F1$P아, $w2알았어$MC!$MD$w4 알았다니까~$MC!$MD$w4\n"
.stringn "도와줘~$MC!$MD$w4 뭐라도 좋으니까\n"
.stringn "먹을 걸 가져와 줘$MC!$MD$K$P안 그러면 $w2얘랑 내가 위험하다고~$MC!!$MD$K"
db 0
.align 4
//MYELL_ELAICE_WAYU_A

//0x12C6C
Text_12C4C:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_WAYU|$F3$FCL_ELAICE|$F1$P아, $w2너는 지난번에$MC……$MD$K\n"
.stringn "$F3$P안녕하세요$MC……$MD$K\n"
.stringn "$F1$P오늘도 왠지\n"
.stringn "휘청휘청거리는데, $w2어디 아파?$K\n"
.stringn "$F3$P아뇨$MC……$MD$w4 아픈 곳은 없어요.$K\n"
.stringn "$F1$P그래도 안색이 안 좋은 것 같은데?$w4\n"
.stringn "한번 의사한테 봐 달라고 부탁해 봐.$K\n"
.stringn "$F3$P정말로, $w2괜찮아요$MC……$MD$K\n"
.stringn "전에 $w2봐 달라고 했을 때에도,$w2\n"
.stringn "병은 없다고 들었거든요$MC……$MD$K\n"
.stringn "$F1$P그래?$w4\n"
.stringn "으~음, $w2그거 돌팔이 아니야?$w4\n"
.stringn "왠지 금방이라도 쓰러질 것 같은데.$K\n"
.stringn "$F3$P죄송해요$MC……$MD$K\n"
.stringn "$F1$P뭐, $w2됐어.$w4\n"
.stringn "안 아프다면 다행이긴 한데.$w4\n"
.stringn "제대로 걸을 순 있어?$K\n"
.stringn "$F3$P네$MC……$MD$w4 그럼 또 봐요$MC……$MD$K$F3$FD\n"
.stringn "$F1$P아니 $w2거긴 막다른 길이야$MC!$MD$K\n"
.stringn "$F3$FCL_ELAICE|$F1$P정말, $w2내가 데려다줄게$MC!$MD$w4\n"
.stringn "어디로 가는지 말해$MC!$MD$K\n"
.stringn "$F3$P$FS네$MC……$MD$w4\n"
.stringn "당신은 상냥한 분이시군요$MC……$MD$K"
db 0
.align 4
//MYELL_ELAICE_WAYU_B

//0x12960
Text_12940:
.stringn "$R背景会話|$B支援背景|$<$F6$FS$F6$FCL_WAYU|$F6$P좋았어, $w2오늘은 상태가 최고야$MC!$MD$w4\n"
.stringn "뭔가 좋은 일이 있을 것만 같아$MC!$MD$w4\n"
.stringn "숙명의 라이벌과 만날지도 몰라$MC!$MD$K\n"
.stringn "$F1$FCL_ELAICE|$F1$P$MC…………$MD$K\n"
.stringn "$F6$FD$F3$FCL_WAYU|$F3$P우와앗$MC!$MD$w4 깜짝 놀랐네$MC!$MD$K$P뭐, $w2뭐야?$w4\n"
.stringn "간단하게 내 뒤를 잡다니\n"
.stringn "꽤 하잖아$MC!$MD$K\n"
.stringn "$F1$P저기$MC……$MD$K\n"
.stringn "잠깐, $w2거기 좀 지나갈게요$MC……$MD$K\n"
.stringn "$F3$P어?$w4 아, $w2미안.$K\n"
.stringn "$F1$P실례하겠습니다$MC……$MD$K\n"
.stringn "$F3$P승부 상대로는$MC……$MD$w4\n"
.stringn "$FS역시 무리겠지.$w4\n"
.stringn "$FA그것보다 제대로 걸을 수나 있어?$K\n"
.stringn "$F1$P네, $w2마음 써 주셔서\n"
.stringn "감사합니다$MC……$MD$K\n"
.stringn "$F1$FD$F3$P엄청 연약한 여자애네$MC……$MD$w4\n"
.stringn "나하고는 정반대인걸.$w4\n"
.stringn "왠지 지켜 주고 싶어질 정도야$MC……$MD$K$P$FS아 이런, $w2수행하자 수행$MC!$MD$K"
db 0
.align 4
//MYELL_ELAICE_WAYU_C

//0x13D7C
Text_13D5C:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_ZIHARK|$F3$FCL_ELAICE|$F3$P아$MC……$MD$K\n"
.stringn "$F1$P$FS안녕, $w2이레이스.$w4\n"
.stringn "요즘 자주 만나네?$K\n"
.stringn "$F3$P$FS$MC…………$MD네, $w2네에$MC……$MD$w4\n"
.stringn "$MC……………………$MD$K\n"
.stringn "$F1$P무슨 일 있어?$w4\n"
.stringn "평소랑 조금$MC…$MD$w2 상태가 다른데.$K\n"
.stringn "$F3$P아, $w2아시겠나요$MC……?$MD$K\n"
.stringn "$F1$P그래.$w4\n"
.stringn "오늘은 왠지$w2\n"
.stringn "평소 이상으로 귀여운 느낌이야.$K\n"
.stringn "$F3$P$MC!$MD$w4\n"
.stringn "그, $w2그런$MC…$MD가요?$K\n"
.stringn "$F1$P$MC…$MD혹시$MC……$MD$K\n"
.stringn "$F3$P$MC………$MD$K\n"
.stringn "$F1$P평소보다도 더$w2\n"
.stringn "배가 고픈 거야?$K\n"
.stringn "$F3$P$FA$MC………$MD네$MC…?$MD$K\n"
.stringn "$F1$P넌 $w2군 남자들 사이에서$w3\n"
.stringn "꽤나 유명 인사거든.$K$P귀여운 얼굴에 이끌려 다가갔다가$w3\n"
.stringn "따끔한 맛을 봤다고.$K\n"
.stringn "$F3$P그$MC……$MD$w3\n"
.stringn "그래요$MC……?$MD$K\n"
.stringn "$F1$P$FA권유한 쪽에도 책임은 있지만,$K$P비싼 밥값을 냈는데$w3\n"
.stringn "다음 날 만나면$w2\n"
.stringn "얼굴도 이름도 기억하지 못한다며?$K\n"
.stringn "너무한 거 같은데.$K\n"
.stringn "$F3$P$MC………$MD저$MC……$MD$w4\n"
.stringn "그$MC……$MD$w2 배가 너무 고프면$MC……$MD$w3\n"
.stringn "쓰러져 버려요$MC……$MD$K$P그러니$MC…$MD$w3 여러분의 도움을$MC…$MD$w2 바로$MC…$MD$w3\n"
.stringn "받아들여$MC…$MD 버려서$MC…$MD$w2$MC…………$MD$K\n"
.stringn "$F1$P$MC…$MD그렇다면 이름 정도는 외워야지.$K$P속셈이 있었다곤 해도,$w3\n"
.stringn "모두 네게 도움$MC…$MD$w2이랄까$w2\n"
.stringn "호의를 베풀고 있는 거잖아.$K\n"
.stringn "$F3$P$MC……$MD죄$MC…$MD$w2죄송합니다$MC……$MD$K\n"
.stringn "$F1$P사과할 상대는 $w2내가 아니라고.$K\n"
.stringn "$F3$P$MC……$MD네$MC………$MD$K\n"
.stringn "$F1$P$FS$MC…$MD자 그럼, $w2같이 가자.$K\n"
.stringn "$F3$P네$MC…?$MD$K\n"
.stringn "$F1$P또 쓰러질 정도로 $w2배가 고픈 거잖아?$w4\n"
.stringn "멋대로 설교한 사죄로 $w3밥 살게.$K\n"
.stringn "$F3$P괜찮으신가요$MC…?$MD$K\n"
.stringn "$F1$P너와는 $w2비교적\n"
.stringn "오랜 동료 사이이기도 하고 말이야.$K$P다만$MC…$MD$w2\n"
.stringn "나는 부자가 아니니까, $w3기껏해야\n"
.stringn "2인분이 한계야.$K\n"
.stringn "$F3$P이, $w2이런 은혜를$MC…$MD$w4$FS\n"
.stringn "저$MC…$MD$w3 그걸로 충분해요$MC…$MD$w4\n"
.stringn "너무 $w2기뻐요$MC…$MD$MC!$MD$K$P감사합니다$MC……$MD$w4\n"
.stringn "$MC…………$MD$w3앗, 그$MC……$MD$K\n"
.stringn "$F1$P$FA$MC…$MD지하크.$K\n"
.stringn "$F3$P$FA$MC…$MD죄$MC…$MD$w2죄송합니다$MC……$MD$w4\n"
.stringn "지하크씨$MC…$MD$K"
db 0
.align 4
//MYELL_ELAICE_ZIHARK_A

//0x1395C
Text_1393C:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_ELAICE|$F3$FCL_ZIHARK|$F1$P$MC……$MD저, $w2저기$MC……$MD$K\n"
.stringn "$F3$P$FS왜 그래, 이레이스?$w4\n"
.stringn "또 배가 고픈 거야?$K\n"
.stringn "$F1$P네, $w2네에$MC……$MD$K\n"
.stringn "$F3$P너는 보기와는 다르게\n"
.stringn "대식가니까.$K$P마법을 쓰는 건 $w2그렇게나\n"
.stringn "체력이 소모되는 일인 거야?$K\n"
.stringn "$F1$P글쎄요$MC……$MD$w2\n"
.stringn "왜 그런지는 모르겠습니다만$MC……$MD$w3\n"
.stringn "곧바로 배가 고파져요$MC……$MD$K$P오늘은 다행히 4인분을 먹었지만$MC……$MD$w3\n"
.stringn "평소에는 3인분밖에 없는 게$MC……$MD$w2 괴로워서$MC……$MD$K\n"
.stringn "$F3$P하하,$w2 그거 굉장한데.$K$P그럼 먹은 만큼\n"
.stringn "열심히 일해서 갚아야지.$w4\n"
.stringn "힘내.$K$F3$FD\n"
.stringn "$F1$P아$MC…$MD 저기$MC…$MD$w4\n"
.stringn "잠깐 기다려$MC…$MD 주세요$MC……$MD$MC!$MD$K\n"
.stringn "$F4$FS$F4$FCL_ZIHARK|$F4$P왜 그래?$K\n"
.stringn "$F1$P저기$MC……$MD$w3\n"
.stringn "뭔가$MC…$MD 잊은 거 없으신가요$MC…?$MD$K\n"
.stringn "$F4$P$FA내가?$w4 $MC……$MD아니,$w2\n"
.stringn "딱히 아무것도 없다고 생각하는데?$K\n"
.stringn "$F1$P$MC……$MD그렇$MC…$MD군요$MC…$MD$K\n"
.stringn "$F4$P$FS그럼, $w3다음에 보자.$K$F4$FD\n"
.stringn "$F1$P$MC………………$MD$K\n"
.stringn "아무것도, $w2주지 않은 사람은$MC……$MD$w2\n"
.stringn "처음이야$MC……$MD$w4 $MC……$MD$K"
db 0
.align 4
//MYELL_ELAICE_ZIHARK_B

//0x13570
Text_13550:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_ZIHARK|$F3$FCL_ELAICE|$F1$P$MC……$MD이레이스?$w4\n"
.stringn "아까부터 뭘 보는 거야?$K\n"
.stringn "$F3$P네?$w4 아$MC……$MD$w4\n"
.stringn "그$MC……$MD$w2 허리에 찬 $w2자루 말인데요$MC……$MD$K\n"
.stringn "$F1$P$FS별로 대단한 건\n"
.stringn "아니라고 생각하는데$MC……$MD$w3\n"
.stringn "약이나 보존식을 넣어서 휴대하고 있어.$K\n"
.stringn "$MC……$MD이게 왜?$K\n"
.stringn "$F3$P그, $w2그게$MC……$MD$w4\n"
.stringn "맛있는 냄새가$MC……$MD$w2 나서$MC……$MD$K\n"
.stringn "$F1$P$MC…$MD그렇게 냄새나?$w4\n"
.stringn "말린 거밖에 안 넣었는데.$K\n"
.stringn "$F3$P죄$MC……$MD$w2죄송합니다$MC……$MD$w4\n"
.stringn "저$MC……$MD 그, $w2배가 고파서$MC……$MD$K\n"
.stringn "$F1$P아까 $w2네가 건강하게\n"
.stringn "식사하는 걸 봤는데?$K$P아직 시간도 별로 안 지났잖아.$w4\n"
.stringn "그렇게 소화가 잘 되다니$w2\n"
.stringn "보기와는 다르게 $w2꽤나 건강하구나.$K$P그럼, $w2난 이만 갈게.$K\n"
.stringn "$F3$P아$MC……$MD$K$F1$FD\n"
.stringn "$F3$P$MC………………$MD$w4\n"
.stringn "어떡하지$MC…………$MD$w4\n"
.stringn "뭔가 먹어야 하는데$MC……$MD$w2 못 움직이겠어$MC…$MD$K$P$MC………………$MD$w5\n"
.stringn "달라고 $w2할 걸 그랬$MC…$MD$w2나$MC……$MD$K"
db 0
.align 4
//MYELL_ELAICE_ZIHARK_C

//0x14C1C
Text_14BFC:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_ERINCIA2|$F3$Fc$F3$FCL_GEOFFRAY|$F1$P$MC……$MD지난번이랑은 $w2반대군요.$w4\n"
.stringn "제프리$MC…?$MD$w4 제 말을 들어주세요.$K\n"
.stringn "$F3$P$Fd$MC……$MD듣고 있습니다.$K\n"
.stringn "$F1$P$MC……$MD제프리$MC…$MD$w4 전장에서의 당신은,$w2\n"
.stringn "저를 감싸려 하는 나머지$MC……$MD$w4\n"
.stringn "너무 무리한 전투 방식을 취하고 있어요.$K\n"
.stringn "$F3$P주군을 보호하고 $w3감싸는 것이 기사의 역할입니다.$K\n"
.stringn "$F1$P하지만 그것 때문에$MC…$MD$w3\n"
.stringn "당신 자신이 $w2여러 번 위험에 처했지요.$K\n"
.stringn "$F3$P확실히, 몇 번인가$MC…$MD$w3\n"
.stringn "얕지 않은 상처를 입었습니다.$K\n"
.stringn "$F1$P당신은$MC…$MD 전에,$w2\n"
.stringn "저를 위해서 $w2목숨을 버리는 짓은\n"
.stringn "하지 않겠다고 약속했습니다.$K$P그런데도$MC……$MD$w3 역시\n"
.stringn "자신의 목숨을 소중히 여기지 않고 있죠.$K\n"
.stringn "$F3$P공주님$MC…$MD$w2 그치만$MC…$MD$MC!$MD$K\n"
.stringn "$F1$P저는, 전장에 나가지 않고$MC…$MD$w3\n"
.stringn "본영에서 가만히 있는 편이\n"
.stringn "더 좋다는 것은$MC……$MD$K\n"
.stringn "알고 있습니다.$K$P그래도$MC……$MD$K$P제 손이 닿지 않는 곳에서$MC…$MD$w2\n"
.stringn "소중한 사람의 목숨이 빼앗긴다는 것을$MC……$MD$w3\n"
.stringn "더는$MC…$MD$w2$Fc 견딜 수 없어서$MC……$MD$K$P그 때문에$MC……$MD$w3\n"
.stringn "제프리에게 부담을$MC………$MD$K\n"
.stringn "$F1$Fd$F3$P공주님$MC…$MD$w4 공주님께선 눈치채지 못하셨군요.$K$P당신이 전장에 나와서,$w2\n"
.stringn "크리미아병들의 사기가$MC…$MD$w3\n"
.stringn "얼마나 올라갔는지 모르십니까?$K$P주군인 당신께서 $w2전장에 계신다는 것은,$w4\n"
.stringn "확실히$MC…$MD$w3 엄청 불안한\n"
.stringn "일임에는 틀림없습니다.$K$P하지만, $w3그렇기 때문에$w2\n"
.stringn "우리는 질 수 없는 겁니다.$K$P반드시 이겨야 한다고 생각해$MC…$MD$w4\n"
.stringn "본래 갖추고 있는 것 이상의 힘을$w2\n"
.stringn "발휘할 수 있는 겁니다.$K\n"
.stringn "$F1$P$MC………$MD$K\n"
.stringn "$F3$P확실히, 저는$MC…$MD$w4\n"
.stringn "최근 무모한 전투 방식을 취했습니다.$K$P그건$MC…$MD$w2$FS 공주님께서 가까이 계셨으면\n"
.stringn "했기 때문이었습니다.$K$P제가 조금만 엉뚱한 짓을 하더라도$MC…$MD$w2\n"
.stringn "공주님이 바로 옆에서 상처를 치유해 주시니$MC……$MD$w4\n"
.stringn "그것에 너무 응석을 부렸던 모양입니다.$K\n"
.stringn "$F1$P$MC……$MD저는$MC…$MD$w3\n"
.stringn "폐를 끼치고 있는 게$MC……$MD$w2 아니었나요$MC…?$MD$K\n"
.stringn "$F3$P공주님을 제외한 전투 방식은$MC…$MD$w4\n"
.stringn "이제 생각할 수도 없습니다.$K$P제 목숨을 아끼고 계신다면,$w3\n"
.stringn "부디 앞으로도$w2\n"
.stringn "전장에서 힘을 빌려주십시오.$K\n"
.stringn "$F1$P제프리$MC…$MD$w4 미안해요.$w4\n"
.stringn "멋대로 오해하고$w2\n"
.stringn "화를 내서$MC…$MD$w3 당신을 괴롭게 했군요.$K\n"
.stringn "저는$MC…$MD$w2 미숙한 주인입니다.$K\n"
.stringn "$F3$P명령을 위반하는 저도, $w3그다지\n"
.stringn "칭찬받을 만한 신사는 아니라구요.$K\n"
.stringn "$F1$P$FS앞으로도 분명$MC…$MD$w3\n"
.stringn "잔뜩 폐를 끼칠 거라 생각하지만$MC……$MD$w4\n"
.stringn "계속 옆에 있어 줘요, $w3제프리.$K\n"
.stringn "$F3$P$FA엘린시아 공주님$MC…$MD$w4\n"
.stringn "제 검은 $w3평생 당신만의 것입니다.$K"
db 0
.align 4
//MYELL_ERINCIA_QUEEN_GEOFFRAY_A

//0x147D4
Text_147B4:
.stringn "$R背景会話|$B支援背景|$<$F1$Fc$F1$FCL_ERINCIA2|$F3$FCL_GEOFFRAY|$F3$P$MC……$MD공주님?$K$P공주님$MC…$MD$w3 부디, 기분을 풀어 주십시오.$K\n"
.stringn "$F1$P$MC………$MD$K\n"
.stringn "$F3$P제가$MC…$MD$w2 공주님의 명령을\n"
.stringn "지키지 않았던 것 때문에,$w3\n"
.stringn "화가 나신 것은 알고 있습니다.$K$P하지만$MC…$MD$MC!$MD$K$P공주님의 기사인 제게$MC…$MD$w2\n"
.stringn "전장에서 상관하지 말라니$MC…$MD$w4\n"
.stringn "너무나도 무리한 명령이 아닌가 해서$MC……$MD$K$P만약 $w3제게 부족한 점이 있고,$w2\n"
.stringn "그것을 불복으로 여기신다면$MC…$MD$w4\n"
.stringn "차라리 $w2기사의 칭호를 박탈해 주십시오.$K\n"
.stringn "$F1$P$MC………$MD$K\n"
.stringn "$F3$P공주님$MC…$MD$MC!$MD$K\n"
.stringn "$F1$P$Fd$MC……$MD기사의 칭호를 빼앗으면$MC…$MD$w4\n"
.stringn "제프리는 $w3저를 지키는 것을\n"
.stringn "그만둬 주는 건가요?$K\n"
.stringn "$F3$P$MC!!$MD$K\n"
.stringn "$F1$P$MC………$MD$K\n"
.stringn "$F3$P$MC…$MD공주님은$MC…$MD$w3 그렇게까지 저를\n"
.stringn "불쾌하게 생각하신 겁니까$MC……$MD$K\n"
.stringn "$F1$P$MC!$MD$w4 아니에요$MC…$MD$MC!$MD$K\n"
.stringn "$F3$P경솔한 말을 했습니다만$MC…$MD$K$P조국 부흥의 날까지는$MC…$MD$w3\n"
.stringn "$MC……$MD부디, 이대로$MC……$MD$w4\n"
.stringn "공주님을 지키는 기사로 있게 해 주십시오.$K$Fc\n"
.stringn "$MC………$MD$w2죄송합니다$MC……$MD$K$F3$FD\n"
.stringn "$F1$P잠깐, $w2제프리$MC…$MD$MC!$MD$w4\n"
.stringn "제프리$MC……$MD$MC!!$MD$K"
db 0
.align 4
//MYELL_ERINCIA_QUEEN_GEOFFRAY_B

//0x1453C
Text_1451C:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_ERINCIA2|$F1$P$MC……$MD$K\n"
.stringn "$F3$FCL_GEOFFRAY|$F3$P공주님?$w4\n"
.stringn "누구를 찾으시는 겁니까?$K\n"
.stringn "$F1$P$FS제프리.$w4\n"
.stringn "다행이다, $w3거기에 있었군요.$K\n"
.stringn "$F3$P제게 용건이 있으십니까?$K\n"
.stringn "$F1$P네. $w4$FA저$MC…$MD$w3\n"
.stringn "제프리에게 부탁이 있어요.$K\n"
.stringn "$F3$P공주님께서 제게 부탁을 하시다니$MC…$MD$K$FS$P어떤 것이라도 상관없습니다.$w4\n"
.stringn "명령을 내려 주십시오.$K\n"
.stringn "$F1$P$MC…$MD정말로요?$K\n"
.stringn "$F3$P예.$K\n"
.stringn "$F1$P그럼, $w2말할게요.$K$P제프리$MC…$MD$w4 앞으로는 일절,$w2\n"
.stringn "전장에서 저를 신경 쓰지 말아 주세요.$K\n"
.stringn "$F3$P$FA예$MC!?$MD$K$P공주님, 그건$MC…$MD$K\n"
.stringn "$F1$P반론은 듣지 않겠습니다.$w4\n"
.stringn "이건$MC…$MD$w2 명령이니까요.$w4\n"
.stringn "반드시, 지켜 주세요.$K$F1$FD\n"
.stringn "$F3$P$MC…$MD공주님$MC……$MD$K"
db 0
.align 4
//MYELL_ERINCIA_QUEEN_GEOFFRAY_C

//0x16010
Text_15FF0:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_ERINCIA2|$F1$P$MC…………$MD$K\n"
.stringn "$F3$FCL_IKE2|$F3$P드디어 $w2내일은 왕도구나.$K\n"
.stringn "$F1$P$MC……$MD네.$K\n"
.stringn "$F3$P기분은 어때?$K\n"
.stringn "$F1$P$MC…$MD무척 불안해요. $w4하지만$MC……$MD$w3\n"
.stringn "드디어 도착했다.$K$P드디어 돌아왔다.$w2\n"
.stringn "그 두 기쁨이 더 강해요.$K\n"
.stringn "$F3$P$FS강해졌구나.$K\n"
.stringn "$F1$P$FS바로 옆에$MC…$MD$w2\n"
.stringn "좋은 본보기가 있었던 덕분이에요.$K\n"
.stringn "$F3$P나쁜 $w2본보기겠지.$K\n"
.stringn "너 남쪽 바다에서$w3\n"
.stringn "자기가 뭐라고 했는지 잊었어?$K\n"
.stringn "$F1$P뭐, $w2뭐라고 했나요$MC…?$MD$w4\n"
.stringn "저 $w2뭔가 이상한 말을 했었나요?$K\n"
.stringn "$F3$P『냅다 날려 버려 주세요$MC!$MD』$w4\n"
.stringn "였던가?$K\n"
.stringn "$F1$P$FA그$MC…$MD$w2 그건$MC…$MD$w3\n"
.stringn "한번 $w3아이크님의 흉내를\n"
.stringn "내보고 싶어서 그랬어요.$K$FS$P저도 $w2다른 분들처럼\n"
.stringn "용감해지고 싶어서$MC……$MD$K\n"
.stringn "$F3$P아무리 그래도 $w2그땐 당황했다니까.$K\n"
.stringn "$F1$P후후$w4 $MC……$MD왠지$w2\n"
.stringn "엄청 그립네요.$K\n"
.stringn "$F3$FA$F1$P$FA왕도에서 도망쳐 나왔을 때$MC…$MD$w4\n"
.stringn "갈리아에서$MC…$MD 크리미아의 패전 소식을\n"
.stringn "들었을 때$MC…$MD$K$P앞으로 $w2절 기다리는 건\n"
.stringn "절망뿐이라고 생각하고 있었어요$MC…$MD$K$P$MC…$MD그렇지만 $w2이렇게 돌이켜 보니$w3$FS\n"
.stringn "희망은 얼마든지 있었네요$MC……$MD$w4$Fc\n"
.stringn "너무나도 따뜻한 희망의 빛이$MC……$MD$K\n"
.stringn "$F3$P$FS그래$MC……$MD$K\n"
.stringn "$F1$P$Fd$FA저는$MC…$MD$w2 이 희망을 가슴에 품고$MC……$MD$w3\n"
.stringn "내일 전투에 임하겠어요.$K$P데인 왕을 쓰러뜨리고,$w2\n"
.stringn "크리미아를 되찾기 위해서.$K\n"
.stringn "$F3$P난 네게 고용된 용병이야.$w4\n"
.stringn "네 소망을 이루기 위해 $w3\n"
.stringn "전력을 다하겠다고 약속할게.$K\n"
.stringn "$F1$P$FS아이크님$MC……$MD$K"
db 0
.align 4
//MYELL_ERINCIA_QUEEN_IKE_A

//0x15A60
Text_15A40:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_IKE2|$F1$P$MC…$MD아직 $w2여기에 있었구나.$K\n"
.stringn "$F3$FCL_ERINCIA2|$F3$P아$MC……$MD 아이크님.$w4\n"
.stringn "그$MC…$MD$w2 자율 훈련을 하고 있었어요$MC…$MD$K$P조금이라도 발목을\n"
.stringn "잡고 싶지 않아서$MC……$MD$K\n"
.stringn "$F1$P$MC……$MD그렇구나.$w4\n"
.stringn "하지만 훈련이라면 누군가 상대가 있는 편이\n"
.stringn "좋지 않을까?$K\n"
.stringn "$F3$P$MC……$MD$w2이렇게 긴장한 상태인 데다가$MC…$MD$w2\n"
.stringn "명백하게 실력이 뒤떨어지는 사람의\n"
.stringn "상대를 부탁드리는 건$MC…$MD$w3 너무 죄송해서$MC……$MD$K\n"
.stringn "$F1$P$MC…$MD지난번에 $w2남에게 의지하는 걸\n"
.stringn "주저하지 말라고 했었는데$MC…$MD$w4\n"
.stringn "잘 전해지지 않은 모양이네.$K\n"
.stringn "$F3$P아뇨, $w2그$MC…$MD$w3\n"
.stringn "충고해 주신 건 마음에 잘 새겨뒀어요.$w4\n"
.stringn "하지만$MC…$MD 그게$MC……$MD$K\n"
.stringn "$F1$P$MC……$MD자신의 나약함이 느껴지고,$w2\n"
.stringn "초조한 마음이 드는 건 잘 알아.$K$P나도 $w2아버지가 남긴 그레일 용병단을\n"
.stringn "잇겠다고 결정했을 때에는$MC……$MD$w3\n"
.stringn "안절부절못했었거든.$K\n"
.stringn "$F3$P$MC…………$MD$K\n"
.stringn "$F1$P뭐, $w2나라와 용병단의 무게는 전혀 다르겠지.$w4\n"
.stringn "$FS미안, $w2건방진 말을 해 버렸어.$K\n"
.stringn "$F1$FA$F3$P아뇨$MC……$MD$w3\n"
.stringn "말씀하신 대로입니다.$K$P앞으로 제가 짊어져야 할 것의 크기를 생각하니$w3\n"
.stringn "자신의 부족함이$MC……$MD$w2 괴로워서$MC……$MD$K\n"
.stringn "$F1$P$FA내가 지난 일 년 동안$MC…$MD$w4\n"
.stringn "싸움을 통해서 배운 것은$MC…$MD$K$P나 혼자서 해낸 일이$w3\n"
.stringn "사실은 얼마 없다는 거야.$K$P동료들이 나를 지지해 주고,$w2\n"
.stringn "내가 그걸 의지할 수 있었기 때문에$MC…$MD$w3\n"
.stringn "여기까지 올 수 있었던 게 아니었을까.$K\n"
.stringn "그렇게 생각해.$K$P$FS너도 똑같아.$w4\n"
.stringn "넌 $w2혼자가 아니야.$K\n"
.stringn "$F3$P$FS$MC…………$MD네$MC……$MD$MC!$MD$K"
db 0
.align 4
//MYELL_ERINCIA_QUEEN_IKE_B

//0x1555C
Text_1553C:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_IKE2|$F3$P엘린시아 공주.$w4\n"
.stringn "왜 그러고 있어?$K\n"
.stringn "$F1$FCL_ERINCIA2|$F1$P아$MC……$MD$w2 아이크님.$w4\n"
.stringn "그, $w2싸울 준비를 하고 있었는데\n"
.stringn "검이 허리에 잘 안 채워져서$MC……$MD$K\n"
.stringn "$F3$P잠깐 보여 줘 봐.$w4\n"
.stringn "$MC…$MD아, $w2칼집이 묶인\n"
.stringn "허리띠가 제대로 안 잠겼네.$K$P이걸 채우려면 조금 요령이 필요해.$w4\n"
.stringn "잠시 움직이지 말아 줘.$K\n"
.stringn "$MC…………$MD$w5\n"
.stringn "좋아, $w2이제 괜찮을 거야.$K\n"
.stringn "$F1$P감사합니다, $w2아이크님.$w4\n"
.stringn "$MC……$MD저, $w2한심하죠.$w4\n"
.stringn "혼자서 싸울 준비도 못 하고$MC……$MD$K\n"
.stringn "다른 분들은 벌써 다 끝내셨는데$MC…$MD$K\n"
.stringn "$F3$P처음에는 $w2누구나 다 그래.$w4\n"
.stringn "나도 $w2전까지만 해도\n"
.stringn "공주랑 비슷했으니까.$K\n"
.stringn "$F1$P아이크님이요?$K\n"
.stringn "$F3$P그래.$K\n"
.stringn "하지만 나는 아버지한테 $w2어떠한 환경에서도\n"
.stringn "살아갈 수 있는 기술과 $w2검을 다루는 법을\n"
.stringn "다른 것보다도 먼저 배웠으니까,$K$P공주와는 조금 다를지도 모르겠네.$K\n"
.stringn "$F1$P그러셨군요$MC……$MD$K\n"
.stringn "$F3$P그러니까 $w2성급해하지 않아도 돼.$w4\n"
.stringn "넌 태어날 때부터 우리들\n"
.stringn "용병과는 다르게 살아왔잖아.$K$P낯선 곳에서 무리를 하면$MC…$MD$w2\n"
.stringn "전장에서 죽을지도 몰라.$K\n"
.stringn "$F1$P아, $w2알겠습니다$MC……$MD$K\n"
.stringn "$F3$P$MC……$MD어쨌든 $w2필요 이상으로\n"
.stringn "깊게 생각하지 마.$K$P할 수 없는 것들을 자각하고$w2\n"
.stringn "남에게 도움을 구하는 건$MC…$MD$w4\n"
.stringn "부끄러운 일이 아니니까.$K\n"
.stringn "$F1$P네$MC……$MD$K\n"
.stringn "$F3$P$MC…………$MD$K"
db 0
.align 4
//MYELL_ERINCIA_QUEEN_IKE_C

