//0x16F28
Text_16F08:
.stringn "$R背景会話|$B支援背景|$<$F3$FS$F3$FCL_MARCIA|$F3$P아, $w2가트리씨.$K\n"
.stringn "$F1$FCL_GATRIE|$F1$P$Fh$MC…………$MD$K\n"
.stringn "$F3$P$FA어라, $w2왜 그러세요?$w4\n"
.stringn "기운이 없네요.$K\n"
.stringn "$F1$P$Fc$MC……$MD나 같은 패배자한테는$w2\n"
.stringn "더 이상 말 걸지 않는 편이 좋아.$K$P나 같은 건$w2\n"
.stringn "널부러진 돌멩이를 보는 듯한 눈으로\n"
.stringn "바라봐 주면 $w2돼$MC……$MD$K\n"
.stringn "$F3$P네, 네에$MC……$MD$K\n"
.stringn "아, $w2혹시 가트리씨$w3\n"
.stringn "지난번 일이 신경 쓰이시는 거예요?$K$P훈련에서 아이크씨에게 완패$MC……$MD$K\n"
.stringn "$F1$P$Fd이, $w2이제 그 일은\n"
.stringn "생각나게 하지 말아 줘~$MC!$MD$K$P실컷 큰소리친 주제에$w3\n"
.stringn "그렇게 꼴사나운 패배를$w2\n"
.stringn "하필이면 네게 보여 주다니$MC…$MD$K$P나는 이제 글렀어.$w4\n"
.stringn "$Fc세계에서 제일 글러먹은 남자야$MC……$MD$K\n"
.stringn "$F3$P$FS그렇지 않아요.$w4\n"
.stringn "확실히 그때는\n"
.stringn "아이크씨가 승리했지만$MC……$MD$K$P그래도 $w2가트리씨가\n"
.stringn "열심히 하는 모습, $w2멋있었거든요.$K\n"
.stringn "$F1$P$Fd저, $w2정말이야$MC!?$MD$K\n"
.stringn "$F3$P네, $w2둘 다 엄청 강했어요.$w4\n"
.stringn "저도 질 수는 없죠.$w4\n"
.stringn "다음에 같이 훈련$w2하게 해 주세요.$K$P아이크씨나 가트리씨에게\n"
.stringn "여러 가지를 배우고 싶으니까요.$K\n"
.stringn "$F1$P$FS무, $w2물론이지$MC!$MD$K\n"
.stringn "$F3$P다행이다.$w4\n"
.stringn "기대하고 있을게요$MC!$MD$w4\n"
.stringn "그럼 이만$MC!$MD$K$F3$FD$P$w5\n"
.stringn "$F1$P$FA$MC……$MD$w2 $MC……$MD$w2 $MC……$MD$K$w4$P아이크, $w2나 살짝\n"
.stringn "너를 원망하고 있었는데$MC……$MD$K$P$FS지금은 고맙다는\n"
.stringn "마음뿐이야$MC!$MD$w4\n"
.stringn "또 보자, $w2마샤$MC!$MD$K"
db 0
.align 4
//MYELL_GATRIE_MARCIA_A

//0x16AB0
Text_16A90:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_MARCIA|$F3$FS$F3$FCL_GATRIE|$F1$P무슨 일인가요, $w2가트리씨?$w4\n"
.stringn "저한테 무슨 볼일이라도 있나요?$K\n"
.stringn "$F3$P안녕, $w2잘 와줬어 마샤.$K\n"
.stringn "실은 내가 지금부터 $w2아이크 녀석하고\n"
.stringn "실전 훈련을 하기로 했거든.$K\n"
.stringn "$F1$P네에$MC!?$MD$w4\n"
.stringn "가트리씨,$w2\n"
.stringn "아이크씨랑 싸우는 거예요?$K\n"
.stringn "$F3$P물론이지$MC!$MD$w3 그래서 널 부른 거야.$w4\n"
.stringn "내가 평소에 감추고 있는 진짜 힘을\n"
.stringn "너한테만 보여 주고 싶어서.$K$P아이크는 단장이라서 강하지만,$w2\n"
.stringn "내 진짜 실력은\n"
.stringn "그보다 더 위니까 말이지.$K\n"
.stringn "$F1$P그렇군요$MC……$MD$w4\n"
.stringn "$FS가트리씨는 $w2굉장히 강하시네요.$w4\n"
.stringn "존경스럽습니다.$K\n"
.stringn "$F3$P아니 뭐~$w2 하하하하하$MC!$MD$w4\n"
.stringn "아무튼, $w2거기서 내 강함을\n"
.stringn "잘 지켜봐 줘 마샤.$K$P$F3$FD$F6$FS$F6$FCL_GATRIE|오, $w2아이크$MC!$MD$w4\n"
.stringn "준비는 됐냐?$w4 간다$MC!$MD$K\n"
.stringn "$F6$FD$F1$P$FA$F8$FCL_GATRIE|$F8$P마샤,$w4\n"
.stringn "너를 향한 사랑으로, $w2나는 이기겠어$MC!$MD$K$P우오오오오오오~~~$MC!!$MD$w4\n"
.stringn "$MC……$MD크헉$MC!?$MD$K\n"
.stringn "$F1$P아~$MC……$MD$w4\n"
.stringn "지금 거 아프겠다.$K\n"
.stringn "$F8$P$MC……$MD자, $w2잠깐 아이크$MC!$MD$w4\n"
.stringn "조금 봐줘$MC……$MD$w4 키에엑$MC!?$MD$K\n"
.stringn "$F1$P가트리씨, $w2괜찮으려나$MC……?$MD$K"
db 0
.align 4
//MYELL_GATRIE_MARCIA_B

//0x165EC
Text_165CC:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_MARCIA|$F3$FS$F3$FCL_GATRIE|$F3$P안녕 $w2마샤$MC!$MD$K\n"
.stringn "$F1$P앗?$w4 어떻게 제 이름을?$K\n"
.stringn "$F3$P너같이 귀여운 애의$w2\n"
.stringn "이름은 당연히 알고 있어야지$MC!$MD$K$P그나저나 $w2내가 예전에 있었을 때는$w3\n"
.stringn "함께 싸우는 여성이라고 하면\n"
.stringn "티아마트씨밖에 없었는데$MC……$MD$K$P잠시 떨어져 있는 사이에$w2\n"
.stringn "좋은 용병단이 되었구나.$w3\n"
.stringn "$Fc응응.$K\n"
.stringn "$F1$P혹시$MC…$MD$w4\n"
.stringn "예전에 $w2그레일 용병단에 있었던 분이신가요?$K\n"
.stringn "$F3$P$Fd맞아.$w4\n"
.stringn "나는 $w2그 아이크의\n"
.stringn "대선배라구.$K\n"
.stringn "$F1$P$FS아~ $w2역시$MC!$MD$K\n"
.stringn "제가 해적에게\n"
.stringn "습격당했을 때$w3\n"
.stringn "도와주러 오셨던 분 맞죠!$K\n"
.stringn "$F3$P어$MC…$MD$MC!?$MD$K\n"
.stringn "$F1$P저, 그때의 일은$w3\n"
.stringn "정말 감사하고 있어요$MC…$MD$K$P받은 은혜를 갚기 위해서$w2\n"
.stringn "열심히 하고 있습니다$MC!$MD$K\n"
.stringn "$F3$P아, $w2아아. $w4그래$MC!$MD$w4\n"
.stringn "너같이 우수한 천마 기사가\n"
.stringn "들어와 준 것만으로도 충분해$MC!$MD$K$P$FA실제로 나는$MC……$MD 네가 이 용병단에\n"
.stringn "있어 주기만 한다면$MC…$MD$w2 다른 건 필요 없다구$MC!$MD$K\n"
.stringn "$F1$P$FA그, $w2그렇게나 기대해 주시다니$w2\n"
.stringn "조금 긴장되는걸요$MC…………$MD$K\n"
.stringn "$FS아, $w2아무튼, $w2앞으로도\n"
.stringn "열심히 할 테니 잘 부탁드려요$MC!$MD$K$F1$FD$P$w5\n"
.stringn "$F3$P$FS아아, $w2이 얼마나 귀여운 아이인가.$w4\n"
.stringn "역시 $w2이건$MC……$MD$w4\n"
.stringn "운명이지?$w2 그렇지?$K"
db 0
.align 4
//MYELL_GATRIE_MARCIA_C

//0x18114
Text_180F4:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_GATRIE|$F3$FS$F3$FCL_STELLA|$F3$P가트리씨,$w2\n"
.stringn "오늘도 잘 부탁드려요.$K\n"
.stringn "$F1$P네$MC!$MD$w4\n"
.stringn "어~ 그럼, $w2지난번의 이야기입니다만$MC…$MD$K$P스텔라씨, $w2『임기응변』$w2이라는 말이\n"
.stringn "무슨 의미인지 아시나요?$K\n"
.stringn "$F3$P네, $w2알고 있어요.$K\n"
.stringn "$F1$P예$MC!?$MD$w4\n"
.stringn "알고 있나요?$K\n"
.stringn "$F3$P그때그때의 상황이나 변화에 따라\n"
.stringn "적절하게 대처하는 것$MC……$MD$w4이죠?$K\n"
.stringn "$F1$P아, $w2과연$MC!$MD$w4\n"
.stringn "뭐야, $w2그런 뜻이구나.$w4\n"
.stringn "지난번의 대답은 그겁니다, $w2예$MC!$MD$K$P역시 스텔라씨는 똑똑하시네요$MC!$MD$K\n"
.stringn "아니, $w2물론 저도 알고 있었습니다?$w4\n"
.stringn "알고 있었는데, $w2잠깐\n"
.stringn "학생을 시험해 볼까 생각했을 뿐이에요.$K$P이야 벌써 합격$MC!$MD$w4 합격입니다$MC!$MD$K\n"
.stringn "$F3$P네, $w2그런 식으로\n"
.stringn "칭찬해 주셔서 기뻐요.$K\n"
.stringn "$F1$P뭐, 그런 식으로 선생과 학생의 사이도\n"
.stringn "깊어졌으니$MC…$MD$K\n"
.stringn "$FA저기, $w2스, $w2스텔라씨는$MC……$MD$w4\n"
.stringn "연인이라든가 있나요?$w4 없겠죠?$K\n"
.stringn "$F3$P$FA연인$MC……$MD$w4이요?$K\n"
.stringn "$F1$P네$MC!$MD$K\n"
.stringn "$FS아, $w2참고로 저는 연인은 없어요$MC!$MD$w4\n"
.stringn "안심하세요$MC!$MD$K\n"
.stringn "$F3$P연인은 없습니다.$w4\n"
.stringn "하지만, $w2약혼자라면$MC……$MD$K\n"
.stringn "$F1$P$FA네?$K\n"
.stringn "야, 약혼자요?$K\n"
.stringn "$F3$P네.$K\n"
.stringn "$F1$P$FS그, $w2그렇군요$MC!$MD$K\n"
.stringn "이야, $w2그거 경사스럽네요$MC!$MD$K\n"
.stringn "$F3$P저기$MC……$MD$w4 어째서 눈물을?$K\n"
.stringn "$F1$P아뇨, $w2저는 신경 쓰지 마세요$MC…$MD$K\n"
.stringn "괜찮아요$MC!$MD$w4\n"
.stringn "스텔라씨가 행복하다면, $w2충분합니다$MC!$MD$K$F1$FD\n"
.stringn "$F3$P아, $w2가트리씨 어디로$MC……$MD$K\n"
.stringn "$F3$FD$P$w7$F5$FCL_GATRIE|$F5$P하아$MC……$MD$w4 또 차여 버렸다.$w4\n"
.stringn "이번에야말로 될 줄 알았는데.$K$P$MC……$MD음, $w2근데 잠깐만?$w4\n"
.stringn "스텔라씨,$w2\n"
.stringn "약혼자가 있다고 했었지?$K$P그런 걸 일부러 말한다는 건\n"
.stringn "돌려 말해서$MC……$MD$w4 자기를 가로채서\n"
.stringn "도망가자는 거 아닌가?$K$P$FS뭐야$MC!$MD$w4 그런 거라면 그렇게 말해 주지$MC!$MD$w4\n"
.stringn "기다려 주세요 스텔라씨~$MC!$MD$K\n"
.stringn "$F5$FD"
db 0
.align 4
//MYELL_GATRIE_STELLA_A

//0x179C8
Text_179A8:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_STELLA|$F3$FS$F3$FCL_GATRIE|$F1$P가트리씨.$w4\n"
.stringn "말씀을 들으러 왔어요.$w4\n"
.stringn "괜찮을까요?$K\n"
.stringn "$F3$P네, $w2물론임다$MC!$MD$w4\n"
.stringn "오히려 제가 찾고 있었을 정도로$MC!$MD$K$P$Fc$FA에, $w2엣헴$w4\n"
.stringn "$Fd$FS그럼, $w2설명할게요$MC!$MD$K\n"
.stringn "$F1$P네.$K\n"
.stringn "$F3$P어~ 우선$MC!$MD$w4\n"
.stringn "용병단의 전투란 말이죠$MC!$MD$w4\n"
.stringn "역할 분담이 중요하답니다$MC!$MD$K$P동료끼리 서로 협력한다면,$w2\n"
.stringn "단 3명이서도 10명분을 할 수 있을 것 같$MC…$MD$w4\n"
.stringn "할 수 있다구요$MC!$MD$K\n"
.stringn "$F1$P과연$MC……$MD$w4 역할 분담이군요.$w4\n"
.stringn "네, $w2알겠습니다.$K\n"
.stringn "$F3$P그레일 용병단에서의 제 역할은$w2\n"
.stringn "적을 막는 방패임다.$K$P일단, $w2제가 용감하게 앞에 나서서\n"
.stringn "적의 공격을 모두 막아 내고$MC!$MD$w4\n"
.stringn "그 틈에 다른 모두가 공격하는 거죠$MC!$MD$K$P활은 제 뒤에서,$w2\n"
.stringn "기마는 일격을 가하고 바로 물러납니다$MC!$MD$K$P뭐어, $w2이런 느낌인 것 같$MC……$MD$w4\n"
.stringn "이런 느낌이에요$MC!$MD$K\n"
.stringn "$F1$P무척 잘 알았습니다.$w4\n"
.stringn "그럼 저는$MC……$MD$K\n"
.stringn "$F3$P스텔라씨는 $w2물론 제 뒤에죠$MC!$MD$K\n"
.stringn "너무 멀어지면 위험하니까,$w2\n"
.stringn "지나치게 붙지 않았나 싶을 정도로\n"
.stringn "제게 붙어 있어 주세요$MC!$MD$w4 헤헤$MC!$MD$K\n"
.stringn "$F1$P네, $w2가능한 만큼 노력하겠습니다.$K$P아, $w2그리고\n"
.stringn "하나 질문을 드려도 될까요?$K\n"
.stringn "$F3$P네, $w2뭐든지요$MC!$MD$K\n"
.stringn "$F1$P저는 기마병이고 $w2가트리씨는 보병이니까,$w2\n"
.stringn "행군의 박자가 안 맞는다는 느낌이 들어요.$w4\n"
.stringn "이런 경우에는 어떻게 해야 하나요?$K\n"
.stringn "$F3$P어 그게, $w2그런 경우에는 말이죠$MC……$MD$K\n"
.stringn "$FA어라?$w4\n"
.stringn "티아마트씨가 뭐라고 했었지?$K\n"
.stringn "$F1$P$FA?$K\n"
.stringn "$F3$P$FS아, 아니 $w2지금 건 혼잣말임다$MC!$MD$K$P그럼 $w2그 건은\n"
.stringn "또 다음에 하는 걸로$MC!$MD$w4\n"
.stringn "다음에는 $w2확실하게 알려 드릴 테니까요$MC!$MD$K\n"
.stringn "$F1$P$FS네, $w2오늘은 대단히 공부가 됐어요.$w4\n"
.stringn "또 부디 가르쳐 주세요.$w4\n"
.stringn "그럼, $w2실례하겠습니다.$K$F1$FD$P$w5\n"
.stringn "$F3$P『또 가르쳐 주세요』$w2라니~$MC……$MD$w4\n"
.stringn "이건 즉 $w2돌려 말해서 결혼해 달라는\n"
.stringn "의미겠지$MC……?$MD$K$P$Fc아아, $w2곤란한걸~$MC…$MD$K"
db 0
.align 4
//MYELL_GATRIE_STELLA_B

//0x17484
Text_17464:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_STELLA|$F3$FS$F3$FCL_GATRIE|$F3$P이야아, $w2스텔라씨$MC!$MD$w4\n"
.stringn "당신과 이렇게 함께 싸울 수 있다니\n"
.stringn "정말 감격임다$MC!$MD$K\n"
.stringn "$F1$P네, $w2앞으로도\n"
.stringn "잘 부탁드려요.$K$P가트리씨는 $w2이전에도\n"
.stringn "아이크씨의 용병단에$w2\n"
.stringn "계신 적이 있다고 들었습니다만$MC……$MD$K\n"
.stringn "$F3$P물론이죠$MC!$MD$w4\n"
.stringn "저는 오래 전부터\n"
.stringn "여기서 일했던 고참이거든요$MC!$MD$K$P모르는 게 있다면\n"
.stringn "뭐든지 물어보십쇼$MC!$MD$w4 뭐든지요$MC!$MD$K\n"
.stringn "$F1$P감사합니다.$K\n"
.stringn "그럼$MC……$MD$w3 제게\n"
.stringn "용병의 전투 방식을\n"
.stringn "가르쳐 주시겠어요?$K\n"
.stringn "$F3$P$FA용병의 전투 방식$MC……$MD$w3이라뇨?$K\n"
.stringn "$F1$P$FA저는 $w2전투 경험이\n"
.stringn "별로 없어요.$K$P그래서 $w2여러분들께\n"
.stringn "폐를 끼치지 않도록\n"
.stringn "배워 두고 싶어서$MC……$MD$K\n"
.stringn "$F3$P$FS과, $w2과연 그렇군요$MC!$MD$w4\n"
.stringn "역시 스텔라씨$MC!$MD$K$P$FA$MC……$MD아, $w2하지만\n"
.stringn "지금은 조금 곤란함다.$K$P티아마트씨도 없고,$w2\n"
.stringn "다음에 만나기 전까지 $w2몰래 듣$MC……$MD$K\n"
.stringn "$F1$P?$K\n"
.stringn "$F3$P$FS아뇨, $w2아무것도 아님다$MC!$MD$K$P이왕이면\n"
.stringn "제대로 준비한 다음에 하고 싶거든요$MC!$MD$w4\n"
.stringn "날을 잡아서 다시 와 주세요$MC!$MD$K\n"
.stringn "$F1$P$FS네. $w4그럼, $w2다음 기회에.$K\n"
.stringn "잘 부탁드릴게요.$K$F1$FD$P$w5\n"
.stringn "$F3$P아아, $w2귀엽다$MC……$MD$w4\n"
.stringn "나한테 전투 방식을\n"
.stringn "가르쳐 달라는 건$MC……$MD$K$P역시, $w2스텔라씨는\n"
.stringn "나한테 관심이 있는 거겠지$MC……$MD$w2\n"
.stringn "곤란하게 됐는걸$MC……$MD$K"
db 0
.align 4
//MYELL_GATRIE_STELLA_C

