//0x18EB8
Text_18E98:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_JILL|$F3$P하알씨.$K\n"
.stringn "$F1$Fc$F1$FCL_HAAR|$F1$P여기다.$K\n"
.stringn "$F3$P$FS드디어 한 번에 대답을 해 주셨군요.$K\n"
.stringn "$F1$P$Fd그러는 게 $w2네 잔소리를\n"
.stringn "듣는 시간이 줄어들지도 모르니까.$K\n"
.stringn "$F3$P정말$MC…$MD$w4$FS\n"
.stringn "상관없어요, $w2딱히.$K\n"
.stringn "$F1$P$MC…$MD질, $w2너\n"
.stringn "이 전쟁이 끝나고 나서 어떻게 할 거냐?$K\n"
.stringn "$F3$P$FA$MC……$MD데인으로 돌아가고 싶습니다.$w4\n"
.stringn "달레카의$MC…$MD$w4 아버님의 무덤 근처에서 살 거예요.$K\n"
.stringn "$F1$P그런가.$K\n"
.stringn "$F3$P하알씨는요?$K\n"
.stringn "$F1$P나는$MC…$MD$w4 아슈나드 놈이랑\n"
.stringn "싸우고도 살아남을 수 있다면$MC……$MD$w4\n"
.stringn "$MC………$MD어떻게 할까.$K$P시하람님의 묘지 쪽은\n"
.stringn "네가 먼저 말해 버렸으니.$K\n"
.stringn "$F3$P저, $w2저와 함께하는 건$MC…$MD$w4\n"
.stringn "불만이라는 건가요$MC!?$MD$K\n"
.stringn "$F1$P$MC…$MD네 쪽에서 나와 함께하는 걸\n"
.stringn "싫어할 것 같아서 사양했을 뿐이야.$K\n"
.stringn "$F3$P$MC……$MD싫어할 리가, $w2없잖아요.$K\n"
.stringn "$F1$P그럼, $w2만약 둘 다 살아남게 된다면\n"
.stringn "달레카에서 비룡을 쓰는\n"
.stringn "짐 운반이라도 하면서 살까?$K\n"
.stringn "$F3$P$FS네.$w4\n"
.stringn "만약$MC…$MD$w2 살아남게 된다면요.$K"
db 0
.align 4
//MYELL_HAAR_JILL_A

//0x18B38
Text_18B18:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_JILL|$F3$P하알씨$MC!$MD$w4\n"
.stringn "하알씨$MC…$MD$w4 어디 계십니까$MC!?$MD$w4\n"
.stringn "하알$MC…$MD$K\n"
.stringn "$F1$Fc$F1$FCL_HAAR|$F1$P여기다.$K\n"
.stringn "$F3$P들린다면 $w2처음 불렀을 때\n"
.stringn "대답해 주세요$MC!$MD$K$P『대장』이라고 부르지 않는다면\n"
.stringn "제대로 대답한다고\n"
.stringn "약속했을 텐데요.$K\n"
.stringn "$F1$P$Fd$MC…$MD귀찮구만.$K\n"
.stringn "$F3$P$MC……$MD계속 생각하고 있었습니다만,$K\n"
.stringn "하알씨가 군인다운\n"
.stringn "성실한 태도로 있었던 건$MC…$MD$w4\n"
.stringn "아버님 앞에서만이었죠.$K\n"
.stringn "$F1$P너도$w2\n"
.stringn "그 올라간 눈썹이 내려가는 건$w2\n"
.stringn "시하람님 앞에서만이었잖냐.$K\n"
.stringn "$F3$P그, $w2그건$MC…$MD$w4\n"
.stringn "어쩔 수 없잖아요?$w4\n"
.stringn "아버님은 특별하니까요.$K\n"
.stringn "$F1$P나도 그래.$w4\n"
.stringn "시하람님은 특별한 존재였지.$K$P그래서 그분 앞에서만큼은,$w2\n"
.stringn "이렇게 게을러터진 모습을\n"
.stringn "보이지 않으려고 신경을 곤두세웠었다.$K\n"
.stringn "$F3$P$MC…$MD하알씨.$K\n"
.stringn "$F1$P$Fc흐아암$MC…$MD$w3$Fh 졸리군.$w5\n"
.stringn "얘기는 끝이야. $w4$Fc오늘은 이제 방해하지 마.$K"
db 0
.align 4
//MYELL_HAAR_JILL_B

//0x18868
Text_18848:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_JILL|$F3$P하알 대장님$MC!$MD$w4\n"
.stringn "하알 대장님$MC…$MD$w4 어디 계십니까$MC!?$MD$w4\n"
.stringn "하알 대장$MC…$MD$K\n"
.stringn "$F1$Fc$F1$FCL_HAAR|$F1$P여기다.$w4\n"
.stringn "너 말이야, $w2사람의 이름을\n"
.stringn "시장의 채소 장수처럼 부르지 말라고.$K\n"
.stringn "$F3$P그럼 $w2처음 불렀을 때\n"
.stringn "대답해 주세요$MC!$MD$K\n"
.stringn "$F1$P$Fd네가 나를 『대장』이라고\n"
.stringn "부르지 않는다면.$K\n"
.stringn "$F3$P그치만$MC…$MD$w4\n"
.stringn "그럼, $w2어떻게 부르면 됩니까?$K\n"
.stringn "$F1$P네 마음대로 해.$K\n"
.stringn "$F3$P하알님$MC…?$MD$K\n"
.stringn "$F1$P평범한걸.$K\n"
.stringn "$F3$P하알씨.$K\n"
.stringn "$F1$P뭔가 딱 안 오는데.$K\n"
.stringn "$F3$P하알$MC!$MD$K\n"
.stringn "$F1$P$FS오오. $w4그거 좋은데.$K\n"
.stringn "$F3$P싫어요.$w4\n"
.stringn "전 상관을 경칭 없이 함부로 부르다니.$w4\n"
.stringn "역시 $w2하알씨라고 부르겠습니다.$K\n"
.stringn "$F1$P뭐어$MC…$MD$w4 상관은 없지만.$K"
db 0
.align 4
//MYELL_HAAR_JILL_C

//0x19848
Text_19828:
.stringn "$R背景会話|$B支援背景|$<$F3$Fc$F3$FCL_HAAR|$F1$FCL_MAKAROV|$F1$P아, $w2$FS있다 있어.$w4\n"
.stringn "하알 형님$MC!$MD$K\n"
.stringn "$F3$P$MC………$MD$K\n"
.stringn "$F1$P형~님.$w4\n"
.stringn "일어나 보시라구요.$K$FA$P앗$MC!$MD$w4 아이크 장군이 보고 있잖아$MC!!$MD\n"
.stringn "$MC………$MD$K\n"
.stringn "$F3$P$MC………$MD$K\n"
.stringn "$F1$P어라~$w3 안 일어나네.$K$P그나저나 $w2이 상태로 잘 수 있다니\n"
.stringn "대단한 신경이구만. $w3$FS존경스러운데.$w4\n"
.stringn "나도 빨리 이 경지까지 도달해야겠어~$K$P빚쟁이도 울면서 도망갈 듯한$w2\n"
.stringn "이런 박력을 몸에 익힐 수만 있다면$w3\n"
.stringn "마구잡이로 해먹었을 텐데.$K$P좋아$MC!$MD$w2 특훈이다 특훈!$w4\n"
.stringn "우선 $w2어디서든지 잘 수 있게 되는 거야.$K$Fc$P$MC……………$MD$w5\n"
.stringn "쿨~$MC…$MD$w3 드르렁드르렁$K\n"
.stringn "$F3$P$MC……$MD$w2$Fd시끄러워 죽겠네.$K\n"
.stringn "나 참, $w2누구 멋대로 형님이냐$MC…$MD$K\n"
.stringn "$F1$P새근새근$w2 $FA음~$MC…$MD$w3\n"
.stringn "마샤아$MC…$MD$w4 오빠가 잘못했어$MC……$MD$K\n"
.stringn "$F3$P$MC………$MD$K\n"
.stringn "$F1$P$MC…$MD돈 $w2좀 빌려주라$MC……$MD$w4$FS 음냐음냐$K\n"
.stringn "$F3$P$MC……$MD이 상태로 $w3여태까지\n"
.stringn "살아남았다는 게\n"
.stringn "어떤 의미로는 $w2기적이군.$K$FS$P어지간히 운이 좋은가 본데.$w4\n"
.stringn "이왕 이렇게 됐으니 $w3이대로 마지막까지\n"
.stringn "꼭 살아남았으면 좋겠군.$K"
db 0
.align 4
//MYELL_HAAR_MAKAROV_A

//0x19430
Text_19410:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_HAAR|$F1$P음$MC…?$MD$w2 너는$MC……$MD$K\n"
.stringn "$F3$FCL_MAKAROV|$F3$P히에엑$MC!?$MD$K\n"
.stringn "$F1$P전에 본 남자로군.$K$F3$FD\n"
.stringn "$F1$P이봐, $w2도망가지 마.$K\n"
.stringn "$F4$FCL_MAKAROV|$F4$P하, $w2한 번만 봐주세요~$MC!$MD$w4\n"
.stringn "꼭 $w2갚을 테니까요~$MC!$MD$K\n"
.stringn "$F1$P$MC…$MD뭔 소리야?$K\n"
.stringn "$F4$P아, $w2아니, $w2그때는 하필\n"
.stringn "가진 게 없어가지고$MC……$MD$K$P그렇다고 $w2지금은 있냐고 하면\n"
.stringn "또 없습니다요$MC……$MD$K$P부디, $w2조금만 더\n"
.stringn "빚 갚는 걸 기다려 주시면$MC……$MD$K\n"
.stringn "$F1$P빚을 갚는다니$MC…$MD$w4\n"
.stringn "무슨 말이야?$K\n"
.stringn "$F4$P어라$MC……?$MD$w4\n"
.stringn "혹시$MC…$MD$w3\n"
.stringn "빚쟁이 아니신가요?$K\n"
.stringn "$F1$P$MC……$MD내가 빚쟁이인가.$K\n"
.stringn "$F4$P아, $w2아닙니까?$K\n"
.stringn "$F1$P그랬던 기억은 없어.$K\n"
.stringn "$F4$P$FS뭐야, $w2괜히 겁먹었네~$w4\n"
.stringn "그야 그런 얼굴을 하고 있으니까,$w3\n"
.stringn "틀림없이 $w2빚쟁이인 줄 알았죠.$K\n"
.stringn "$F1$P$MC…$MD호오,$w4 내가 틀림없이\n"
.stringn "빚쟁이일 거 같은 얼굴이란 건가.$K\n"
.stringn "$F4$P아, $w2아뇨 아뇨$MC!$MD$K$P말실수예요 말실수.$w4\n"
.stringn "정말 $w2착각해서\n"
.stringn "죄송했습니다~$K$F4$FD\n"
.stringn "$F1$P$MC………$MD$w4\n"
.stringn "자 그럼, $w2한숨 자 볼까.$K"
db 0
.align 4
//MYELL_HAAR_MAKAROV_B

//0x19274
Text_19254:
.stringn "$R背景会話|$B支援背景|$<$F3$Fc$F3$FCL_HAAR|$F3$P$MC………$MD$K\n"
.stringn "$F1$FCL_MAKAROV|$F1$P$MC!!$MD$K\n"
.stringn "$F3$P$Fh$MC……$MD응?$K\n"
.stringn "$F1$P어, $w2어버버버$MC……$MD$K\n"
.stringn "$F3$P$Fd뭐야, 넌?$K\n"
.stringn "$F1$P옥$w2 오, 오$MC…$MD$K\n"
.stringn "$F3$P이봐, $w2왜 그래$MC……$MD$K\n"
.stringn "$F1$P히~익$MC!$MD$w4\n"
.stringn "사, $w3사람 살려~$w2엇$MC!!$MD$K\n"
.stringn "$F1$FD$w4$F3$P$MC………$MD$w4\n"
.stringn "날 데인병으로 착각한 건가?$w4\n"
.stringn "$MC…$MD뭐, $w2아무래도 좋지만$MC……$MD$K$P흐아암$w2$Fc $MC…………$MD$K"
db 0
.align 4
//MYELL_HAAR_MAKAROV_C

