//0x1A9A4
Text_1A984:
.stringn "$R背景会話|$B支援背景|$<$F1$Fo$F1$FCL_LAY|$F1$P$MC!$MD$K\n"
.stringn "$F3$FCL_IKE2|$F3$P$MC…$MD라이, $w2왜 그래?$K\n"
.stringn "$F1$P$Fd아이크였냐$MC…$MD$w2$Fc\n"
.stringn "놀래키지 말라고.$K\n"
.stringn "$F3$P$MC……$MD요즘$w2\n"
.stringn "너무 긴장하는 거 아니야?$K\n"
.stringn "$F1$P$Fd왕도에 가까워지니까$MC…$MD$w4\n"
.stringn "데인 왕의$MC……$MD$K$P아니, $w3그 녀석보다는$w2\n"
.stringn "메달리온 쪽인가?$K$P어쨌든 $w2거기서 나오는\n"
.stringn "【부】의 기운 때문에$MC…$MD$w4\n"
.stringn "온몸에 소름이 끼쳐.$K\n"
.stringn "$F3$P라구즈는 예민한걸.$K\n"
.stringn "$F1$P$MC…$MD이곳에 왔는데 아무 반응도 없는\n"
.stringn "베오크가 더 무섭다고.$w4\n"
.stringn "어떻게 아무렇지도 않게 있을 수 있는 건지$MC…$MD$K$P이$MC…$MD$w4 위압감은$MC……$MD$w4\n"
.stringn "심상치 않아.$K\n"
.stringn "$F3$P나는 $w2잠시 비켜 주는 게 좋을까?$K\n"
.stringn "$F1$P그렇게 부탁$MC…$MD$K$P$MC……$MD아니, $w3역시 옆에 있어 줘.$w4\n"
.stringn "금방 $Fc가라앉을 테니까$MC……$MD$w3\n"
.stringn "$MC……………$MD$K\n"
.stringn "$F3$P$MC………$MD$K\n"
.stringn "$F1$P$MC…………$MD후우$w4\n"
.stringn "$Fd$MC…$MD미안해. $w4시간 쓰게 해서.$K\n"
.stringn "$F3$P괜찮아?$K\n"
.stringn "$F1$P그래. $w4이젠 좀 나아졌어.$K$P내가$w2\n"
.stringn "베오크에게 약한 모습을\n"
.stringn "보여주게 되다니$MC…$MD$w3 말세구만.$K\n"
.stringn "$F3$P날 $w2못 믿는 거야?$K\n"
.stringn "$F1$P$FS믿어.$w2$FA\n"
.stringn "$MC…$MD하지만 $w2완전히는 아니야.$K$P나는 거의 $w2\n"
.stringn "너를 인정하고 있지만$MC……$MD$K$P아직 다른 수아족 동료들처럼\n"
.stringn "대하는 건$MC…$MD$w3 좀 힘들어.$K\n"
.stringn "$F3$P나는 널 믿고 있어.$K\n"
.stringn "$F1$P$FS$MC……$MD정색하면서\n"
.stringn "말하는 거냐고~$w4\n"
.stringn "정$w2말, $w4너란 놈은$MC…$MD$K\n"
.stringn "$F3$P너란 놈은?$K\n"
.stringn "$F1$P$FA바보구나.$K\n"
.stringn "$F3$P뭐라고?$K\n"
.stringn "$F1$P$FS그렇게 $w2아무나\n"
.stringn "믿고 다니다간$MC…$MD$K$P언젠가 분명$w2\n"
.stringn "발목 잡힌다고$MC!$MD$w4\n"
.stringn "잊지 마라$MC!!$MD$K$F1$FD\n"
.stringn "$F3$P잠깐 $w2기다려$MC!$MD$w4 라이$MC!$MD$K$P$FS$MC…$MD정말, $w3대하기 쉬운 건지\n"
.stringn "까다로운 건지 알 수 없는 녀석이야.$K"
db 0
.align 4
//MYELL_IKE_LAY_A

//0x1A3F4
Text_1A3D4:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_IKE2|$F1$P라이.$K\n"
.stringn "$F3$FS$F3$FCL_LAY|$F3$P응?$w4 무슨 일이야?$K\n"
.stringn "$F1$P$MC……$MD혹시 훈련 중?$K\n"
.stringn "$F3$P오, $w2예리한데$MC!$MD$K$P노력가 아이크 장군님께\n"
.stringn "뒤처지지 않기 위해서 $w3\n"
.stringn "잠깐 훈련하고 있었지.$K\n"
.stringn "$F1$P좋은 마음가짐인걸.$K\n"
.stringn "$F3$P$FA아~$MC…$MD$w3 됐어.$w4\n"
.stringn "비아냥거리는 것도 안 통하는구나, $w2너.$K$P훈련은 $w2거짓말이야.$w4\n"
.stringn "이 모습으로 해 봤자 의미 없다고.$K\n"
.stringn "$F1$P그럼 $w2뭘 하고 있었어?$w4\n"
.stringn "근육을 풀고 있던 것처럼 보였는데.$K\n"
.stringn "$F3$P맞아. $w4몸을 쭉 늘여서\n"
.stringn "긴장을 풀었을 뿐이야.$K\n"
.stringn "$F1$P뭐야. $w4수아족의 $w2특별한\n"
.stringn "훈련 방법인 줄 알고 기대했었다고.$K\n"
.stringn "$F3$P기대를 저버려서 미안하지만$w3\n"
.stringn "화신하지 않으면$w2\n"
.stringn "나도 너랑 $w2그렇게 다를 거 없어.$K$P보는 대로 말이지.$K\n"
.stringn "$F1$P그래?$w4\n"
.stringn "꼬리가 있는 것밖에 차이가 없는 거구나.$K\n"
.stringn "$F3$P$FS꼬리는 좋다니까~$K$P갑자기 몸을 돌릴 때나$w2\n"
.stringn "높은 곳을 다닐 때,$w3\n"
.stringn "균형을 잡을 때 $w2엄청 편리해.$K$P꼬리 없는 삶이라니\n"
.stringn "생각할 수 없어.$K\n"
.stringn "$F1$P잘 때 $w2방해될 거 같은데.$K\n"
.stringn "$F3$P그건 맞아. 하지만$w4\n"
.stringn "좋은 방법이 있지.$K\n"
.stringn "$F1$P뭔데?$K\n"
.stringn "$F3$P그건 말이지$MC……$MD$K$FA$P$MC…$MD이런, $w3위험했어.$w4\n"
.stringn "아슬아슬하게 $w2유도 신문에\n"
.stringn "걸릴 뻔했구만.$K\n"
.stringn "$F1$P유도 신문은 무슨, $w2그냥 듣고 있기만 했는데.$K\n"
.stringn "$F3$P잘 들어, $w2아이크.$w4\n"
.stringn "이건 라구즈 종족 전체랑 관련된\n"
.stringn "비밀이야.$K$P베오크인 네게 $w2쉽게\n"
.stringn "폭로할 수는 없다고.$K\n"
.stringn "$F1$P그래.$w4\n"
.stringn "그럼 $w2뭐 됐어.$K$F1$FD\n"
.stringn "$F3$P야~아.$w4\n"
.stringn "여기선 더 물고 늘어져야지?$K"
db 0
.align 4
//MYELL_IKE_LAY_B

//0x19CA4
Text_19C84:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_LAY|$F3$FCL_IKE2|$F1$P여어, $w2아이크.$w4\n"
.stringn "그렇게나 강해졌는데 $w2또 훈련하는 거야?$K\n"
.stringn "$F3$P나는$MC…$MD$w2 검 훈련을 빠뜨린 적이 없어.$w4\n"
.stringn "아무리 짧은 시간이라도 여유가 생기면$w2\n"
.stringn "반드시 검을 휘두르도록 하고 있지.$K$P이러고 있으면 $w2정신이 집중돼서\n"
.stringn "진정되는 것도 있고.$K\n"
.stringn "$F1$P그렇구만.$w4\n"
.stringn "네 강함은$MC…$MD$K$P아버지에게서 물려받은\n"
.stringn "뛰어난 재능뿐만이 아니라$w4\n"
.stringn "꾸준한 노력이 있었기에 가능했던 거였어.$K$P어쩐지 $w2만날 때마다 점점 성장하더라.$w4\n"
.stringn "좋아 좋아$MC………$MD$K\n"
.stringn "$F3$P$MC…………$MD$K\n"
.stringn "$F1$P아, $w2나$MC…$MD$w2 혹시 방해되나?$w4\n"
.stringn "그럼 난 갈$MC……$MD$K\n"
.stringn "$F3$P잠깐.$w4\n"
.stringn "뭔가 볼일이 있어서 온 게 아니었어?$K\n"
.stringn "$F1$P$MC……$MD$w4조금 쓸데없는\n"
.stringn "걱정을 했을 뿐이야.$K$P너 말이지, $w2아무리 쉬라고 해도\n"
.stringn "쉴 생각을 안 하잖아.$K$P$MC…$MD지금도 $w2말을 걸면\n"
.stringn "멈추겠지 싶었는데$MC……$MD$w3\n"
.stringn "보기 좋게 실패한 것 같으니까 물러갈게.$K\n"
.stringn "$F3$P$MC……$MD뭐야. $w4내가\n"
.stringn "그렇게나 걱정되는 거야?$K\n"
.stringn "$F1$P$FA그야 당연하지$MC!!$MD$K\n"
.stringn "너같이 강압적이고 고집 센 장군은$w2\n"
.stringn "어디를 가도 없을걸.$K$P『귀찮아$MC!$MD$w4 마음대로 싸워$MC!$MD』라니$w2\n"
.stringn "그게 무슨 작전인고, $w3기가 막혀서 원.$K\n"
.stringn "$F3$P별로$MC…$MD$w3 나는 나야.$w4\n"
.stringn "다른 녀석들이랑 같지 않아도 상관없잖아.$K\n"
.stringn "$F1$P$MC……$MD봐봐, $w2이렇잖아.$w4\n"
.stringn "대체 뭐야?$w4 그 근거 없는 자신감은.$K$FS$P베오크는 $w2남들과 똑같이 행동하고\n"
.stringn "안심하는 종족이잖아$MC…$MD$w4\n"
.stringn "넌 왠지 혼자 붕~붕 $w3떠 있다고.$K\n"
.stringn "$F3$P그거참 미안하게 됐어.$K\n"
.stringn "$F1$P이렇게 말하면서도 $w3베오크를\n"
.stringn "신경 쓰고 있는 나도$MC…$MD$w4\n"
.stringn "혼자서 붕 뜬 $w2라구즈지만.$K$P물고기마냥 $w2둥둥 떠 있는 거지.$K\n"
.stringn "$F3$P$FS$MC……$MD훗$w4\n"
.stringn "고양이 주제에 $w2자신을 생선에 비유하지 말라고.$K\n"
.stringn "$F1$P오$MC!$MD$w3 웃었다.$w4\n"
.stringn "좋~아 좋아. $w4그 상태로 어깨에 $w2힘 좀 빼라고.$K\n"
.stringn "$F3$P알았어. $w4휴식할게.$w5\n"
.stringn "쉬는 김에 차라도 마시면 되겠지?$K\n"
.stringn "$F1$P물론이지. $w4밥 먹고 잠까지 자 두면 $w2더 좋고.$K"
db 0
.align 4
//MYELL_IKE_LAY_C

//0x1B7AC
Text_1B78C:
.stringn "$R背景会話|$B支援背景|$<$F3$FS$F3$FCL_LETHE|$F3$P왔다, $w2아이크.$K\n"
.stringn "$F1$FS$F1$FCL_IKE|$F1$P그래, $w2오늘도 하는 거지?$K\n"
.stringn "$F3$P너는 최근에\n"
.stringn "눈부신 성장을 보이고 있으니까.$w4\n"
.stringn "나도 질 수는 없지.$K\n"
.stringn "$F1$P그래?$w4\n"
.stringn "$MC……$MD너한테 칭찬받다니\n"
.stringn "기분이 좋은걸.$K\n"
.stringn "$F3$P$FA뭐야, $w4설마$MC……$MD$w3\n"
.stringn "처음 만났을 때의 일을\n"
.stringn "아직도 신경 쓰고 있는 건가?$K\n"
.stringn "$F1$P$FA그런 게 아니야.$K$P$FS넌 강하니까.$w4\n"
.stringn "그냥 강한 녀석한테\n"
.stringn "칭찬받는 게 기쁜 것뿐이야.$K\n"
.stringn "$F3$P$FS흥$MC……$MD$w4\n"
.stringn "그건 과대평가다.$K$P$FA$MC…………$MD$w5\n"
.stringn "저기, $w2아이크.$K\n"
.stringn "$F1$P$FA왜?$K\n"
.stringn "$F3$P이 싸움이 끝나면$MC……$MD$w3\n"
.stringn "모든 게 끝나고 나면$MC……$MD$w4\n"
.stringn "갈리아로 오지 않겠나?$K\n"
.stringn "$F1$P갈리아로?$K\n"
.stringn "$F3$P그래. $w4갈리아에서 단련한다면,$w2\n"
.stringn "너는 더욱더 강해질 수 있을 거다.$K$P갈리아의 환경은 $w2베오크에게\n"
.stringn "살아가기조차 힘든 땅이라고 하지.$K$P하지만 $w2그렇기 때문에 그 땅에서는\n"
.stringn "네가 아버지에게서 물려받은\n"
.stringn "그 검술을$MC……$MD$K$P한계까지 이끌어 낼 수 있을 거라고 생각한다.$K\n"
.stringn "$F1$P$MC…$MD단련 상대는 $w2당연히\n"
.stringn "레테가 해 주는 거겠지?$K\n"
.stringn "$F3$P네, $w1네가$MC…$MD$w2\n"
.stringn "그걸로 괜찮다면$MC…$MD$w4 나는 상관없다.$K\n"
.stringn "$F1$P그럼 $w2갈리아에서 사는 것도 나쁘지 않겠어.$K\n"
.stringn "$F3$P$FS좋아, $w2그럼 약속이다.$w4\n"
.stringn "언제든지 네가 마음 내킬 때 와라.$w4\n"
.stringn "나는 그때를 기대하고 있을 테니까.$K\n"
.stringn "$F1$P$FS알았어. $w4약속할게.$K"
db 0
.align 4
//MYELL_IKE_LETHE_A

//0x1B3B4
Text_1B394:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_LETHE|$F3$P어이.$K\n"
.stringn "$F1$FCL_IKE|$F1$P레테구나.$w4\n"
.stringn "무슨 일이야?$K\n"
.stringn "$F3$P전의 싸움,$w2 꽤 괜찮았다.$w4\n"
.stringn "생각보다 한 실력 하는 것 같군.$K\n"
.stringn "$F1$P나 말이야?$K\n"
.stringn "$F3$P그래. $w4여기 너 말고 누가 있지?$K\n"
.stringn "$F1$P$MC……$MD$w2의외인걸.$w4\n"
.stringn "난 너희들의 경이로운 힘에\n"
.stringn "항상 놀라고 있는데.$K\n"
.stringn "$F3$P서로 $w2완전히\n"
.stringn "다른 방식으로 싸우기 때문이겠지.$K$P움직임이나 생각을\n"
.stringn "읽을 수 없는 것도 그렇지만$MC…$MD$K$P너희들은 의외로 빠르고 세심한$w2\n"
.stringn "반사 신경을 가지고 있다.$K$P자신의 신체와는 별개인 칼날을\n"
.stringn "그렇게까지 잘 다루다니.$w4\n"
.stringn "단련의 성과라는 건가.$K\n"
.stringn "$F1$P그래.$w4\n"
.stringn "우리는 너희처럼 발톱이나 이빨을\n"
.stringn "가지고 있지 않으니까.$K$P어떻게든 무기를\n"
.stringn "자신의 신체의 일부로 만들기 위해$MC……$MD$K$P날마다\n"
.stringn "훈련을 빠뜨릴 수는 없어.$K\n"
.stringn "$F3$P흠$MC……$MD$w4 과연.$K$P그럼 나도 너희들을 본받아\n"
.stringn "단련에 힘써야겠군.$w4\n"
.stringn "$FS지난번에 했던 약속은 기억하고 있겠지?$K\n"
.stringn "$F1$P$FS물론이지.$w4\n"
.stringn "부탁해도 될까?$K\n"
.stringn "$F3$P이쪽이야말로 잘 부탁한다.$w4\n"
.stringn "서로 $w2봐주는 건 없는 걸로.$w4\n"
.stringn "알겠나?$K\n"
.stringn "$F1$P알았어.$w4\n"
.stringn "$MC……$MD간다$MC!$MD$K"
db 0
.align 4
//MYELL_IKE_LETHE_B

//0x1B000
Text_1AFE0:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_IKE|$F1$P좋아$MC……$MD$w2 이 쯤 해 둘까$MC……$MD$w4\n"
.stringn "$MC……$MD응?$K\n"
.stringn "$F3$FCL_LETHE|$F3$P열심히 단련하고 있는 것 같군.$K\n"
.stringn "$F1$P레테구나. $w4보고 있었어?$K\n"
.stringn "$F3$P그래, $w2흥미가 있다.$K$P앞으로는 베오크의 전투법을\n"
.stringn "얼마나 잘 알고 있는지가\n"
.stringn "승패를 가르게 될 테니까.$K$P네놈들에게 뒤처질 수는 없지.$K\n"
.stringn "$F1$P그래서 $w2날 연구하는 거야?$K\n"
.stringn "$F3$P안심해라, $w2뒤에서 네 목을\n"
.stringn "칠 생각은 없으니까.$K$P그런 건 아무런 의미도 없고,$w2\n"
.stringn "그렇게 얍삽하고 비겁한 수단을 쓰는 건\n"
.stringn "베오크들뿐이다.$K\n"
.stringn "$F1$P그렇구나.$w4\n"
.stringn "라구즈는 그럼 보통 정정당당하게\n"
.stringn "정면에서 싸우는 거야?$K\n"
.stringn "$F3$P$MC……$MD대개 그렇지.$w4\n"
.stringn "모두가 그렇다고 할 수는 없지만.$K$P뭐, $w2어떤 잔재주를 부리든\n"
.stringn "우리들은 냄새로 알아챌 수 있다.$w4\n"
.stringn "어둠 속으로 숨으려고 해도 소용없지.$K$P$MC……$MD코를 찌부러트린다면 얘기는 다르지만.$K\n"
.stringn "$F1$P레테.$w4\n"
.stringn "다음에라도 좋으니까$w2\n"
.stringn "수아족의 전투법에 대해서 알려 줄래?$K\n"
.stringn "$F3$P$FS그런 일이라면 맡겨라.$w4\n"
.stringn "전력으로 상대해 주지.$K\n"
.stringn "$F1$P$FS그래, $w2부탁해.$K"
db 0
.align 4
//MYELL_IKE_LETHE_C

//0x1C6D0
Text_1C6B0:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_OSCAR|$F1$P아이크.$K\n"
.stringn "$F3$FCL_IKE|$F3$P오스카?$w4\n"
.stringn "$MC……$MD무슨 일이야?$K\n"
.stringn "$F1$P$MC…………$MD$w4\n"
.stringn "괜찮아?$K\n"
.stringn "$F3$P괜찮아$MC……$MD$w2 문제없도록 할 테니까.$w4\n"
.stringn "내가 불안하게 한 거야?$K\n"
.stringn "$F1$P아니, $w2그런 건 아니야.$w4\n"
.stringn "그$MC…$MD$w2 점점 전쟁이 격렬해져서$MC…$MD$K$P얼마 전까지만 해도\n"
.stringn "우리가 이렇게 큰 사건에 말려들게 될 줄은\n"
.stringn "생각도 못했으니까.$K\n"
.stringn "$F3$P그래$MC……$MD$K$P아버지가 죽고$MC……$MD$w2\n"
.stringn "상당히 상황이 급박하게 돌아가고 있지.$w4\n"
.stringn "솔직히, $w2숨 돌릴 틈도 없어.$K\n"
.stringn "$F1$P그러니까$MC……$MD$w2 괜찮은 거지?$w4\n"
.stringn "아니, $w2괜찮지는 않겠지만$MC……$MD$w4\n"
.stringn "내가$MC……$MD$w2 뭔가 할 수 있는 게 없을까?$K\n"
.stringn "$F3$P$FS$MC……$MD고마워.$w4\n"
.stringn "너한테는 계속 고생만\n"
.stringn "시키게 되네.$K$P이런 미덥지 못한 단장을\n"
.stringn "지금까지 따라와 준 것만으로도\n"
.stringn "이미 충분해.$K\n"
.stringn "$F1$P아이크$MC……$MD$K\n"
.stringn "$F3$P앞으로도 함께해 줄래?$K\n"
.stringn "$F1$P$FS그래, $w2물론이지.$w4\n"
.stringn "나는, $w2그레일 단장님께서 말씀하셨듯이\n"
.stringn "너를 가족이라고 생각하고 있어.$K$P용병단은 $w2내가 돌아올 집이나 다름없으니까.$K\n"
.stringn "$F3$P$FA오스카$MC……$MD$K$P$FS오랜만에 $w2네가 해 준 밥을 먹고 싶어.$w4\n"
.stringn "나중에 또 미스트랑 같이 만들어 줄래?$K\n"
.stringn "$F1$P그래, $w2알았어.$w4\n"
.stringn "오늘은 실력 발휘 좀 해 볼까?$w4 기대해 줘.$K"
db 0
.align 4
//MYELL_IKE_OSCAR_A

//0x1C23C
Text_1C21C:
.stringn "$R背景会話|$B支援背景|$<$F3$FS$F3$FCL_OSCAR|$F3$P아이크.$w4\n"
.stringn "상태는 괜찮아?$K\n"
.stringn "$F1$FCL_IKE|$F1$P오스카구나.$w4\n"
.stringn "아, $w2잠시 싸우는 데에\n"
.stringn "고민하고 있는 게 있어서$MC……$MD$K\n"
.stringn "$F3$P나라도 괜찮다면 들어줄까?$K\n"
.stringn "$F1$P별건 아니고, $w2수아족이나 조익족을 상대로\n"
.stringn "어떻게 싸우면 좋을지\n"
.stringn "생각하고 있던 중이었어.$K\n"
.stringn "$F3$P$FA그렇구나$MC……$MD$w4\n"
.stringn "그건 나도 생각하고 있었어.$K$P모습을 바꾸는 순간$w2\n"
.stringn "우리가 상상하는 전투의 범주를\n"
.stringn "아득히 뛰어넘지.$K\n"
.stringn "$F1$P맞아.$K$P수아족은 그 발톱으로 일격에\n"
.stringn "바위를 부수는 것도,\n"
.stringn "땅을 가르는 것도 가능해.$K$P조익족은 우리의 사각을\n"
.stringn "쉽게 찾아내겠지.$K$P게다가 $w2하늘로 도망쳐 버리면\n"
.stringn "내 검술은 아무 의미도 없게 돼$MC…$MD$K\n"
.stringn "$F3$P$FS$MC……$MD역시 $w2가장 좋은 건\n"
.stringn "그들에게 연습 상대를 부탁해 보는 거겠지.$w4\n"
.stringn "어려운 일이지만$MC……$MD$K\n"
.stringn "$F1$P$MC……$MD어렵다고?$w4\n"
.stringn "그래?$K\n"
.stringn "$F3$P$FA아$MC……$MD$w5\n"
.stringn "아니, $w2응.$w4\n"
.stringn "$FS$MC……$MD아이크는$MC……$MD$w2 대단하네.$K\n"
.stringn "$F1$P?$w4 오스카한테 대단하다는 소리를\n"
.stringn "들으니 기분이 이상한걸.$K$P너는 뭐든지 할 수 있고$w2\n"
.stringn "아는 것도 많잖아.$K\n"
.stringn "$F3$P내가 하는 일들은 $w2노력하면\n"
.stringn "누구나 할 수 있는 것들이야.$K$P$MC……$MD너는 역시 $w2단장님의 아들이구나.$w4\n"
.stringn "널 본받고 싶다고 $w2생각하게 돼.$K\n"
.stringn "$F1$P$MC…………$MD$K"
db 0
.align 4
//MYELL_IKE_OSCAR_B

//0x1BCD8
Text_1BCB8:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_IKE|$F3$P오스카,$w2\n"
.stringn "훈련하는데 좀 도와줄$MC……$MD$K$P?$w4\n"
.stringn "어디 가는 거야?$K\n"
.stringn "$F1$FCL_OSCAR|$F1$P$FS미안해, $w2아이크.$w4\n"
.stringn "오늘은 내가 식사 담당이야.$K\n"
.stringn "$F3$P미스트는?$K\n"
.stringn "$F1$P빨래가 아직 안 끝난 것 같아.$w4\n"
.stringn "요리는 오랜만이라서$w2\n"
.stringn "실력이 줄은 게 아닐까 모르겠네.$K\n"
.stringn "$F3$P오스카의 요리는 오랜만인걸.$w4\n"
.stringn "기대돼.$K\n"
.stringn "$F1$P$MC…$MD정말이야?$K\n"
.stringn "$F3$P응. $w4왜 그래?$w4\n"
.stringn "네 요리는 항상 맛있었어.$K\n"
.stringn "$F1$P내가 느끼기로$MC…$MD$K$P항상 반응이 없는 세네리오와$w2\n"
.stringn "원래 $w2내 요리에 익숙한\n"
.stringn "동생 두 명은 제외하고$MC…$MD$K$P단장님, $w2티아마트 부장님, $w2아이크,$w2\n"
.stringn "가트리는 $w3감사히 먹어 주긴 했지만$MC…$MD$w4\n"
.stringn "먹을 수만 있다면 뭐든 상관없다는 느낌이었거든.$K$P매번 맛의 차이를 미세하게 알아채고\n"
.stringn "감상을 말해 준 건$MC…$MD$K$P미스트와 시논, $w2그리고\n"
.stringn "킬로이뿐이었어.$K\n"
.stringn "$F3$P딱히 말을 안 했을 뿐이지,$w2\n"
.stringn "맛은 제대로 느끼고 있다고? $w4일단은.$K$P식사 담당이 오스카에서\n"
.stringn "미스트로 교체됐던 날의 저녁밥은$MC…$MD$w3\n"
.stringn "지금 생각해도 속이 울렁거려.$K$P아버지조차도 진땀을 흘리면서\n"
.stringn "먹었던 것 같고.$K$P그러고 보니$w2\n"
.stringn "미스트의 요리도 최근에는 괜찮아졌지.$K\n"
.stringn "$F1$P맞아, $w2네가 검 실력을 연마하는 것처럼$w4\n"
.stringn "뒤에서 열심히 특훈하고 있어.$K$P맛있다$w2고 말해 주는 건\n"
.stringn "만드는 사람 입장에서 가장 큰 격려가 되니까.$w3\n"
.stringn "그걸 위해서라도, 알지?$K\n"
.stringn "$F3$P그렇구나$MC……$MD$w4\n"
.stringn "$FS앞으로는 제대로\n"
.stringn "맛있다고 말할게.$K\n"
.stringn "$F1$P하하,$w2 고마워.$K"
db 0
.align 4
//MYELL_IKE_OSCAR_C

//0x1D804
Text_1D7E4:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_IKE2|$F3$P뤼시온.$K\n"
.stringn "$F1$FCL_RIEUSION|$F1$P$MC……$MD아이크$MC…$MD$w3 알고 있다.$K$P자기 몸이니까$w4\n"
.stringn "누구보다도 잘 알고 있다.$K$P$MC………$MD하지만, $w2부디$MC…$MD$w3\n"
.stringn "마지막까지$MC…$MD$w2 함께 하게 해 줘.$K\n"
.stringn "$F3$P$MC…………$MD$w4\n"
.stringn "모든 게 끝나는 순간에$w2\n"
.stringn "네 목숨도 끝나는 게 아니라면 말이지$MC…$MD$K\n"
.stringn "$F1$P$MC……$MD$w4\n"
.stringn "메달리온이 안정되면$MC…$MD$w3\n"
.stringn "내 몸도 $w2원래대로 돌아갈 거다.$K$P괜찮다, $w3내 정신력은 아직$MC…$MD$w2\n"
.stringn "조금도 꺾이지 않았으니까.$K$P아슈나드와 만나서$MC…$MD$w4\n"
.stringn "사건의 진상을 $w2밝혀내고야 말겠다.$K\n"
.stringn "$F3$P$FS뤼시온.$w4\n"
.stringn "내가 널 도울게.$K\n"
.stringn "$F1$P나를 특별 취급하지 말라고 했$MC…$MD$K\n"
.stringn "$F3$P그러니까, $w2너도 날 도와줘.$K\n"
.stringn "$F1$P$MC!$MD$K\n"
.stringn "$F3$P우리가 각자 가지고 있는 힘은$w2\n"
.stringn "전혀 달라.$K$P서로 돕는다면$MC…$MD$w3\n"
.stringn "앞으로의 전투에서도 $w2승리할 수 있을 거야.$K\n"
.stringn "$F1$P$FS$MC……$MD그렇$MC…$MD$w4군.$w4\n"
.stringn "알았다. $w4잘 부탁하지.$K\n"
.stringn "$F3$P이쪽이야말로 $w2마지막까지 잘 부탁해.$K"
db 0
.align 4
//MYELL_IKE_RIEUSION_A

//0x1D2D8
Text_1D2B8:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_IKE2|$F3$P뤼시온$MC!$MD$K\n"
.stringn "$F7$FCL_RIEUSION|$F7$P여기다, $w2아이크.$K$F7$FD\n"
.stringn "$F1$FS$F1$FCL_RIEUSION|$F1$P전투에 관해서 얘기할 게 있나?$K\n"
.stringn "$F3$P그래. $w4다음 작전에서는$w2\n"
.stringn "네 힘이 승패를 좌우하게 될 거라고$w2\n"
.stringn "얘기하러 왔어. $w4몸은 괜찮아?$K\n"
.stringn "$F1$P$MC…$MD그래.$K$P하늘 높이 올라가 있으면$w2\n"
.stringn "조금은 【부】의 기운으로부터 벗어날 수 있는 것 같다.$w4\n"
.stringn "지금도 바람을 쐬고 오니 $w2꽤 편해졌지.$K$P다음 전투까지는 버틸 수 있을 거다.$K\n"
.stringn "$F3$P$MC……$MD네 모습을 보고 있으니$w3\n"
.stringn "어떻게 해서든 널 싸우지 않게 하려던\n"
.stringn "페니키스 왕의 기분을 알 것 같아.$K$P무리하게 해서 $w2정말로 미안해.$K\n"
.stringn "$F1$P$FA$Fh스스로 원해서 이곳에 있는 나에게$MC…$MD$w3\n"
.stringn "그렇게 말하는 건 모욕이다.$K\n"
.stringn "$F3$P$MC……$MD그랬었지, $w3미안.$w4\n"
.stringn "네가 이런 배려를 싫어한다는 건\n"
.stringn "알고 $w3있었는데 말이지$MC……$MD$K\n"
.stringn "$F1$P$Fc$MC…$MD네가 아니었다면$w2\n"
.stringn "진작에 때려서 입을 다물게 했을지도 모른다.$K\n"
.stringn "$F3$P$MC……$MD백로 민족은 $w3아예 공격을\n"
.stringn "못하는 게 아니었어?$K\n"
.stringn "$F1$P$Fd$MC…………$MD$w3\n"
.stringn "때리는 것 정도는 할 수 있다. $w4다만$MC…$MD$K\n"
.stringn "$F3$P다만?$K\n"
.stringn "$F1$P맞은 상대보다$w2\n"
.stringn "때린 내 주먹이 더 피해가 크다.$K\n"
.stringn "$F3$P예를 들면?$K\n"
.stringn "$F1$P$MC…$MD전에 $w2타나스 공작의 안면을\n"
.stringn "때렸을 때$MC……$MD$K$P놈은 코피를 흘릴 뿐이었지만$w2\n"
.stringn "나는 손등뼈에 $w3금이 갔었다$MC…$MD$K\n"
.stringn "$F3$P$MC…………$MD$K\n"
.stringn "$F1$P$MC…………$MD$K\n"
.stringn "$F3$P사나이구만.$K\n"
.stringn "$F1$P뭐, $w3그렇지.$K"
db 0
.align 4
//MYELL_IKE_RIEUSION_B

//0x1CB60
Text_1CB40:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_IKE2|$F1$P뤼시온.$K\n"
.stringn "$F3$FS$F3$FCL_RIEUSION|$F3$P아이크인가. $w4무슨 일이지?$K\n"
.stringn "$F1$P상태를 보러 왔을 뿐이야.$w4\n"
.stringn "좀 어때?$K\n"
.stringn "$F3$P괜찮다. $w4아무런 문제도 없어.$K\n"
.stringn "$F1$P$MC…$MD문제없다고 하기에는$w2\n"
.stringn "설득력이 없는 안색인데.$K\n"
.stringn "$F3$P$FA$MC……$MD우리 백로 민족은 $w2【정】에 가까운 존재.$w4\n"
.stringn "【부】의 기운이 넘치는 전장에서는$MC…$MD$w4\n"
.stringn "상태에 만전을 기할 수 없다.$K$P그렇지만 $w2지쳐서 쓰러지지 않도록\n"
.stringn "잘 휴식하고 있으니$MC…$MD$w3 부디 마지막까지\n"
.stringn "함께 싸우게 해 줘. $w4부탁한다.$K\n"
.stringn "$F1$P본인이 조심하고 있으면$w2\n"
.stringn "나는 불만은 없지만$MC…$MD$K$P몸에 맞는 음식이라든지,$w3\n"
.stringn "조금이라도 도움되는 게 있다면$w2\n"
.stringn "어떻게든 준비해 줄 수 있다고?$K\n"
.stringn "$F3$P$FA$MC…$MD그 마음만으로도 충분하다.$K$P실은 나도 옛날에$MC…$MD$w2 이 연약한 몸에\n"
.stringn "싫증이 나서$MC……$MD$w4\n"
.stringn "여러 가지를 시도해 봤었다.$K$P고기, $w2생선, $w2술$MC…$MD$w4 티반이 좋아하는 것들을\n"
.stringn "늘어놓고 $w2하나씩 먹었지.$K\n"
.stringn "$F1$P$MC…$MD결과는 어땠는데?$K\n"
.stringn "$F3$P10일 동안 사경을 헤맸다.$K$P아무래도 우리 백로 민족은$w2\n"
.stringn "신선한 나무 열매 외에는 \n"
.stringn "잘 안 받는 체질인 것 같더군.$K\n"
.stringn "$F1$P$MC…$MD목숨을 건 행위였구나.$K\n"
.stringn "$F3$P티반처럼 되고 싶었다.$w3\n"
.stringn "크고 늠름한 몸과 $w2날개$MC…$MD$K$P내가 그것들을 가지고 해 달라고,$w3\n"
.stringn "직접 베그니온에 쳐들어가$w2\n"
.stringn "인간들에게 복수할 수 있게 해 달라고$MC…$MD$K$P매일 밤 $w2여신에게 기도하며$MC…$MD$w2 빌었다.$w4\n"
.stringn "하지만$MC………$MD$w2 이루어지지 않았지.$K\n"
.stringn "$F1$P$MC…$MD왠지 $w2네 그 기분이\n"
.stringn "이해가 가긴 하지만$MC……$MD$w4\n"
.stringn "오히려 잘된 일 아니야?$K\n"
.stringn "$F3$P어째서지?$K\n"
.stringn "$F1$P싸움의 기운만으로도 몸이 망가지는 네가,$w3\n"
.stringn "직접 $w2상대방을 다치게 하는\n"
.stringn "짓을 한다면$MC…$MD$w3 가볍게 끝나지는 않았을 거야.$K\n"
.stringn "$F3$P$MC……$MD그렇군.$K$P절망에 지배당했을 때의 나는$w3\n"
.stringn "목숨과 맞바꿔도 상관없다고 $w2\n"
.stringn "진지하게 생각했었지.$K$P하지만$MC…$MD$w3 지금은 이렇게 살아 있어서 다행이라고 생각한다.$w4\n"
.stringn "살아 있었기에 $w2리아네를 만날 수 있었으니까.$K\n"
.stringn "$F1$P$FS뤼시온$MC…$MD$w3 너,$w2\n"
.stringn "생각했던 것보다 남자다운데.$K\n"
.stringn "$F3$P$FS정신력만큼은$w2\n"
.stringn "남에게 뒤지지 않을 자신이 있다.$K"
db 0
.align 4
//MYELL_IKE_RIEUSION_C

//0x1EAE8
Text_1EAC8:
.stringn "$R背景会話|$B支援背景|$<$F5$Fc$F5$FCL_SENERIO|$F3$FCL_IKE2|$F3$P$MC……$MD$K\n"
.stringn "$F5$P$MC……$MD$K\n"
.stringn "$F3$P$MC…$MD지난번 이야기를 듣고,$w2\n"
.stringn "내 나름대로 없는 지혜를 짜서 생각해 봤는데,$K$P역시 $w2모르겠어.$K$P네가 자신의 존재에 대해$w2\n"
.stringn "뭔가 불만을 가지고 있다는 것 말고는\n"
.stringn "아무것도 알 수가 없었어.$K$P그러니까 $w2역시 얘기를 듣고 싶어.$K\n"
.stringn "$F5$FD$F1$FCL_SENERIO|$F1$P$MC……$MD어째서$w2\n"
.stringn "그냥 놔두지 않으시는 건가요?$K$P$Fh제게는$MC…$MD$w3 당신밖에\n"
.stringn "의지할 상대가 없는데$MC……$MD$K$P$Fc당신에게까지 미움받으면$MC……$MD$w3\n"
.stringn "더 이상 살아갈 수 없는데$MC……$MD$K\n"
.stringn "$F3$P그래서야.$w4\n"
.stringn "너는 나 말고 누구에게도\n"
.stringn "마음을 열려고 하지 않아.$K$P그러니까 $w2내가 어떻게 하지 않으면\n"
.stringn "너는 언제까지나\n"
.stringn "고통을 껴안고 있겠지.$K\n"
.stringn "$F1$P$Fd$MC………$MD아이크$MC…$MD$w4\n"
.stringn "저는$MC…$MD$w4 저는$MC……$MD$K\n"
.stringn "$F3$P나를 믿어 줘.$w4\n"
.stringn "네가 어떤 사람이라고 해도,$w2\n"
.stringn "내가 너를 인정해 줄 테니까.$K\n"
.stringn "$F1$P$Fh$MC………$MD으$MC……$MD$w4\n"
.stringn "$Fc$MC………………………$MD$w5\n"
.stringn "$MC…………$MD$w2네$MC……$MD$K$w3$P$MC………………$MD$w4\n"
.stringn "$Fh$MC…$MD저는$MC…$MD$w2 아마도$MC……$MD$w4\n"
.stringn "【인붙이】입니다.$K\n"
.stringn "$F3$P【인붙이】$MC…$MD$w4\n"
.stringn "그게 $w2뭔데?$K\n"
.stringn "$F1$P$Fc베오크와 라구즈의$MC…$MD$w2 혼혈입니다$MC……$MD$w4\n"
.stringn "여신의 이치를 거스른 이유로$MC…$MD$K$P어느 종족에게나$MC…$MD$w3\n"
.stringn "미움을 받는 꺼림칙한 존재죠$MC……$MD$K\n"
.stringn "$F3$P$MC……$MD잘 모르겠지만,$w2\n"
.stringn "어쨌든 $w2너는\n"
.stringn "라구즈의 핏줄을 이어받았다는 거지?$K\n"
.stringn "$F1$P$Fd$MC…$MD네.$K\n"
.stringn "제 이마에 있는 증표가 $w2그 증거입니다$MC…$MD$w4\n"
.stringn "베그니온의 대신전 마나일에서$MC……$MD$w3\n"
.stringn "오래된 책을 조사하다가$MC…$MD$w2 알게 되었어요.$K$P그 전까지는$MC…$MD$w4\n"
.stringn "마도사가 $w2더 강한 마력을 얻기 위해\n"
.stringn "새기는 【정령의 부적】이라고 생각했었죠$MC……$MD$K$w2$P현자가 $w2그것에 눈을 떴다고\n"
.stringn "자주 말했으니까요$MC………$MD$K\n"
.stringn "$F3$P그래서?$K\n"
.stringn "$F1$P네$MC…?$MD$w4 그래서, $w2라뇨?$K\n"
.stringn "$F3$P네게 $w2라구즈의 피가 섞여 있고\n"
.stringn "인 뭐시기$MC…$MD$w2라는 건 알겠어.$w4\n"
.stringn "그래서 $w2그게 어쨌다는 거야?$K\n"
.stringn "$F1$P그게 어쨌다니$MC…$MD$w5\n"
.stringn "불쾌하지 않으신가요$MC!?$MD$K$P자신의 곁에$MC…$MD$w2 이런\n"
.stringn "어떤 것에도 속하지 않는 존재가 있다는 게$MC…$MD$MC!$MD$K\n"
.stringn "$F3$P$MC………$MD아니.$w4\n"
.stringn "전혀 이상하지 않아.$w4\n"
.stringn "$FS세네리오는 세네리오야.$K$P우리 용병단의 유능한 참모지.$w4\n"
.stringn "네가 없으면,$w2\n"
.stringn "금세 단을 이어나갈 수 없게 될 거고.$K\n"
.stringn "$F1$P$Fh$MC…………$MD$w2아이크$MC…$MD$w4\n"
.stringn "$Fc저는$MC…$MD$w3 그래서 당신을$MC……$MD$K\n"
.stringn "$F3$P응?$K\n"
.stringn "$F1$P$Fh$FA갈리아였어요$MC…$MD$w4\n"
.stringn "제가 현자와 살고 있었던 곳은$MC…$MD$w2\n"
.stringn "갈리아에 있는 작은 마을이었습니다.$K$P$Fc그곳에는 $w2몇몇 베오크가\n"
.stringn "모여서 살고 있었고$MC……$MD$K\n"
.stringn "$F3$P$FA$MC…$MD갈리아?$w4\n"
.stringn "너, $w2그럼$MC…$MD$K\n"
.stringn "$F1$P현자가 죽고$MC……$MD$w2 말을 못하는 저는\n"
.stringn "굶어 죽어 가고 있었어요$MC……$MD$K$P$Fd그런 저에게\n"
.stringn "당신만이 $w2손을 내밀어 주었죠.$K$P$FS그래서$MC……$MD$w4\n"
.stringn "당신이 $w2제게 있어\n"
.stringn "특별한 사람이 된 겁니다$MC……$MD$K"
db 0
.align 4
//MYELL_IKE_SENERIO_A

//0x1DEF0
Text_1DED0:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_SENERIO|$F3$P$MC………$MD$K\n"
.stringn "$F1$FCL_IKE|$F1$P세네리오, $w2잠시 시간 돼?$K\n"
.stringn "$F3$P$FS네, $w2네에.$w4\n"
.stringn "무슨 일이신가요, $w2아이크?$K\n"
.stringn "$F1$P$MC…$MD이제 그만 $w2말해 주면 안 될까?$w4\n"
.stringn "왜 그렇게\n"
.stringn "우울해하고 있는 건지.$K\n"
.stringn "$F3$P$FA아$MC…$MD$w4 $MC………$MD$K\n"
.stringn "$F1$P$MC………$MD$K\n"
.stringn "$F3$P$MC……$MD$w2저기$MC……$MD$w4\n"
.stringn "$MC……………………$MD$K$w4$P$MC…$MD아이크는, $w2자신이 누구인지$MC…$MD$w4\n"
.stringn "고민해 본 적 없나요?$K\n"
.stringn "$F1$P자신이 누구인지$MC…?$MD$w4\n"
.stringn "$MC…$MD글쎄, $w2딱히 없는데.$K$P아버지와 엄마의 아들이고, $w2그거에\n"
.stringn "불만을 가져 본 적도 없고.$K\n"
.stringn "$F3$P$FS$MC……$MD부모님의 존재는 $w2크죠.$K$P$FA자신의 어린 시절을 아는 사람의\n"
.stringn "존재는$MC…$MD$K$P유아가 자아를 형성해 가는 과정에$w2\n"
.stringn "꼭 필요하다고 생각합니다.$K$P아무것도 모르는 생물이 $w2확신을 가진\n"
.stringn "한 사람이 되기 위해서$MC…$MD$w2그걸 긍정해 주고\n"
.stringn "후원해 주는 어른이 없다면$MC……$MD$K$P아이는 자신이 나아가는 길을 알 수 없게 되고$MC…$MD$w2\n"
.stringn "자신이 대체 무엇인지도\n"
.stringn "알 수 없게 될 거예요.$K\n"
.stringn "$F1$P세네리오는 $w2부모에 대한 기억이 없어?$K\n"
.stringn "$F3$P네. $w4저를 키운 여자는,$w2\n"
.stringn "적어도 저를 낳은 자가 아니에요.$K$P그 여자의 말버릇은$MC…$MD$K$P『왜 내가?』$w3\n"
.stringn "『세상은 불공평해』$w3\n"
.stringn "『가까이 오지 마』$MC…$MD$w2였거든요.$K$P일말의 애정도 없이$w2\n"
.stringn "뭔가의 의무감에 휩싸여서\n"
.stringn "저를 돌보는 것 같았죠.$K\n"
.stringn "$F1$P$MC……$MD$K\n"
.stringn "$F3$P그리고$MC…$MD$w2 네 살 정도 됐을 때,$w2\n"
.stringn "부근에 살고 있던 현자가$MC……$MD$w3\n"
.stringn "저를 데려가겠다고 제안했죠.$K$P제게$MC…$MD$w4 보기 드문\n"
.stringn "마도의 재능이 있다고 하면서요$MC…$MD$w3\n"
.stringn "여자는 매우 기뻐하며 현자에게 저를 양보했어요.$K$P잘 기억하고 있습니다.$K$P제가 그 여자의 웃는 얼굴을 본 건\n"
.stringn "그때뿐이었어요.$w4\n"
.stringn "정말 기쁜 것 같더군요.$K$P귀찮은 것을 쫓아낼 뿐만 아니라$w2\n"
.stringn "사례금까지\n"
.stringn "손에 넣을 수 있었으니까요.$K\n"
.stringn "$F1$P$MC……$MD$K\n"
.stringn "$F3$P현자는 죽을 때가 가까워졌고,$w2\n"
.stringn "자신의 지식을 이어받을 사람을 구했습니다.$K$P시간이 없다고 들으면서,$w2\n"
.stringn "먹고 자는 시간도 아껴 가며 마도 수행을 끝내면\n"
.stringn "어느새 새벽이 되어 있었습니다.$K$P그래도$MC…$MD$w2 제게 있어선$w2\n"
.stringn "그 여자와의 생활보다 훨씬 나았어요.$K$P자신이 누구인지\n"
.stringn "돌아볼 여유조차 없었으니까요.$K$P2년 후, $w2현자가 죽었을 때$MC……$MD$w3\n"
.stringn "저는 약간의 마도를 쓸 수 있었어요.$K$P현자의 집에 먹을 것이 떨어져서,$w2\n"
.stringn "밖으로 나가 마을로 갔습니다.$K$P그리고$MC……$MD$w4\n"
.stringn "저는$MC…$MD$w2 처음으로 깨달았죠.$w4\n"
.stringn "자신이 한 마디도 말할 줄 모른다는 것을.$K\n"
.stringn "$F1$P$MC…$MD세네리오$MC……$MD$K\n"
.stringn "$F3$P읽고 쓸 줄은 알았어요.$w4\n"
.stringn "상대방의 말도 이해할 수 있었죠.$w4\n"
.stringn "하지만$MC…$MD$w2 스스로는 아무 말도 할 줄 몰랐어요.$K$P어쩔 수 없었죠.$K$P여자도 현자도, 제게 일방적으로\n"
.stringn "말을 던지기만 했을 뿐 거기에 제가\n"
.stringn "대답할 필요는 없다고 생각했으니까요$MC……$MD$K\n"
.stringn "$F1$P$MC…$MD세네리오$MC!!$MD$K\n"
.stringn "$F3$P$MC!$MD$K$P$MC…$MD아$MC…$MD$w4\n"
.stringn "죄, $w2죄송합니다$MC……$MD$w4\n"
.stringn "이런 시시한 이야기를$MC…$MD$K\n"
.stringn "$F1$P시시하지 않아.$w4\n"
.stringn "그게 네가$MC…$MD$w2\n"
.stringn "우울해하고 있었던 이유야?$K$P혹시 $w2어렸을 때$w2\n"
.stringn "네가 살았던 곳은\n"
.stringn "베그니온이었어?$K\n"
.stringn "$F3$P$MC…$MD아니에요.$w4\n"
.stringn "$MC……$MD제가 말하고 싶었던 건$MC…$MD$w4\n"
.stringn "$MC………………$MD$K$w3$P아뇨, $w2이제 됐어요.$w4\n"
.stringn "$Fc죄송해요, $w2실례하겠습니다.$K$F3$FD\n"
.stringn "$F1$P잠깐, $w2세네리오$MC…$MD$MC!$MD$K$P$MC…………$MD$K"
db 0
.align 4
//MYELL_IKE_SENERIO_B

//0x1DBC0
Text_1DBA0:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_SENERIO|$F3$FCL_IKE|$F1$P그래서 $w2이번 지출은$MC…$MD$w3\n"
.stringn "물자도 부족하고$MC……$MD$K$P$MC………$MD아이크?$w4\n"
.stringn "제대로 듣고 있는 건가요?$K\n"
.stringn "$F3$P응?$w4\n"
.stringn "아, $w2못 들었어.$w4\n"
.stringn "미안해.$K\n"
.stringn "$F1$P$MC………$MD$K\n"
.stringn "$F3$P미안하지만 $w2다시 한번\n"
.stringn "처음부터 보고해 줘.$K\n"
.stringn "$F1$P좀 $w2쉬시는 게 어때요?$w4\n"
.stringn "굉장해 피곤해 보여요.$K\n"
.stringn "$F3$P$MC…$MD그래 보여?$K\n"
.stringn "$F1$P$FS네.$w4\n"
.stringn "상태가 안 좋을 때의 아이크는$w2\n"
.stringn "미간의 주름이 깊어지니까요.$K\n"
.stringn "$F3$P$MC…$MD묘한 판단인걸.$K\n"
.stringn "$F1$P아무튼 $w2휴식을 취해 주세요.$w4\n"
.stringn "나머지 일은\n"
.stringn "제가 잘 처리할 테니까요.$K\n"
.stringn "$F3$P그럼, $w2그렇게 해 줘.$K\n"
.stringn "$F1$P네.$K\n"
.stringn "$F3$P$MC……$MD다른 녀석들한테도$w2\n"
.stringn "이렇게 친절하면\n"
.stringn "좋을 텐데$MC……$MD$K\n"
.stringn "$F1$P$FA네? $w2뭐라고 하셨나요?$K\n"
.stringn "$F3$P$FS아무것도 아니야.$w4\n"
.stringn "그럼, $w2부탁해.$K\n"
.stringn "$F1$P$MC…$MD네.$K"
db 0
.align 4
//MYELL_IKE_SENERIO_C

//0x1FEDC
Text_1FEBC:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_IKE|$F3$FCL_TIAMAT|$F1$P저기, $w2티아마트$MC……$MD$w4\n"
.stringn "고마워.$K\n"
.stringn "$F3$P? $MC……$MD$w4왜 그래?$w2 아이크.$w4\n"
.stringn "새삼스럽게$MC……$MD$K\n"
.stringn "$F1$P내일 얘기할 수 있을진 장담 못 하니까.$w4\n"
.stringn "생각이 났을 때 전해 두고 싶었어.$w4\n"
.stringn "$MC……$MD$w2들어 줄래?$K\n"
.stringn "$F3$P어, $w2으응$MC……$MD$w2 상관없어$MC……$MD$w4\n"
.stringn "그런데 갑자기 왜 그래?$K$P내가 $w2너한테 감사받을 만한 일을\n"
.stringn "한 적이 있었나$MC……?$MD$K\n"
.stringn "$F1$P그래.$K$P너는$MC……$MD$w2 갈리아에서 엄마를 잃고$w2\n"
.stringn "어린 나와 미스트를 키워야 하는 아버지를\n"
.stringn "도와, $w2용병단을 만들어 주었어.$K$P그 일에 대해$MC……$MD$w2 감사를 전하고 싶었어.$K\n"
.stringn "$F3$P$MC…………$MD$K\n"
.stringn "$F1$P지금까지 $w2아무것도 모르고 지내서 미안해.$K$P네가 지켜 주었기에\n"
.stringn "존재하는 것들을 $w2당연하다는 듯이\n"
.stringn "누리고 있었어.$K\n"
.stringn "$F3$P$MC……$MD아니야, $w2아이크.$w4\n"
.stringn "나는 자신을 위해서$MC……$MD$K\n"
.stringn "$F1$P$FS알고 있어.$w4\n"
.stringn "아버지를$MC……$MD$w3 사랑하고 있었던 거지?$K\n"
.stringn "$F3$P$MC……$MD$MC!!$MD$K\n"
.stringn "$F1$P$FA만약 $w2그게 아니라\n"
.stringn "다른 생각이 있었다고 해도\n"
.stringn "지금 $w2나는 이렇게 살아 있어.$K$P그 사실에\n"
.stringn "감사하는 마음은 변하지 않아.$K$P아버지가 강했어도, $w2네가 도와주지 않았다면\n"
.stringn "어쩌면 우리와 함께\n"
.stringn "죽었을지도 몰라.$K$P아버지의 목숨을, $w2그때 $w2그곳에서\n"
.stringn "칠흑의 기사에게 쓰러질 때까지$MC……$MD\n"
.stringn "지켜 주고 있었던 거구나.$K$P$FS$MC………$MD정말로, $w2고마워.$K\n"
.stringn "$F3$P$MC……$MD $w3$MC……$MD $w3$MC……$MD$K$w2$P$Fc흐, $w2흑$MC………$MD$w2 흐윽$MC…$MD$K\n"
.stringn "$F1$P$FA아버지와는 달리 $w2나에겐 아직 경험도 힘도\n"
.stringn "없지만$MC……$MD$w4 괜찮다면 앞으로도\n"
.stringn "우리를 이끌고, $w2지지해 줄 수 있을까?$K$P$FS$MC……$MD부탁해.$K\n"
.stringn "$F3$P$Fd$FS응$MC……$MD$w4\n"
.stringn "그래, $w2물론이지$MC……$MD$w2 아이크$MC……$MD$K"
db 0
.align 4
//MYELL_IKE_TIAMAT_A

//0x1F910
Text_1F8F0:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_IKE|$F3$P티아마트. $w4잠깐 괜찮을까?$K\n"
.stringn "$F1$FCL_TIAMAT|$F1$P아이크?$w4\n"
.stringn "나한테 볼일이 있는 거야?$K\n"
.stringn "$F3$P잊어버렸어?$w4\n"
.stringn "저번에 $w2얘기했었잖아.$K$P너와 아버지는\n"
.stringn "언제부터 서로 알게 된 거냐고.$K\n"
.stringn "$F1$P아, $w2그래$MC……$MD$w4\n"
.stringn "그러고 보니 $w2말해 주기로 했었지$MC……$MD$K\n"
.stringn "$F3$P$MC……$MD말하기 싫다면$w4\n"
.stringn "억지로 물어보진 않겠지만$MC……$MD$K\n"
.stringn "$F1$P싫다, $w2기보다는$MC……$MD$w4\n"
.stringn "자신의 과거를 말하는 게 어색해서 그래.$K$P$MC……$MD그래도$MC……$MD$K$P$FS그 사람에 대해 $w2네가 조금이라도 더\n"
.stringn "많이 알고 있었으면 하니까$MC……$MD$w4\n"
.stringn "얘기해 줄게.$K\n"
.stringn "$F3$P그래, $w2부탁해.$K\n"
.stringn "$F1$P내가 아직 크리미아 기사였을 때$MC……$MD$w3\n"
.stringn "크리미아와 갈리아의 교환 무관에 지원해서,$w2\n"
.stringn "갈리아에 머무는 동안에 만났어.$K$P왕궁에서 열린 합동 투기로\n"
.stringn "그 사람의 강함을 목격하게 되었지.$K$P덮쳐 오는 여러 강호들을 $w2마치\n"
.stringn "어린아이 다루듯이 쓰러뜨려 갔어.$K$P상대는 도대체 자신이 왜 쓰러져 있는지도\n"
.stringn "모를 정도로$MC……$MD$w2 훌륭한 검술이었지.$K$P일기당천이란 건 $w2이런 거구나 하고$MC……$MD$w4\n"
.stringn "몸이 떨렸어.$K\n"
.stringn "$F3$P$MC…………$MD$K\n"
.stringn "$F1$P나도 검을 맞댔었지만$MC……$MD$w4\n"
.stringn "도저히 당해낼 수가 없었지.$K$P하지만 $w2그 후에도 시간이 있을 때\n"
.stringn "상대를 해 주셨거든.$K$P그렇게 $w2친해지고$MC……$MD$w4\n"
.stringn "그 사람의 집에 초대받았을 때,$w2\n"
.stringn "네가 있었어.$K\n"
.stringn "$F3$P내가?$K\n"
.stringn "$F1$P그래. $w4미소 지은 에르나에게 안겨서\n"
.stringn "자고 있었는데$MC……$MD$w2 귀여웠지.$K$P그 사람이 너를 보고 있을 때의 눈은\n"
.stringn "무척 상냥해서$MC……$MD$w3\n"
.stringn "검을 겨눌 때하곤 완전히 다른 사람 같았어.$K\n"
.stringn "$F3$P$MC…………$MD그랬구나$MC……$MD$K"
db 0
.align 4
//MYELL_IKE_TIAMAT_B

//0x1F578
Text_1F558:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_TIAMAT|$F1$P어머, $w2아이크.$w4\n"
.stringn "너도 훈련하려고?$K\n"
.stringn "$F3$FCL_IKE|$F3$P티아마트구나.$w4\n"
.stringn "그럼, $w2상대를 부탁해도 될까?$w4\n"
.stringn "네가 상대라면 배울 게 많아서 좋거든.$K\n"
.stringn "$F1$P그래?$w4 다행이네.$w4\n"
.stringn "이제 네게 내 지도는\n"
.stringn "필요 없을 줄 알았어.$K\n"
.stringn "$F3$P무슨 소리야.$K$P아버지한테서 물려받은 검술을\n"
.stringn "쓸 만하게 다듬어 준 건\n"
.stringn "너라고 생각하는데.$K\n"
.stringn "$F1$P후후,$w2 그렇게 말해 주니 영광이야.$w4\n"
.stringn "$MC……$MD저기, $w2아이크.$K\n"
.stringn "$F3$P왜?$K\n"
.stringn "$F1$P네가 그레일 단장님께\n"
.stringn "물려받은 검술은$MC……$MD$w4\n"
.stringn "이 세상에서 유일한 거야.$K$P소중히 해 줘.$K\n"
.stringn "$F3$P$MC…………$MD$K\n"
.stringn "저기, $w2티아마트.$w4\n"
.stringn "갑자기 궁금해서 그런데$MC……$MD$w2\n"
.stringn "너는 언제부터 아버지와 함께 있었어?$K$P티아마트는 $w2크리미아 기사였지?$K\n"
.stringn "$F1$P$FA$MC……$MD맞아.$K$P$FS하지만 그 얘기는 다음에 할게.$w4\n"
.stringn "마음의 준비를 하고 싶어.$w4\n"
.stringn "지금은 다음 싸움에만 전념하자.$K\n"
.stringn "$F3$P$MC……$MD알았어.$K"
db 0
.align 4
//MYELL_IKE_TIAMAT_C

//0x2050C
Text_204EC:
.stringn ""
db 0
.align 4
//MYELL_IKE_ZIHARK_A

