//0x20504
Text_204E4:
.stringn ""
db 0
.align 4
//MYELL_IKE_ZIHARK_C

//0x20EA0
Text_20E80:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_JANAFF|$F3$FS$F3$FCL_LUCHINO|$F3$P베오크도 라구즈도\n"
.stringn "서로 차별하지 않고,$w2\n"
.stringn "나라와 종족을 넘어선 우호$MC……$MD$K$P우리 크리미아의 이상은$w2\n"
.stringn "모든 사람들의 평화입니다.$K\n"
.stringn "$F1$P종족을 넘어서$MC……$MD$w3인가.$w4\n"
.stringn "크리미아는 별난 나라네.$K$P라구즈를 자기 나라 안에서\n"
.stringn "살게 해 준다며?$K\n"
.stringn "$F3$P네, $w2카이네기스 왕과의\n"
.stringn "동맹에 의한 것입니다.$K$P엘린시아 공주님께서는 $w2언젠가\n"
.stringn "갈리아뿐만 아니라, $w2다른\n"
.stringn "라구즈 국가들과도 그렇게 되길 원하십니다$MC…$MD$K\n"
.stringn "$F1$P$FS$MC……$MD$w2좋은 이야기라고 생각해.$K$P$FA그래도 $w2종족이나 나라를\n"
.stringn "초월한 우호라니,$w2\n"
.stringn "그렇게 잘 될까?$K\n"
.stringn "$F3$P$FA$MC……$MD라고 말씀하신다면?$K\n"
.stringn "$F1$P예를 들어 $w2보자고.$K$P우리 페니키스와\n"
.stringn "베그니온이 대립했던 건\n"
.stringn "당연히 알고 있지?$K\n"
.stringn "$F3$P네$MC……$MD$K\n"
.stringn "$F1$P신사는 셀리노스에게 사죄하긴 했지만\n"
.stringn "그렇다고 그 사실이\n"
.stringn "나라 전체에 영향을 끼치진 못했어.$K$P언제 $w2무슨 일로 다시 대립하고,$w2\n"
.stringn "전쟁이 일어날지도 몰라.$w4\n"
.stringn "그렇게 된다면 $w2너는 어디에 붙을 거야?$K\n"
.stringn "$F3$P그건$MC……$MD$K\n"
.stringn "$F1$P베그니온이겠지. $w4아니야?$K$P우리 페니키스 입장에서 보면,$w2\n"
.stringn "크리미아는 베그니온의 속국,$w2\n"
.stringn "베그니온의 부하라고 할 수 있지.$K$P그렇다면 $w2나는 너를 상대로\n"
.stringn "싸우게 될 거고.$K\n"
.stringn "$F3$P$MC……$MD엘린시아 공주님께서는 결코\n"
.stringn "그런 사태를 바라지 않으십니다.$K$P온갖 방법을 써서\n"
.stringn "전쟁을 피하려고 하시겠지요.$K$P$MC……$MD하지만, $w2저는 엘린시아 공주님의 신하.$w4\n"
.stringn "만일 싸워야만 한다면$MC……$MD$K$P그때는 $w2망설이지 않을 겁니다.$K\n"
.stringn "$F1$P나도 마찬가지야.$w4\n"
.stringn "왕의 아군은 나의 아군.$w4\n"
.stringn "왕의 적은 나의 적이니까.$K$P$FS그래도 가능하다면$w2\n"
.stringn "너하고 싸우고 싶지는 않은걸.$K\n"
.stringn "너같이 괜찮은 여자하고는 $w2싸우는 것보다\n"
.stringn "마시면서 얘기하고 싶으니까.$K\n"
.stringn "$F3$P$FS네$MC……$MD$w4 저도 동감입니다.$K$P이 전쟁이 끝나고 나면,$w2\n"
.stringn "크리미아의 부흥을 이루고 나면$MC……$MD$w4\n"
.stringn "또 뵙도록 해요.$K$P적이 아니라, $w2친구로서.$K\n"
.stringn "$F1$P그 무렵에는 너도 술을 마실 수 있는\n"
.stringn "나이가 되어 달라고. $w4부탁한다?$K\n"
.stringn "$F3$P$FA네$MC……$MD$w3네에$MC……$MD$w4\n"
.stringn "$MC…………?$MD$K"
db 0
.align 4
//MYELL_JANAFF_LUCHINO_A

//0x20970
Text_20950:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_JANAFF|$F3$FS$F3$FCL_LUCHINO|$F1$P우리 페니키스는 남해에 있어.$w4\n"
.stringn "따뜻하고 살기 좋은 곳이지.$K$P인구는 적지만\n"
.stringn "우리들은 동족끼리 다투거나 하지 않아.$K$P나는 이 눈으로 여러 나라들을 봐 왔지만,$w2\n"
.stringn "틀림없이 우리 나라만큼 좋은 곳은 없었어.$K\n"
.stringn "$F3$P타국과의 국교는\n"
.stringn "갖고 계셨나요?$K\n"
.stringn "$F1$P$FA아니, $w2우린 타국과 어울리지 않아.$K$P친분을 가지고 있던 셀리노스는\n"
.stringn "베오크 놈들에게 멸망당했고$MC……$MD$K$P그 네사라 왕이 있는 키르바스는\n"
.stringn "신용할 수가 없으니까.$K\n"
.stringn "$F3$P베오크 국가들과는 어땠나요?$K\n"
.stringn "$F1$P그건 더욱 $w2있을 수 없는 얘기지.$K$P셀리노스 학살 이후로 $w2우리에게\n"
.stringn "베오크는 적이었으니까.$K\n"
.stringn "$F3$P$FA그렇군요$MC……$MD$w4\n"
.stringn "$FS하지만 앞서 말씀드렸다시피 $w2우리 크리미아는\n"
.stringn "여러분들과의 국교를 희망합니다.$K$P돌아가신 폐하께서는 라구즈와 우호를$w2\n"
.stringn "다지는 데 힘쓰셨고, 갈리아의 카이네기스 왕과도\n"
.stringn "친밀한 관계에 있었어요.$K\n"
.stringn "$F1$P그래, $w2그렇다며.$K\n"
.stringn "우리 페니키스는\n"
.stringn "타국과 손을 잡지 않아도 잘 살 수 있지$MC…$MD$K$P만, $w2우리 왕께서\n"
.stringn "그렇게 결단하신다면$w2\n"
.stringn "크리미아와의 우호도 생길 수 있겠지.$K\n"
.stringn "$F3$P야나프님께서는 어떻게 생각하시나요?$K\n"
.stringn "$F1$P나는$MC……$MD$w4 그렇지.$K$P전에는 베오크라는 이유 하나로\n"
.stringn "싫어했었지만$MC……$MD$w4\n"
.stringn "지금은 우호를 쌓는 것도 나쁘지 않다고 생각해.$K$P$FS이것도 저것도$MC……$MD$w4\n"
.stringn "다 너와 만난 덕분이야$MC……$MD$K\n"
.stringn "$F3$P$FA네$MC……$MD$w2네에$MC……$MD$w4\n"
.stringn "황송합니다$MC…………$MD$K"
db 0
.align 4
//MYELL_JANAFF_LUCHINO_B

//0x20510
Text_204F0:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_JANAFF|$F3$FCL_LUCHINO|$F3$P페니키스의 기사님이시군요.$K\n"
.stringn "$F1$P응?$K\n"
.stringn "$F3$P$FS처음 뵙겠습니다.$w4\n"
.stringn "저는 크리미아 왕국의 루키노,$w2\n"
.stringn "엘린시아 공주님의 신하입니다.$K$P이번 귀국의 조력에,$w2\n"
.stringn "진심으로 감사를 표합니다.$K\n"
.stringn "$F1$P흐음$MC……$MD$K\n"
.stringn "$F3$P$FA?$K\n"
.stringn "$F1$P$FS아니아니, $w2친절하네.$w4\n"
.stringn "나는 야나프.$w4\n"
.stringn "우리 왕의 명령으로 여기에 있어.$K$P그러니까 감사는\n"
.stringn "내가 아니라 왕께 해 줘.$K\n"
.stringn "$F3$P$FS네.$K$P가능하면 직접 뵈어\n"
.stringn "전하고 싶습니다만$MC……$MD$w2\n"
.stringn "상황이 상황이니까요.$K$P티반 왕께는\n"
.stringn "부디 안부 전해 주시면 감사하겠습니다.$K\n"
.stringn "$F1$P$MC……$MD흐~음.$K\n"
.stringn "$F3$P$FA무, $w2무슨 일이라도?$K\n"
.stringn "$F1$P$FS아니 그게, $w2앞으로는 너하고\n"
.stringn "이 군에 싸우는 거지?$K$P그렇다면 $w2우호의 의미를 겸해서\n"
.stringn "같이 $w2술이라도 마실래?$K\n"
.stringn "$F3$P아뇨, $w2그럴 수는 없습니다.$K$P여러분의 관습이 어떤지는 모르지만$MC……$MD$w4\n"
.stringn "우리 나라에서는 $w2아직 술에 흥미를\n"
.stringn "가져선 안 되는 나이인지라$MC……$MD$K\n"
.stringn "$F1$P$FA흐~음$MC……$MD$w4\n"
.stringn "뭐, $w2그렇다면 어쩔 수 없지.$K$P$FS그나저나 너 $w2외견은 괜찮은 여자인 것 같은데$w2\n"
.stringn "나이는 아직 어린가 봐?$w4\n"
.stringn "베오크의 나이는 알 수가 없다니까.$K\n"
.stringn "$F3$P$MC……?$MD$K"
db 0
.align 4
//MYELL_JANAFF_LUCHINO_C

//0x21CD0
Text_21CB0:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_OSCAR|$F3$P저기$MC……$MD$K\n"
.stringn "$F1$FCL_JANAFF|$F1$P응?$w4\n"
.stringn "$MC…$MD흥, $w2또 너냐.$K\n"
.stringn "$F3$P지난번에는 정말로\n"
.stringn "죄송했습니다.$K$P여러분 조익족에 대한\n"
.stringn "제 공부가 $w2소홀했던 점을 부디 용서해 주십시오.$K\n"
.stringn "$F1$P$MC……$MD호오.$w4\n"
.stringn "뭐어$MC……$MD$w4 알았으면 됐어.$K$P근데 $w2넌 몇 살이냐?$w4\n"
.stringn "베오크의 나이는 알 수가 없다니까.$K\n"
.stringn "$F3$P저는 이제 24살입니다.$K\n"
.stringn "$F1$P24$MC!?$MD$K$P24살이라니$MC……$MD$w4 이봐 이봐,$w2\n"
.stringn "아직 깃털도 안 난\n"
.stringn "어린애잖아$MC!$MD$K$P베오크는 아기를 전장에 내보내는 거냐$MC!?$MD$w4\n"
.stringn "나 참$MC…$MD$w4 피도 눈물도 없는 녀석들이구만.$K\n"
.stringn "$F3$P하$MC…$MD$w2하하$MC……$MD$K\n"
.stringn "$F1$P$MC……$MD꼬맹이, $w2네 이름은?$K\n"
.stringn "$F3$P오, $w2오스카입니다.$K\n"
.stringn "$F1$P나는 야나프다.$w4\n"
.stringn "$MC……$MD정말 $w2예의도 모르는 놈인 줄\n"
.stringn "녀석인가 싶었다고$MC……$MD$K$P어린애였다면 어쩔 수 없지.$K\n"
.stringn "$F3$P$MC………………$MD$K\n"
.stringn "$F1$P뭐, $w2세상물정 모르는 아이를\n"
.stringn "날 수 있게 될 때까지 이끌어 주는 게\n"
.stringn "연장자의 의무 아니겠어.$K$P여태까지의 무례는 용서해 줄게.$w4\n"
.stringn "무슨 일이 있으면 나를 의지하라고.$w4\n"
.stringn "알겠지?$K\n"
.stringn "$F3$P네$MC……$MD$w2넵.$w4\n"
.stringn "감사합니다.$K"
db 0
.align 4
//MYELL_JANAFF_OSCAR_A

//0x21878
Text_21858:
.stringn "$R背景会話|$B支援背景|$<$F3$FS$F3$FCL_OSCAR|$F3$P얘, $w2안녕.$K\n"
.stringn "$F1$FCL_JANAFF|$F1$P응?$K\n"
.stringn "$F3$P또 만났네.$K$P저번에는 $w2미안했어.$w4\n"
.stringn "난 너희들과 얘기했던 경험이\n"
.stringn "별로 없어서$MC……$MD$K$P그렇지. $w4뭔가 이 군에 대해서\n"
.stringn "모르는 게 있으면 물어봐도 돼!$K\n"
.stringn "$F1$P아니, $w2딱히 없어.$w4\n"
.stringn "왜 갑자기?$K\n"
.stringn "$F3$P나한테는 딱 너만한 동생이 있거든.$w4\n"
.stringn "그러니까 $w2왠지 내버려 둘 수 없어서.$K$P그나저나 $w2라구즈는 대단하구나.$w4\n"
.stringn "너처럼 $w2아직 어린애까지\n"
.stringn "뛰어난 전사이고$MC……$MD$K\n"
.stringn "$F1$P야, $w2잠깐 기다려$MC……$MD$K\n"
.stringn "어린애$MC……$MD$w4 어린애라고$MC!?$MD$K\n"
.stringn "$F3$P$FA왜, $w2왜 그래?$K\n"
.stringn "$F1$P알겠냐, $w2잘 들어$MC!$MD$w4\n"
.stringn "나는 꼬맹이가 아냐$MC!$MD$w4\n"
.stringn "벌써 100년은 넘게 살았거든$MC!$MD$K\n"
.stringn "$F3$P응?$w4\n"
.stringn "100$w2년$MC……?$MD$K\n"
.stringn "$F1$P네가 몇 살인지는 모르겠지만\n"
.stringn "내 얼굴을 좀 본 다음에 말해라!\n"
.stringn "애 취급 받는 건 못 참는다고$MC!$MD$K$P다시는 착각하지 마$MC!$MD$w4\n"
.stringn "알겠지$MC!$MD$K\n"
.stringn "$F3$P아, $w2잠깐$MC……$MD$MC!$MD$K\n"
.stringn "$F1$FD$P$w4$F3$P실수했다$MC……$MD$w4\n"
.stringn "많이 화나게 해 버린 것 같은데$MC……$MD$K$P겉모습으로만 판단해선 안 된다는 건가.$w4\n"
.stringn "나중에 날을 잡아서 $w2사과하러 가야겠네$MC……$MD$K"
db 0
.align 4
//MYELL_JANAFF_OSCAR_B

//0x21628
Text_21608:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_OSCAR|$F1$P너는$MC……$MD$K\n"
.stringn "$F3$FCL_JANAFF|$F3$P응?$K\n"
.stringn "$F1$P$FS안녕.$w4\n"
.stringn "$FA$MC………………$MD$K\n"
.stringn "$F3$P?$w4\n"
.stringn "나한테 볼일 있어?$K\n"
.stringn "$F1$P$FS아니, $w2별로 볼일이 있는 건\n"
.stringn "아니지만$MC……$MD$K\n"
.stringn "$F1$P$FA$F3$P뭐야?$w4 이상한 녀석이네.$w4\n"
.stringn "볼일 없는 거지?$w4\n"
.stringn "그럼 $w2간다.$K$P$MC……$MD베오크는 잘 모르겠다니까.$K\n"
.stringn "$F3$FD$P$w5$F1$P곤란한걸$MC……$MD$K$P어떻게 말을 걸면 좋을까$MC……$MD$w4\n"
.stringn "여태까지 조익족이랑 어울렸던 적은\n"
.stringn "없었는데$MC……$MD$K$P하지만 $w2동료끼리$w2\n"
.stringn "교류를 가지지 않는 건 이상하고$MC…$MD$w4\n"
.stringn "다음엔 $w2좀 더 제대로 얘기해 보자$MC……$MD$K"
db 0
.align 4
//MYELL_JANAFF_OSCAR_C

