//0x2320C
Text_231EC:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_LETHE|$F1$P$MC……$MD$K\n"
.stringn "$F3$FCL_JILL|$F3$P$MC!$MD$w4 레테$MC…$MD$K\n"
.stringn "$F1$P$MC……$MD어째서냐?$w4\n"
.stringn "달레카에서 싸운 용 기사는$MC……$MD$w4\n"
.stringn "네 아버지였다고 들었다.$K$P$MC…$MD어째서, $w2그렇게까지 해서\n"
.stringn "이쪽에 남을 결심을 한 거지?$K\n"
.stringn "$F3$P$MC………$MD$w4\n"
.stringn "운명이란 건 $w2신기하지.$K$P만약, $w2이 군을$MC…$MD$w4\n"
.stringn "아이크님이나 용병단$MC…$MD$K$P그리고 무엇보다$MC……$MD$w4\n"
.stringn "레테와 라구즈들을 몰랐다면$MC……$MD$w4\n"
.stringn "난 지금도 분명 데인군에 있었을 거야.$K$P데인 왕국 군인으로서의 자부심에 불타$w2\n"
.stringn "아슈나드를 위해서\n"
.stringn "기꺼이 목숨을 바쳤겠지.$K$P너희를 쓰러뜨리는 걸\n"
.stringn "주저하지 않았을 거야.$w4\n"
.stringn "$MC……$MD그렇지만, $w2알아 버렸어.$K\n"
.stringn "$F1$P$MC……$MD$K\n"
.stringn "$F3$P공을 세우기 위해 $w2항구 마을 토하에서\n"
.stringn "너희들의 배를 쫓았을 때와는 달라.$K$P나는 처음으로$MC…$MD$w4 스스로 생각하고 행동했어.$w4\n"
.stringn "내가$MC…$MD$w4\n"
.stringn "더 옳다고 생각하는 길을 선택하기 위해서.$K$P그것이 비록$MC…$MD$w4 친아버지를\n"
.stringn "상대하는 것이었다고 해도.$w4\n"
.stringn "이젠, $w2몰랐던 시절로 돌아갈 수 없어.$K$P그래서$MC…$MD$w4 나는 여기에 있어.$K\n"
.stringn "$F1$P$MC………$MD질.$w4\n"
.stringn "내 손을 잡아 주지 않겠나?$K\n"
.stringn "$F3$P어$MC…?$MD$K\n"
.stringn "$F1$P우애의 마음을 표시할 때$MC…$MD$w4\n"
.stringn "서로의 손을 잡는 것이\n"
.stringn "베오크의 관례라고 들었다.$K$P$FS나는 $w2너의 강함에$MC…$MD$w4\n"
.stringn "너의 삶의 방식에 경의를 표하지.$K\n"
.stringn "$F3$P$FS레테$MC…$MD$w4\n"
.stringn "아$MC……$MD$w4 응. $w4$MC…$MD고마워.$K\n"
.stringn "$F1$P$MC…$MD베오크와 라구즈는\n"
.stringn "이해할 수 있다.$K$P서로를 이해하려는 계기와$MC…$MD$w4\n"
.stringn "양보하려는 마음이 있다면, $w2반드시.$K"
db 0
.align 4
//MYELL_JILL_LETHE_A

//0x22548
Text_22528:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_JILL|$F1$P레$MC…$MD$w4 레테?$K\n"
.stringn "$F3$FCL_LETHE|$F3$P$MC…$MD누군가 했더니, $w2또 너인가.$K\n"
.stringn "$F1$P나는 질이야.$w4\n"
.stringn "너가$MC…$MD$w4 아니라.$K\n"
.stringn "$F3$P그럼 $w2질.$w4\n"
.stringn "오늘은 무슨 용무지?$w4\n"
.stringn "또 $w2쓸데없는 질문인가?$K\n"
.stringn "$F1$P$MC…$MD쭉, $w2알 수 없었어.$K$P데인에서는$MC…$MD$w4\n"
.stringn "너희들이 맹수나 다름없다고,$w2$K$P인간을 습격하는 적이라고$MC…$MD$w4\n"
.stringn "그렇게 가르쳐 왔으니까.$K\n"
.stringn "$F3$P하,$w4 우리가 베오크를\n"
.stringn "무차별적으로 습격한다고?$K$P설령 그렇게 부탁받았다 해도\n"
.stringn "관여조차 안 하고 싶다만?$K\n"
.stringn "$F1$P$MC……$MD하지만, $w2데인에서는\n"
.stringn "주위의 누구나 그렇게 믿고 있었어.$K$P그러니까$MC…$MD$w4 그럴 거라고\n"
.stringn "의심하지도 않고 살아 왔지$MC……$MD$K$P하지만$MC…$MD$w4 남쪽 바다에서$MC……$MD$w4\n"
.stringn "아이크네와 함께 싸우는\n"
.stringn "레테의 모습에$MC…$MD$w4 위화감을 느꼈어.$K$P어째서 $w2이렇게\n"
.stringn "상상했던 것과 다른 걸까.$K$P어렸을 때부터 들어 왔던\n"
.stringn "괴물 같은 짐승이 아니었어.$K$P그리고 화신을 푼 너는$MC……$MD$w4\n"
.stringn "짐승이 아니라$MC…$MD$w4 오히려 $w2우리와 가까웠지.$K\n"
.stringn "$F3$P$MC………$MD$K\n"
.stringn "$F1$P애초에$MC…$MD$w4\n"
.stringn "베오크와 라구즈가 싸우기 시작한 건\n"
.stringn "언제부터였을까?$K$P뭔가 계기가 있었던 걸까?$K\n"
.stringn "$F3$P$MC…$MD그건 나도 모른다.$K$P처음부터$MC…$MD$w4 여신이 그렇게\n"
.stringn "만들어 냈기 때문인지,$w2\n"
.stringn "근본적으로 그런 것인지.$K$P다만$MC…$MD$w4 고르드아를 제외한\n"
.stringn "갈리아, $w2페니키스, $w2키르바스$MC…$MD$K$P이 나라들에 한해서\n"
.stringn "베오크가 증오받는 이유는 명확하다.$K\n"
.stringn "$F1$P무, $w2무슨 이유인데?$K\n"
.stringn "$F3$P$MC……$MD그 반응을 보니,$w2\n"
.stringn "베오크는 후세에게$MC…$MD$w4 정확한 역사를\n"
.stringn "전하지 않고 있는 것 같군.$Fc$K$P$MC………$MD후우$MC…$MD$Fd\n"
.stringn "$MC…$MD잘 들어라. $w4베그니온이 아직\n"
.stringn "제국이 아닌 $w2왕국이었던 때$MC…$MD$K$P테리우스에는 베그니온과\n"
.stringn "고르드아 두 나라만이 존재했다.$K$P고르드아는 지금과 다름없이$w2\n"
.stringn "용린족들뿐인 폐쇄적인 나라였고$MC…$MD$K$P다른 라구즈$MC…$MD$w4 수아족, $w2조익족은\n"
.stringn "베그니온에서\n"
.stringn "베오크와 함께 살고 있었지.$K\n"
.stringn "$F1$P과거의 베그니온에서는$MC…$MD$w4\n"
.stringn "인간과 라구즈가 공존하고 있었다고$MC…?$MD$K$P그, $w2그런 이야기는$MC…$MD$w4\n"
.stringn "들어본 적도 없어.$K\n"
.stringn "$F3$P나라의 왕으로는$MC…$MD$w4 초대엔$w2\n"
.stringn "베오크가 뽑혔다는 것 같지만$K$P그 뒤로는$MC…$MD$w4 완력이 뛰어난 라구즈가\n"
.stringn "왕위에 오르는 경우도 많았다고 한다.$K$P그러나 $w2그에 불복한 원로원이\n"
.stringn "【신사】의 이름 아래 $w2$K$P베오크야말로 베그니온의\n"
.stringn "지배자라며 크게 내란을 일으켰지.$K$P결국 오합지졸에 불과했던\n"
.stringn "라구즈의 왕들은$MC…$MD$K$P개량을 거듭해 진화를 이룬\n"
.stringn "무기와 마도 앞에서 무릎을 꿇고 말았다.$K$P$MC………………$MD$w4\n"
.stringn "$MC…$MD그리고$MC…$MD$w4 길고 긴$MC……$MD$w4\n"
.stringn "라구즈의 노예 시대가 시작됐지.$K\n"
.stringn "$F1$P$MC……$MD$K\n"
.stringn "$F3$P200년에 이르는 시간을 거쳐$w2\n"
.stringn "베오크의 손아귀에서 벗어나기 위해\n"
.stringn "베그니온 탈출에 성공한 라구즈들이 있었다.$K$P수아족은 험준한 산악을 목숨을 걸고\n"
.stringn "돌파해 미개척된 대삼림 지대로$MC…$MD$w4\n"
.stringn "조익족은 남쪽 섬으로 각자 빠져나갔지.$K$P그것이 우리 라구즈 왕국의 시작이다.$K$P그로부터 $w2정식 국가로 인정받기까지는\n"
.stringn "80년의 시간을 거치며 $w2많은\n"
.stringn "동포들의 피가 흘렀다.$K$P싸움의 이유는 있었다.$w4\n"
.stringn "베오크들은 $w2한 번은 굴복했던 노예들이\n"
.stringn "나라를 세우고 자신들과 대등해지는 것을 싫어했지.$K$P라구즈들은 $w2과거의 굴욕을 안고\n"
.stringn "지금도 $w2자유를 찾아 쟁취하려 하고 있다.$K$P이것이 너희 베오크가 후세에 전하지 않고\n"
.stringn "어둠 속에 묻으려고 하는 역사의 진실이다.$K\n"
.stringn "$F1$P$MC…………$MD$K\n"
.stringn "$F3$P흥,$w4 할 말이 없나 보군.$K$P잘$MC…$MD$w4 생각해 봐라.$w4\n"
.stringn "자신의 눈으로 본 것을$MC…$MD$w4\n"
.stringn "그 귀로 들은 것을 생각해 봐라.$K$P그것조차도 할 수 없다면,$w2\n"
.stringn "두 번 다시 내 앞에 모습을 드러내지 마라.$K$F3$FD\n"
.stringn "$F1$P$MC………………$MD$K"
db 0
.align 4
//MYELL_JILL_LETHE_B

//0x22110
Text_220F0:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_LETHE|$F3$FCL_JILL|$F3$P아$MC…$MD$K\n"
.stringn "$F1$P?$w4\n"
.stringn "나한테 볼일이라도 있나?$K\n"
.stringn "$F3$P지, $w2질문이 있는데\n"
.stringn "물어봐도 괜찮을까?$K\n"
.stringn "$F1$P$MC…$MD내용에 따라서.$K\n"
.stringn "$F3$P$MC…………$MD그$MC…$MD$K$P왜 $w2반수$MC…$MD$w4 아니\n"
.stringn "라구즈$MC…$MD$w4는,$w2\n"
.stringn "전투에 무기를 사용하지 않는 거야?$K\n"
.stringn "$F1$P$MC………$MD$w4\n"
.stringn "라구즈에게는 $w2선천적으로$w2\n"
.stringn "전투술이 몸에 배어 있다.$K$P무기는 $w2힘을 가질 수 없는\n"
.stringn "너희들 베오크가$MC…$MD$K$P우리의 손톱과 이빨에 대항하여\n"
.stringn "만들어낸 것.$w4\n"
.stringn "쓸 필요가 없다.$K\n"
.stringn "$F3$P그, $w2그렇구나$MC…$MD$K\n"
.stringn "$F1$P그것뿐인가?$K\n"
.stringn "$F3$P어$MC…$MD$w4 아, $w2아니.$w4\n"
.stringn "또 있어.$K$P너희들은 어째서\n"
.stringn "우리들$MC…$MD$w4 그, $w2인간을\n"
.stringn "증오하는 거야?$K\n"
.stringn "$F1$P$MC……$MD그 질문이라면\n"
.stringn "오히려 이쪽이 먼저\n"
.stringn "네 대답을 듣고 싶군.$K$P왜 $w2베오크는 라구즈를 증오하지?$w4\n"
.stringn "나는$MC…$MD$w4 그 이유를 알고 싶다.$K\n"
.stringn "$F3$P그건$MC…$MD$w4\n"
.stringn "반수$MC…$MD$w4 라구즈가 적이니까.$K\n"
.stringn "$F1$P적인가$MC…$MD$K$P그렇다면 $w2이쪽도\n"
.stringn "적이니까 베오크를 증오하는 것이라고\n"
.stringn "대답할 수밖에 없다.$K$P$MC……$MD그럼, $w2이만 가지.$w4\n"
.stringn "이 이상 $w2시간을 낭비하고 싶지 않아.$K$F1$FD\n"
.stringn "$F3$P$MC………$MD$K"
db 0
.align 4
//MYELL_JILL_LETHE_C

//0x24FC4
Text_24FA4:
.stringn ""
db 0
.align 4
//MYELL_JILL_MIST_A

//0x23C94
Text_23C74:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_JILL|$F3$FCL_MIST|$F1$P미스트, $w2잠깐 괜찮을까?$K\n"
.stringn "$F3$P아, $w2질.$K\n"
.stringn "$F1$P$MC…$MD딱히 뭔가 중요한 볼일이\n"
.stringn "있는 건 아니야$MC…$MD$w4\n"
.stringn "미스트랑 같이 있고 싶어서.$K$P방해된다면 말해 줘?$K\n"
.stringn "$F3$P$FS아냐.$w4\n"
.stringn "나도 마침 $w2질이랑\n"
.stringn "만나고 싶다고 생각했어.$K$P와 줘서 기뻐.$K\n"
.stringn "$F1$P$FS다행이다.$K\n"
.stringn "$F3$P헤헤$K\n"
.stringn "$F1$P$MC………$MD$K\n"
.stringn "$F3$P$MC………$MD$K\n"
.stringn "$F1$P$MC…………$MD$K\n"
.stringn "$F3$P$MC……$MD대단했지.$K\n"
.stringn "$F1$P$MC…?$MD$K\n"
.stringn "$F3$P셀리노스의 숲.$K$P뤼시온씨와 리아네씨의 노랫소리가$MC…$MD$w4\n"
.stringn "눈부신 빛으로 바뀌어서$MC……$MD$w4\n"
.stringn "숲이$MC…$MD 숲이 살아났잖아.$K\n"
.stringn "$F1$P$MC……$MD그$MC…$MD$w2$FA랬지.$w5$Fc\n"
.stringn "$MC…………$MD$K\n"
.stringn "$F3$P$FA질?$w4\n"
.stringn "$MC…$MD왜 울어?$K\n"
.stringn "$F1$P그걸 보고$MC…$MD$w4 깨달았어$MC……$MD$w4\n"
.stringn "라구즈는$MC…$MD$w4 악한 존재가 아니야.$K$P틀린 건$MC…$MD$w4 나였어$MC……$MD$w4\n"
.stringn "$MC……$MD내가 믿어 온$MC…$MD$w4 것들은$MC……$MD$K\n"
.stringn "$F3$P$MC………$MD질$MC……$MD$K\n"
.stringn "$=0500"
db 0
.align 4
//MYELL_JILL_MIST_A_a_1

//0x2403C
Text_2401C:
.stringn "$R背景会話|$B支援背景|$<$F1$Fc$F1$FCL_JILL|$F3$FCL_MISTs|$F1$P$MC…$MD아버님은$MC…$MD$w4 어째서$MC…$MD$w4\n"
.stringn "내게 거짓말을$MC……?$MD$K$P이렇게 괴로워질 줄 알았다면$MC…$MD$w4\n"
.stringn "처음부터 진실을 아는 게 나았을 텐데$MC……$MD$K$P$Fd설마$MC…$MD$w4 데인이 쓰기 편한 군인으로\n"
.stringn "만들기 위해서$MC……?$MD$K\n"
.stringn "$F3$P그럴 리가 없어$MC!$MD$K\n"
.stringn "$F1$P$MC!?$MD$K\n"
.stringn "$F3$P아빠는 $w2절대$MC…$MD$w4\n"
.stringn "자기 아이를$MC……$MD$w4\n"
.stringn "그런$MC…$MD$w4 도구처럼 생각하지 않아$MC!$MD$K$P만약$MC…$MD$w4 거짓말을 했다면,$w2\n"
.stringn "분명 그건 자식을 위해서\n"
.stringn "한 걸 거야$MC…$MD$w4 그러니까$MC……$MD$K\n"
.stringn "$F1$P미스트$MC…$MD$K\n"
.stringn "$F3$P질은 바보야$MC!$MD$K$P아무리 풀이 죽어도 그렇지\n"
.stringn "아빠의 애정까지 의심하다니$MC…$MD$w4\n"
.stringn "완전 바보라고$MC!$MD$K$P$Fh그야, $w2아빠는$MC…$MD$w4\n"
.stringn "아빠는$MC………$MD$Fc$K\n"
.stringn "$F1$P미스트$MC…$MD$MC!$MD$w4\n"
.stringn "알았어$MC…$MD$w4 이제 알았으니까$MC…$MD$K\n"
.stringn "$F3$P아빠$MC…$MD$w4\n"
.stringn "아$MC…$MD$w4빠$MC……$MD$w4\n"
.stringn "$MC………………$MD$K\n"
.stringn "$F1$P$MC……………………$MD$w4\n"
.stringn "$MC……$MD미스트$MC…$MD$w4\n"
.stringn "울지 마$MC…………$MD$K$P$MC………$MD$FS미스트$MC…?$MD$K\n"
.stringn "$F3$P$MC……$MD응$MC…$MD$w4 미$MC…$MD$w4안$MC…$MD$K\n"
.stringn "$F1$P$MC……$MD미스트, $w2고마워.$K$P내 아버지에 대해$MC…$MD$w4\n"
.stringn "그렇게 말해 줘서\n"
.stringn "고마워$MC……$MD$K\n"
.stringn "$F3$P$Fd$MC…$MD질$MC…$MD$K\n"
.stringn "$F1$P$FA난$MC…$MD$w4 정말 바보인가 봐.$K$P그렇게나$MC…$MD$w4 나를\n"
.stringn "소중하게 키워 준 사람을\n"
.stringn "한순간 의심하다니$Fc$MC……$MD$K$P어떻게 됐나 보네$MC……$MD$w5\n"
.stringn "$Fd$MC……$MD나, $w2정했어.$w4\n"
.stringn "자신이 믿는 길을 고를 거야.$K$P아버님께선$MC…$MD$w4 분명 이해해 주시겠지.$K\n"
.stringn "$F3$P$FS질$MC…$MD$w4 그래.$w4\n"
.stringn "$MC……$MD그럴 거야$MC!$MD$K"
db 0
.align 4
//MYELL_JILL_MIST_A_a_2

//0x24678
Text_24658:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_JILL|$F3$FCL_MIST|$F1$P미스트, $w2잠깐 괜찮을까?$K\n"
.stringn "$F3$P아, $w2질.$K\n"
.stringn "$F1$P$MC…$MD딱히 뭔가 중요한 볼일이\n"
.stringn "있는 건 아니야$MC…$MD$w4\n"
.stringn "미스트랑 같이 있고 싶어서.$K$P방해된다면 말해 줘?$K\n"
.stringn "$F3$P$FS아냐.$w4\n"
.stringn "나도 마침 $w2질이랑\n"
.stringn "만나고 싶다고 생각했어.$K$P와 줘서 기뻐.$K\n"
.stringn "$F1$P$FS다행이다.$K\n"
.stringn "$F3$P헤헤$K\n"
.stringn "$F1$P$MC………$MD$K\n"
.stringn "$F3$P$MC………$MD$K\n"
.stringn "$F1$P$MC…………$MD$K\n"
.stringn "$F3$P$MC……$MD대단했지.$K\n"
.stringn "$F1$P$MC…?$MD$K\n"
.stringn "$F3$P셀리노스의 숲.$K$P뤼시온씨와 리아네씨의 노랫소리가$MC…$MD$w4\n"
.stringn "눈부신 빛으로 바뀌어서$MC……$MD$w4\n"
.stringn "숲이$MC…$MD$w4 숲이 살아났잖아.$K\n"
.stringn "$F1$P$MC……$MD그$MC…$MD$w2$FA랬지.$w5$Fc\n"
.stringn "$MC…………$MD$K\n"
.stringn "$F3$P$FA질?$w4\n"
.stringn "$MC…$MD왜 우는 거야?$K\n"
.stringn "$F1$P그걸 보고$MC…$MD$w4 깨달았어$MC……$MD$w4\n"
.stringn "라구즈는$MC…$MD$w4 악한 존재가 아니야.$K$P틀린 건$MC…$MD$w4 나였어$MC……$MD$w4\n"
.stringn "$MC……$MD내가 믿어 온$MC…$MD$w4 것들은$MC……$MD$K\n"
.stringn "$F3$P$MC………$MD질$MC……$MD$K\n"
.stringn "$=0500"
db 0
.align 4
//MYELL_JILL_MIST_A_b_1

//0x24A24
Text_24A04:
.stringn "$R背景会話|$B支援背景|$<$F1$Fc$F1$FCL_JILL|$F3$FCL_MISTs|$F3$P$FS그걸$MC…$MD$w4 알았으니까,$w2\n"
.stringn "질은 여기에 남아 준 거잖아.$w4\n"
.stringn "아빠가 있는 데인군으로 돌아가지 않고$MC…$MD$K\n"
.stringn "$F1$P$Fd알아 버렸다면$MC…$MD$w4\n"
.stringn "돌아갈 수 있을 리가$MC…$MD$w4 없어$MC……$MD$K$P아버님은$MC…$MD$w4 내게 실망하셨겠지$MC……$MD$Fh$w4\n"
.stringn "쓸모없는$MC…$MD$w4 배신자라면서$MC……$MD$K\n"
.stringn "$F3$P$FA그렇지 않아$MC!$MD$K\n"
.stringn "$F1$P$Fd$MC!?$MD$K\n"
.stringn "$F3$P아빠는 $w2절대$MC…$MD$w4\n"
.stringn "자기 아이에 대해서$MC……$MD$w4\n"
.stringn "그런 식으로 말하지 않아$MC!$MD$K$P아무리 실패해도$MC…$MD$w4\n"
.stringn "마지막에는 웃으면서\n"
.stringn "어쩔 수 없는 애라면서$MC…$MD$w4 용서해 줘.$K$P하물며$MC…$MD$w4 아이가$w2\n"
.stringn "자신이 믿는 길을 선택했다면\n"
.stringn "틀림없이 기뻐하셨을 거야.$K$P그야, $w2아빠는$MC…$MD$w4\n"
.stringn "아빠는$MC………$MD$Fc$K\n"
.stringn "$F1$P미스트$MC…$MD$MC!$MD$w4\n"
.stringn "알았어$MC…$MD$w4 이제 알았으니까$MC…$MD$K\n"
.stringn "$F3$P아빠$MC…$MD$w4\n"
.stringn "아$MC…$MD$w4빠$MC……$MD$w4\n"
.stringn "$MC………………$MD$K\n"
.stringn "$F1$P$MC……………………$MD$w4\n"
.stringn "$MC……$MD미스트$MC…$MD$w4\n"
.stringn "울지 마$MC…………$MD$K$P$MC………$MD$FS미스트$MC…?$MD$K\n"
.stringn "$F3$P$MC……$MD응$MC…$MD$w4 미$MC…$MD$w4안$MC…$MD$K\n"
.stringn "$F1$P$MC……$MD미스트.$w4\n"
.stringn "나는$MC…$MD$w4 미스트 옆에 있으면$MC……$MD$w4\n"
.stringn "$MC…$MD마음이 좀 가벼워져.$K\n"
.stringn "$F3$P$Fd질$MC…$MD$K\n"
.stringn "$F1$P사는 건 힘들지만$MC…$MD$w4\n"
.stringn "그래도, $w2계속 살고 싶다고\n"
.stringn "생각할 수 있어. $w4고마워.$K\n"
.stringn "$F3$P$Fh질$MC…$MD$Fc$w4 $MC…$MD$K\n"
.stringn "$F1$P울지 말라니까$MC…$MD$w4\n"
.stringn "정말$MC…$MD$w4 어쩔 수 없네$MC……$MD$K"
db 0
.align 4
//MYELL_JILL_MIST_A_b_2

//0x239A4
Text_23984:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_MIST|$F3$FCL_JILL|$F1$P질, $w2그거$MC…$MD$w4\n"
.stringn "맛없어?$K\n"
.stringn "$F3$P$MC…$MD그렇진 않은데.$w4\n"
.stringn "왜?$K\n"
.stringn "$F1$P$FS다행이다.$w4\n"
.stringn "그거, $w2내가 만든 거야.$K\n"
.stringn "$F3$P미스트가?$K\n"
.stringn "$F1$P응. $w4그건 말이지,$w2\n"
.stringn "사실 아플 때 먹는\n"
.stringn "영양분이 가득한 수프거든.$K$P질이 $w2기운도 없고 밥도 잘 안 먹으니까$MC…$MD$w4\n"
.stringn "이거라면 괜찮을까 해서.$K\n"
.stringn "$F3$P$MC…$MD나는 $w2미스트가 신경 쓰게 해 버렸구나.$K$P왜 그렇게\n"
.stringn "나한테 잘해 주는 거야$MC…?$MD$w4\n"
.stringn "나는 데인의$MC…$MD$K\n"
.stringn "$F1$P$FA이제, $w2그만하자$MC…$MD$w4 그런 거.$K\n"
.stringn "$F3$P뭐$MC…?$MD$K\n"
.stringn "$F1$P데인병이니까$w2\n"
.stringn "함께 있으면\n"
.stringn "안 되는 게 당연하다니$MC…$MD$w4 그런 건 싫어.$K$P$FS내 눈앞에 있는 질은\n"
.stringn "전혀 $w2나쁜 애도 아니고.$w4\n"
.stringn "난$MC…$MD$w4 너랑 친해지고 싶은걸?$K\n"
.stringn "$F3$P미스트$MC…$MD$K"
db 0
.align 4
//MYELL_JILL_MIST_B

//0x237A0
Text_23780:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_JILL|$F3$FS$F3$FCL_MIST|$F3$P아, $w2있다.$K\n"
.stringn "$F1$P$MC……$MD미스트, $w2또 온 거야?$K\n"
.stringn "$F3$P응. $w4그야 질이$w2\n"
.stringn "또 밥 먹으러 안 왔으니까.$K\n"
.stringn "$F1$P데인 사람이 $w2모두와 같은 장소에\n"
.stringn "있을 수는 없잖아.$w4\n"
.stringn "모처럼의 식사가 맛없어질 거야.$K\n"
.stringn "$F3$P오빠는 상관없다고\n"
.stringn "말했었는데?$K\n"
.stringn "$F1$P$MC……$MD$K\n"
.stringn "$F3$P$FS나도 $w2또래\n"
.stringn "여자애가 있으면 기쁘기도 하고.$K\n"
.stringn "$F1$P$MC……$MD$w4\n"
.stringn "미안.$K\n"
.stringn "$F3$P그래. $w4그럼 어쩔 수 없지.$K$F3$FD\n"
.stringn "$F1$P$MC………$MD$K"
db 0
.align 4
//MYELL_JILL_MIST_C

