//0x25A10
Text_259F0:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_KILROY|$F3$P케빈씨.$w4\n"
.stringn "$MC……$MD또 훈련 중이세요?$K\n"
.stringn "$F1$FS$F1$FCL_KEVIN|$F1$P오오, $w2킬로이$MC!$MD$w4\n"
.stringn "저번에는 고마웠다.$K$P내 도끼가 머리에 수직으로 떨어졌을 때는\n"
.stringn "정말 어떻게 되는 줄 알았다.$K\n"
.stringn "$F3$P그렇다면 좀 더$MC……$MD$w4\n"
.stringn "자신의 안전을 생각하는 건\n"
.stringn "어떨까요$MC……?$MD$K\n"
.stringn "$F1$P안전?$w4 핫핫하$MC!$MD$w4\n"
.stringn "난 그런 겁쟁이가 아니다$MC!$MD$w4\n"
.stringn "기사에게 두려움 따위는 없다$MC!$MD$w4 절대로$MC!$MD$K\n"
.stringn "$F3$P그, $w2그치만$MC……$MD$w4\n"
.stringn "하지만 만에 하나라는 게 있으니까,$w2\n"
.stringn "케빈씨의 명예에 흠집이 날 수도 있는걸요?$K\n"
.stringn "$F1$P$FA내 명예에?$K\n"
.stringn "$F3$P예를 들면$MC……$MD$K$P『기사 케빈, $w2훈련 도중 어째서인지 대출혈.$w4\n"
.stringn " 수수께끼의 죽음을 맞이하다』$MC……$MD$w4\n"
.stringn "후세에 그렇게 기록될지도 몰라요.$K\n"
.stringn "그래도 괜찮으신가요?$K\n"
.stringn "$F1$P큭$MC!$MD$w4\n"
.stringn "화, $w2확실히 그건\n"
.stringn "싫군$MC……$MD$K\n"
.stringn "$F3$P그럼 $w2약속해 주세요.$w4\n"
.stringn "이제 위험한 훈련은 하지 않기로.$K\n"
.stringn "$F1$P큭$MC!$MD$w4 어쩔 수 없는 건가$MC!?$MD$w4\n"
.stringn "전장에 나가기도 전에 혼자서 멋대로 죽다니,\n"
.stringn "후세에도 치욕으로 남을 텐데.$K$P하, $w2하지만$MC……$MD$K\n"
.stringn "$F3$P$MC…………$MD$w4\n"
.stringn "케, $w2케빈씨, $w2당신을 잃으면\n"
.stringn "저희가 곤란해져요$MC!$MD$K$P으~음$MC……$MD$w2 그렇지, $w2우리 군에서\n"
.stringn "가장 든든한 케빈씨를 잃게 된다면$w2\n"
.stringn "승리란 있을 수 없겠죠$MC……$MD$K\n"
.stringn "$F1$P$MC……$MD그런가$MC…$MD$w2$FS 그렇군$MC!$MD$w4\n"
.stringn "그 말대로다$MC!$MD$K$P우리 군 최고의 전력인 내가\n"
.stringn "무모한 짓을 할 수는 없지$MC!$MD$K$P알았다.$w4\n"
.stringn "아직 부족하지만 자중하도록 하지$MC!$MD$K\n"
.stringn "$F3$P$Fc휴우$MC……$MD$w4$Fd$FS 알아 주셔서\n"
.stringn "다행이에요$MC……$MD$K$P앞으로도 $w2가끔씩 보러 올 테니까$w4\n"
.stringn "아무쪼록 무리한 짓은 하지 말아 주세요?$K\n"
.stringn "$F1$P그래, $w2알겠다$MC!$MD$K"
db 0
.align 4
//MYELL_KEVIN_KILROY_A

//0x2556C
Text_2554C:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_KILROY|$F1$P케빈씨,$w2\n"
.stringn "여기 계셨군요.$K\n"
.stringn "$F3$FS$F3$FCL_KEVIN|$F3$P오오, $w2킬로이 아닌가$MC!$MD$w4\n"
.stringn "무슨 일이지?$K\n"
.stringn "$F1$P케빈씨가 훈련하는 모습을\n"
.stringn "구경해도 될까요?$K$P또 지난번과 같은 사고가\n"
.stringn "일어날 수 있으니, $w2지팡이를 사용할 줄 아는\n"
.stringn "사람이 옆에 있는 편이 좋을 것 같아서요.$K\n"
.stringn "$F3$P하하하,$w2 킬로이는 걱정이 많군.$w4\n"
.stringn "하지만 $w2다른 이에게 보여 주는 것은 좋지$MC!$MD$K$P평소보다 한층 더 훈련에\n"
.stringn "열중할 수 있겠어$MC!$MD$w4\n"
.stringn "$FA흡$MC!$MD$w4 하앗$MC!$MD$K\n"
.stringn "$F1$P$FA저기, $w2부디\n"
.stringn "저는 신경 쓰지 마시고$MC……$MD$K\n"
.stringn "$F3$P$FS좋아, $w2기술을 하나 보여 주마.$K$P$MC……$MD봐라$MC!$MD$w4 내 도끼 실력을$MC!$MD$w4\n"
.stringn "너희 용병단원들은\n"
.stringn "도저히 따라할 수 없겠지$MC!!$MD$K\n"
.stringn "$F1$P아뇨, $w2저기,$w2\n"
.stringn "저는 다치지 않게 하려고\n"
.stringn "보고 있는 것뿐이니까$MC……$MD$K$P너무 지나치게 힘을 쓰지 않는 편이$MC……$MD$K\n"
.stringn "$F3$P보아라, $w2이것이야말로\n"
.stringn "크리미아 기사 케빈의 오의.$w2\n"
.stringn "그 이름하여――$K$P$FA$MC……$MD크옷$MC!$MD$w4 방심했다$MC!$MD$K$F3$FD\n"
.stringn "$F1$P잠깐$MC……$MD 케빈씨$MC!?$MD$w4\n"
.stringn "$Fc$MC……$MD아아$MC……$MD$w2 역효과였나 보네$MC……$MD$K$P$Fd케빈씨, $w2가만히 계세요.$w4\n"
.stringn "지금 치료할 테니까$MC……$MD$K\n"
.stringn "$F8$FCL_KEVIN|$F8$P미안하다$MC……$MD$K"
db 0
.align 4
//MYELL_KEVIN_KILROY_B

//0x24FD4
Text_24FB4:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_KEVIN|$F1$P여어, $w2킬로이$MC!$MD$K\n"
.stringn "$F3$FS$F3$FCL_KILROY|$F3$P앗, 케빈씨$MC……$MD$w3\n"
.stringn "$FA$MC!?$MD$w4\n"
.stringn "무, $w2무슨 일이 있었던 거예요?$K\n"
.stringn "$F1$P$FA무슨 말이지?$K\n"
.stringn "$F3$P피, $w2피가$MC……$MD$w4\n"
.stringn "머리 쪽에서 피가 흐르고 있다고요$MC!?$MD$K\n"
.stringn "$F1$P음?$w4\n"
.stringn "$FS아아 그렇군$MC!$MD$w4 깜빡하고 있었다.$K\n"
.stringn "$F3$P까, $w2깜빡했다고요$MC……?$MD$K$P어, $w2어쨌든\n"
.stringn "그 자리에서 움직이지 마세요.$w4\n"
.stringn "지금 $w2라이브 지팡이를 사용할 테니까$MC……$MD$K\n"
.stringn "$F1$P괜찮다,$w2\n"
.stringn "이 정도는 놔두면 나으니까$MC!$MD$K\n"
.stringn "$F3$P나, $w2나을 리가 없잖아요$MC!$MD$K\n"
.stringn "가만히 있어 주세요$MC……$MD$K$w5$P$Fc$MC…………$MD$w2휴우$MC……$MD$w4\n"
.stringn "$Fd이걸로 일단 괜찮으려나.$w4\n"
.stringn "그나저나$MC……$MD$w2 어쩌다가 다치신 거예요?$K\n"
.stringn "$F1$P뭐, $w2별건 아니고\n"
.stringn "훈련에 너무 열중했을 뿐이다.$K\n"
.stringn "$F3$P훈련?$w4 누구랑\n"
.stringn "겨루시기라도 한 건가요?$K\n"
.stringn "$F1$P아니, $w2그냥 무기를 휘두르고 있었다.$K\n"
.stringn "$F3$P대, $w2대체 뭘 어떻게\n"
.stringn "휘둘렀길래 피가$MC……?$MD$K\n"
.stringn "$F1$P나는 크리미아 기사니까 말이다$MC!$MD$w4\n"
.stringn "꽤 자주 있는 일이지,$w2\n"
.stringn "신경 쓸 필요는 없다$MC!$MD$K\n"
.stringn "$F3$P$Fc$F1$P$MC……$MD응? $w2왜 그러지 킬로이?$K\n"
.stringn "$F3$P죄, $w2죄송해요$MC……$MD$w4\n"
.stringn "조금 현기증이$MC……$MD$K$P$Fd어, $w2언제나 그렇게\n"
.stringn "혹독한 훈련을 하고 계신 건가요?$K\n"
.stringn "$F1$P물론이다.$w4\n"
.stringn "나는 크리미아 기사니까 말이지$MC!$MD$K$P비록 훈련이더라도$w2\n"
.stringn "하려면 제대로 해야 하는 법$MC!$MD$K\n"
.stringn "언제 어떤 장소든지 간에\n"
.stringn "전력을 다해 $w2단련할 뿐이다$MC!$MD$K\n"
.stringn "$F3$P그 마음가짐은\n"
.stringn "대단히 훌륭하다고 생각하지만$MC……$MD$w4\n"
.stringn "$MC……$MD불안한데$MC……$MD$K"
db 0
.align 4
//MYELL_KEVIN_KILROY_C

