//0x26B88
Text_26B68:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_MARCIA|$F1$P케빈씨$MC!$MD$K\n"
.stringn "$F3$FS$F3$FCL_KEVIN|$F3$P음, $w2마샤 공인가$MC!$MD$K\n"
.stringn "$F1$P케빈씨의 말,$w2\n"
.stringn "건강해진 것 같네요.$w4\n"
.stringn "다행이다.$K\n"
.stringn "$F3$P그래, $w2마샤 공 덕분이다.$w4\n"
.stringn "다시 한번 예를$MC……$MD$K\n"
.stringn "$F1$P그 얘기는 이제 됐다고 했잖아요.$w4\n"
.stringn "그것보다, $w2지금\n"
.stringn "어디 외출하시려고요?$K\n"
.stringn "$F3$P아니, $w2오랜만에\n"
.stringn "말의 몸을 씻겨 주려고 한다.$K$P항상 고생을 하고 있으니$w2\n"
.stringn "전쟁 중간에\n"
.stringn "가능한 만큼 보살펴 주고 싶군.$K\n"
.stringn "$F1$P$MC……$MD멋지네요.$K\n"
.stringn "$F3$P$FA뭐가 말이냐?$K\n"
.stringn "$F1$P저번에도 생각했지만,$w2\n"
.stringn "케빈씨, $w2말을 $w2무척이나\n"
.stringn "신경 써 주시잖아요$MC……$MD$K\n"
.stringn "$F3$P$FS물론이다$MC!$MD$w4 내게 있어서는$w2\n"
.stringn "소중한 전우니까.$K$P기사 동료들 중에는 『그래 봤자 탈것』이라는\n"
.stringn "녀석들도 있지만, $w2내 생각은 다르다.$K$P말뿐만이 아니다,$w2\n"
.stringn "갑옷도 도끼도, $w2함께 싸우는 것들 전부\n"
.stringn "내게 있어서는 소중한 전우다$MC!$MD$K\n"
.stringn "$F1$P훌륭하시네요.$K\n"
.stringn "$F3$P$FA훌륭하다고?$w4\n"
.stringn "당연한 이야기를 한 것뿐이다.$K\n"
.stringn "$F1$P당연하지 않은걸요.$w4\n"
.stringn "다른 건 자주 잊어버리거나$w2\n"
.stringn "깜빡하고 그러시면서$MC……$MD$K\n"
.stringn "우후후$K\n"
.stringn "$F3$P그런가?$w4\n"
.stringn "조금 $w2납득이 안 간다만$MC…$MD$K\n"
.stringn "$F1$P후후$K"
db 0
.align 4
//MYELL_KEVIN_MARCIA_A

//0x26604
Text_265E4:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_KEVIN|$F1$P마샤 공$MC!$MD$K\n"
.stringn "$F3$FS$F3$FCL_MARCIA|$F3$P아, $w2케빈씨.$w4\n"
.stringn "$FA$MC…$MD말의 상태는 $w2좋아졌나요?$K\n"
.stringn "$F1$P$FS그래, $w2상당히 괜찮아졌다$MC!$MD$w4\n"
.stringn "마샤 공 덕분이야.$K$P$FA처음에 $w2상태가 이상할 때는\n"
.stringn "어쩌나 했는데$MC……$MD$w2\n"
.stringn "$FS마샤 공의 응급 처치 덕분에 산 것 같군$MC!$MD$K\n"
.stringn "$F3$P행군하면서 피로가 쌓였었나 봐요.$w4\n"
.stringn "그만큼 오랫동안 $w2이동하면서 싸웠으니까\n"
.stringn "어쩔 수 없죠.$K$P$FS토지의 변화에 적응할 때까지\n"
.stringn "잠시 쉬게 하면 다시 건강해질 거예요.$K\n"
.stringn "$F1$P$FA나는 크리미아 국내에서만\n"
.stringn "싸웠기 때문에$w2\n"
.stringn "그런 지식은 없었다.$K$P정말로, $w2마음 깊이 감사를 표하지$MC!$MD$K\n"
.stringn "$F3$P에이, $w2됐어요$MC!$MD$K$P저도 용병이 되고 나서$w2\n"
.stringn "여기저기 다니다 보니까\n"
.stringn "우연히 알게 된 것뿐이니까요.$K\n"
.stringn "$F1$P이 은혜는, $w2무슨 일이 있더라도$MC…$MD$K\n"
.stringn "$F3$P그러니까 $w2괜찮다니까요.$K$P앞으로의 전투에서$w2\n"
.stringn "케빈씨는 알고 계시지만\n"
.stringn "저는 모르는 것들이 많을 거라 생각해요.$K$P그때 힘이 되어 주신다면\n"
.stringn "그걸로 충분합니다.$K\n"
.stringn "$F1$P$FS알았다$MC!$MD$w4\n"
.stringn "그때는, $w2내 목숨과 맞바꿔서$MC…$MD$K\n"
.stringn "$F3$P$FA죽을 것까지는 없다구요$MC!$MD$K$P$MC……$MD그러고 보니 케빈씨,$w2\n"
.stringn "전에 저한테 무슨 볼일이\n"
.stringn "있던 게 아니었나요?$K\n"
.stringn "$F1$P$FA그건$MC……$MD$w2 애마의 상태 건도 있고 하니\n"
.stringn "완전히 잊어버리고 말았군$MC……$MD$w4\n"
.stringn "언젠가 꼭 떠올리겠다고 이 도끼에 맹세를$MC…$MD$K\n"
.stringn "$F3$P맹세하지 않아도 된다고요~$MC!$MD$w4\n"
.stringn "정말, $w2왜\n"
.stringn "그렇게 되는 거냐구요~$K"
db 0
.align 4
//MYELL_KEVIN_MARCIA_B

//0x26070
Text_26050:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_KEVIN|$F3$P으음, $w2능력 향상을 위해\n"
.stringn "한번 천마 기사와$w2\n"
.stringn "겨뤄 보고 싶은데$MC……$MD$K$P$FS오, $w2있다 있다, $w2마샤 공$MC!$MD$K\n"
.stringn "$F1$FCL_MARCIA|$F1$P네?$K\n"
.stringn "$F3$P크흠, $w2어, $w2한번 귀공과$MC…$MD$w4\n"
.stringn "$FA이런, $w2그 전에 이름을 대야지.$w4\n"
.stringn "내 이름은$MC……$MD$K\n"
.stringn "$F1$P$FS알고 있습니다.$w4\n"
.stringn "크리미아 왕국 왕궁 기사,$w2\n"
.stringn "5번 소대 대장 케빈씨 맞죠?$K\n"
.stringn "$F3$P엇!? $w2어떻게 내 이름을?$w4\n"
.stringn "게다가 소속까지$MC…$MD$K$P설마, $w2내가 지난번 전투에서\n"
.stringn "자신도 모르게 공을 세웠던 것인가?$w4\n"
.stringn "$MC…$MD하지만, $w2짚이는 구석이 없는데.$K\n"
.stringn "$F1$P$FA$MC……$MD저기~$K\n"
.stringn "$F3$P혹시, $w2그럴 리 없지만\n"
.stringn "이 내가 엄청난 실수를 했다든가?$w4\n"
.stringn "아냐, $w2그런 기억도 없어.$K\n"
.stringn "$F1$P저기~$MC……$MD$K\n"
.stringn "$F3$P그것도 아니라면, $w2나의 무용이\n"
.stringn "타국에까지 울려 퍼진 것인가?$w4\n"
.stringn "$FS$MC…$MD아니아니, $w2아무리 그래도 그건.$K$P$FA허나, $w2있을 수 없는 이야기는 아니군.$w4\n"
.stringn "다른 가능성으로는$MC…$MD$K\n"
.stringn "$F1$P저기요~$MC!!$MD$K\n"
.stringn "$F3$P뭐, $w2뭐냐.$w4\n"
.stringn "갑자기 놀래키다니$MC!$MD$K\n"
.stringn "$F1$P케빈씨 이름이라면 다 알죠.$w4\n"
.stringn "그야 $w2싸우기 전에,$w2\n"
.stringn "항상 이렇게 이름을 대잖아요.$K$P『나는 $w2크리미아 왕국 왕궁 기사,$w2\n"
.stringn " 5번 소대 대장 케빈이다』$w2라고.$K\n"
.stringn "$F3$P$FS과연, $w2그런 것이었군$MC!$MD$K\n"
.stringn "$F1$P$FS그래서, $w2용건이 뭔가요?$K\n"
.stringn "$F3$P$FA어?$K\n"
.stringn "$F1$P$FA제게 볼일이\n"
.stringn "있는 게 아니셨나요?$K\n"
.stringn "$F3$P$FS아, $w2그랬지.$w4\n"
.stringn "그러니까$MC…$MD$w4 $FA응?$w4 뭐였더라?$K\n"
.stringn "$F1$P$MC……$MD생각나면 말씀해 주세요.$K"
db 0
.align 4
//MYELL_KEVIN_MARCIA_C

//0x27934
Text_27914:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_KEVIN|$F1$P오스카$MC!!$MD$K\n"
.stringn "$F3$FS$F3$FCL_OSCAR|$F3$P안녕, $w2또 기사단으로 돌아오라는 얘기야?$K\n"
.stringn "$F1$P그 말대로다$MC!$MD$w4\n"
.stringn "나는 크리미아 기사지.$w4\n"
.stringn "그리고 난 그걸 자랑스럽게 생각한다$MC!$MD$K$P전장에서 화려하게 공을 세워$w2\n"
.stringn "사람들의 찬사를 받아 승리해 나가고$w2\n"
.stringn "주군께서는 칭송을 내리신다.$K$P기사로서 이름을 날린다면\n"
.stringn "온 세상에 널리 퍼지게 되고$w2\n"
.stringn "나아가 영지를 하사받을 수도 있다.$K$P무엇보다 $w2사랑하는 크리미아와 그 백성들을\n"
.stringn "이 손으로 지킬 수 있는 것이다$MC!!$MD$K\n"
.stringn "$F3$P그렇지.$K\n"
.stringn "$F1$P무법자들의 무리에 섞여$w2\n"
.stringn "한 치 앞도 모르는 싸움에 뛰어드는\n"
.stringn "용병 따위보다 훨씬 나을 거다.$K$P그런데 어째서지?$w4\n"
.stringn "난 도저히 이해할 수가 없다$MC!$MD$K\n"
.stringn "$F3$P$FA$MC…………$MD$K\n"
.stringn "$F1$P네놈의 실력은\n"
.stringn "내가 제일 잘 알고 있다.$w4\n"
.stringn "어찌 됐든 내 영원한 호적수니까.$K$P네놈에게 돌아올 의지가 있다면$w2\n"
.stringn "기사단으로 복귀할 수 있도록\n"
.stringn "내가 전력을 다해 추진하도록 하지$MC!$MD$K\n"
.stringn "$F3$P$FS고마워.$w4\n"
.stringn "하지만 $w2돌아갈 마음은 전혀 없어.$K$P$FA$MC……$MD용병단에 들어가$w4\n"
.stringn "여러 일들을 하면서$MC……$MD$w4\n"
.stringn "나는 백성들이 겪는 슬픔을 알게 됐어.$K$P아무도 모르게 죽어 가는 사람들이 있고$w4\n"
.stringn "나라조차 구할 수 없는 사람들이 있어.$K$P그렇다면 $w2그들을 구할 수 있는 건\n"
.stringn "우리 같은 민간인이라고 생각해.$K$P$FS그리고 나는 $w2명예 같은 건 필요 없어.$w4\n"
.stringn "용병단이라는 내 가족을 지킬 수만 있다면$w2\n"
.stringn "그걸로 충분해.$K\n"
.stringn "$F1$P제$MC……$MD$w4젠자앙$MC!$MD$w4\n"
.stringn "네놈, $w2뭔지 모르겠지만 눈부시다$MC!$MD$K$P어째서냐$MC……$MD$w2 또다시\n"
.stringn "네놈에게 진 기분이다$MC……$MD$MC!$MD$K\n"
.stringn "$F3$P그렇지 않아.$w4\n"
.stringn "너 같은 기사가 아니라면$w2\n"
.stringn "못하는 일도 많은걸.$K$P그러니까 $w2서로 힘내자.$w4\n"
.stringn "입장은 다르지만,$w2\n"
.stringn "목표로 하는 이상은 같으니까.$K\n"
.stringn "$F1$P$MC…………$MD그런가.$w4\n"
.stringn "그렇다면 $w2아무 말 않겠다$MC!!$MD$K$P크리미아 부흥이 이루어진 새벽,$w2\n"
.stringn "나는 반드시 대륙 전체에\n"
.stringn "울려퍼질 만한 활약을 하고야 말 것이다$MC!$MD$K$P$FS네놈이 어디에 있든,$w2\n"
.stringn "내 활약이 전해지도록 말이다$MC!$MD$K\n"
.stringn "$F3$P그래, $w2너라면 반드시 할 수 있어.$w4\n"
.stringn "이 대륙 어딘가에서$w2\n"
.stringn "무운을 빌고 있을게.$K"
db 0
.align 4
//MYELL_KEVIN_OSCAR_A

//0x273F8
Text_273D8:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_KEVIN|$F1$P오스카$MC!!$MD$K\n"
.stringn "$F3$FS$F3$FCL_OSCAR|$F3$P안녕, $w2여전히 기운이 넘치는구나.$K\n"
.stringn "$F1$P크리미아 기사단으로 돌아와라$MC!$MD$K\n"
.stringn "$F3$P그리고 $w2여전히 뜬금없네.$K\n"
.stringn "$F1$P전 크리미아 기사로서$w2\n"
.stringn "주군을 향한 충성심을 가지란 말이다$MC!$MD$K$P지금은 조국의 위기$MC!$MD$w4\n"
.stringn "크리미아 기사였던 자라면\n"
.stringn "곧바로 이 위기에 나서야 할 때가 아닌가$MC!$MD$K\n"
.stringn "$F3$P그렇지.$K$P지금은 용병이지만$w2\n"
.stringn "조국 부흥에 도움이 되어서 기뻐.$K\n"
.stringn "$F1$P기뻐, $w2좋아하시네$MC!$MD$w4\n"
.stringn "난 네놈에게 다시 기사가 되라고 말하는 거다$MC!$MD$K$P용병으로서는 $w2조국에 대한\n"
.stringn "충성심을 다할 수 없지$MC!$MD$w4\n"
.stringn "그래도 괜찮은 거냐$MC!$MD$K\n"
.stringn "$F3$P그래, $w3괜찮아.$K$P나는 $w2그레일 용병단의 단원으로서\n"
.stringn "언제까지나 $w2아이크와 모두랑\n"
.stringn "함께 지내고 싶어.$K\n"
.stringn "$F1$P큭$MC……$MD$w2 어째서냐$MC!$MD$w4\n"
.stringn "무엇이 네놈을 그렇게까지 끌어당기지$MC…$MD$K$P위대한 조국 크리미아를 향한\n"
.stringn "충성과도 맞바꿀\n"
.stringn "용병단이라니 대체$MC……$MD$MC!?$MD$K$P하$MC!$MD$w4 그렇다면 높은 급료인가$MC!?$MD$w4\n"
.stringn "그렇겠지$MC!$MD$w4 네놈은 가족을 위해서\n"
.stringn "돈이 필요하다고 했으니까$MC!$MD$K\n"
.stringn "$F3$P돈이 문제였다면 $w2그대로\n"
.stringn "크리미아 기사단에 남았겠지.$w4\n"
.stringn "지금 받는 보수는 $w2그때의 절반도 안 되고.$K\n"
.stringn "$F1$P뭐라고$MC!?$MD$w4\n"
.stringn "정신 차려라$MC!$MD$w4\n"
.stringn "네놈은 $w2속고 있는 거다$MC!!$MD$K\n"
.stringn "$F3$P아냐 아냐.$K\n"
.stringn "$F1$P에에잇$MC…$MD$MC!$MD$w2\n"
.stringn "정말이지 완고한 녀석이군$MC!$MD$K\n"
.stringn "$F3$P$MC……$MD네가 말이지.$K"
db 0
.align 4
//MYELL_KEVIN_OSCAR_B

//0x2700C
Text_26FEC:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_OSCAR|$F1$P안녕 $w2케빈.$w4\n"
.stringn "요즘 잘 지내?$K\n"
.stringn "$F3$FCL_KEVIN|$F3$P오스카 $w2네놈$MC!$MD$w4\n"
.stringn "뻔뻔하게 인사하지 마랏$MC!$MD$K\n"
.stringn "$F1$P$FA$MC…$MD오늘은 내 어떤 점에\n"
.stringn "화난 거야?$K\n"
.stringn "$F3$P잊을 리가 없지. $w2입대 2년 차 때,$w4\n"
.stringn "우리는 승마로 경주를 했다$MC!$MD$K$P나와 애마는 훌륭히 달렸지만,$w2\n"
.stringn "근소한 차이로$w2\n"
.stringn "네놈에게 패배했지$MC……$MD 큭$MC!$MD$K\n"
.stringn "$F1$P음$MC…$MD$w4 아, $w2그때.$K$P내 기억으로는$w2\n"
.stringn "근소한 차이가 아니라 한$w3\n"
.stringn "3마신 정도는 떨어져 있었던 것 같은데.$K\n"
.stringn "$F3$P그 순간부터$w2\n"
.stringn "네놈과 나는 영원한 호적수로\n"
.stringn "정해진 것을 몰랐나$MC!?$MD$K\n"
.stringn "$F1$P$MC……$MD모르고 있었어.$K\n"
.stringn "$F3$P그랬던 네놈이 대체 왜$MC!$MD$w4\n"
.stringn "이 내게 한 마디도 없이$MC!$MD$w4\n"
.stringn "기사단을 그만둔 거냐$MC!?$MD$K$P난 $w2설욕을 위해$w2\n"
.stringn "애마와 함께 훈련에 몰두했다$MC…$MD$K$P$MC……$MD너무 몰두한 탓에,$w3\n"
.stringn "네놈이 없어진 걸 깨달았을 때는$w2\n"
.stringn "이미 반년이 지나 있었지$MC!$MD$K\n"
.stringn "$F1$P잠깐 $w2케빈$MC…$MD$w4\n"
.stringn "그거$MC…$MD$w2 내 탓이야?$K"
db 0
.align 4
//MYELL_KEVIN_OSCAR_C

//0x28CB0
Text_28C90:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_LOFA|$F1$P킬로이씨?$K\n"
.stringn "$F3$FS$F3$FCL_KILROY|$F3$P요파?$w4 왜 그래?$K\n"
.stringn "$F1$P아$MC……$MD$w3\n"
.stringn "$FS오늘은 아프지 않나 보네.$w4\n"
.stringn "다행이다.$K\n"
.stringn "$F3$P$FA$MC……$MD미안해.$w4\n"
.stringn "계속 요파에게 걱정만 끼치고$MC…$MD$K$P이럴 바에는 $w2내가 용병단을\n"
.stringn "나가는 편이 좋을지도 모르겠어$MC…$MD$K\n"
.stringn "$F1$P$FA$MC!?$MD$w4 안 돼$MC!$MD$w4\n"
.stringn "그런 뜻으로 말한 게 아니야$MC!$MD$K\n"
.stringn "$F3$P$FS응, $w2알고 있어.$w4\n"
.stringn "$FA그치만$MC……$MD$w2 내가 괴로워.$K$P싸우는 것만으로도 힘들 텐데,$w2\n"
.stringn "괜한 걱정까지 시키고$MC……$MD$K$P아이크나 티아마트씨에게도 폐를 끼치고 있어.$w4\n"
.stringn "그러니까$MC…$MD$w2 모두와 헤어지고 싶지 않지만$MC……$MD$K\n"
.stringn "$F1$P싫어$MC!!$MD$w4\n"
.stringn "킬로이씨가 없어지다니\n"
.stringn "싫다고$MC!$MD$K$P미안해, $w2나$MC……$MD$w3\n"
.stringn "킬로이씨를 탓한 건 아니야$MC……$MD$K$P그야 $w2병에 걸린 건 킬로이씨의\n"
.stringn "잘못이 아니니까$MC……$MD$K\n"
.stringn "$F3$P$MC…………$MD요파$MC……$MD$K\n"
.stringn "$F1$P$MC……$MD나는 그냥 $w4킬로이씨가 $w2제대로\n"
.stringn "나를 $w2의지해 주길 바랐을 뿐이었어.$K\n"
.stringn "$F3$P뭐?$K\n"
.stringn "$F1$P싸운다는 건$MC……$MD$w3 사람을, $w2쓰러뜨리는$MC…$MD 거잖아.\n"
.stringn "정말로 무섭고 $w2떨리지만$MC……$MD$K$P그래도 $w2난 $w2용병단의 모두가 죽지 않았으면 좋겠어.$w4\n"
.stringn "전에는 아무것도 못하고 기도할 수밖에 없었지만$MC…$MD$w3\n"
.stringn "지금은 $w2싸워서 모두를 지킬 수 있어.$K$P그러니까 $w2다행이라고 $w2생각했어.$K$P이렇게 모두와 같이 $w2싸울 수 있게\n"
.stringn "된 건 잘된 일이라고$MC……$MD$w3\n"
.stringn "생각해서$MC……$MD$K\n"
.stringn "$F3$P$MC…………$MD$K\n"
.stringn "$F1$P그러니까 $w2꼭 지키고 싶어.$w4\n"
.stringn "킬로이씨를.$K$P지키기 위해 싸운다고 생각하면$w2\n"
.stringn "떨리지 않아.$K$P나 $w2노력할 테니까$MC…$MD$w2 강해질 테니까$MC……$MD$w4\n"
.stringn "그러니까 $w2나간다고 하지 마$MC……$MD$K\n"
.stringn "$F3$P요파$MC……$MD$w2 너$MC…………$MD$w4\n"
.stringn "$MC……………………$MD$K$P$FS강해졌구나, $w2요파$MC……$MD$w3\n"
.stringn "앞으로는 무슨 일이 있으면 제대로\n"
.stringn "말하도록 할게.$K$P그리고 $w2의지도 할 테니까$MC……$MD$w4\n"
.stringn "$MC…………$MD고마워.$K\n"
.stringn "$F1$P$FS$MC……$MD응$MC!$MD$K"
db 0
.align 4
//MYELL_KILROY_LOFA_A

//0x286F4
Text_286D4:
.stringn "$R背景会話|$B支援背景|$<$F3$FS$F3$FCL_LOFA|$F3$P아, $w2킬로이씨$MC!$MD$K\n"
.stringn "$F1$FS$F1$FCL_KILROY|$F1$P$MC……$MD응?$w4\n"
.stringn "요파, $w2무슨 일 있어?$K\n"
.stringn "$F3$P$FA아$MC……$MD$w4 오늘도 어디 아픈 거지?$K\n"
.stringn "$F1$P아냐, 난 괜찮아.$w4\n"
.stringn "왜 그래?$K\n"
.stringn "$F3$P거짓말하면 안 돼$MC!$MD$w4\n"
.stringn "난 알 수 있거든$MC!$MD$K$P킬로이씨는 $w2힘들 때\n"
.stringn "얼굴이 새파래지는걸$MC!$MD$K$P$MC……$MD손, $w2이리 줘 봐$MC!$MD$K$F3$FD\n"
.stringn "$F2$FCL_LOFA|$F1$P$FA아$MC……$MD$K\n"
.stringn "$F2$P봐봐, $w2완전 차갑네$MC!$MD$w4\n"
.stringn "$MC……$MD힘들 때는 제대로 나한테 알려 달라$w2고\n"
.stringn "말했었는데$MC……$MD$K\n"
.stringn "$F1$P미안해, $w2요파.$w4\n"
.stringn "그래도 $w2제대로 전장에 설 수 있을 정도는\n"
.stringn "되니까, $w2괜찮아$MC……$MD$K\n"
.stringn "$F2$FD$F3$FCL_LOFA2|$F3$P괜찮긴 뭐가 괜찮아$MC!$MD$w4\n"
.stringn "여긴 전장이야,$w2\n"
.stringn "요새 안이 아니라고$MC!$MD$K$P몸이 안 좋은데 자꾸 숨기면$MC……$MD$w2\n"
.stringn "$Fh자꾸 그러면$MC……$MD$w3\n"
.stringn "킬로이씨 $w2언젠가 죽을지도 몰라$MC…$MD$K\n"
.stringn "$F1$P$MC……$MD요파$MC…………$MD$w4\n"
.stringn "미, $w2미안해$MC……$MD$K\n"
.stringn "$F3$P$MC……………………$MD$K\n"
.stringn "$F1$P$MC……$MD정말로 미안해, $w2요파.$w4\n"
.stringn "요파가$MC……$MD$w2 나보다도 훨씬\n"
.stringn "잘 알고 있었구나$MC……$MD$K\n"
.stringn "$F3$P$Fd$MC…………$MD$w2지팡이로 병도$MC……$MD$w3\n"
.stringn "고칠 수 있으면 좋을 텐데$MC……$MD$K\n"
.stringn "$F1$P$MC……$MD그러게.$w4\n"
.stringn "병이 나으면$MC……$MD$w2 이런 걱정은 $w2하지 않아도\n"
.stringn "될 텐데 말이야$MC……$MD$w4 $Fc$MC……$MD$K\n"
.stringn "$F3$FD$F1$P$Fd$F4$FS$F4$FCL_LOFA|$F4$P아이크씨한테 $w2부탁해 볼게.$w4\n"
.stringn "나랑 킬로이씨가 전투에 나갈 때\n"
.stringn "같이 있을 수 있게 해 달라고.$K\n"
.stringn "$F1$P$FS고마워, $w2요파$MC……$MD$K"
db 0
.align 4
//MYELL_KILROY_LOFA_B

//0x28094
Text_28074:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_LOFA|$F1$P킬로이씨$MC!$MD$K\n"
.stringn "$F3$FS$F3$FCL_KILROY|$F3$P안녕 $w2요파.$w4\n"
.stringn "그렇게 급하게 달려오고$MC…$MD$w2 무슨 일 있어?$K\n"
.stringn "$F1$P아니, $w2킬로이씨가 보이길래\n"
.stringn "그냥 달려 온 것뿐이야.$w4\n"
.stringn "있지, $w2몸은 괜찮아?$K\n"
.stringn "$F3$P고마워. $w4오늘은 괜찮아.$w4\n"
.stringn "아침에도 가볍게 운동을 했고,$w2\n"
.stringn "식사도 모두랑 같이 잘 먹었어.$K\n"
.stringn "$F1$P그래? $w2다행이다$MC!$MD$w4\n"
.stringn "힘들 때는 꼭 나한테 말해 줘$MC!$MD$K$P$FA킬로이씨, $w2모두하고 용병단 요새에\n"
.stringn "있었을 때에는 $w2자주 몸이 아파서\n"
.stringn "누워 있었는데$MC……$MD$K$P계속 싸우고 있잖아.$K\n"
.stringn "$F3$P응$MC……$MD$w3 하지만 $w2모두와 함께\n"
.stringn "있을 수 있어서 기뻐.$K\n"
.stringn "$F1$P$FS나도$MC!$MD$w4\n"
.stringn "미스트랑 킬로이씨랑 나는\n"
.stringn "요새에서 기다리기만 했으니까.$K$P$FA혼자 남겨져서 외롭고$w2\n"
.stringn "엄청 무서웠었어$MC……$MD$K\n"
.stringn "$F3$P$FA그랬지$MC……$MD$K$P다음 임무는 위험하다$w2고\n"
.stringn "우연히 작전실 앞을\n"
.stringn "지나가다가 들어 버렸을 때$MC…$MD$K$P셋이서 열심히\n"
.stringn "무사하기를 빌었던 적도 있었고.$K$P고작 2일 동안이었지만$MC……$MD$w4\n"
.stringn "너무나도 길게 느껴졌었어$MC……$MD$K\n"
.stringn "$F1$P그래서 $w2싸우는 건 무서울 때도 있지만$MC…$MD$K\n"
.stringn "$FS항상 모두의 곁에 있을 수 있게 된 건\n"
.stringn "다행일지도 모른다고 $w1생각해.$K\n"
.stringn "$F3$P$MC…………$MD$w3조금 생각이 복잡하지만$MC……$MD$w4\n"
.stringn "$FS나도 잘됐다고 여기는 게 맞다고 봐.$w4\n"
.stringn "나쁘다고 생각해 봤자 좋을 것도 없고.$K$P긍정적으로 생각하도록 노력해야겠어.$K\n"
.stringn "$F1$P그렇지$MC!$MD$w4\n"
.stringn "긍정적으로 생각해야 돼.$w4\n"
.stringn "$FA그렇지 않으면, $w2나는$MC……$MD$K\n"
.stringn "$F3$P$FA$MC……$MD요파?$K\n"
.stringn "$F1$P$FS아무것도 아냐$MC!$MD$w4\n"
.stringn "나, $w2미스트한테도 볼일이 있으니까$MC……$MD$w4\n"
.stringn "나중에 봐, $w2킬로이씨$MC!$MD$K$F1$FD\n"
.stringn "$F3$P$MC………………$MD$K"
db 0
.align 4
//MYELL_KILROY_LOFA_C

//0x2A234
Text_2A214:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_KILROY|$F1$P티아마트씨.$w4\n"
.stringn "오늘도 잠깐이지만$w2\n"
.stringn "훈련에 동참할 수 있을까요?$K\n"
.stringn "$F3$FS$F3$FCL_TIAMAT|$F3$P그래, $w2물론이야.$K$P너 제법 체력이 붙지 않았어?$w4\n"
.stringn "예전보다 안색도 좋은 것 같고.$K\n"
.stringn "$F1$P네,$w2\n"
.stringn "티아마트씨 덕분이에요.$K\n"
.stringn "$F3$P후후$MC……$MD$w2 그렇다면 다행인걸.$K$w3$P$FA$MC……$MD저기, $w2킬로이.$w4\n"
.stringn "너는 아이크를 어떻게 생각해?$K\n"
.stringn "$F1$P$FA아이크 말인가요?$w4\n"
.stringn "전투 능력 같은 건\n"
.stringn "잘 모르겠지만$MC……$MD$K$P$FS아이크는 그래 보여도\n"
.stringn "세심한 배려가 있는 사람이고,$K$P무엇보다 흔들림 없는 의지와\n"
.stringn "이상을 현실로 이끌 만한 힘을 가지고 있죠.$K$P그레일 용병단의 단장에\n"
.stringn "걸맞은 인물이라고 생각해요.$K\n"
.stringn "$F3$P$FS그래. $w4나도 그렇게 생각해.$K$P$FA그렇지만$MC……$MD 아이크는 아직 젊어.$w4\n"
.stringn "앞으로 겪게 될 일들이$w2\n"
.stringn "그 애를 어느 쪽으로 이끌지$MC……$MD$K\n"
.stringn "조금 걱정돼.$K\n"
.stringn "$F1$P$FA어째선가요?$K\n"
.stringn "$F3$P앞으로 $w2용병단이 커지면서\n"
.stringn "여러 가지 유혹이 늘어날 거라고 생각해.$K$P돈은 벌 수 있지만 $w2어디의 누군가는\n"
.stringn "상처받고, $w2눈물을 흘리는$MC……$MD$w4\n"
.stringn "그런 의뢰도 들어오겠지.$K$P하지만, $w2단원들을 부양하고 $w2용병단을 존속시키려면\n"
.stringn "돈이 되는 일을 선택해야 쉽게 살아갈 수 있어.$K\n"
.stringn "$F1$P$FS하지만$w2\n"
.stringn "그레일 단장님은 달랐어요.$K\n"
.stringn "$F3$P$FS그래$MC……$MD$w4\n"
.stringn "우리 그레일 용병단은$w2\n"
.stringn "용병단답지 않기로 유명했지.$K$P때로는 무상으로 일을 맡고$MC……$MD$w4\n"
.stringn "사람들을 많이 구해 왔어.$K\n"
.stringn "$F1$P아이크도 $w2마찬가지예요.$w4\n"
.stringn "분명 $w2그레일 단장님과\n"
.stringn "같은 이상을 가지고 있을 거라고 생각해요.$K\n"
.stringn "$F3$P$MC……$MD그렇지, $w2분명$MC……$MD$K$P나 같은 사람이 말해 주지 않아도,$w2\n"
.stringn "우리가 싸우는 이유를, $w2살아가는 의미를$MC…$MD$w2\n"
.stringn "아이크라면 반드시 올바른 길로 이끌어 줄 거야.$K$P우리는 $w2그저 아이크를 믿고\n"
.stringn "함께 따라가 주면 돼$MC……$MD$K\n"
.stringn "$F1$P$MC……$MD네.$K"
db 0
.align 4
//MYELL_KILROY_TIAMAT_A

//0x29AE8
Text_29AC8:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_KILROY|$F1$P티아마트씨,$w2\n"
.stringn "오늘도 훈련하세요?$K\n"
.stringn "$F3$FS$F3$FCL_TIAMAT|$F3$P그래, $w2몸을 움직이지 않으면\n"
.stringn "뭔가 심란해서.$K\n"
.stringn "$F1$P잠깐 $w2같이 해도\n"
.stringn "괜찮을까요?$K\n"
.stringn "$F3$P$FA어, $w2물론 상관없어.$w4\n"
.stringn "근데 갑자기 왜?$K\n"
.stringn "$F1$P적어도 $w2제 몸만큼은 지킬 수 있도록\n"
.stringn "뭔가 할 수 있는 일이 없을까 $w2해서요$MC……$MD$K$P모두의 발목을\n"
.stringn "잡는 건 싫어서$MC……$MD$K\n"
.stringn "$F3$P그래도 $w2그건 어쩔 수 없잖아?$w4\n"
.stringn "킬로이는 $w2이곳에 들어올 때까지\n"
.stringn "싸움 같은 건 해본 적이 없었으니까.$K$P그리고 지금은 용병단의 일원$MC……$MD$w4\n"
.stringn "$MC…………$MD$K\n"
.stringn "$F1$P$FA티아마트씨?$K\n"
.stringn "$F3$P$MC……$MD사실, $w2나를 구해 주지 않았던 편이\n"
.stringn "킬로이한테는 더 행복했을지도 몰라.$K$P부모님과 평온한 삶을 보내는 게\n"
.stringn "킬로이한테는 더 맞는 일일텐데.$K\n"
.stringn "$F1$P$FS하지만 $w2부모님께서 벌어 오시는 돈만으로는\n"
.stringn "먹고 살기 힘들었어요.$K$P저처럼 몸이 약한 사람을$w2\n"
.stringn "고용해 주는 일은$w2\n"
.stringn "그 작은 마을엔 아무것도 없었거든요.$K$P부모님께서도 몸이 약한 걸 걱정하셔서\n"
.stringn "제게 마을에 머무르라고 하셨지만$MC……$MD$K$P티아마트씨 같은 사람이 있는 용병단이라면\n"
.stringn "안심이라고 $w2바래다 주셨어요.$K\n"
.stringn "$F3$P$MC……$MD그래도 $w2분명 다른 곳에 더\n"
.stringn "안전한 일이 있을지도 모르는데$MC……$MD$K\n"
.stringn "$F1$P티아마트씨.$w4\n"
.stringn "저는 계속 $w2동경하고 있었어요.$K$P어렸을 때는 이불에 누워 있던 적이 많아서$MC……$MD$w2\n"
.stringn "사이좋게 밖에서 노는 아이들의 목소리를\n"
.stringn "부러워하면서 듣고 있었죠.$K$P그런 저를 귀여워해 주셨던 숙부님은\n"
.stringn "용병이셨는데$MC……$MD$w2 여러 곳의 $w2다양한 이야기를\n"
.stringn "잔뜩 들려주셨어요.$K$P그래서 $w2저는 언젠가 반드시$w2\n"
.stringn "용병이 되겠다고 생각했었답니다.$K\n"
.stringn "$F3$P그랬던 거야?$w4 의외인걸.$K\n"
.stringn "$F1$P그렇죠.$K$P그러니까, $w2지금 이렇게 싸워 나가고 있는 걸$MC…$MD$w3\n"
.stringn "말하긴 좀 그렇지만, $w2꿈이 이루어진 것 같아서\n"
.stringn "기쁘다는 생각이 $w2들 때도 있어요.$K\n"
.stringn "$F3$P$FS$MC……$MD그렇구나.$K$P우리에게 $w2네 존재는 정말로\n"
.stringn "크니까$MC……$MD$w3 그렇게 생각해 준다고 하니\n"
.stringn "기쁘네$MC……$MD$K"
db 0
.align 4
//MYELL_KILROY_TIAMAT_B

//0x29450
Text_29430:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_TIAMAT|$F1$P킬로이, $w2몸은 좀 괜찮아?$K\n"
.stringn "$F3$FS$F3$FCL_KILROY|$F3$P네.$w4\n"
.stringn "오늘은 열도 없고$w2\n"
.stringn "기분도 좋아요.$K$P항상 신경 써 주셔서\n"
.stringn "감사합니다.$K\n"
.stringn "$F1$P그러고 보니$MC……$MD$w2\n"
.stringn "벌써 1년이 다 되어 가네.$w4\n"
.stringn "너와 처음 만난 지$MC……$MD$K\n"
.stringn "$F3$P그렇네요.$K\n"
.stringn "$F1$P그렇다고는 해도,$w2\n"
.stringn "나는 며칠 동안 의식이 없었으니까\n"
.stringn "잘 기억이 안 나지만.$K$P내가 임무에서 중상을 입고$MC……$MD$w4\n"
.stringn "그 당시에는 지팡이 사용자도 없어서,$K$P그때 $w2치료를 해 준 게\n"
.stringn "우연히 거기 있었던 너였지.$K\n"
.stringn "$F3$P마침 약초를 캐러 나가는 중이어서\n"
.stringn "발견할 수 있었습니다만$MC……$MD$w2그런 숲속에서는\n"
.stringn "정말로 위험했어요$MC……$MD$K\n"
.stringn "$F1$P맞아. $w4상대는 오래 전부터\n"
.stringn "네가 살던 마을 근처에서\n"
.stringn "세력을 떨치던 산적단이었고,$K$P생각보다 애먹었어.$K$P놓친 한 명이 숲으로 도망쳤는데$MC……$MD$w3\n"
.stringn "그걸 뒤쫓아갔던 게 패인이었지.$K$P숲속에서는 말의 움직임이 자유롭지 못하니까$MC…$MD$w3\n"
.stringn "시논이 달려와 주지 않았다면\n"
.stringn "어떻게 됐을지…$K\n"
.stringn "$F3$P가트리씨도 시논씨도 $w2저희 집으로\n"
.stringn "티아마트씨를 옮기는 동안 $w2정말로\n"
.stringn "걱정하는 것 같았어요.$K\n"
.stringn "$F1$P어머, $w2그랬었어?$w4 $MC…$MD후후$K$P그래서$MC…$MD$w2 내 상처가 나을 때까지\n"
.stringn "간병을 계속해 줬고$MC……$MD$K$P그때 네가 도와주지 않았다면$w2\n"
.stringn "나는 두 번 다시 도끼를\n"
.stringn "휘두르지 못했을 거야.$K$P정말로 $w2감사하고 있어.$K\n"
.stringn "$F3$P아뇨, $w2저야말로 감사하죠.$K$P지금 이렇게 $w2용병단에\n"
.stringn "고용되어 있는 덕분에 고향에 계신 부모님께\n"
.stringn "생활비를 보내드릴 수 있으니까요.$K$P두 분 다 다리가 안 좋으셔서 $w2저밖에\n"
.stringn "변변한 일꾼이 없거든요.$K\n"
.stringn "$F1$P그래$MC……$MD$w3 그때는 부모님께도\n"
.stringn "정말로 신세 많이 졌어.$K$P그 은혜에 보답하기 위해서라도\n"
.stringn "넌 내가 꼭 지켜 줄게.$K\n"
.stringn "$F3$P감사합니다, $w2티아마트씨.$K"
db 0
.align 4
//MYELL_KILROY_TIAMAT_C

//0x2B1D8
Text_2B1B8:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_VULCI|$F3$FS$F3$FCL_KILROY|$F3$P우르키씨$MC!$MD$K$P다음이 기대되네요$MC!$MD$w4\n"
.stringn "아니 그, $w2싸우는 건 무섭고$w2\n"
.stringn "피해야 한다고 생각하지만$MC……$MD$K$P아 그래도, $w2네$MC!$MD$w4\n"
.stringn "엄청 도움이 될 거라고 생각해요$MC!$MD$K\n"
.stringn "$F1$P$MC…………$MD그렇다면 $w2다행이군.$K\n"
.stringn "$F3$P$FA하지만 $w2우르키씨의 등 뒤에서\n"
.stringn "떨어지지 않게 조심해야겠어요$MC……$MD$K$P$FS아, $w2한 번 더 연습해도\n"
.stringn "괜찮을까요?$K\n"
.stringn "$F1$P$MC……$MD아니$MC…………$MD$w3\n"
.stringn "다음 전투 전까지 이 이상\n"
.stringn "체력을 소모할 순 없다$MC……$MD$K\n"
.stringn "$F3$P$FA그, $w2그렇군요$MC……$MD$w4\n"
.stringn "죄송합니다$MC……$MD$K$w2$P$MC…………$MD$w2혹시$MC……$MD$w4\n"
.stringn "화신하는 건\n"
.stringn "체력이 소모되나요$MC……?$MD$K\n"
.stringn "$F1$P$MC………………$MD그래.$K\n"
.stringn "$F3$P네$MC!?$MD$w4 그랬어요$MC!?$MD$w4\n"
.stringn "그런데도 며칠 동안 $w2그것도 몇 번씩이나\n"
.stringn "연습시켜 주신 겁니까$MC!?$MD$K\n"
.stringn "$F1$P$MC………………$MD괜찮다.$w4\n"
.stringn "말 안하고 있던 내 잘못이니.$K$P네가 그렇게 기뻐하니\n"
.stringn "그만$MC……$MD$w2 말하는 것도 잊었었군.$K\n"
.stringn "$F3$P$MC……$MD지금$MC……$MD$w3\n"
.stringn "안색이 $w2안 좋아 보이는데요?$K$P$MC……………………$MD$w4\n"
.stringn "$Fc죄송합니다$MC……$MD$w4\n"
.stringn "방금 이야기는 없었던 걸로 해요.$MC……$MD$K\n"
.stringn "$F1$P$MC……$MD그러는 편이 $w2좋겠군.$w4\n"
.stringn "체력이 소모된 상태에서 전장에 나가는 건\n"
.stringn "위험할 테니.$K\n"
.stringn "$F3$P$Fd$MC………………$MD$w2네$MC……$MD$K\n"
.stringn "$F1$P$MC…………$MD하지만$MC……$MD$w4\n"
.stringn "또 $w2시간이 된다면$MC……$MD$K$P전장이 아닌 곳에서\n"
.stringn "다시 태워 주도록 하지$MC……$MD$K\n"
.stringn "$F3$P$FS$MC!!$MD$w4\n"
.stringn "네, $w2네에$MC!$MD$w4\n"
.stringn "감사합니다, $w2우르키씨$MC!!$MD$K"
db 0
.align 4
//MYELL_KILROY_VULCI_A

//0x2AD58
Text_2AD38:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_KILROY|$F1$P우르키씨$MC!$MD$K\n"
.stringn "$F3$FCL_VULCI|$F3$P$MC……$MD킬로이인가.$K\n"
.stringn "$F1$P저기, $w2전에 우르키씨가 싸우는 모습을\n"
.stringn "봤습니다만$MC……$MD$w3\n"
.stringn "공중에서 빙글 한 바퀴 돌았었죠?$K\n"
.stringn "$F3$P그랬$MC……$MD$w2던가?$K\n"
.stringn "$F1$P그 뒤로도 몇 번이고 돌면서\n"
.stringn "재빠르게 오른쪽 왼쪽$MC……$MD$w4\n"
.stringn "정말 대단해요$MC!$MD$K\n"
.stringn "$F3$P$MC……$MD아니$MC…………$MD$K\n"
.stringn "$F1$P$Fc아아$MC……$MD$w2 저도 그렇게\n"
.stringn "하늘을 날 수 있다면$MC……$MD$K\n"
.stringn "$F3$P$MC…………$MD$K\n"
.stringn "$F1$P날씨가 좋은 날에는 하늘로 올라가\n"
.stringn "높은 산 위에 내려서서$MC……$MD$w2\n"
.stringn "아래에 보이는 마을이나 상가를 바라보겠죠$MC……$MD$K$P아아$MC……$MD$w2 생각만 해도 즐거워$MC……$MD$K\n"
.stringn "$F3$P$MC……………………$MD$K$P네가$MC……$MD$w2 날 수 있다면$MC……$MD$w3\n"
.stringn "다친 사람을$MC…$MD$w2 더 빨리 치료할 수 있을지도$MC…$MD$K\n"
.stringn "$F1$P$Fd아, $w2그것도 굉장하네요$MC!$MD$w4\n"
.stringn "다친 사람이 아무리 멀리 있더라도\n"
.stringn "치료하러 갈 수 있고요$MC!$MD$K$P할 수만 있다면 해 보고 싶네요, $w2그거$MC!$MD$K\n"
.stringn "$F3$P$MC……………………$MD$w4\n"
.stringn "$MC…………………………$MD$w5\n"
.stringn "$MC………$MD$w3해$MC……$MD$w2 보겠나?$K\n"
.stringn "$F1$P$FA네$MC!?$MD$w4\n"
.stringn "어, $w2어떻게요$MC!?$MD$w4\n"
.stringn "전 날개가 없는데$MC……$MD$K\n"
.stringn "$F3$P$MC……………………$MD$K"
db 0
.align 4
//MYELL_KILROY_VULCI_B

//0x2A8F4
Text_2A8D4:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_VULCI|$F3$FCL_KILROY|$F3$P아$MC……$MD$w2안녕하세요.$K\n"
.stringn "$F1$P$MC……$MD$K\n"
.stringn "$F3$P저, $w2저기$MC……$MD$w4 죄, $w2죄송합니다.$K\n"
.stringn "화나게 할 생각은 없었어요.$w4\n"
.stringn "저는 단지 당신과 이야기를$MC……$MD$K\n"
.stringn "$F1$P아니. $w4화나지 않았다.$w4\n"
.stringn "뭔가 볼일이 있나.$K\n"
.stringn "$F3$P$FS그, $w2그렇군요$MC……$MD$w3 다행이다.$K$P저는 킬로이예요$MC!$MD$w4\n"
.stringn "자, $w2잘 부탁드립니다$MC!$MD$K\n"
.stringn "$F1$P$MC……$MD그래.$w4\n"
.stringn "나는 우르키다. $w4잘 부탁하지.$K\n"
.stringn "$F3$P저기, $w2으음$MC……$MD$w4 우르키씨는\n"
.stringn "그 날개로 하늘을 날잖아요.$K$P매의 모습이 되었을 때도 봤는데$MC……$MD$w4\n"
.stringn "부럽네요$MC……$MD$w2 대단합니다$MC……$MD$K\n"
.stringn "$F1$P?$K\n"
.stringn "$F3$P$FA아, $w2죄송해요$MC……$MD$w4\n"
.stringn "$FS저는 어렸을 때부터 병약해서$w2\n"
.stringn "침대에서 하루를 보낼 때가 많았거든요.$K$P그래서$MC……$MD$w2 자주 창밖을 내다보며\n"
.stringn "하늘을 나는 작은 새들을 보고 있었습니다.$K$P자유롭게 어디든 날아갈 수 있다는 것은$MC…$MD$w2\n"
.stringn "참 근사한 일이네요$MC……$MD$K\n"
.stringn "$F1$P$MC……$MD$w4\n"
.stringn "근사하다$MC……$MD$w4라.$K$P그런 식으로$w2\n"
.stringn "생각해 본 적은 없군.$K\n"
.stringn "$F3$P그건 $w2그렇겠죠.$w4\n"
.stringn "태어날 때부터 날 수 있으니까요.$w4\n"
.stringn "그치만$MC……$MD$w2 부럽네요$MC……$MD$K\n"
.stringn "$F1$P$MC…………$MD$K"
db 0
.align 4
//MYELL_KILROY_VULCI_C

//0x2C150
Text_2C130:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_WAYU|$F1$P으~음$MC……$MD$w2\n"
.stringn "정말 미안.$w4\n"
.stringn "무리를 시켜 버린 것 같네$MC……$MD$K\n"
.stringn "$F3$FS$F3$FCL_KILROY|$F3$P아냐$MC……$MD$w2 나도 검사를\n"
.stringn "동경했던 적이 있으니까$MC……$MD$w4\n"
.stringn "그래도 $w2조금 즐거웠어.$K\n"
.stringn "$F1$P그치만 $w2요즘 계속\n"
.stringn "열 나잖아?$w4\n"
.stringn "그런 몸으로 전장에 나가도 괜찮은 거야?$K\n"
.stringn "$F3$P익숙하니까 괜찮아.$w4\n"
.stringn "무리할 생각은 없고,$w2\n"
.stringn "후위에 있는 게 기본이니까 문제없어.$K$P그리고 $w2와유도 곁에 있어 주는걸.$K\n"
.stringn "$F1$P그야 $w2나도 책임감을 느끼니까$MC…$MD$w4\n"
.stringn "항상 『괜찮으려나~ $w2어떠려나~』$w2 하면서\n"
.stringn "킬로이씨 생각만 나고.$K\n"
.stringn "최근 킬로이씨 생각밖에 안 한다고.$K$P$Fc하아~$MC……$MD$w4\n"
.stringn "이제부터 점 같은 건 안 믿을 거야.$K\n"
.stringn "$F3$P$FA아니$MC……$MD$w2 믿었다기보다는\n"
.stringn "도중에 의미가 완전히\n"
.stringn "바뀐 것 같은데$MC……?$MD$K\n"
.stringn "$F1$P$Fd$FS사소한 건 신경 쓰지 마$MC!$MD$K$P$FA$MC……$MD아니, $w2근데 잠깐.$w4\n"
.stringn "백마를 타고 찾아오는\n"
.stringn "숙명의 라이벌$MC……$MD$K$w3$P$MC………$MD혹시 $w2검사가 아니라\n"
.stringn "기병인가$MC………$MD$K\n"
.stringn "$F3$P$MC……$MD응?$K\n"
.stringn "$F1$P킬로이씨한테 딱 맞는 직업.$w4\n"
.stringn "$FS그렇구나, $w2그럴지도 몰라$MC!$MD$K$P말에 타면 행군도 편하고$w2\n"
.stringn "몸에도 좋잖아?$K\n"
.stringn "$F3$P뭐어$MC!?$MD$w4 마, $w2말$MC!?$MD$K\n"
.stringn "$F1$P그래$MC!$MD$w4 말 탄 기사 킬로이씨$MC!$MD$w4\n"
.stringn "옷도 하얗고, $w2꽤 멋질 거 같지 않아$MC!?$MD$K$P킬로이씨가 말 위에서 지팡이를 쓰고,$w2\n"
.stringn "나는 그 옆에서 화려하게 싸우는 거지$MC!$MD$K\n"
.stringn "$F3$P자, $w4잠깐 와유$MC……$MD$K\n"
.stringn "$F1$P좋아, $w2그거였어$MC!$MD$w4\n"
.stringn "다음엔 그걸로 가 보자$MC!$MD$K\n"
.stringn "$F3$P잠깐 기다려 봐, $w2와유.$w4\n"
.stringn "애초에 내가 아니라\n"
.stringn "다른 사람이 너의$MC……$MD$K\n"
.stringn "$F1$P$FA그건 싫어.$K\n"
.stringn "$F3$P싫다고?$K\n"
.stringn "$F1$P$FS응. $w4이제 킬로이씨 말고는\n"
.stringn "생각할 수 없다구? $w2내 운명의 상대$MC!$MD$K\n"
.stringn "$F3$P우, $w2운명$MC……$MD$MC!?$MD$w4 숙명의 라이벌이 아니라$MC……$MD$K\n"
.stringn "$F1$P사소한 건 신경 쓰지 마~$MC!$MD$w4\n"
.stringn "그럼 $w2앞으로도 잘 부탁해, $w2킬로이씨$MC!$MD$K"
db 0
.align 4
//MYELL_KILROY_WAYU_A

//0x2BC28
Text_2BC08:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_KILROY|$F3$FCL_WAYU|$F1$P와유.$w4\n"
.stringn "또 훈련 중이야?$K\n"
.stringn "$F3$P어라, $w2킬로이씨?$w4\n"
.stringn "또 『누군가 와 줘~』$w2라고 생각했더니\n"
.stringn "처음으로 만나 버렸어$MC……$MD$K\n"
.stringn "$F1$P$FA아, $w2그 점 얘기구나.$w4\n"
.stringn "미안, $w2까맣게 잊고 있었어.$w4\n"
.stringn "방해할 생각은 없었는데$MC……$MD$K\n"
.stringn "$F3$P$FS아냐. $w4역시 점은\n"
.stringn "믿는 게 아닌가 봐~$K$P완전 잘 들어맞는다고 소문난\n"
.stringn "점술가였는데$MC……$MD$w4\n"
.stringn "$FA$MC…………$MD아니, $w2설마$MC……$MD$K\n"
.stringn "$F1$P?$K\n"
.stringn "$F3$P$FS킬로이씨, $w2나랑 승부하지 않을래?$K\n"
.stringn "$F1$P뭐어$MC!?$MD$K\n"
.stringn "$F3$P아~ 왜 몰랐을까?$w4\n"
.stringn "킬로이씨는 검사나 전사에\n"
.stringn "소질이 있다구$MC!$MD$K$P지금은 아직 눈치채지 못했을 뿐이고$w2\n"
.stringn "킬로이씨에게는 굉장한 재능이 잠들어 있는 거야.$K$P그러니까 검사로서 눈을 뜬 다음에\n"
.stringn "나랑 숙명의 대결이라든가\n"
.stringn "할 수 있을지도 몰라, $w2확실해$MC!$MD$K\n"
.stringn "$F1$P그, $w2그건 말도 안 돼, $w2와유.$K$P그야 $w2나는 어렸을 때\n"
.stringn "몸이 약했으니까$MC……$MD$K$P강한 용병이 되고 싶다고\n"
.stringn "생각한 적도 있었지만$MC……$MD$K\n"
.stringn "$F3$P봐봐$MC!$MD$w4 역시나$MC!$MD$w4\n"
.stringn "몸이 약하다고 포기해 버리면\n"
.stringn "안 되지~$w2 아깝잖아$MC!$MD$K$P자 자, $w2한번 속는 셈 치고\n"
.stringn "해 보자.$w4\n"
.stringn "제대로 기본부터 가르쳐 줄 테니까$MC!$MD$K\n"
.stringn "$F1$P그, $w2그럴까$MC……?$MD$K\n"
.stringn "$F3$P사소한 건 신경 쓰지 말고$MC!$MD$w4\n"
.stringn "자, $w2가 보자구~우$MC!$MD$K"
db 0
.align 4
//MYELL_KILROY_WAYU_B

//0x2B7BC
Text_2B79C:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_WAYU|$F3$FCL_KILROY|$F1$P아$MC……$MD$w2 킬로이씨$MC!$MD$w4\n"
.stringn "자, $w2이거 받아$MC!$MD$K\n"
.stringn "$F3$P이건$MC……$MD$w2 검?$K\n"
.stringn "$F1$P그래$MC!$MD$w4 근데 설마\n"
.stringn "킬로이씨였을 줄이야~$w4\n"
.stringn "여튼 이렇게 됐으니까, $w2승부하자$MC!$MD$K\n"
.stringn "$F3$P그, $w2그렇게 말해도\n"
.stringn "잘 모르겠는데$MC……$MD$w4\n"
.stringn "그리고 $w2나는 무기를 못 다뤄.$K\n"
.stringn "$F1$P$FA뭐어$MC!?$MD$w4\n"
.stringn "그래도 $w2조금 정도는\n"
.stringn "할 수 있지 않아?$K\n"
.stringn "$F3$P아니, $w2지금까지 잡아 본 적도 없는데$MC…$MD$w4\n"
.stringn "이걸 쥐고 서 있기만 해도 된다면\n"
.stringn "그렇게 해 줄게.$K\n"
.stringn "$F1$P$Fc뭐야, $w2실망인걸.$K$P$Fd전에 $w2점술가가 점을 봐 줬는데,$w2\n"
.stringn "난 이제 곧 운명의 상대를 만난다는$w2\n"
.stringn "말을 들었어.$K$P$FS백마를 타고 찾아오는\n"
.stringn "내 숙명의 라이벌$MC……$MD$w4\n"
.stringn "$FA기대하고 있었는데.$K\n"
.stringn "$F3$P$FS그건 내가 잘못했네.$w4\n"
.stringn "미안해.$K\n"
.stringn "$F1$P아냐, $w2킬로이씨가\n"
.stringn "잘못한 건 없는걸.$K$P그냥 잠깐 『누군가 와 줘~』$w2라고\n"
.stringn "생각했더니 이곳에 누가 있길래$w2\n"
.stringn "혹시나 $w2했을 뿐이야.$K\n"
.stringn "$F3$P$FA그럼$MC……$MD$w2 쥐고 있을 뿐이지만\n"
.stringn "상대해 줄까?$K\n"
.stringn "$F1$P$FS괜찮아 괜찮아. $w2다칠 수도 있고.$w4\n"
.stringn "$FA오늘은 포기할까$MC……$MD$w3$Fc 아~아.$K"
db 0
.align 4
//MYELL_KILROY_WAYU_C

//0x2D0D0
Text_2D0B0:
.stringn "$R背景会話|$B支援背景|$<$F3$FS$F3$FCL_LARGO|$F3$P오오, $w2무와림$MC!$MD$w4\n"
.stringn "지난번에는 즐거웠어$MC!$MD$K\n"
.stringn "$F1$FS$F1$FCL_MWARIM|$F1$P그래, $w2나도다.$K\n"
.stringn "$F3$P모두의 짐을 $w2얼마나 들 수 있나\n"
.stringn "힘겨루기를 하고 있는데,$K$P다들 재밌다고 아무거나\n"
.stringn "쌓아 올리고 앉았었다니까.$K\n"
.stringn "$F1$P그래. $w4물건뿐만 아니라$w2\n"
.stringn "사람까지 위로\n"
.stringn "올라타길래 곤란했었지.$K\n"
.stringn "$F3$P그래, $w2마지막까지$w2\n"
.stringn "결국 엇비슷했어.$K$P가장 마지막에 올린 게,$w2\n"
.stringn "나는 큰 무쇠솥 하나,$w2\n"
.stringn "네가 그 작은 여자아이$MC……$MD$K$P이름이 뭐였더라.$K\n"
.stringn "$F1$P미스트다.$K\n"
.stringn "$F3$P그래, $w2그 아이.$K$P그 아이랑 무쇠솥 중에$w2\n"
.stringn "어느 쪽이 더 무거웠는지 알았다면\n"
.stringn "결판이 났을 텐데.$K\n"
.stringn "$F1$P$MC……$MD너는 $w2굉장하군.$K\n"
.stringn "$F3$P음?$w4 뭐가?$w4\n"
.stringn "너도 굉장했잖아.$K\n"
.stringn "$F1$P그런 뜻이 아니다.$K$P긴장되는 행군 분위기를\n"
.stringn "역으로 $w2순식간에\n"
.stringn "바꿔 버렸지.$K$P숨통이 트였다, $w2재밌었다며\n"
.stringn "모두가 고마워했다.$K\n"
.stringn "$F3$P뭐, $w2난 단순히 긴장하고 있는 게\n"
.stringn "싫었던 것뿐이야.$w4\n"
.stringn "딱딱하게 굳어 있으면 전력으로 못 싸우잖아?$K\n"
.stringn "$F1$P게다가, $w2너는 나를 대하든\n"
.stringn "누구를 대하든 태도가 변하지 않는다.$w4\n"
.stringn "그게 $w2굉장하다고 생각한다.$K\n"
.stringn "$F3$P와하하하$MC!$MD$w4 잘은 모르겠지만\n"
.stringn "그렇게 칭찬하지 마$MC!$MD$K$P뭐어, $w2사소한 건 됐으니까.$w4\n"
.stringn "승부는 무승부였지, $w2다음은$MC……$MD$K$P그래, $w2팔씨름 같은 건 어때$MC!$MD$w4\n"
.stringn "나 팔씨름에는 자신이 있다고$MC!$MD$K\n"
.stringn "$F1$P$MC…………$MD그래, $w2좋다.$w4\n"
.stringn "다음 기회를 기대하도록 하지.$K"
db 0
.align 4
//MYELL_LARGO_MWARIM_A

//0x2CBFC
Text_2CBDC:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_LARGO|$F3$FCL_MWARIM|$F1$P오오, $w2무와림이잖아.$w4\n"
.stringn "상태는 어때?$K\n"
.stringn "$F3$P$MC……$MD아, $w2라르고인가.$w4\n"
.stringn "전에는$MC……$MD$w2 고마웠다.$K\n"
.stringn "$F1$P와하하하하$MC!$MD$w2 별거 아니야$MC!$MD$w4\n"
.stringn "근데 넌 $w2대단하구만.$K$P여러 곳을 여행해 봤지만,$w2\n"
.stringn "나 정도로 힘이 센 남자는\n"
.stringn "본 적이 없었는데.$K$P아무리 나라도 네게는\n"
.stringn "질지도 모르겠어.$K$P저기, $w2나하고 너,$w2\n"
.stringn "누가 더 힘이 셀까?$K\n"
.stringn "$F3$P$MC……$MD글쎄.$K\n"
.stringn "$F1$P나는$MC……$MD$w4 그래.$w4\n"
.stringn "제일 무거웠던 건 그거야.$K$P옛날에 $w2수명이 몇백 년 됐다던\n"
.stringn "직경이 내 키의 3배인 거목을$w2\n"
.stringn "메고 날랐던 적이 있었지.$K$P넌 어때?$K\n"
.stringn "$F3$P$MC……$MD그렇군.$K$P성벽을 복원하는 데 사용할 바위를$w2\n"
.stringn "바위산에서 깎아$w2\n"
.stringn "쌓아 올렸던 적이 있었다.$K\n"
.stringn "$F1$P호오, $w2얼마나 큰 바위였는데?$K\n"
.stringn "$F3$P내 키의 3배 정도$w2였나.$K\n"
.stringn "$F1$P오오, $w2역시 넌 대단해$MC!$MD$w4\n"
.stringn "왠지 기쁜걸$MC!$MD$w4\n"
.stringn "어때, $w2다음에 힘겨루기를 해 보지 않을래?$K$P나하고 너라면$w2\n"
.stringn "좋은 승부를 할 수 있을 것 같아$MC!$MD$K\n"
.stringn "$F3$P아니, $w2나는$MC……$MD$K\n"
.stringn "$F1$P쩨쩨하게 그러지 말고$MC!$MD$w4\n"
.stringn "닳는 것도 아니잖아, $w2괜찮지?$K\n"
.stringn "$F3$P$MC………………$MD$Fc후우$MC……$MD$w4\n"
.stringn "어쩔 수 없군$MC……$MD$w3\n"
.stringn "$Fd알았다. $w4한 번만이야.$K"
db 0
.align 4
//MYELL_LARGO_MWARIM_B

//0x2C8D8
Text_2C8B8:
.stringn "$R背景会話|$B支援背景|$<$F3$FS$F3$FCL_LARGO|$F3$P오?$K\n"
.stringn "너, $w2제법 몸이 좋잖아.$w4\n"
.stringn "잠깐 팔 좀 보여 줘 봐.$K\n"
.stringn "$F1$FCL_MWARIM|$F1$P$MC……?$MD$K\n"
.stringn "$F3$P오오, $w2대단한데.$w4\n"
.stringn "나도 팔뚝 굵기에는 자신이 있지만$w2\n"
.stringn "너는 엄청나구만.$K\n"
.stringn "$F1$P$MC…………$MD너도 엄청나다고 생각한다.$K\n"
.stringn "$F3$P와하하하하$MC!$MD$w2 난\n"
.stringn "이 괴력이 유일한 장점이니까$MC!$MD$K\n"
.stringn "그런데 그건 $w2어디로 옮기는 거야?$K\n"
.stringn "$F1$P아, 이것 말이지.$w4\n"
.stringn "이 물독에 물을 떠 가는 중이다.$K\n"
.stringn "$F3$P그런 큰 독에 물을?$w4\n"
.stringn "그것참 힘들겠구만.$K$P하나 둘 셋,$w2\n"
.stringn "수도 제법 많네.$w4\n"
.stringn "좋아, $w2나도 도와줄게.$K\n"
.stringn "$F1$P아니, $w2그럴 필요는 없다.$K\n"
.stringn "$F3$P오, $w2여유롭네 이거$MC!$MD$w4 가볍구만$MC!$MD$w4\n"
.stringn "난 팔 힘밖에\n"
.stringn "가진 게 없으니까$MC!$MD$w4 자, $w2가자고$MC!$MD$K$F3$FD\n"
.stringn "$F1$P$MC………………$MD$K"
db 0
.align 4
//MYELL_LARGO_MWARIM_C

//0x2E034
Text_2E014:
.stringn "$R背景会話|$B支援背景|$<$F1$Fc$F1$FCL_LARGO|$F1$P으~음$MC……$MD$w4\n"
.stringn "으~~음$MC……$MD$K\n"
.stringn "$F3$FCL_TAURONEO|$F3$P또 가게 일로\n"
.stringn "고민하고 있는 건가?$K\n"
.stringn "$F1$P$Fd$FS아, $w2당신이구만.$w4\n"
.stringn "또 뭔가 $w2좋은 지혜를 빌려줄 수 있을까?$K\n"
.stringn "$F3$P그러지.$K\n"
.stringn "$F1$P내 가게 이름을 생각 중이었어.$w4\n"
.stringn "머리를 쥐어짜서 여러 가지를 생각해 봤지.$K\n"
.stringn "$F3$P호오. $w4예를 들면?$K\n"
.stringn "$F1$P『내 가게』$w2라는 이름은 어때?$K\n"
.stringn "$F3$P흠. $w4좀 단순하군.$K\n"
.stringn "$F1$P$FA그럼$MC……$MD$w4 좀 더 쥐어짜 볼까.$K$P나는 베오크든 라구즈든 누구든\n"
.stringn "부담 없이 와서, $w2잔뜩 마시고 얘기하면서$w2\n"
.stringn "행복해지는 술집이 되도록 하고 싶어.$K$P그러니까 『베오크든 라구즈든 누구든\n"
.stringn " 부담없이 와서, $w2잔뜩 마시고 얘기하면서\n"
.stringn " 행복해지는 가게』는 어때$MC!?$MD$K\n"
.stringn "$F3$P흠. $w4좀 길군.$K\n"
.stringn "$F1$P아, $w2역시 안 되겠다.$K$P곤란하게 됐다구,$w2\n"
.stringn "나 이런 거\n"
.stringn "전혀 생각 못 하겠어.$K\n"
.stringn "$F3$P굳이 어렵게 생각할 필요는 없다.$w4\n"
.stringn "제일 아끼는 사람의 이름은 어떤가?$K\n"
.stringn "$F1$P그럼 $w2카릴이지.$w4\n"
.stringn "나한텐 언제나 카릴이 첫 번째니까$MC…$MD$K\n"
.stringn "$F3$P$FS반한 여자의 이름인가.$w4\n"
.stringn "그렇다면 그걸로 충분하겠지.$K$P가게가 문을 열면$w2\n"
.stringn "나도 들러도 되겠나?$K\n"
.stringn "$F1$P$FS그래, $w2당신한테는\n"
.stringn "잔뜩 신세를 졌으니까.$K$P당신이 좋아하는 술은$MC……$MD$w4\n"
.stringn "분명 어딘가에 적어 놨었는데$MC……$MD$w4 어디지?$K$P오오, $w2찾았다. $w4독한 술 맞지?$K\n"
.stringn "$F3$P그렇다.$K\n"
.stringn "$F1$P와하하하하$MC!$MD$w4 맡겨 둬$MC!$MD$w4\n"
.stringn "불이라도 뿜을 만한\n"
.stringn "독한 술을 준비해 놓고 있을게$MC!$MD$K"
db 0
.align 4
//MYELL_LARGO_TAURONEO_A

//0x2DABC
Text_2DA9C:
.stringn "$R背景会話|$B支援背景|$<$F5$FCL_LARGO|$F3$FCL_TAURONEO|$F5$P으~~음.$K\n"
.stringn "$F3$P$MC……$MD$K\n"
.stringn "$F5$P으~~음.$K\n"
.stringn "$F3$P$MC……$MD또 무슨 일이 있나?$K\n"
.stringn "$F5$FD$F1$FCL_LARGO|$F1$P응?$w4\n"
.stringn "$FS오오, $w2당신이었구만.$K\n"
.stringn "$F3$P방금 전부터 끙끙거리면서 서 있더군.$w4\n"
.stringn "하늘만 $w2바라보고 있던데.$K$P자군의 진영 내라고는 해도, $w2방심하면\n"
.stringn "목숨을 잃게 될 거다.$K\n"
.stringn "$F1$P$FA아, $w2확실히 그렇지.$w4\n"
.stringn "안 되겠다 안 되겠어.$K$P난 머리가 나쁘니까 두 가지 일을\n"
.stringn "한꺼번에 생각할 수가 없다고.$K\n"
.stringn "$F3$P뭔가 고민이라도 있나?$K\n"
.stringn "$F1$P$FS그래, $w2들어줄래?$K$P난 $w2언젠가 가게를 열려고 하거든.$w4\n"
.stringn "여기서 돈도 잔뜩 모았고,$w2\n"
.stringn "술집 같은 걸 차려 보려고 하는데.$K\n"
.stringn "$F3$P호오.$K\n"
.stringn "$F1$P나는 손님을 소중하게 생각하고 싶어.$w4\n"
.stringn "와 주는 손님들을$w2\n"
.stringn "모두 행복하게 만들고 싶어.$K$P그래서 여러 사람이 모이는 이곳에서\n"
.stringn "여러 가지를 공부하고 있지.$w4\n"
.stringn "사람 수만큼 취향도 다양한 법이니까.$K\n"
.stringn "$F3$P$FS그거 훌륭한 이상이로군.$w4\n"
.stringn "$FA그런데 $w2그 가게는 어디에 차릴 셈이지?$K\n"
.stringn "$F1$P$FA으~~~음$MC……$MD$K$P이래 봬도\n"
.stringn "베그니온 출신이라서 말이지.$w2\n"
.stringn "역시 고향인 베그니온이 좋을까.$K$P그치만 다른 사람의 얘기도 들어보니까,$w2\n"
.stringn "크리미아나 데인도 좋은 것 같고$MC…$MD$w4\n"
.stringn "아아, $w2이거 큰일이네.$K$P내가 머리가 나빠서$MC……$MD$K\n"
.stringn "$F3$P$MC………………$MD$w4\n"
.stringn "나라도 괜찮다면 상담을 해 줘도 되겠나?$K\n"
.stringn "$F1$P$FS오오, $w2그거 고맙겠어.$w4\n"
.stringn "두 명이라면 $w2두 가지를 생각할 수 있겠지.$K$P$FA그리고 가게 메뉴랑,$w2\n"
.stringn "$Fc으음$MC……$MD$w2 뭐였더라$MC……$MD$K"
db 0
.align 4
//MYELL_LARGO_TAURONEO_B

//0x2D690
Text_2D670:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_LARGO|$F1$P으~~음$MC……$MD$w4 으~~음$MC……$MD$K\n"
.stringn "$F6$FCL_TAURONEO|$F6$P$MC……$MD$K\n"
.stringn "$F1$P오?$w4\n"
.stringn "$FS저기, $w2거기 당신.$K\n"
.stringn "$F6$FD$F3$FCL_TAURONEO|$F3$P음?$K\n"
.stringn "$F1$P이 군, $w2상당히 별난 곳이라고\n"
.stringn "생각하지 않아?$K\n"
.stringn "이렇게 다양한 나라 사람들이\n"
.stringn "섞여 있는 건 드문 일이라고.$K$P나 이쪽저쪽으로 여행을 다녔는데,$w2\n"
.stringn "이 정도로 뒤죽박죽인 건\n"
.stringn "처음이야 처음.$K\n"
.stringn "$F3$P$MC……$MD그럴지도 모르겠군.$K$P무엇보다 적이었던 전 데인병도\n"
.stringn "섞여 있을 정도니까.$w4\n"
.stringn "국가의 다양함에는 부족함이 없겠지.$K\n"
.stringn "$F1$P맞아, $w2그래서 여러 인종이\n"
.stringn "다양하게 있어서\n"
.stringn "희귀한 요리도 나오잖아.$K\n"
.stringn "$F3$P$MC……$MD그 손에 있는 것은 뭐지?$K\n"
.stringn "$F1$P응?$w4 아아, $w2생각해 두었던 걸\n"
.stringn "잊어버리지 않도록 기록하는 거야.$w4\n"
.stringn "난 머리가 나빠서 금방 잊어버리거든.$K$P라구즈들은 진한 양념을 좋아하는 거 같고,$w2\n"
.stringn "게다가 우리랑 같이 술도 마셔 준다고$MC!$MD$w4\n"
.stringn "정말 최고야 최고$MC!$MD$K$P저기, $w2당신은 어떤 술이 좋아?$K\n"
.stringn "$F3$P$MC……$MD술 말인가.$w4\n"
.stringn "독한 술을 좋아하지.$K\n"
.stringn "$F1$P맛은?$K\n"
.stringn "$F3$P맛은 상관없다.$K\n"
.stringn "$F1$P와하하하$MC!$MD$w4 좋네, $w2사나이답구만$MC!$MD$K\n"
.stringn "좋아, $w2그것도 잊어버리지 않게 써 둬야지.$K"
db 0
.align 4
//MYELL_LARGO_TAURONEO_C

//0x2EED4
Text_2EEB4:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_WAYU|$F1$FCL_LARGO|$F3$P봐준 거야?$K\n"
.stringn "$F1$P아니.$K\n"
.stringn "$F3$P$MC……$MD정말로?$K\n"
.stringn "$F1$P정말이야.$K\n"
.stringn "$F3$P정말 정말로?$K\n"
.stringn "$F1$P$FS정말 정말로.$w4\n"
.stringn "보기 좋게 당해 버렸구만.$K$P졌다 졌어.$w4\n"
.stringn "네 성장은 대단한걸.$K\n"
.stringn "$F3$P$MC…………$MD$K$P$FS하~~~$MC……$MD$w4 지쳤어.$K\n"
.stringn "그럼, $w2오늘은 정말 내 승리인 거다$MC!$MD$w4\n"
.stringn "일단 잠깐 한숨 자고 올까$MC……$MD$K\n"
.stringn "$F1$P$FA그래, $w2그 전에 네가$w4\n"
.stringn "지쳤다는 건 알고 있지만$MC……$MD$w4\n"
.stringn "하나 물어봐도 되냐?$K\n"
.stringn "$F3$P$FA응?$K\n"
.stringn "$F1$P너,$w2\n"
.stringn "왜 그렇게 고집을 부리는 거야?$K$P내가 전에 한 말$MC……$MD$w4\n"
.stringn "너는 나 이상으로\n"
.stringn "뼈저리게 알고 있을 거 아냐.$K$P그런데 어째서$w2\n"
.stringn "그렇게까지 열심히 하는 거야?$K\n"
.stringn "$F3$P난 $w2질 수 없어.$K$P여자니까, $w2여자한테 맞는 일이 아니야.$w4\n"
.stringn "지금까지 몇 번이나 그런 말을 들었으니까.$w4\n"
.stringn "그래서 $w2질 수 없어.$K\n"
.stringn "$F1$P$MC……$MD$K\n"
.stringn "$F3$P약해서 지는 건 $w2납득할 수 있어.$w4\n"
.stringn "기술이 부족하면 $w2갈고닦으면 돼.$w4\n"
.stringn "경험이 부족하면 $w2더 싸우면 돼.$K$P하지만 여자라서 진다는 건\n"
.stringn "스스로 용서가 안 돼.$K$P아저씨한테 진 건,$w2\n"
.stringn "내가 여자라서가 아니야.$w4\n"
.stringn "그런 이유로 도망치고 싶지 않아.$K$P내가 미숙해서 진 거라고.$w4\n"
.stringn "그렇다면 수행하면 돼.$w4\n"
.stringn "검 솜씨를 갈고닦으면, $w2언젠가는 이길 테니까.$K\n"
.stringn "$F1$P$MC……$MD그렇구만.$K$P$FS대단한걸.$w4\n"
.stringn "이러니 내가 지는 것도 당연하지.$K$P나도 지지 않을 거다,$w2\n"
.stringn "너의 그 의지를 본받아야겠어.$K\n"
.stringn "$F3$P$FS그럼, $w2언제 할래?$K\n"
.stringn "$F1$P응?$K\n"
.stringn "$F3$P다음 승부 말이야.$K$P아저씨도$w2\n"
.stringn "진 채로 끝내기는 싫지?$K\n"
.stringn "$F1$P와하하하하$MC!$MD$w2 역시 너다워.$w4\n"
.stringn "그야 물론이지.$w4\n"
.stringn "이길 때까지 몇 번이라도 해 주마$MC!$MD$K\n"
.stringn "$F3$P바라던 바야$MC!$MD$K"
db 0
.align 4
//MYELL_LARGO_WAYU_A

//0x2E934
Text_2E914:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_WAYU|$F1$FCL_LARGO|$F3$P아저씨$MC!$MD$K\n"
.stringn "$F1$P오오, $w2너구나.$w4\n"
.stringn "저번에 그, $w2뭐냐.$w4\n"
.stringn "무시하는 듯이 말해서 미안했다.$K\n"
.stringn "$F3$P그런 건 아무렇지도 않아.$w4\n"
.stringn "그것보다 아저씨,$w2\n"
.stringn "알고 있겠지$MC!$MD$K\n"
.stringn "$F1$P음?$w4\n"
.stringn "뭔데?$K\n"
.stringn "$F3$P지난번의 빚을 갚으러\n"
.stringn "온 게 당연하잖아$MC!$MD$K$P그때는 $w2확실히 져 버렸지$MC!$MD$w4\n"
.stringn "하지만 지금의 나를 전과 같다고\n"
.stringn "생각하면 곤란해$MC!$MD$K\n"
.stringn "$F1$P아직도 하는 거야?$w4\n"
.stringn "기분은 알겠지만$MC……$MD$K$P그만두는 편이 좋아,$w2\n"
.stringn "여자애의 힘으론$w2\n"
.stringn "나를 이길 수 없을 테니까.$K\n"
.stringn "$F3$P$MC!$MD$w4\n"
.stringn "또 여자라고 무시하고 있어$MC!$MD$K\n"
.stringn "$F1$P난감하구만$MC……$MD$K$P있잖아.$w4\n"
.stringn "이건 너를\n"
.stringn "무시하는 게 아니야.$K$P남자와 여자는 뼈와 살이 붙은 구조가 다르다고.$w4\n"
.stringn "싸움에서는 어떻게 해도\n"
.stringn "불리해져 버릴걸.$K\n"
.stringn "$F3$P그런 건 알고 있어$MC!$MD$w4\n"
.stringn "하지만 나는 지지 않을 거야.$w4\n"
.stringn "질 수 없어, $w2절대로.$K$P오늘 지면 수행해서 $w2내일 이길 거야.$w4\n"
.stringn "$Fh내일 지면 수행해서 $w2그 다음 날에도$MC……$MD$K\n"
.stringn "$F1$P이, $w2이봐$MC……$MD$w4\n"
.stringn "너 잘 보니까\n"
.stringn "휘청거리고 있잖아.$K$P그런 상태로 싸우는 건\n"
.stringn "애초에 무리라고.$w4\n"
.stringn "오늘은 좀 쉬어$MC……$MD$K\n"
.stringn "$F3$P$Fd신경 쓸 필요 없어$MC!$MD$K$P좀 휘청거리는 건$w2\n"
.stringn "오늘 아저씨를 이기기 위해\n"
.stringn "훈련하고 와서 그런 거야.$K$P그러니까 오늘\n"
.stringn "아저씨랑 싸우지 않으면 의미가 없어.$K\n"
.stringn "$F1$P$MC……$MD$K$P알았다.$w4\n"
.stringn "네가 그렇게까지 말한다면$MC……$MD$w4\n"
.stringn "나도 사나이야. $w4받아 줄게.$K\n"
.stringn "$F3$P간다$MC!$MD$K"
db 0
.align 4
//MYELL_LARGO_WAYU_B

//0x2E5B0
Text_2E590:
.stringn "$R背景会話|$B支援背景|$<$F3$FS$F3$FCL_WAYU|$F1$FCL_LARGO|$F3$P흐음.$w4\n"
.stringn "아저씨, $w2몸이 좋은걸.$K\n"
.stringn "$F1$P음?$w4 뭐야, $w2넌.$K\n"
.stringn "$F3$P나는 와유$MC!$MD$w4\n"
.stringn "수행 중인 검사야.$w4\n"
.stringn "한 판 $w2승부하지 않을래?$K\n"
.stringn "$F1$P승부라고?$w4\n"
.stringn "으~음$MC……$MD$w4 곤란하구만.$K\n"
.stringn "$F3$P$FA왜?$K\n"
.stringn "$F1$P너는 여자잖아.$w4\n"
.stringn "여자애를 상대로 승부하는 건\n"
.stringn "조금 그런데$MC……$MD$K\n"
.stringn "$F3$P$MC!$MD$K\n"
.stringn "$F1$P너도 그 뭐냐,$w2\n"
.stringn "검을 가지고 싸우는 것보다$MC……$MD$K$P좀 더 $w2뭐랄까\n"
.stringn "가정적인 일을 하는 게 낫지 않아?$K$P잘 모르지만 $w2예를 들자면\n"
.stringn "뜨개질이라든지 요리라든지$MC……$MD$w4\n"
.stringn "적어도 마도 사용자가 된다든지$MC……$MD$K\n"
.stringn "$F3$P무슨 소리야$MC!$MD$w4\n"
.stringn "여자는 싸울 수 없다는 거야?$K\n"
.stringn "$F1$P으~음$MC……$MD$w4\n"
.stringn "미안.$K\n"
.stringn "$F3$P알았으면\n"
.stringn "빨리 빨리$MC!$MD$w4 자세 잡아$MC!$MD$K\n"
.stringn "$F1$P으~음$MC……$MD$w4 큰일났구만.$K$P저기, $w2이건 어때?$w4\n"
.stringn "뜨개질로 승부를 낸다든지$MC……$MD$K\n"
.stringn "$F3$P문답무용$MC!$MD$K"
db 0
.align 4
//MYELL_LARGO_WAYU_C

//0x2FF34
Text_2FF14:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_LETHE|$F3$FCL_LAY|$F3$P레테, $w2전에 했던 이야기 말인데.$w4\n"
.stringn "부대장급의 지원자를 몇 명 정도$w2\n"
.stringn "파견지에서 갈리아로 귀환시키자는 의견이 나왔어.$K$P아직 정식으로 결정된 건 아니지만$MC……$MD$w4\n"
.stringn "만약 그렇게 된다면 넌 $w2어떡할 거야?$w4\n"
.stringn "갈리아로 돌아가고 싶다면 그렇게 전해 둘게.$K\n"
.stringn "$F1$P나는$MC……$MD$K\n"
.stringn "여기에 남겠다.$K\n"
.stringn "$F3$P뭐?$w4\n"
.stringn "괜찮겠어?$K\n"
.stringn "$F1$P$MC……$MD내가 없어지자마자\n"
.stringn "아이크 일행에게 무슨 일이 생기면 곤란하니까.$w4\n"
.stringn "그러니, $w2여기에 남겠다.$K\n"
.stringn "$F3$P$FS호오$MC……$MD$K\n"
.stringn "$F1$P뭐, $w2뭐냐\n"
.stringn "그 의미심장한 미소는.$K\n"
.stringn "$F3$P아냐, $w2아무것도.$w4\n"
.stringn "『인간 놈들이$MC!$MD』$w2라고 말하던\n"
.stringn "네가 $w2그러니까 뭔가$MC……$MD$K\n"
.stringn "$F1$P나, $w2나는 딱히$MC……$MD$K\n"
.stringn "$F3$P넌 동요하면 꼬리에서 다 드러나니까$w2\n"
.stringn "금방 알 수 있다고.$w4\n"
.stringn "그래그래, $w2역시 그런 거였어.$K\n"
.stringn "$F1$P$MC……$MD단련 중이었다.$w4\n"
.stringn "이야기가 끝났다면 가 보지.$K$F1$FD\n"
.stringn "$F3$P아, $w2미안.$w4\n"
.stringn "너무 놀렸나.$K\n"
.stringn "$F0$FCL_LETHE|$F0$P$MC…………$MD$K$P라이.$K\n"
.stringn "$F3$P응?$K\n"
.stringn "$F0$P$MC……$MD$w4내 생각이\n"
.stringn "이전과 달라진 것은 인정하겠다.$K\n"
.stringn "$F3$P$MC……$MD그래?$K\n"
.stringn "$F0$P그동안 쭉$MC……$MD$w4 네 생각에는\n"
.stringn "동의할 수 없었다만$MC……$MD$K$P이제는 네 기분을 알 것 같다.$w4\n"
.stringn "함께 싸우는 그들은 $w2소중한 동료다.$K$P저주받은 【부】의 기운이 소용돌이치는 땅으로\n"
.stringn "향하는 동료들을 내버려 둘 수는 없지.$w4\n"
.stringn "그러니, $w2나는 아이크와 함께 가겠다.$K\n"
.stringn "$F3$P그렇구나$MC……$MD$K$P좋아, $w2이긴다면 아이크네랑\n"
.stringn "다 같이 신나게 놀아 보자구.$K\n"
.stringn "$F0$P지금은 아직 방심할 때가 아니다.$K$P$FS하지만$MC……$MD$w4 그렇군.$w4\n"
.stringn "언젠가$MC……$MD$w2 그렇게 되면 좋겠어.$K"
db 0
.align 4
//MYELL_LAY_LETHE_A

//0x2F9F8
Text_2F9D8:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_LAY|$F3$FCL_LETHE|$F3$P라이, $w2갈리아에 있는\n"
.stringn "내 부하들은 단련을 계속하고 있나?$K\n"
.stringn "$F1$P그래, $w2물론이지.$K$P그놈들도 갈리아의 전사야.$w4\n"
.stringn "나라의 수비는\n"
.stringn "녀석들에게 맡겨도 괜찮겠지.$K\n"
.stringn "$F3$P하지만 $w2아무래도 걱정이군.$K$P열심히 단련하는 건 좋다만,$w2\n"
.stringn "겨루는 도중에 진심이 되어서$w2\n"
.stringn "피가 끓어올라 싸움이 벌어질 때가 자주 있었다.$K\n"
.stringn "$F1$P뭐, $w2혈기 왕성한 녀석들이\n"
.stringn "잔뜩 있으니까 말이지$MC……$MD$w4\n"
.stringn "그래도 $w2어떻게든 될 거야.$K\n"
.stringn "$F3$P너, 그렇게 태평하게 넘기$MC……$MD$K\n"
.stringn "$F1$P너 말야,$w2\n"
.stringn "그렇게 온종일 긴장하고 있지 말고$w2\n"
.stringn "가끔은 어깨에서 힘 좀 빼지 그래?$K$P물론 그렇다고 네 여동생처럼$w2\n"
.stringn "전장에서 틈만 나면 털을 갈거나,$w2\n"
.stringn "발톱을 다듬거나 하는 건 곤란하지만.$K\n"
.stringn "$F3$P$MC…$MD리레는 지금 $w2네 부대에 있나?$K\n"
.stringn "$F1$P그래. $w4키사랑 같이 날 애먹이고 있어.$K\n"
.stringn "$F3$P키사도 덩치는 큰 주제에\n"
.stringn "너를 잘 따르니까 말이다.$w4\n"
.stringn "힘들겠지만$MC…$MD$w3 잘 부탁한다.$K\n"
.stringn "$F1$P리레랑 안 본 지 오래됐다면서?$K\n"
.stringn "$F3$P$MC……$MD$K\n"
.stringn "$F1$P말 안 하는 거구나. $w4뭐, $w2딱히 상관없지만.$w4\n"
.stringn "빨리 화해하도록 해.$w4\n"
.stringn "서로 하나뿐인 자매니까.$K\n"
.stringn "$F3$P너하고는 관계없다.$K\n"
.stringn "$F1$P네네.$K\n"
.stringn "$F3$P여동생 일은 둘째 치고$MC……$MD$w4\n"
.stringn "본국의 부대가 꽤나 걱정되는군.$K$P너와 우리가 여기에 파견되어 있으니,$w2\n"
.stringn "나라의 수비가 느슨해지고 있을 거다.$K\n"
.stringn "$F1$P그렇긴 하지$MC……$MD$w4\n"
.stringn "나도 좀 위하고 상의해 봐야겠어.$K"
db 0
.align 4
//MYELL_LAY_LETHE_B

//0x2F53C
Text_2F51C:
.stringn "$R背景会話|$B支援背景|$<$F3$FS$F3$FCL_LAY|$F1$FCL_LETHE|$F3$P잘 지냈어? $w2레테.$K\n"
.stringn "$F1$P라이인가. $w4드디어 참전하는군.$K\n"
.stringn "$F3$P그래, $w2드디어\n"
.stringn "형세가 역전되었으니까.$K$P그것보다 상태는 어때, $w2레테?$w4\n"
.stringn "여태까지는 $w2너나 모우디한테만\n"
.stringn "맡겼잖아.$K$P사실은 나도 함께하려고 했는데\n"
.stringn "미안하게 됐어.$K\n"
.stringn "$F1$P사과 같은 건 의미가 없다.$w4\n"
.stringn "행동으로 갚아.$K\n"
.stringn "$F3$P변함없이 딱딱하다니까~ $w2너는.$K$P그건 그렇고, $w2어때?$w4\n"
.stringn "용병단 녀석들하고는 친해진 것 같아?$K\n"
.stringn "$F1$P$MC…………$MD$w3나름대로, $w2는.$w4\n"
.stringn "하지만 $w2여전히 불만은 있다.$K$P어쩔 수 없겠지만 $w2갑옷이 문제야.$w4\n"
.stringn "아군까지 쇠 냄새를 풍기고 있으니,$w2\n"
.stringn "내가 적을 감지할 수가 없어.$K\n"
.stringn "$F3$P뭐어, $w2그건 그렇겠지~$MC…$MD$w4\n"
.stringn "아무리 그래도 아이크네에게 전원 맨몸으로\n"
.stringn "싸워 달라고도 할 수 없는 노릇이고.$K\n"
.stringn "$F1$P그리고, $w2베오크의 눈은 좀 어떻게 안 되는 건가?$w4\n"
.stringn "어둠 속에서 보지 못하는 건 치명적이다.$K$P조익족은 불가능하겠지만,$w2\n"
.stringn "조금이라도 앞이 보인다면 기합으로 어떻게든$MC……$MD$K\n"
.stringn "$F3$P$FA아니 말도 안 되지, $w2그건$MC……$MD$K\n"
.stringn "$F1$P$FS다만$MC……$MD$w4\n"
.stringn "여기 있는 건 생각보다 할 만하다.$K\n"
.stringn "$F3$P$FS그렇구나, $w2다행이네.$w4\n"
.stringn "처음에 아이크네랑 같이 가게\n"
.stringn "되었을 때 네 비장한 얼굴이 마치$MC……$MD$K\n"
.stringn "$F1$P$FA시, $w2시끄러워$MC!$MD$K"
db 0
.align 4
//MYELL_LAY_LETHE_C

//0x30D6C
Text_30D4C:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_LAY|$F1$FCL_MORDY|$F1$P미안하다, $w2라이.$K\n"
.stringn "$F3$P왜 그래, $w2모우디?$K\n"
.stringn "$F1$P라이한테 듣고 나서, $w2생각해 봤다.$w4\n"
.stringn "하지만, $w2아무리 그래도 모우디는\n"
.stringn "싸우는 게 싫다.$K\n"
.stringn "$F3$P$FS아아$MC…$MD$w4 그건\n"
.stringn "이해한다고 말했잖아?$K\n"
.stringn "$F1$P모우디는 전사니까, $w2싸운다.$w4\n"
.stringn "동료를 지키기 위해, $w2싸운다.$K$P그런데도$MC……$MD 모우디는,$w2\n"
.stringn "지금까지처럼 $w2싸울 수밖에 없다.$K\n"
.stringn "$F3$P$FA$MC……$MD모우디.$w4\n"
.stringn "$FS그래$MC……$MD$w4 너는\n"
.stringn "옛날부터 그랬지.$K$P숲에서 다람쥐랑 낮잠 자는 게 취미인$MC…$MD$w2\n"
.stringn "쾌활하면서도 느긋한 녀석이었어.$K\n"
.stringn "$F1$P으으$MC……$MD$w3 미안.$K\n"
.stringn "$F3$P$FS아니, $w2신경 쓰지 말라니까.$K\n"
.stringn "$F1$P$MC……$MD혹시$w3\n"
.stringn "모우디는$MC…$MD$w2 좋아하는 아이크와 모두에게\n"
.stringn "민폐일지도 모른다$w2$MC……$MD$K$P그렇게 생각하니 무척 괴로웠다$MC………$MD$K\n"
.stringn "$F3$P그럼, $w2빨리 전쟁을 끝내자.$w4\n"
.stringn "그러면 $w2이렇게 고민하지 않아도 되잖아?$K\n"
.stringn "$F1$P$FS그렇다$MC!$MD$w4 그러면 되겠다$MC!$MD$K\n"
.stringn "$F3$P그럼 $w2평소보다 더 기합을 넣고 가 볼까?$w4\n"
.stringn "같이 어울려 줘.$w3\n"
.stringn "다음을 대비해서 몸을 $w2움직여 두자구.$K\n"
.stringn "$F1$P그래$MC!!$MD$K"
db 0
.align 4
//MYELL_LAY_MORDY_A

//0x308A4
Text_30884:
.stringn "$R背景会話|$B支援背景|$<$F7$FCL_MORDY|$F7$P쿨$MC……$MD$w4쿨$MC……$MD$K\n"
.stringn "$F3$FS$F3$FCL_LAY|$F3$P어~이 모우디.$w4\n"
.stringn "뭐지?$w4 자는 건가?$K\n"
.stringn "$F7$FD$F1$FCL_MORDY|$F1$P으으으으음$MC……$MD$w4 라이?$K\n"
.stringn "$F3$P오$MC!$MD$w2 일어났구나.$K$P잘도 이런 곳에서 자네.$w4\n"
.stringn "너도 무신경한 건$w2\n"
.stringn "아이크랑 맞먹는단 말이지.$K\n"
.stringn "$F1$P$FS모우디는 $w2아이크와 모두를\n"
.stringn "신뢰하고 있다.$w4\n"
.stringn "모두가 있다고 생각하면, $w2안심이 된다.$K\n"
.stringn "$F3$P하하,$w2 그러냐.$K$FA$P$MC……$MD그러고 보니 모우디.$w4\n"
.stringn "이전에 $w2네가 싸우는 걸 보다가\n"
.stringn "눈치챘는데.$K$P너, $w2적을 공격할 때\n"
.stringn "가끔씩 눈을 감고 있더라?$K\n"
.stringn "$F1$P$FA$MC……$MD$w3그렇다.$w4\n"
.stringn "라이가 잘 봤다.$K\n"
.stringn "$F3$P왜 그러는 거야?$K\n"
.stringn "$F1$P아파하는 적을 보면, $w2모우디도 아프다.$w4\n"
.stringn "그래도, $w2싸움이다.$w4\n"
.stringn "싸움에 자비는 없다.$K$P열심히 싸워야 한다.$w4\n"
.stringn "그래서 $w2눈을 조금 감는다.$K\n"
.stringn "$F3$P가끔 $w2부자연스럽게\n"
.stringn "움직임이 둔해지는 것도 그 때문이었구나$MC…$MD$K\n"
.stringn "$F1$P맞다$MC…$MD$w3 라이는 잘 보고 있다.$K\n"
.stringn "$F3$P뭐 그렇지$MC…$MD$K$P$FS그나저나 아까운걸.\n"
.stringn "그 상냥한 마음이 없었다면$w2\n"
.stringn "너는 더 강한 전사가 됐겠지.$K\n"
.stringn "$F1$P으으$MC……$MD$w2 미안하다$MC……$MD$K\n"
.stringn "$F3$P딱히 사과할 필요는 없어.$w4\n"
.stringn "네 성격은 $w2잘 이해하고 있으니까.$K\n"
.stringn "$F1$P응$MC……$MD$K"
db 0
.align 4
//MYELL_LAY_MORDY_B

//0x30500
Text_304E0:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_MORDY|$F3$FS$F3$FCL_LAY|$F3$P안녕, $w2모우디.$K\n"
.stringn "$F1$P라이.$w4\n"
.stringn "이렇게 얘기하는 거 오랜만이다.$K\n"
.stringn "$F3$P그래, $w2여태까지 수고 많았어.$w4\n"
.stringn "다 들었어, $w2용병단 내에서도\n"
.stringn "맹활약했다면서?$K\n"
.stringn "$F1$P그런가?$w4\n"
.stringn "도움이 되어서 다행이다.$K$P아이크는 좋은 베오크니까\n"
.stringn "모우디는 힘냈다.$K\n"
.stringn "$F3$P이제 용병단 동료들과도\n"
.stringn "잘 지내는 거야?$K\n"
.stringn "$F1$P글쎄?$w4\n"
.stringn "아마, $w2잘 지내는 것 같다.$K$P근데 라이,$w2\n"
.stringn "모우디가 말하는 거, $w2이상한가?$K\n"
.stringn "$F3$P아니, $w2하나도 안 이상해.$w4\n"
.stringn "조금 딱딱하긴 하지만.$K\n"
.stringn "$F1$P말은 어렵다.$w4\n"
.stringn "우리들은 화신하면$w2\n"
.stringn "어려운 말은 할 필요가 없다.$K$P숲속의 동료들과도 $w2한 번에\n"
.stringn "의사를 주고받을 수 있다.$K\n"
.stringn "$F3$P뭐 그렇지.$w4\n"
.stringn "하지만 우리가 짖어도\n"
.stringn "베오크들은 모를걸.$K$P마구 짖어 댔다가\n"
.stringn "모두를 겁주게 되면 큰일이고.$K\n"
.stringn "$F1$P그렇다. $w4라이 말이 맞다.$K$P여기 있는 건$w2\n"
.stringn "좋은 베오크들뿐이다.$w4\n"
.stringn "무섭게 하면 안 된다.$K"
db 0
.align 4
//MYELL_LAY_MORDY_C

//0x311B0
Text_31190:
.stringn ""
db 0
.align 4
//MYELL_LAY_TAURONEO_A

