//0x31AE4
Text_31AC4:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_MWARIM|$F3$FCL_LETHE|$F1$P레테.$K\n"
.stringn "$F3$P$MC……$MD무슨 일이지?$K\n"
.stringn "$F1$P불쾌하게 해서 미안했다.$K$P포기하고 있었던 주제에$MC……$MD$w4\n"
.stringn "나는 네가\n"
.stringn "부러웠던 모양이야.$K\n"
.stringn "$F3$P그래$MC……?$MD$K\n"
.stringn "$F1$P베오크에게 꺾이지 않고$w2\n"
.stringn "대등하게 대할 수 있다.$K$P네 입장에서는 당연한 일이겠지만,$w2\n"
.stringn "나는 그런 일을 생각해 본 적도 없었다.$K\n"
.stringn "$F3$P$MC…………$MD그렇다면$MC……$MD$w4\n"
.stringn "생각만이라도 해 본다면 $w2가능하게\n"
.stringn "될 일이 아닌가?$K\n"
.stringn "$F1$P$MC……$MD그래, $w2그럴지도 모르지.$w4\n"
.stringn "아니$MC……$MD$w4 그렇게 해야만 하는 걸지도 몰라.$K\n"
.stringn "$F3$P의무는 아니라고 생각하지만$MC……$MD$w4\n"
.stringn "그렇게 하는 편이 $w2분명 네가\n"
.stringn "편해질 거라고 생각한다.$K$P네가 편안한 얼굴을 하고 있는 걸\n"
.stringn "나는 본 적이 없어.$w4\n"
.stringn "그게 신경 쓰여서$MC……$MD$w2 괴롭다.$K\n"
.stringn "$F1$P$MC…………$MD그런가$MC……$MD$K\n"
.stringn "$F3$P$MC……$MD그, $w2괴로울지도 모르지만$MC……$MD$w4\n"
.stringn "네가 어떤 식으로 살아왔는지\n"
.stringn "들려주지 않겠나?$K$P$FS$MC……$MD조금이라도, $w2네 기분을\n"
.stringn "알게 될지도 모른다.$K\n"
.stringn "$F1$P$MC…………$MD$w2레테$MC……$MD$K"
db 0
.align 4
//MYELL_LETHE_MWARIM_A

//0x315D4
Text_315B4:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_MWARIM|$F3$FCL_LETHE|$F3$P무와림.$w4\n"
.stringn "$MC……$MD요즘은 잘 지내나?$K\n"
.stringn "$F1$P그래, $w2이 군에도 꽤\n"
.stringn "적응했다.$K$P다른 라구즈들의 시선에도$MC…$MD$w4\n"
.stringn "제법 익숙해졌고.$K\n"
.stringn "$F3$P?$w4 라구즈의$MC……?$MD$K$P그나저나 $w2너$MC……$MD 또 짐을 옮기는 거냐?$w4\n"
.stringn "그런 물자를 나르는 일 따윈\n"
.stringn "다른 병사들에게 맡겨 두면 될 텐데.$K\n"
.stringn "$F1$P신경이 쓰여서 말이지.$w4\n"
.stringn "그대로 지나치기에는\n"
.stringn "공포심마저 느끼게 된다.$K\n"
.stringn "$F3$P공포$MC……?$MD$K\n"
.stringn "$F1$P$FS태어날 때부터 그런 환경에서 자라면\n"
.stringn "뼛속까지 새겨지는 법이지.$K\n"
.stringn "$F3$P$MC…………$MD그렇군.$K\n"
.stringn "$F1$P너는 $w2화내지 않는 건가?$w4\n"
.stringn "라구즈로서의 긍지는 어쨌냐고.$K\n"
.stringn "$F3$P$MC…………$MD$w2아니$MC……$MD$w4\n"
.stringn "옛날의 나라면 $w2그렇게 말했을지도 모른다.$K$P하지만 지금은$MC……$MD$w2 아이크 곁에서\n"
.stringn "싸우면서$MC……$MD$K$P라구즈와 베오크의 관계에 대해\n"
.stringn "여러 가지를 생각하게 된단 말이지$MC……$MD$K\n"
.stringn "$F1$P$FA$MC…………$MD$K\n"
.stringn "$F3$P무엇보다, $w2이미 체념하고 있는 네게\n"
.stringn "할 말은 아무것도 없다.$K\n"
.stringn "$F1$P$MC!$MD$K\n"
.stringn "$F3$P그게 나쁘다고는 할 수 없어.$w4\n"
.stringn "나로서는 이해할 수 없는 삶을$MC……$MD$w3\n"
.stringn "너는 살아온 거지?$K$P다만$MC……$MD$w3 하나만 부탁하지.$K$P네가 모든 걸 받아들이고 $w2포기했다면\n"
.stringn "그렇게 비굴한 태도로 지내진 말아 줘.$w4\n"
.stringn "$MC……$MD신경이 쓰여서 $w2견딜 수가 없다.$K$F3$FD\n"
.stringn "$F1$P$MC…………$MD$K"
db 0
.align 4
//MYELL_LETHE_MWARIM_B

//0x311B4
Text_31194:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_LETHE|$F3$FCL_MWARIM|$F1$P무와림.$K\n"
.stringn "$F3$P$MC……$MD레테인가.$K\n"
.stringn "$F1$P상태는 어떻지?$w4\n"
.stringn "이런 식으로 군대에서 싸우는 건 처음일 텐데.$K\n"
.stringn "$F3$P그래, $w2맞다.$w4\n"
.stringn "모르는 것이 많아서 $w2당혹스러운 점도 있지.$K\n"
.stringn "$F1$P뭐든지 물어봐라.$w4\n"
.stringn "나는 갈리아에서 부대를 이끌고 있었으니까.$w4\n"
.stringn "전투 지식이라면 풍부하게 가지고 있다.$K\n"
.stringn "$F3$P$FS$MC……$MD여자의 몸으로 말인가.$w4\n"
.stringn "레테는 대단하군.$K\n"
.stringn "$F1$P$MC………………$MD$K\n"
.stringn "그런가$MC……$MD$w4 너는 베그니온에서\n"
.stringn "태어나 자랐다고 했었지$MC……$MD$K$P갈리아에선 남자든 여자든 관계없다.$w4\n"
.stringn "보다 우수한 전사라면 그걸로 된다.$K$P신체 구조의 문제로 $w4남자보다\n"
.stringn "여자 쪽이 아무래도 뒤떨어지는 부분은 있다만$MC…$MD$w4\n"
.stringn "노력으로 $w2보완하면 어떻게든 된다.$K\n"
.stringn "$F3$P훌륭하군.$K\n"
.stringn "$F1$P$MC……$MD너, $w2그렇게 남의 일인 것마냥\n"
.stringn "듣고만 있지 마라.$K$P베그니온에서 노예로 살았다고 했지만$MC……$MD$w4\n"
.stringn "베오크 따위, $w2네가 진심으로 상대하면$MC…$MD$K\n"
.stringn "$F3$P$FA$MC……$MD넌 모르겠지.$K$P태어날 때부터 위대한 갈리아 왕에게 보호받으며,$w2\n"
.stringn "라구즈로서의 자부심을 안고 살아왔다.$w4\n"
.stringn "그런 너로서는 이해할 수 없는 일이야.$K\n"
.stringn "$F1$P$MC…………$MD$K"
db 0
.align 4
//MYELL_LETHE_MWARIM_C

//0x32784
Text_32764:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_LOFA|$F3$FS$F3$FCL_MARCIA|$F3$P굉장해~$MC!$MD$w4\n"
.stringn "요파, $w2전부 적중시켰네.$K\n"
.stringn "$F1$P응.$w4\n"
.stringn "그래도 더 열심히 해야지.$K$P게다가 $w2맞히기만 하는 걸로는 안 돼.$w4\n"
.stringn "나한테 활을 가르쳐 준 사람은\n"
.stringn "확실하게 갑옷 틈새만 노려서 맞히니까.$K\n"
.stringn "$F3$P굉장하네$MC……$MD$w4\n"
.stringn "요파도 그렇게 되려나$MC……$MD$K$P$FA$MC…………$MD어라?$w4\n"
.stringn "자, $w2잠깐 요파,$w2\n"
.stringn "손 보여 줘 봐$MC!$MD$K\n"
.stringn "$F1$P손$MC……?$MD$K\n"
.stringn "$F3$P역시나$MC……$MD$w4\n"
.stringn "물집이 뭉개져서 피가 나잖아.$K$P정말, $w2뭐 하는 거야$MC!$MD$w4\n"
.stringn "왜 이렇게 될 때까지 놔뒀어$MC!?$MD$K\n"
.stringn "$F1$P정말이네$MC……$MD$w4\n"
.stringn "아프다$w2고 생각은 했었는데$MC……$MD$K$P도중에 안 아프게 돼서\n"
.stringn "그대로 계속 있었어.$K\n"
.stringn "$F3$P요파$MC……$MD$w4\n"
.stringn "요파는 정말 강하구나$MC……$MD$K$w3$P잠깐만, $w2상처약이$MC……$MD$w4\n"
.stringn "$FS아, $w2여기 있다.$w4\n"
.stringn "가만히 있어. $w4조금 따끔할 거야.$K\n"
.stringn "$F1$P$FS$MC……$MD고마워.$K\n"
.stringn "$F3$P요파는 크면$w2\n"
.stringn "더 강해질 거야.$w4\n"
.stringn "지금도 이렇게 강하니까$MC……$MD$K\n"
.stringn "$F1$P그래?$K\n"
.stringn "$F3$P응. $w4실력도 실력이지만 $w2마음가짐이 훌륭한걸.$K$P아픈 걸 잊어버릴 정도로\n"
.stringn "집중할 수 있잖아.$w4\n"
.stringn "쉽게 할 수 있는 일이 아니야.$K\n"
.stringn "$F1$P그럼$MC……$MD$w2 나는 제대로$w2\n"
.stringn "모두를 지킬 수 있을까?$w4\n"
.stringn "위험할 때, $w2제대로 도움이 될 수 있을까?$K\n"
.stringn "$F3$P물론이지$MC!$MD$w4\n"
.stringn "소중한 사람들을 $w2분명 지킬 수 있을 거야.$w4\n"
.stringn "제멋대로지만 내가 보증할게$MC!$MD$K\n"
.stringn "$F1$P$MC……$MD고마워, $w2마샤씨.$w4\n"
.stringn "제대로 $w2마샤씨도 지켜 줄게.$w4\n"
.stringn "항상 곁에 있어 줘서, $w2고마워.$K\n"
.stringn "$F3$P$FA요파$MC…………$MD$w4\n"
.stringn "$MC…………$MD$w3나도$MC…$MD$w3 나도, $w2요파를 지켜 줄게.$K$P$Fh요파는 아직 어린데$MC……$MD$w4\n"
.stringn "$Fc어째서 $w2어른스럽게\n"
.stringn "되어야 하는 걸까$MC…………$MD$K"
db 0
.align 4
//MYELL_LOFA_MARCIA_A

//0x32330
Text_32310:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_LOFA|$F4$FS$F4$FCL_MARCIA|$F4$P와, $w2굉장하다$MC!$MD$w4\n"
.stringn "23번 연속으로 과녁을 맞혔잖아$MC!$MD$K\n"
.stringn "$F3$P으~음$MC……$MD$w2 사실은 30번 연속으로\n"
.stringn "맞히고 싶었는데$MC……$MD$K\n"
.stringn "$F4$FD$F1$FS$F1$FCL_MARCIA|$F1$P그래도 $w2절반 이상은 맞혔다는 거 아냐?$w4\n"
.stringn "잘한다, $w2요파$MC!$MD$K\n"
.stringn "$F3$P그치만 $w2전장에서는 모두 적중시켜야 한다$w2고\n"
.stringn "나한테 활을 가르쳐 준 사람이 말했어.$K$P23번으로 만족하면 안 돼.$w4\n"
.stringn "훈련용이라 거리도 짧고.$K\n"
.stringn "$F1$P그렇구나$MC……$MD$w2 장하네, $w2요파는.$w4\n"
.stringn "자신에게 엄격하구나.$K\n"
.stringn "$F3$P마샤는 자신에게 상냥해?$K\n"
.stringn "$F1$P응?$w4 그런 건 아니야.$K$P자신에게 엄격하게, $w2타인에게도 엄격하게$MC!$MD$w4\n"
.stringn "가 $w2예전에 소속되어 있던 군의\n"
.stringn "부대장이 하던 말이었으니까.$K$P그래도, $w2요파는 아직$MC……$MD$K\n"
.stringn "$F3$P어린애가 아니야.$w4\n"
.stringn "$MC……$MD나도 $w2적을 쓰러뜨리고 있어.$K\n"
.stringn "$F1$P$FA$MC……$MD응, $w2그렇지.$K\n"
.stringn "$F3$P마샤씨는 $w2내가 어린애니까\n"
.stringn "걱정해 주고 있는 거야?$K\n"
.stringn "$F1$P응$MC……$MD$K\n"
.stringn "$F3$P그럼 $w2이제 걱정 안 해 줘도 돼.$w4\n"
.stringn "난 $w2그렇게 약하지 않으니까.$K\n"
.stringn "$F1$P그렇구나$MC……$MD$w4 미안해.$K"
db 0
.align 4
//MYELL_LOFA_MARCIA_B

//0x31EF4
Text_31ED4:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_LOFA|$F3$P영차$MC……$MD$w2 휴우.$K\n"
.stringn "$F1$FCL_MARCIA|$F1$P어라?$w4 너는$MC……$MD$w4\n"
.stringn "분명 $w2요파라 했었지.$w4\n"
.stringn "혼자서 뭐 하고 있었니?$K\n"
.stringn "$F3$P활 훈련이야.$K$P여기에 이렇게 나무를 세우고,$w2\n"
.stringn "적중시킬 장소를 정한 다음에$w2\n"
.stringn "그곳을 노리는 거지.$K$P다른 곳에 맞히면 위험하니까\n"
.stringn "화살 끝에는 천을 달아 놨어.$K$P게다가 $w2과녁과의 거리도 짧게 잡아서\n"
.stringn "제대로 훈련이 되지는 않지만.$K\n"
.stringn "$F1$P$FS우와, $w2대단하네.$w4\n"
.stringn "어린데도 열심히 하는구나.$K\n"
.stringn "$F3$P어리다고 하지 마.$w4\n"
.stringn "나도 $w2어엿한 용병인걸?$K\n"
.stringn "$F1$P알아 $w2알아.$w4\n"
.stringn "그럼 내가\n"
.stringn "훈련하는 거 도와줄까?$K\n"
.stringn "$F3$P어$MC……? $MD$w4괜찮아.$w4\n"
.stringn "혼자서 할 수 있어.$K\n"
.stringn "$F1$P사양하지 말고.$w4\n"
.stringn "난 말이지, $w2세상에서 제일 큰 나라의\n"
.stringn "기사였다니까.$K$P게다가 $w2궁병에 대한 지식은 풍부한걸?$w4\n"
.stringn "천마 기사에게 $w2궁병은 강적이거든.$K\n"
.stringn "$F3$P난 $w2기사가 아니거든.$w4\n"
.stringn "상관없어.$K\n"
.stringn "$F1$P아, $w2잠깐 요파.$K$P이런 데서 활을 쏠 때는$w2\n"
.stringn "주변에 사람이 있는지\n"
.stringn "확인해야 돼.$K\n"
.stringn "$F3$P나 참, $w2그런 건 알고 있다구.$K\n"
.stringn "$F1$P그렇구나, $w2미안 미안$MC!$MD$K"
db 0
.align 4
//MYELL_LOFA_MARCIA_C

//0x33898
Text_33878:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_MIST|$F3$FCL_LOFA2|$F1$P저기, $w2요파.$K\n"
.stringn "$F3$P$MC……$MD$K\n"
.stringn "$F1$P무시하지 마.$w4\n"
.stringn "제대로 얘기$w2하자.$K\n"
.stringn "$F3$P$MC………$MD$K\n"
.stringn "$F1$P요파를 탓할 생각은 없어.$K$P단지 $w2용병단 때처럼\n"
.stringn "산적 퇴치라든가$MC…$MD$w4 그런 식으로\n"
.stringn "상대를 그저 나쁜 사람들로만 보면 안 된다는 걸$MC…$MD$K$P알아 줬으면 했어.$K\n"
.stringn "$F3$P$MC…$MD내가 아무런 생각도 없이\n"
.stringn "그러는 줄 알았어?$K\n"
.stringn "$F1$P$MC…$MD뭐?$K\n"
.stringn "$F3$P상대는 과녁이 아니야$MC…$MD$w4\n"
.stringn "과녁은 움직이지도 않고, $w2비명도 지르지 않아$MC…$MD$w4\n"
.stringn "피를 흘리지도 않지$MC……$MD$K$P그런 것쯤은 $w2알고 있었어.\n"
.stringn "처음으로 적을 쓰러뜨린$MC…$MD$w4 그때부터$MC……$MD$K$P적도$MC…$MD$w4\n"
.stringn "우리처럼 동료나 가족들을\n"
.stringn "지키기 위해서 싸우는 $w2인간이라는 걸$MC…$MD$K\n"
.stringn "$F1$P요파$MC…$MD$K\n"
.stringn "$F3$P그래도 $w2나쁜 놈들이야.$K$P나한테는$MC…$MD$w4\n"
.stringn "소중한 사람들을 상처 입힌다면\n"
.stringn "적이고, $w2나쁜 놈들이야.$K$P그러니까 쓰러뜨리겠어.$w4\n"
.stringn "그야 $w2녀석들을 살려 뒀다간\n"
.stringn "다음엔 아군 중 누군가가 죽을 테니까$MC!$MD$K$P난$MC…$MD$w4 그게 무서워.$w4\n"
.stringn "전쟁이 끝나지 않으면\n"
.stringn "언제까지고$MC…$MD$w4 계속될 거야$MC!$MD$K$P그러니까$MC…$MD$w4\n"
.stringn "빨리 싸움을 끝내고 싶으니까$MC…$MD$K\n"
.stringn "$F1$FD$F1$FCL_MISTs|$F1$P요파$MC…$MD$MC!$MD$K\n"
.stringn "$F3$P$Fh미스트가$MC…$MD$w4\n"
.stringn "죽는 건, $w2싫어.$K$P난 $w2이제$MC…$MD$w4\n"
.stringn "아무도$MC…$MD$w4 잃고 싶지 않아$MC……$MD$w4\n"
.stringn "$Fc$MC…$MD$w4 $MC…$MD$w4 $MC…$MD$K\n"
.stringn "$F1$P요파, $w2미안해$MC!$MD$w4\n"
.stringn "미안해$MC…$MD$K\n"
.stringn "$F3$P$MC…$MD흑$w4 $MC…$MD$w4 $MC…$MD$K\n"
.stringn "$F1$P요파가$MC…$MD$w4 바뀐 줄 알았어.$K$P상냥한 아이였는데,$w2\n"
.stringn "사람의 죽음을$MC…$MD$w4 아무렇지도 않게$MC…$MD$w4 넘기면서\n"
.stringn "싸우는 줄 알았어$MC……$MD$K$P미안해$MC…$MD$w4 내가\n"
.stringn "요파의 마음을$MC…$MD$w4\n"
.stringn "이해해 주지 못해서$MC…$MD$w4 미안해$MC…$MD$K$P싸우기 위해서 필사적이었구나$MC…$MD$w4\n"
.stringn "발버둥치고 있었구나$MC……$MD$K\n"
.stringn "$F3$P$Fd$MC……$MD나$MC…$MD$w4 싸울 거야$MC…$MD$K$P다시 한번$MC…$MD$w4 모두와 함께\n"
.stringn "평화롭게 살기 위해서$MC…$MD$w4\n"
.stringn "$MC………$MD싸울 거야$MC……$MD$K\n"
.stringn "$F1$P응$MC…$MD$w4\n"
.stringn "나도 싸울게$MC…$MD$K$P$FS둘이서$MC…$MD$w4 같이$MC……$MD$w4\n"
.stringn "힘$MC…$MD$w4내자.$K"
db 0
.align 4
//MYELL_LOFA_MIST_A

//0x33274
Text_33254:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_LOFA|$F3$P$MC……$MD어디 $w2보자.$K\n"
.stringn "$F4$FCL_MIST|$F4$P$MC…$MD요파, $w2잠깐 괜찮아?$K\n"
.stringn "$F3$P$FS아, $w2응.$K$P잠깐만, $w2활시위 좀\n"
.stringn "고쳐야 돼서.$w4\n"
.stringn "안 하면 여차할 때 $w2곤란하니까.$K\n"
.stringn "$F4$P$MC……$MD$K\n"
.stringn "$F3$FD$F1$FS$F1$FCL_LOFA|$F1$P기다렸지$MC!$MD$w4\n"
.stringn "무슨 일이야?$w4 미스트.$K\n"
.stringn "$F4$P요파, $w2이제\n"
.stringn "전장에 나가는 거 $w2그만두지 않을래?$K$P역시, $w2우리 같은\n"
.stringn "어린애가 싸우는 건$MC…$MD$w4 좋지 않아.$K\n"
.stringn "$F1$P$MC…$MD뭐$MC…?$MD$w4\n"
.stringn "왜 갑자기 그런 말을 하는 거야?$K\n"
.stringn "$F4$P제발$MC!$MD$w4\n"
.stringn "오빠한테는 내가 말해 둘 테니까$MC…$MD$K$P그러니까, $w2예전처럼\n"
.stringn "둘이서 다른 일을 도와$MC…$MD$K\n"
.stringn "$F1$P$MC…$MD그렇구나,$w2\n"
.stringn "미스트는 싸우는 게 무섭다고\n"
.stringn "했었지$MC…$MD$K$P응, $w2전장에 나가지 않는 편이 좋겠어.$w4\n"
.stringn "걱정하지 마$MC!$MD$w4\n"
.stringn "미스트의 몫까지, $w2내가 싸울게.$K\n"
.stringn "$F4$P아니야$MC!$MD$w4\n"
.stringn "요파가 그만두지 않으면 $w2의미가 없다고$MC!!$MD$K\n"
.stringn "$F1$P$FA그건 안 돼$MC!$MD$w4\n"
.stringn "나는 남자니까$MC…$MD$w4\n"
.stringn "적을 쓰러뜨리고, $w2모두를 지켜야 해$MC…$MD$K\n"
.stringn "$F4$P쓰러뜨린다니$MC…$MD$w4 그렇게 쉽게 말하지 마$MC!$MD$w4\n"
.stringn "적도 한 명의 인간이라구!?$K\n"
.stringn "$F1$P$MC!!$MD$K\n"
.stringn "$F4$P요파, $w2알겠어?$w4\n"
.stringn "적도$MC…$MD$w4 우리와 같은 인간이야$MC…$MD$w4\n"
.stringn "연습용 과녁 같은 게 아니라고$MC……$MD$K\n"
.stringn "$F1$P$MC………………$MD$w4알 게 뭐야$MC…$MD$K\n"
.stringn "$F4$P요파$MC!$MD$K\n"
.stringn "$F1$P알 게 뭐냐고$MC!$MD$w4 $MC…$MD난\n"
.stringn "그런 거 몰라$MC!!$MD$K$P적은 우리를 상처 입히는 놈들이잖아$MC!$MD$w4\n"
.stringn "난 $w2그것들을 쓰러뜨리고 있을 뿐이야$MC!$MD$w4\n"
.stringn "모두를 지키고 있을 뿐이라고$MC!!$MD$K$F1$FD\n"
.stringn "$F4$P기다려, $w2요파$MC!$MD$w4\n"
.stringn "$MC……$MD안 돼$MC…$MD$w4 이대로는$MC……$MD$K"
db 0
.align 4
//MYELL_LOFA_MIST_B

//0x32E4C
Text_32E2C:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_MIST|$F3$FCL_LOFA|$F1$P요파$MC!$MD$w4\n"
.stringn "여기 있었구나?$K\n"
.stringn "$F3$P미스트,$w2\n"
.stringn "무슨 일이야?$w4\n"
.stringn "날 찾고 있었어?$K\n"
.stringn "$F1$P응.$w4\n"
.stringn "요파랑 얘기하고 싶어서.$K$P그때$MC…$MD$w4\n"
.stringn "처음으로 전장에 나가서 싸운 이후로$w2\n"
.stringn "요파랑 얘기할 기회가 $w2없었으니까.$K\n"
.stringn "$F3$P$FS$MC…$MD무사해서 다행이야.$w4\n"
.stringn "우리 둘 다$MC……$MD$w4 잘 살아 있네.$K\n"
.stringn "$F1$P응$MC……$MD$w4 정말 다행이야$MC…$MD$K\n"
.stringn "$F3$P나 있지, $w2무척 가슴이 두근거리고\n"
.stringn "손이 떨렸어.$K\n"
.stringn "$F1$P$FA나도$MC……$MD$K$P주위에서 굉장한 소리가 나더니,$w2\n"
.stringn "눈앞이 어지러워서$MC……$MD$w4\n"
.stringn "$MC……$MD정말$MC……$MD$w4 무서웠어.$K\n"
.stringn "$F3$P미스트는\n"
.stringn "역시 여자애구나.$w4\n"
.stringn "나는 전혀 $w2무섭지 않았는데.$K$P긴장해서$MC…$MD$w4 처음에는\n"
.stringn "잘 못 쐈지만$w2\n"
.stringn "나중에는 제대로 적에게 맞혔다고$MC!$MD$K\n"
.stringn "$F1$P어$MC…?$MD$K\n"
.stringn "$F3$P다음 전투가 기다려져.$K$P다음번에는 더 잘 싸울 수 있을 거야.$w4\n"
.stringn "더 많이\n"
.stringn "적을 쓰러뜨려야지$MC!$MD$K$P자, $w2좀 더 연습해야 돼.$w4\n"
.stringn "다음에 보자, $w2미스트.$K$F3$FD\n"
.stringn "$F1$P아, $w2요파$MC!$MD$w4\n"
.stringn "$MC………$MD$w4요파$MC…$MD$K"
db 0
.align 4
//MYELL_LOFA_MIST_C

//0x34A4C
Text_34A2C:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_LOFA|$F3$FCL_TAURONEO|$F3$P$MC……$MD역시, $w2나는$MC……$MD$w4\n"
.stringn "착각하고 있었다.$K$P할 수 있다면 가족에게$MC……$MD$w4\n"
.stringn "한 마디로라도 사과하고 싶구나.$K\n"
.stringn "$F1$P$MC……$MD있죠, $w2아저씨.$w4\n"
.stringn "아저씨네 가족은\n"
.stringn "정말 어디 있는지 모르는 거예요?$K$P아무런 단서도 $w2없어요?$K\n"
.stringn "$F3$P$MC…………$MD$w4\n"
.stringn "$MC……$MD아내는 데인을 떠나$w2\n"
.stringn "크리미아에 있는 친척에게로 갔단다.$K$P아마도 크리미아 땅에서\n"
.stringn "살고 있겠지$MC……$MD$K\n"
.stringn "$F1$P$FS그렇구나$MC!$MD$w4 그럼$w2\n"
.stringn "만나러 가면$MC……$MD$K\n"
.stringn "$F3$P$MC……$MD그럴 순 없다.$w4\n"
.stringn "내가 이제 와서$MC……$MD$w4 무슨 낯으로\n"
.stringn "아이들을 만나러 갈 수 있겠느냐.$K$P이제 와서 모습을 드러내 봤자$MC……$MD$w4\n"
.stringn "아내와 아이들에게 피해만 줄 뿐이야.$K\n"
.stringn "$F1$P$FA그렇지 않아요$MC!$MD$K$P그야, $w2저는$MC……$MD$w4\n"
.stringn "저는, $w2아빠를 만나고 싶은걸요$MC!$MD$K\n"
.stringn "$F3$P$MC……$MD요파.$K\n"
.stringn "$F1$P형들한테는$MC……$MD$w4\n"
.stringn "난 괜찮다고, $w2외롭지 않다고\n"
.stringn "항상 말했어요.$K$P하지만 사실은, $w2아빠를 만나고 싶었어요.$w4\n"
.stringn "만나서 여러 가질 얘기하고 싶었어요$MC……$MD$K\n"
.stringn "$F3$P$MC……$MD$K\n"
.stringn "$F1$P하지만 우리 아빠는\n"
.stringn "죽어 버렸으니까$MC……$MD$w3 이제 못 만나요.$w4\n"
.stringn "하지만 아저씨는 $w2아직 살아 있잖아요?$K\n"
.stringn "$F3$P그렇$MC……$MD$w4구나.$K\n"
.stringn "하지만 $w2이미 늦었어$MC……$MD$K\n"
.stringn "$F1$P늦지 않았어요$MC……$MD$w4\n"
.stringn "그야 $w2아저씨는 아직 살아 있으니까요.$K\n"
.stringn "그분들도 아직 $w2아빠랑\n"
.stringn "만날 수 있어요$MC……$MD$K$P$FS그러니까, $w2만나러 가 줘요.$w4\n"
.stringn "분명, $w2분명 기다리고 있을 거예요$MC……$MD$K\n"
.stringn "$F3$P$MC……$MD$w4\n"
.stringn "$MC………$MD요파$MC……$MD$K"
db 0
.align 4
//MYELL_LOFA_TAURONEO_A

//0x34488
Text_34468:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_LOFA|$F3$FCL_TAURONEO|$F3$P우리 집안은 대대로 데인의\n"
.stringn "무인으로서 이름을 떨치고 있었단다.$K$P아버지도 나도, $w2데인의 장군으로서\n"
.stringn "데인 왕가를 모셔 왔지.$w4\n"
.stringn "그것이 우리 가문의 자랑이었다.$K\n"
.stringn "$F1$P그럼, $w2조쉬씨도$MC……?$MD$K\n"
.stringn "$F3$P나는 당연하다는 듯이 아들 조쉬를\n"
.stringn "데인군에 입대시킬 생각으로 키웠지.$K\n"
.stringn "그리고 조쉬도 내 기대에\n"
.stringn "응하려고 해 주었다$MC……$MD고, $w2생각한단다.$K$P최연소로 기사 훈장을 받고,$w2\n"
.stringn "친위대에 임명되었으니까.$w4\n"
.stringn "하지만$MC……$MD$K\n"
.stringn "$F1$P$MC……$MD어떻게 됐는데요?$K\n"
.stringn "$F3$P아슈나드의 측근으로 출진했다가$MC……$MD$w4\n"
.stringn "빈사 상태로 중상을\n"
.stringn "입고 귀환했다.$K$P목숨은 건졌지만$MC……$MD$w4\n"
.stringn "$MC……$MD두 번 다시는 걸을 수 없게 되어 버렸지.$K\n"
.stringn "$F1$P$MC…………$MD그럴 수가$MC……$MD$K\n"
.stringn "$F3$P아내는 미친 듯이 한탄했다.$K$P이런 일이 두 번 다시 일어나선 안 된다며\n"
.stringn "내가 군에서 물러나고,$w2\n"
.stringn "평화로운 생활을 하길 원했지.$K$P하지만 나는 $w2승낙할 수 없었다.$w4\n"
.stringn "우리 집안은 대대로 장군으로서\n"
.stringn "이름을 떨쳐 왔으니까.$K$P이대로 군을 그만두고 도망가기에는$w2\n"
.stringn "지금까지 이어져 온 우리 집안의\n"
.stringn "무인으로서의 이름이 허락하지 않았지.$K$P나는 아직 나이가 어린 차남을 길러,$w2\n"
.stringn "데인군의 장수로 뒤를 잇게 해\n"
.stringn "체면을 지키려고 했다.$K\n"
.stringn "$F1$P그러면 $w2안 되죠$MC……$MD$K\n"
.stringn "$F3$P그러게나 말이다$MC……$MD$w4\n"
.stringn "하지만 그때의 나는 어리석었다.$w4\n"
.stringn "그런 것조차도 모를 정도로.$K$P$MC……$MD깨닫고 나니,$w2\n"
.stringn "아내와 아이들은 집을 떠나고 없더구나.$K$P그리고 나는$MC……$MD$w4\n"
.stringn "무수한 훈장이 달린 저택에서$w2\n"
.stringn "혼자 살아가게 됐지.$K\n"
.stringn "$MC…………$MD몇 년$w2이고$MC……$MD$K"
db 0
.align 4
//MYELL_LOFA_TAURONEO_B

//0x3403C
Text_3401C:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_LOFA|$F3$FCL_TAURONEO|$F3$P$MC!$MD$w4\n"
.stringn "조쉬$MC……?$MD$K\n"
.stringn "$F1$P응$MC……?$MD$K\n"
.stringn "$F3$P$MC……$MD아니, $w2그럴 리가 없지.$K$P미안하군, $w2사람을 잘못 봤다.$w4\n"
.stringn "$MC……$MD소년, $w2네 이름은?$K\n"
.stringn "$F1$P요파예요.$K\n"
.stringn "$F3$P요파, $w2너 같은 어린애가\n"
.stringn "왜 이런 곳에 있는 거냐?$K$P전장은 어린애가 있을 곳이 아니다.$w4\n"
.stringn "너의 부모님께선 왜\n"
.stringn "이런 일을 허락하신 거지?$K\n"
.stringn "$F1$P저$MC……$MD$w4 부모님이 없어요.$K\n"
.stringn "엄마는 집을 나갔고,$w2\n"
.stringn "아빠는 죽었으니까$MC……$MD$K\n"
.stringn "$F3$P그랬던$MC……$MD$w4 건가.$w4\n"
.stringn "미안하다.$w4\n"
.stringn "괴로운 일을 생각나게 했구나.$K\n"
.stringn "$F1$P$FS괜찮아요.$w4\n"
.stringn "지금은 $w2모두와 함께니까.$K\n"
.stringn "$MC……$MD아저씨,$w2\n"
.stringn "저 누구 닮았어요?$K\n"
.stringn "$F3$P내$MC……$MD 아들을 닮았다.$w4\n"
.stringn "조쉬는 장남의 이름이지.$K$P하지만 조쉬는 벌써 성인이란다.$w4\n"
.stringn "너 같은 소년이었던 건$w2\n"
.stringn "벌써 몇 년 전의 이야기인데$MC……$MD$K$P$FS그런데도 잘못 보다니$MC……$MD$w4\n"
.stringn "나도 망령이 든 것 같군.$K\n"
.stringn "$F1$P그 조쉬씨는$w2\n"
.stringn "지금 어디에 있는데요?$K\n"
.stringn "$F3$P$FA$MC……$MD모른다.$K\n"
.stringn "$F1$P$FA네?$K\n"
.stringn "$F3$P나는 아내와 이혼했거든.$w4\n"
.stringn "그때 이후로$w2\n"
.stringn "벌써 몇 년이나 만나지 못했지$MC……$MD$K"
db 0
.align 4
//MYELL_LOFA_TAURONEO_C

//0x35034
Text_35014:
.stringn ""
db 0
.align 4
//MYELL_LUCHINO_TIAMAT_A

//0x35030
Text_35010:
.stringn ""
