//MYELL_LUCHINO_TIAMAT_C

//0x356D8
Text_356B8:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_ULYSSES|$F3$FCL_LUCHINO|$F1$P루키노 공, $w2오늘만큼은\n"
.stringn "달콤한 대답을\n"
.stringn "들려주시길.$K\n"
.stringn "$F3$P율리시스 백작$MC…$MD$w4\n"
.stringn "나는 $w2당신의 그\n"
.stringn "까불거리는 태도가 겉모습뿐이라는 거 알아.$K$P크리미아의 충신으로서$MC…$MD$w4\n"
.stringn "의지하고 있어.$FS\n"
.stringn "그래$MC…$MD$w4 분하지만 $w2인정할게.$K$P나는 당신을 좋게 생각하고 있어.$K\n"
.stringn "$F1$P그럼, $w2제 마음을\n"
.stringn "받아 주시는 거군요?$K\n"
.stringn "$F3$P$MC…$MD그래.$K$P이 전쟁이 끝나고$MC……$MD$w4\n"
.stringn "크리미아가 $w2무사히 부흥한다면\n"
.stringn "생각해 볼게.$K\n"
.stringn "$F1$P오오, $w2루키노$MC!$MD$w4\n"
.stringn "내가 가장 사랑하는 그대여$MC!!$MD$K\n"
.stringn "$F3$P율리시스$MC…$MD$w4\n"
.stringn "정말 미워할 수 없는 사람이야.$K$P$FA아, $w2이런.$w4\n"
.stringn "엘린시아님의 준비를\n"
.stringn "도우러 갈 시간이네.$K\n"
.stringn "$F1$P$FA기, $w2기다려 주시길. $w4루키노$MC!$MD$w4\n"
.stringn "오늘 저녁의 예정은?$w4\n"
.stringn "괜찮다면 저와 함께$MC…$MD$K\n"
.stringn "$F3$P$FS미안해.$w4\n"
.stringn "엘린시아님의 용무가 있어.$w4\n"
.stringn "당분간 $w2시간은 낼 수 없겠네.$K$F3$FD\n"
.stringn "$F1$P$FS이런$MC…$MD$w4 아직도\n"
.stringn "앞길이 막막하군요.$K"
db 0
.align 4
//MYELL_LUCHINO_ULYSSES_A

//0x35354
Text_35334:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_LUCHINO|$F1$P율리시스 백작$MC!$MD$w4\n"
.stringn "어, $w2어디 있어$MC!?$MD$K\n"
.stringn "$F3$FS$F3$FCL_ULYSSES|$F3$P오오, $w2루키노 공$MC…$MD$w4\n"
.stringn "당신답지 않게$w2\n"
.stringn "뭘 그리 당황하면서$MC…$MD$K\n"
.stringn "$F1$P사, $w2상처는?$w4\n"
.stringn "괜찮은 거야$MC!?$MD$K\n"
.stringn "$F3$P흠, $w2제 몸에\n"
.stringn "딱히 불편한 점은\n"
.stringn "없습니다만?$K\n"
.stringn "$F1$P$MC……$MD그래$MC…?$MD$K$P얼빠진 모습을 한\n"
.stringn "콧수염 난 광대가\n"
.stringn "크게 다쳤다고 들어서$MC…$MD$K$P틀림없이 $w2당신일 거라고 생각했는데$MC…$MD$w4\n"
.stringn "착각한 모양이네$MC……$MD$K\n"
.stringn "$F3$P$MC…$MD루키노 공,$w2\n"
.stringn "저를 너무나 걱정한 나머지$MC…$MD$w4\n"
.stringn "그렇게나 당황했던 겁니까.$K$P이것 참 귀엽기가 따로 없군요.$K\n"
.stringn "$F1$P뭐$MC!?$MD$w4\n"
.stringn "아, $w2아니야$MC…$MD$K\n"
.stringn "$F3$P이젠 숨겨도 소용없습니다.$w4\n"
.stringn "그대의 마음,$w2\n"
.stringn "확실히 받았으니 말이지요.$K\n"
.stringn "$F1$P아니라고 했잖아$MC!?$MD$K\n"
.stringn "$F3$P부정하면 부정할수록\n"
.stringn "겉으로 드러나는 것이 사람의 마음이죠.$K\n"
.stringn "$F1$P정말$MC!$MD$w4 사람 말 좀 들으라고$MC!!$MD$K"
db 0
.align 4
//MYELL_LUCHINO_ULYSSES_B

//0x35038
Text_35018:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_ULYSSES|$F3$FS$F3$FCL_LUCHINO|$F3$P어머 율리시스 백작.$w4\n"
.stringn "안녕하신지.$K\n"
.stringn "$F1$P오오$MC…$MD$w4 루키노 공.$K$P그 아름다운 손을 빌려,$w2\n"
.stringn "인사를 전하는\n"
.stringn "영예를 안겨 주실 수 있겠습니까?$K\n"
.stringn "$F3$P사양할게.$w4\n"
.stringn "방금 전까지 검을 손질해서\n"
.stringn "손가락 끝이 기름투성이거든.$K\n"
.stringn "$F1$P저는 전혀 상관없습니다만?$K\n"
.stringn "$F3$P내가 상관있어.$w4\n"
.stringn "미안하지만 포기하도록 해.$K\n"
.stringn "$F1$P후우,$w4 쌀쌀맞게 대해지니\n"
.stringn "더욱 마음이 끌리고$MC…$MD$K$P도망칠 기미를 보이니\n"
.stringn "더욱 쫓고 싶어지는 것이 인지상정.$K$P언제까지 이 가련한\n"
.stringn "사랑의 하수인을 사로잡고 있을 셈입니까.$w4\n"
.stringn "제 마음의 주인 $w2루키노 공.$K\n"
.stringn "$F3$P내가$MC…$MD$w4 다른 귀부인들처럼\n"
.stringn "그런 농간에 넘어갈 거라고\n"
.stringn "생각하지 마.$K$P이제 그만 $w2포기하는 게 어때?$w4\n"
.stringn "끈질긴 남자는 미움받기 쉬운 법이야.$K\n"
.stringn "$F1$P이런 이런, 이거 매섭군요.$K"
db 0
.align 4
//MYELL_LUCHINO_ULYSSES_C

//0x3687C
Text_3685C:
.stringn ""
db 0
.align 4
//MYELL_MAKAROV_STELLA

//0x36880
Text_36860:
.stringn "$R背景会話|$B支援背景|$<$F5$FCL_STELLA|$F5$P$MC……$MD$K\n"
.stringn "$F8$FCDUMMY|$F8$P$F8$FD이~봐.$w4\n"
.stringn "스텔라씨$MC!$MD$K\n"
.stringn "$F5$P$MC!$MD$K\n"
.stringn "$F3$FCL_MAKAROV|$F5$FD$F1$FS$F1$FCL_STELLA|$F1$P안녕하세요.$w3\n"
.stringn "마카로프님.$K\n"
.stringn "$F3$P$FS이거, $w2돌려줄게.$K\n"
.stringn "$F1$P$FA$MC…$MD이 펜던트에$w2\n"
.stringn "무슨 문제라도 있었나요?$K\n"
.stringn "$F3$P아니, $w2굉장히\n"
.stringn "좋은 물건이었어.$K$P최소 5000골드는$w2\n"
.stringn "받아낼 수 있을 것 같던데$MC…$MD$K\n"
.stringn "$F1$P그렇다면 $w2어째서$MC…$MD$K\n"
.stringn "$F3$P$FA고물상에 들어갔더니$w3\n"
.stringn "여동생하고 $w2딱 마주쳐 버렸거든.$K$P어디서 구했냐, $w2라든가$w3\n"
.stringn "훔친 건 아니냐, $w2라든가$MC…$MD$w4\n"
.stringn "여러 가지로 추궁을 받아서 말이야$MC…$MD$K\n"
.stringn "$F1$P이건$MC…$MD$w2 제가\n"
.stringn "마카로프님께 드린 거예요.$K$P$F3$P물론 그 말대로야. $w4하지만$MC…$MD$w2\n"
.stringn "여자를 협박하다니 최악이야$MC!$MD$K$P라면서 $w2울어 버리더라고$MC…$MD$w4\n"
.stringn "그래서 뭐, $w2포기하기로 했어.$K\n"
.stringn "$F1$P그렇군요$MC…$MD$w3\n"
.stringn "알겠습니다.$K\n"
.stringn "$F3$P그건 그렇고,$w2\n"
.stringn "너도 참 복 받았다.$K$P그런 값비싼 펜던트를$w2\n"
.stringn "아까운 기색도 없이 $w2남에게 주다니.$K$P우리 여동생은 $w2싸구려 하나도\n"
.stringn "못 사는 처지인데 말이지.$K$P아~아. $w4여신님은 불공평해.$w4\n"
.stringn "귀족들 편만 들고.$K\n"
.stringn "$F1$P$MC…$MD죄$MC…$MD$w2죄송합니다$MC……$MD$K\n"
.stringn "$F3$P아니, $w2딱히\n"
.stringn "너한테 사과받고 싶은 게$MC…$MD$K\n"
.stringn "$F1$P이 펜던트는$MC…$MD$w3\n"
.stringn "그렇게나 비싼 물건이었군요?$K$P$MC…$MD저$MC…$MD$w4 이건$MC…$MD$w3 정말 좋아했던 할머님의\n"
.stringn "유품이어서 $w2걸고 있었을 뿐$MC……$MD$w4\n"
.stringn "아무것도$MC…$MD$w2 몰랐는데$MC……$MD$K\n"
.stringn "$F3$P켁$MC!$MD$w3 유품$MC!?$MD$w4\n"
.stringn "어, $w2어째서 그렇게 소중한 걸$w2\n"
.stringn "나 같은 놈에게$MC…$MD$K\n"
.stringn "$F1$P이 펜던트와 떨어지더라도$MC…$MD$w4\n"
.stringn "할머님과의 추억은$MC…$MD$w3\n"
.stringn "제 가슴속에 $w2남아 있습니다.$K$P그러니까$MC…$MD$w3 곤란하신 분의\n"
.stringn "도움이 되는 편이 낫다고 생각했어요.$K\n"
.stringn "$F3$P너$MC…$MD$w2 너 정말$MC……$MD$w4\n"
.stringn "미안$MC!$MD$w4 정말로 미안했어$MC!!$MD$K$P나는 $w3도박 때문에\n"
.stringn "너한테서 돈을 뜯어내려고 했는데$MC…$MD$K$P진심으로 반성하고 있어.$w4\n"
.stringn "죄송합니다$MC!$MD$w4 용서해 주세요$MC!!$MD$K\n"
.stringn "$F1$P그럴 수가$MC…$MD$w4$FS\n"
.stringn "마카로프님, $w3저는\n"
.stringn "아무것도 신경 쓰지 않아요.$K\n"
.stringn "$F3$P$FS스텔라씨$MC…$MD$w4 당신\n"
.stringn "여신님보다도 상냥한 여자구나.$K\n"
.stringn "$F1$P$FA$MC………$MD그$MC…$MD$w4\n"
.stringn "그렇지 않아요.$K\n"
.stringn "$F3$P아니. $w4이젠 진짜로\n"
.stringn "눈부시기 시작했어.$K\n"
.stringn "$F1$P놀리지 마세요.$K$P마카로프님 같은\n"
.stringn "멋진 남성분께$MC…$MD$w4\n"
.stringn "그런 식으로 보여 지다니$MC…$MD$K$P$MC…$MD저$MC……$MD$w2 부끄러워요$MC…$MD$K\n"
.stringn "$F3$P$FA어?$w4\n"
.stringn "멋지다니$MC…$MD$w2 내가?$K\n"
.stringn "$F1$P어, $w2어멋$MC…$MD$w4\n"
.stringn "$MC…$MD나도 참$MC…$MD$w3 상스럽게$MC…$MD$MC!$MD$w4\n"
.stringn "시, $w2실례하겠습니다$MC!!$MD$K$F1$FD\n"
.stringn "$F3$P$MC…………………$MD$K$P$MC……$MD$Fh저렇게 자라 오면$w3\n"
.stringn "남자 보는 눈도 안 자라는 건가.$w4\n"
.stringn "불쌍하구만$MC……$MD$K"
db 0
.align 4
//MYELL_MAKAROV_STELLA_A_a

