//0x36304
Text_362E4:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_MAKAROV|$F3$FS$F3$FCL_STELLA|$F3$P아, $w2안녕하세요.$w3\n"
.stringn "마카로프님.$K\n"
.stringn "$F1$P$FS안녕, $w2스텔라씨.$w3\n"
.stringn "당신하고는 $w2자주 만나네.$w4\n"
.stringn "꽤나 인연이 있을지도 모르겠는걸~$K\n"
.stringn "$F3$P그, $w2그런가요?$w4\n"
.stringn "그렇다면$MC…$MD$w3 영광입니다.$K\n"
.stringn "$F1$P인연이라고 하니$w3\n"
.stringn "조금 부탁이 있는데 말이야.$K\n"
.stringn "$F3$P뭔가요?$w4\n"
.stringn "제가 할 수 있는 일이라면 $w2할게요.$K\n"
.stringn "$F1$P돈 좀 빌려주면 안 될까?$K\n"
.stringn "$F3$P$FA돈$MC…$MD$w2이요?$K\n"
.stringn "$F1$P그래, $w2아주 조금이면 되는데.$w4\n"
.stringn "어떻게 안 되려나?$K\n"
.stringn "$F3$P$MC……$MD어떡하죠?$w4\n"
.stringn "저, $w2돈은 1골드도\n"
.stringn "가지고 있지 않아요.$K\n"
.stringn "$F1$P$FA단 1골드도?$w4\n"
.stringn "이 군에서 받은 월급은$w2\n"
.stringn "어디다 썼길래.$K\n"
.stringn "$F3$P마을에 나갔을 때$MC…$MD$w2\n"
.stringn "무척 곤란해 보이는 분이 계시길래$MC…$MD$w4\n"
.stringn "그분께 드렸어요.$K\n"
.stringn "$F1$P우왓,$w3 말도 안 돼.$K$P어차피 베풀 거라면 $w3남이 아니라\n"
.stringn "아는 사람에게 해 주면 좋을 텐데.$w4\n"
.stringn "나 참$MC…$MD$K\n"
.stringn "$F3$P죄, $w2죄송합니다.$w4\n"
.stringn "마카로프님께서 곤란하실 거라고는\n"
.stringn "생각하지 못해서$MC…$MD$K\n"
.stringn "$F1$P으~$MC…$MD$w3 알았어.$w4\n"
.stringn "그럼 $w2다른 사람한테 빌려야겠다.$K\n"
.stringn "$F3$P자, $w2잠깐만요.$K\n"
.stringn "$F1$P음~?$K\n"
.stringn "$F3$P이걸로는 $w2안 될까요?$K\n"
.stringn "$F1$P$FS오$MC!$MD$w4 뭐야\n"
.stringn "딱 봐도 비싸 보이는 펜던트잖아$MC!$MD$w4\n"
.stringn "이거, $w2받아도 되는 거야?$K\n"
.stringn "$F3$P$FS네.$K\n"
.stringn "$F1$P크~$w3 고마워$MC!$MD$w4\n"
.stringn "당신 좋은 여자구나.$w4\n"
.stringn "그럼 이만$MC!$MD$w4 또 보자$MC!!$MD$K$F1$FD\n"
.stringn "$F3$P$MC………$MD$K"
db 0
.align 4
//MYELL_MAKAROV_STELLA_B

//0x35AA0
Text_35A80:
.stringn ""
db 0
.align 4
//MYELL_MAKAROV_STELLA_C

//0x35AA4
Text_35A84:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_STELLA|$F3$FCL_MAKAROV|$F1$P안녕하세요, $w3기사님.$K\n"
.stringn "$F3$P음?$w4 그, $w2그래$MC…$MD$w3\n"
.stringn "나한테 인사하는 거야?$K\n"
.stringn "$F1$P네.$w4\n"
.stringn "저는 $w2스텔라라고 합니다.$w4\n"
.stringn "기사님의 성함은?$K\n"
.stringn "$F3$P기사님이라고 불릴 정도는 아닌데$MC…$MD$w3$FS\n"
.stringn "나는 마카로프야.$w4\n"
.stringn "잘 부탁해, $w3스텔라씨.$K\n"
.stringn "$F1$P저야말로요.$w4\n"
.stringn "그리고$MC…$MD$w2 마카로프님.$w4\n"
.stringn "이걸 떨어뜨리셨더라고요.$K\n"
.stringn "$F3$P$FA어라, $w2어느새$MC…$MD$K\n"
.stringn "$F1$P예쁜 꽃이네요.$K\n"
.stringn "$F3$P$FS그치? $w3근처에 피어 있었던 것 치곤$w2\n"
.stringn "괜찮지 않아?$K\n"
.stringn "$F1$P어머, $w2직접 따신 건가요?$w4\n"
.stringn "마카로프님은 $w2무척 우아한\n"
.stringn "취미를 가지고 계시군요.$K\n"
.stringn "$F3$P$FA아니, $w2그게.$w4$FS\n"
.stringn "여동생 기분 풀어 주려고 $w3조금 따 왔어.$K\n"
.stringn "$F1$P자상한 오라버니시네요.$w4\n"
.stringn "아차, $w3꽃이 시들기 전에$w2\n"
.stringn "여동생분께 가져다 드려야죠.$K$P여기요.$K\n"
.stringn "$F3$P아, $w3한 송이 정도는 가져도 돼.$K\n"
.stringn "$F1$P$FA$MC…$MD네?$K\n"
.stringn "$F3$P주워 준 보답이야.$K$P너랑 잘 어울리는 것 같고.$w4\n"
.stringn "그럼 이만 $w2실례할게~$K$F3$FD\n"
.stringn "$F1$P가, $w2감사합니다$MC!$MD$w4$FS\n"
.stringn "$MC…………$MD마카로프님.$K"
db 0
.align 4
//MYELL_MAKAROV_STELLA_C_a

