//0x38C68
Text_38C48:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_MAKAROV|$F3$FS$F3$FCL_ULYSSES|$F3$P왜 그러나, $w2마카로프?$K\n"
.stringn "$F1$P$MC………$MD$K\n"
.stringn "$F3$P자네의 열정과 끈기에 지친 내가$w2\n"
.stringn "이렇게 함께 와 $w2즐기고\n"
.stringn "도박장을 뒤로한 지금$MC…$MD$K$P무엇이 자네의 얼굴을\n"
.stringn "찌푸리게 만드는 거지?$K\n"
.stringn "$F1$P율리시스$MC…$MD$w4\n"
.stringn "당신 $w2나한테 거짓말했지?$K\n"
.stringn "$F3$P글쎄?$w4\n"
.stringn "내가 자네에게 거짓말을 할 이유가\n"
.stringn "있을 리 없지 않나.$K\n"
.stringn "$F1$P도박장 가 본 적\n"
.stringn "없다고 했잖아.$K$P근데 $w2당신 엄청\n"
.stringn "익숙해 보였고$MC…$MD$w4 게다가 잘하던데.$K$P나는 망했는데,$w2\n"
.stringn "당신은 대박났잖아.$w4\n"
.stringn "얼굴이 안 썩는 게 더 이상하다고.$K\n"
.stringn "$F3$P거짓말은 하지 않았네.$K$P도박장에 발을 들여놓는 건\n"
.stringn "내 생애에 있어\n"
.stringn "이번이 처음이었으니.$K$P단지$MC…$MD$w4 귀족들의 유희에도\n"
.stringn "비슷한 도박이 있는데,$K$P나는 그것에 정통하다네.$w4\n"
.stringn "그것뿐이야.$K\n"
.stringn "$F1$P젠장,$w4 부자가\n"
.stringn "돈을 더 잘 벌다니\n"
.stringn "세상은 $w2잘못되어 있어엇$MC!$MD$K\n"
.stringn "$F3$P내게 있어$MC…$MD$w4 손에 넣은\n"
.stringn "골드는 큰 의미가 없네.$K$P자네가 이번 판은 운에 달렸다고\n"
.stringn "내게 말했었지.$K$P하지만 $w2승부에서 압승했다.$w4\n"
.stringn "훌륭한 결과를 얻을 수 있었으니\n"
.stringn "나는 지극히 만족하고 있네.$K\n"
.stringn "$F1$P그럼, $w2돈은 필요 없는 거야?$w4\n"
.stringn "그렇다면 내가 받아가도$MC…$MD$K\n"
.stringn "$F3$P그렇게는 안 되지.$w4\n"
.stringn "전쟁에는 일단 돈이 드는 법.$w4\n"
.stringn "저축은 많을수록 좋으니까.$K\n"
.stringn "$F1$P$MC…$MD걱정하지 않아도$w2\n"
.stringn "이번 전쟁은 크리미아의 승리일걸.$K\n"
.stringn "$F3$P호오?$w4 어째서 그리 생각하는지\n"
.stringn "들려줄 수 있겠나?$K\n"
.stringn "$F1$P당신같이 운이 좋은 남자가\n"
.stringn "곁에 있잖아.$w4\n"
.stringn "두 번이나 질 리가 없지.$K\n"
.stringn "$F3$P과연.$w4\n"
.stringn "자네에게는 선견지명이 있는 것 같군.$K\n"
.stringn "$F1$P$FS그러니까, $w2돈은 나한테$MC…$MD$K\n"
.stringn "$F3$P크리미아가 이 전쟁에서 승리한다면\n"
.stringn "내가 얼마든지\n"
.stringn "자네 지갑을 돈으로 축여 주겠네.$K\n"
.stringn "$F1$P$FA저, $w2정말이야$MC!?$MD$K\n"
.stringn "$F3$P나는 할 수도 없는 약속은 하지 않는다네.$w4\n"
.stringn "거짓말도 할 필요가 없지.$K$P돈을 벌 수단은\n"
.stringn "얼마든지 갖고 있으니.$K$F3$FD\n"
.stringn "$F1$P$FS조, $w2좋~아$MC!$MD$w4\n"
.stringn "일생일대의 큰 도박이라 생각하고\n"
.stringn "힘내 봐야지.$K"
db 0
.align 4
//MYELL_MAKAROV_ULYSSES_A

//0x386D8
Text_386B8:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_MAKAROV|$F3$FS$F3$FCL_ULYSSES|$F1$P저기, $w2율리시스 공.$w4\n"
.stringn "나하고 당신은 $w2이미 친구 맞지?$K\n"
.stringn "$F3$P물론이다.$w4\n"
.stringn "몇 번이나 술잔을 기울이며$MC…$MD$w3\n"
.stringn "서로의 가문 내력도 이야기했지.$K$P나와 자네가 우호를 쌓는 것에$w3\n"
.stringn "더 이상 아무런 장애도 없네.$K\n"
.stringn "$F1$P그럼 $w3지금부터 같이\n"
.stringn "재미있는 놀이를 하러 가자고.$K$P율리시스는 모를 만한$w2\n"
.stringn "서민들의 놀이인데 말이지.$w4\n"
.stringn "이게 해 보면 푹 빠진다니까.$K\n"
.stringn "$F3$P오호. $w4서민의 유희라$MC…$MD$w4\n"
.stringn "그래서, $w2그건\n"
.stringn "어떠한 것이지?$K\n"
.stringn "$F1$P단순해.$w4\n"
.stringn "돈을 걸고, $w2뒤집혀 있는 나무패에\n"
.stringn "그려져 있는 무늬를 맞추는 거야.$K$P정답이라면 배당금을 받고,$w3\n"
.stringn "빗나가면 돈을 잃지. $w4그것뿐이야.$K\n"
.stringn "$F3$P과연,$w4\n"
.stringn "마카로프는 $w2나를\n"
.stringn "도박장으로 이끌려고 하는 건가.$K\n"
.stringn "$F1$P$FA어어$w4 자, $w2잠깐$MC…$MD$w4\n"
.stringn "당신 설마\n"
.stringn "도박장에 가 본 적 있어?$K\n"
.stringn "$F3$P아니, $w2지식으로만 알고 있을 뿐\n"
.stringn "실제로 발을 들인 적은\n"
.stringn "없다네.$K$P흠, $w2흥미가 없지는 않지.$K\n"
.stringn "$F1$P$FS그럼 $w2내가 안내할 테니까\n"
.stringn "가 보자구.$K$P당신 정도의 부자라면\n"
.stringn "실컷 놀아도 거스름돈이 남으니까\n"
.stringn "처음이라고 걱정할 필요도 없고.$K\n"
.stringn "$F3$P$MC…$MD아니, $w2사양하도록 하겠네.$K\n"
.stringn "$F1$P$FA뭐어$MC!?$MD$w4 왜?$K\n"
.stringn "$F3$P조국이 위험에 $w2처했는데\n"
.stringn "도박장에서 게으름을 피울 순 없지.$w4\n"
.stringn "그럼, $w2슬슬 실례하겠네.$K$P자네도 너무 흥겨운 나머지\n"
.stringn "도를 넘지 않도록 주의하게나.$K$F3$FD\n"
.stringn "$F1$P아아$MC!$MD$w4 $MC…$MD가 버렸다.$w4\n"
.stringn "내 지갑$MC……$MD$K"
db 0
.align 4
//MYELL_MAKAROV_ULYSSES_B

//0x37DDC
Text_37DBC:
.stringn "$R背景会話|$B支援背景|$<$F5$FCL_ULYSSES|$F3$FS$F3$FCL_MAKAROV|$F3$P흐음~$w4 이 군은$w2\n"
.stringn "광대를 부를 정도의 여유가\n"
.stringn "있었구나.$K$P그 데인을 상대로 싸우고 있으니$w4\n"
.stringn "좀 더 살벌할 줄 알았는데.$K\n"
.stringn "$F5$P$MC…$MD흠.$K\n"
.stringn "$F5$FD$F1$FS$F1$FCL_ULYSSES|$F1$P지금의 언동은 $w2혹시 나를 향해\n"
.stringn "말한 것인가?$w4\n"
.stringn "베그니온의 용병 기사 $w2마카로프 공.$K\n"
.stringn "$F3$P$FA우왓$MC!?$MD$K$P어, $w2어떻게 광대가\n"
.stringn "내 이름을$MC…$MD$w2 아니$w3$FS\n"
.stringn "그렇구만.$K$P너, $w2그런 묘기를 부리는구나?$w4\n"
.stringn "알아맞히는 게 특기인 거지?$w4\n"
.stringn "그렇다면 $w2꽤 솜씨가 좋은걸.$K$P지금 건 $w2정답이었거든.$K\n"
.stringn "$F1$P$FA나를 광대라 평하는 건가?$w4\n"
.stringn "그럴 수 있네.$K$P한때의 모습이긴 하나, $w2일시적으로\n"
.stringn "그것을 생업으로 삼고 있었으니.$K$P아아, $w3그 시절을 떠올리니\n"
.stringn "앞으로 $w2닥칠 고난도 아무렇지 않구나.$K$P조국 해방의 여명까지,$w3\n"
.stringn "내가 $w2이 몸을\n"
.stringn "어떻게 변화시켰는지$MC…$MD$K\n"
.stringn "$F3$P하하,$w4 당신\n"
.stringn "재미있는 사람이구만.$K$P오늘 밤에 $w2내 천막으로\n"
.stringn "술이라도 마시러 오지 않을래?$K\n"
.stringn "$F1$P$FS매력적인 제안이지만,$w2\n"
.stringn "오늘 밤은 선약이 있다네.$K$P다음 기회 때 $w2이쪽에서\n"
.stringn "권유하려고 생각하는데$w4\n"
.stringn "그걸로 어떻겠나?$K\n"
.stringn "$F3$P그게 좋다면$w2\n"
.stringn "나는 상관없어.$K\n"
.stringn "$F1$P의견이 일치한 것 같군.$w4\n"
.stringn "그럼 $w2실례.$K$F1$FD\n"
.stringn "$F3$P하~$w4 지금까지\n"
.stringn "본 적 없는 느낌의 남자인걸.$w4\n"
.stringn "다음에 만나는 게 기대되는구만.$K\n"
.stringn "$F8$FCDUMMY|$F8$P이봐$MC!$MD$w4 거기 너$MC!!$MD$K\n"
.stringn "$F3$P응~?$w4\n"
.stringn "$F3$FD$F1$FCL_MAKAROV|$F4$FCL_CRIMEA1|$F1$P나한테 볼일이라도 있어?$w2\n"
.stringn "크리미아 병사님.$K\n"
.stringn "$F4$P김빠지게 대답하지 마라$MC!$MD$w4\n"
.stringn "너도 $w2지금은 크리미아군에\n"
.stringn "소속되어 있지 않나$MC!?$MD$K\n"
.stringn "$F1$P아, $w2그렇구나.$w4\n"
.stringn "아이크씨가 크리미아군의\n"
.stringn "총대장이 되었으니까,$K$P나도 자동으로 크리미아병이 된 거구만.$w4\n"
.stringn "하하,$w4 이제부터 당신이랑 동료네.$K\n"
.stringn "$F4$P웃기는 남자로군$MC…$MD$K$P아이크 장군님 직속\n"
.stringn "용병단의 일원이니$w3\n"
.stringn "이번엔 봐주겠다만$MC……$MD$K$P한 가지 충고해 주지.$w4\n"
.stringn "네놈이 $w2방금까지 이야기를 나눈 상대는\n"
.stringn "페일 백작님이시다$MC!$MD$K\n"
.stringn "$F1$P$FA뭐?$K\n"
.stringn "$F4$P페일 백작 $w2율리시스님은,$K$P돌아가신 왕제 전하의 필두 문관으로\n"
.stringn "근무했을 정도로$w2\n"
.stringn "크리미아 왕궁의 중진이시다.$K$P네놈 따위가 $w2함부로\n"
.stringn "입을 놀릴 상대가 아니야.$K$P알았다면 $w3앞으로는$w2\n"
.stringn "태도를 고치도록.$w4\n"
.stringn "알겠나$MC!?$MD$K$F4$FD\n"
.stringn "$F1$P그 광대가$MC…$MD$w4\n"
.stringn "크리미아의 귀족이라고?$K$P$MC………$MD그렇다면,$w2$FS\n"
.stringn "좋은 돈줄이 될지도 모르겠는걸.$w4\n"
.stringn "친해져서 손해 볼 건 없지.$K"
db 0
.align 4
//MYELL_MAKAROV_ULYSSES_C

//0x39F6C
Text_39F4C:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_TANIS|$F3$FCL_MARCIA|$F3$P그러니까 그$MC……$MD$w4\n"
.stringn "벌한다고 하셨던 건\n"
.stringn "봐주셨으면 좋겠어요$MC……$MD$K\n"
.stringn "$F1$P탈영엔 가장 무거운 벌을 내리는 게 철칙이다.$w4\n"
.stringn "네게만 특례를 $w2줄 수는 없어.$K\n"
.stringn "$F3$P$Fh하아$MC……$MD$w4\n"
.stringn "부대장님은 나빠요$MC……$MD$K\n"
.stringn "$F1$P왜 내가 나쁜 것이냐$MC!$MD$w4\n"
.stringn "나는 네가 탈영했으니까$MC……$MD$K\n"
.stringn "$F3$P$Fd그야, $w2부대장님은\n"
.stringn "항상 그렇잖아요.$K$P시그룬 대장님과는 다르게,$w2\n"
.stringn "우리에 대해 칭찬해 주신 적은\n"
.stringn "한 번도 없었고$MC……$MD$K$P이쪽 사정은 봐 주고\n"
.stringn "계신 것 같지도 않고$MC……$MD$K\n"
.stringn "$F1$P정말이지, $w2답답한 녀석이군.$w4\n"
.stringn "왜 내가 너에게\n"
.stringn "이렇게까지 말하고 있다고 생각하나$MC!$MD$K\n"
.stringn "$F3$P네?$K\n"
.stringn "$F1$P다른 단원이었다면 이렇게까지 안 한다.$w4\n"
.stringn "마샤, $w2난\n"
.stringn "네게 기대하고 있었다.$K$P너라면 장래에 대장님이나 내 뒤를 이어$w2\n"
.stringn "기사단을 맡아 줄 거라고 생각했는데.$K\n"
.stringn "$F3$P네에$MC!?$MD$K\n"
.stringn "왜, $w2왜 갑자기\n"
.stringn "그런 말씀을 하시는 거예요?$K$P베그니온에 있었을 때$w2\n"
.stringn "그런 말은 한 마디도$MC……$MD$K\n"
.stringn "$F1$P당연하지$MC!$MD$w4\n"
.stringn "내 입으로 그런 말을 할 수 있을 것 같나.$w4\n"
.stringn "하지만 어쩔 수 없지.$K$P내가 대장님께 진언해서,$w2\n"
.stringn "기사단에 복귀할 수 있도록 해 주마.$w4\n"
.stringn "탈영은 불문에 부치겠다. $w4그러니 돌아와라.$K\n"
.stringn "$F3$P부대장님$MC……$MD$K$P$FS가$MC……$MD$w3감사합니다$MC!$MD$K"
db 0
.align 4
//MYELL_MARCIA_TANIS_A

//0x39A24
Text_39A04:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_TANIS|$F1$P마샤$MC!$MD$K\n"
.stringn "$F3$FCL_MARCIA|$F3$P히익$MC!?$MD$w4\n"
.stringn "부, $w2부대장님$MC……$MD$MC!$MD$K\n"
.stringn "$F1$P이전의 상관을 상대로$w4\n"
.stringn "한심한 비명을 지르지 마라.$K\n"
.stringn "$F3$P그, $w2그치만 부대장님$MC……$MD$w4\n"
.stringn "아직도 화나셨잖아요?$K\n"
.stringn "$F1$P물론이다.$w4\n"
.stringn "마샤, $w2네가 기사단을\n"
.stringn "떠난 이유는 뭐지?$K$P너는 임무의 엄격함을 견디지 못해$w2\n"
.stringn "도망갈 정도로 연약한 자는 아니다.$K$P이성과의 연애 때문에$w2\n"
.stringn "문제를 일으킬 만한 여자도 아니지.$K$P왜 나에게 한 마디 상의도 없이 $w2떠났나?$K\n"
.stringn "$F3$P사실은 그~$MC……$MD$K\n"
.stringn "오빠가 $w2빚을 많이 져서$MC……$MD$w4\n"
.stringn "행방불명이 된 상태였거든요.$K\n"
.stringn "$F1$P빚$MC……?$MD$K\n"
.stringn "$F3$P그래서 $w2대신 제가 있던\n"
.stringn "병영에 빚쟁이가 찾아오게 돼서\n"
.stringn "오빠의 행방을 찾으려고 했어요.$K$P그러다가 아이크씨 일행과 만나서,$w2\n"
.stringn "해적으로부터 도움을 받은 것을 계기로\n"
.stringn "함께하게 되었습니다.$K$P그치만 오빠는 역시 찾지 못했기에$MC……$MD$K\n"
.stringn "$F1$P$MC……$MD$K\n"
.stringn "$F3$P그래서, $w2아이크씨를 따라가서\n"
.stringn "여기저기 여행하다 보면$w2\n"
.stringn "오빠의 행방을 알 수 있을까 싶다가$K$P지금에 이르렀습니다.$MC……$MD$K\n"
.stringn "$F1$P$MC……$MD과연. $w4사정은 알았다.$K$P설마 빚을 지고서 야반도주라니$MC……$MD$w4\n"
.stringn "과거의 상관으로서,$w2\n"
.stringn "다소라도 동정을 금할 길이 없군.$K\n"
.stringn "$F3$P$FS그, $w2그럼$MC……$MD$K\n"
.stringn "$F1$P하지만 탈영은 탈영이다.$w4\n"
.stringn "여기서의 임무가 끝나면, $w2너를\n"
.stringn "벌할 수밖에 없어.$K\n"
.stringn "$F3$P$FA그, $w2그럴 수가아$MC……$MD$K"
db 0
.align 4
//MYELL_MARCIA_TANIS_B

//0x393C8
Text_393A8:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_TANIS|$F3$FCL_MARCIA|$F3$P어$MC……$MD$w2어라?$K\n"
.stringn "$F1$P$MC……$MD오랜만이군, $w2마샤.$K\n"
.stringn "$F3$P타, $w2타니스 부대장님$MC!?$MD$w4\n"
.stringn "어$MC……$MD$w4어째서 여기에?$K\n"
.stringn "$F1$P그건 내가 할 말이다.$w4\n"
.stringn "나는 친위 기사단 부대장으로서\n"
.stringn "칙명을 받아 이 임무를 맡고 있지.$K$P설마 이곳에서\n"
.stringn "과거의 부하와 만날 줄이야.$K\n"
.stringn "$F3$P$FS그, $w2그랬군요$MC!$MD$w4\n"
.stringn "데인에 온 이후로 부대장님이 함께 계셨다니\n"
.stringn "전혀 눈치채지 못했어요$MC!$MD$K$P엄청난 우연이네요, $w2네$MC!$MD$K\n"
.stringn "$F1$P$FS그래. $w4귀여운 부하와\n"
.stringn "드디어 만나게 되어서 기쁘군.$K$P나는 오랫동안$w2\n"
.stringn "네 행방을 쫓고 있었으니 말이지$MC……$MD$K\n"
.stringn "$F3$P$FA부, $w2부대장님,$w2\n"
.stringn "눈이 안 웃고 있는$MC……$MD$w2데요$MC……$MD$K$P$FS혹시$MC……$MD$w3 화나셨나요?$K\n"
.stringn "$F1$P그래, $w2네 말대로다.$w4\n"
.stringn "나는 매우 화가 많이 났지.$K$P무단으로 베그니온 천마 기사단을 떠난\n"
.stringn "탈영병 마샤에게 어떤 벌을$w2\n"
.stringn "내릴까 생각 중이다.$K\n"
.stringn "$F3$P$FA타, $w2탈영이라니요$MC!$MD$w4\n"
.stringn "제대로 『그만두겠습니다』$w2라고\n"
.stringn "편지에 써서 남기$MC……$MD$K\n"
.stringn "$F1$P$FA네가 어린애냐$MC!$MD$w4\n"
.stringn "그런 휘갈겨 쓴 편지 한 장으로\n"
.stringn "제대가 허용될 줄 안 거냐$MC!$MD$K$P베그니온 기사단원의 무게를 알아라$MC!$MD$K\n"
.stringn "$F3$P죄, $w2죄$MC……$MD$w4죄송합니다$MC!$MD$w4\n"
.stringn "그렇지만 $w2그때는 급했단 말이에요$MC……$MD$K\n"
.stringn "$F1$P$Fc$MC……$MD시그룬 대장님은 상냥하신 분이지.$w4\n"
.stringn "네가 부대를 떠난 건에 대해서는\n"
.stringn "불문에 부치라고 하셨다.$K\n"
.stringn "$F3$P$FS헉$MC……$MD$K\n"
.stringn "$F1$P$Fd하지만 내가 반대했다.$K$P어떻게든 데려와$w2\n"
.stringn "마땅한 벌을 받게 할 거라고 보고해 뒀지.$w4\n"
.stringn "각오해라.$K\n"
.stringn "$F3$P아$MC!$MD$w4 저, $w2갑자기 급한 일이 생각났어요$MC!$MD$w4\n"
.stringn "$MC……$MD실례하겠습니다$MC!$MD$K\n"
.stringn "$F3$FD$F1$P이봐,$w2\n"
.stringn "또 도망가는 거냐 마샤$MC!$MD$K"
db 0
.align 4
//MYELL_MARCIA_TANIS_C

//0x3A458
Text_3A438:
.stringn ""
db 0
.align 4
//MYELL_MARCIA_WAYU_A

//0x3A454
Text_3A434:
