//MYELL_MARCIA_WAYU_C

//0x3AC24
Text_3AC04:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_MORDY|$F3$FS$F3$FCL_MIST|$F3$P어라, $w2모우디씨.$w4\n"
.stringn "무슨 일 있었어?$K\n"
.stringn "$F1$P미스트.$w4\n"
.stringn "아이크는 어딨나?$K\n"
.stringn "$F3$P아, $w2오빠라면\n"
.stringn "티아마트씨네랑 같이 있을걸?$w4\n"
.stringn "근데 곧 있으면 여기도 올 거야.$K\n"
.stringn "$F1$P$FS알았다.$w4\n"
.stringn "$MC……$MD미스트는 아이크랑 사이좋나?$K\n"
.stringn "$F3$P글쎄, $w2잘 모르겠네.$w4\n"
.stringn "그냥 평범하다고 생각해.$K\n"
.stringn "$F1$P아이크는 좋은 베오크다.$w4\n"
.stringn "만난 지 얼마 안 된 모우디에게$w2\n"
.stringn "바로 마음을 열어줬다.$K$P베오크인데도,$w2\n"
.stringn "마치 수아족 동포 같다.$w4\n"
.stringn "아이크는 대단하다고 생각한다.$K\n"
.stringn "$F3$P아하하,$w4 그런가?$w4\n"
.stringn "오빠는 좀 이상하니까.$K\n"
.stringn "$F1$P그런가?$w4 그래도 모우디는\n"
.stringn "아이크가 좋다.$K$P$FA$MC……$MD미스트.$w4\n"
.stringn "지금이니까 모우디는 미스트에게 말한다.$w4\n"
.stringn "비웃지 마라.$K\n"
.stringn "$F3$P$FA응?$w4 뭔데?$K\n"
.stringn "$F1$P처음에 $w2미스트에게 빨래를 주워 줬을 때,$w2\n"
.stringn "사실은 $w2모우디도 무서웠다.$K\n"
.stringn "$F3$P무서웠다고$MC……?$MD$w4\n"
.stringn "모우디씨가?$K\n"
.stringn "$F1$P그렇다. $w4미스트에게 거절당할까 봐 무서웠다.$w4\n"
.stringn "미스트가 두려워서 기절할까 봐 무서웠다.$w4\n"
.stringn "두근두근해서, $w2엄청 긴장하고 있었다.$K\n"
.stringn "$F3$P뭐야$MC……$MD$w4 그런 거였구나.$w4\n"
.stringn "$FS후후,$w2 뭔가 이상하다.$K$P똑같네, $w2나랑.$K\n"
.stringn "$F1$P$FS그래, $w2똑같다.$K"
db 0
.align 4
//MYELL_MIST_MORDY_A

//0x3A7EC
Text_3A7CC:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_MORDY|$F3$FS$F3$FCL_MIST|$F3$P모우디씨$MC!$MD$w4 안녕$MC!$MD$K\n"
.stringn "$F1$P미스트, $w2기분이 좋아 보인다.$K\n"
.stringn "$F3$P응, $w2나\n"
.stringn "기운이 넘쳐나$MC!$MD$K\n"
.stringn "$F1$P잘됐다.$K\n"
.stringn "$F3$P저기, $w2나,$w2\n"
.stringn "나, $w2성격은 밝은 편이라고 생각해$MC!$MD$K$P취미는 빨래, 청소,$w2\n"
.stringn "바느질은 잘 못 하는데, $w2그리고$MC…$MD$K\n"
.stringn "$F1$P그래.$K\n"
.stringn "$F3$P그리고 그리고$MC……$MD$w4\n"
.stringn "또 뭐가 있었지?$K$P어, $w2그게,$w2\n"
.stringn "그게$MC…………$MD$K\n"
.stringn "$F1$P미스트.$w4\n"
.stringn "천천히 말해도, $w2된다.$K\n"
.stringn "$F3$P$FA어$MC……?$MD$K\n"
.stringn "$F1$P미스트는 라구즈와 얘기해 본 경험이 적다.$w4\n"
.stringn "그러니까, $w2무섭다는 거 안다.$K$P그치만 마음은 이미, $w2전달됐다.$w4\n"
.stringn "미스트는 진심으로, $w2우리들과\n"
.stringn "친하게 지내려고 $w2노력하고 있다$MC……$MD$K$P잘 알고 있다.$K\n"
.stringn "$F3$P$MC…………$MD$K\n"
.stringn "$F1$P그러니까, $w2무리하지 않아도 된다.$w4\n"
.stringn "서로,$w2\n"
.stringn "조금씩 익숙해지면 된다.$K$P모우디도, $w2미스트와 같은\n"
.stringn "마음이다.$K\n"
.stringn "$F3$P모우디씨$MC……$MD$K$P$FS응$MC……$MD$w4 고마워.$w4\n"
.stringn "왠지 $w2엄청 편해졌어.$K$P그래, $w2무리하지 말고\n"
.stringn "자연스럽게 하는 게 가장 중요하니까.$K\n"
.stringn "$F1$P그래.$K"
db 0
.align 4
//MYELL_MIST_MORDY_B

//0x3A45C
Text_3A43C:
.stringn "$R背景会話|$B支援背景|$<$F8$FCL_MIST|$F8$P기다려~$w2\n"
.stringn "기다리$w3라니까~$MC!$MD$K$F8$FD\n"
.stringn "$F3$FCL_MIST|$F3$P어라?$w4 어라라?$w4\n"
.stringn "어디로 간 거지$MC……$MD$w4\n"
.stringn "분명 이쪽에$MC……$MD$K\n"
.stringn "$F1$FCL_MORDY|$F1$P이건가?$K\n"
.stringn "$F3$P우왓$MC!$MD$w4\n"
.stringn "모, $w2모우디씨$MC……$MD$w4\n"
.stringn "깜짝 놀랐네.$K\n"
.stringn "$F1$P$FS미안하다. $w4놀라게 했다.$K\n"
.stringn "거기서 주웠다.$w4\n"
.stringn "이게 미스트가 찾던 건가?$K\n"
.stringn "$F3$P아$MC……$MD$w4 으, $w2응,$w2\n"
.stringn "빨래를 걷다가\n"
.stringn "날아가 버려서$MC……$MD$K$P$FS고마워, $w2모우디씨.$K\n"
.stringn "$F1$P별거 아니다.$K\n"
.stringn "$F3$P$FA저$MC……$MD$w2저기, $w2모우디씨.$K\n"
.stringn "$F1$P$FA뭐냐?$K\n"
.stringn "$F3$P음$MC……$MD$w4 그$MC……$MD$w4 저기.$K\n"
.stringn "$MC……$MD$w2미안, $w2아무것도 아니야.$K\n"
.stringn "$F1$P$FS알았다.$w4\n"
.stringn "그럼, $w2모우디는 이만 가 본다.$K\n"
.stringn "$F1$FD$P$w4$F3$P$Fc하아$MC……$MD$w4\n"
.stringn "나는 정말 $w2바보야$MC……$MD$K$P$Fd왜 오빠처럼$w2\n"
.stringn "평범하게 못 대하는 걸까$MC……$MD$w4\n"
.stringn "좀 더 $w2힘내야겠어.$K"
db 0
.align 4
//MYELL_MIST_MORDY_C

//0x3BE04
Text_3BDE4:
.stringn "$R背景会話|$B支援背景|$<$F3$FS$F3$FCL_MIST|$F1$FS$F1$FCL_TIAMAT|$F1$P미스트, $w2잠깐 이쪽으로 와봐.$K\n"
.stringn "$F3$P뭔데?$K\n"
.stringn "$F1$P자, $w2내가 주는 선물.$K\n"
.stringn "$F3$P이건 $w2전에 봤던 옷이잖아$MC!$MD$K\n"
.stringn "내가 가장 마음에 들어했던$MC……$MD$MC!$MD$K\n"
.stringn "$F1$P역시.$w4\n"
.stringn "같이 간 보람이 있었네.$K\n"
.stringn "$F3$P고마워, $w2티아마트씨.$K\n"
.stringn "$F1$P후후후$MC……$MD$w4\n"
.stringn "미스트가 기뻐하는 얼굴을\n"
.stringn "볼 수 있어서 다행이야.$K$P$FA솔직히 말하자면$w2\n"
.stringn "조금 미스트가 걱정됐어.$K$P갑자기 전장에 나가게 돼서\n"
.stringn "그 무거운 부담감에\n"
.stringn "언젠가 짓눌리는 게 아닐까 하고.$K$P$FS그래서 $w2내가 할 수 있는 일은\n"
.stringn "뭐든지 해 주고 싶었어.$K\n"
.stringn "$F3$P$FA티아마트씨$MC……$MD$K\n"
.stringn "$F1$P있지, $w2미스트.$K$P앞으로 혹시 뭔가 괴로운 일이 있는데,$w2\n"
.stringn "만약 아이크에게 말하기 어려운 거라면$MC…$MD$w4\n"
.stringn "나를 의지해 줘.$K$P에르나처럼은\n"
.stringn "될 수 없을지도 모르지만,$w2\n"
.stringn "널 생각하는 마음은 변함없으니까.$K\n"
.stringn "$F3$P$FS응$MC……$MD$w4 응$MC……$MD$w4 고마워$MC……$MD$K\n"
.stringn "나$MC……$MD$w4 엄청 기뻐\n"
.stringn "티아마트씨.$K$P에헤헤$MC…$MD$w4 왠지 벌써 이 옷,$w2\n"
.stringn "아까워서 못 입을 것 같아$MC……$MD$K"
db 0
.align 4
//MYELL_MIST_TIAMAT_A

//0x3BAFC
Text_3BADC:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_MIST|$F1$FCL_TIAMAT|$F3$P아, $w2지난번에 미안했어,$w2\n"
.stringn "티아마트씨.$K$P모처럼 같이 옷을 사러\n"
.stringn "가 줬는데$MC……$MD$K\n"
.stringn "$F1$P$FS그런 건 $w2괜찮아.$K\n"
.stringn "그래도 모처럼 간 거니까 과감히\n"
.stringn "샀으면 좋았을 텐데.$K\n"
.stringn "$F3$P응, $w2하지만 막상 때가 되면\n"
.stringn "이것저것 고민을 하게 돼서$MC……$MD$K\n"
.stringn "$F1$P미스트는 식료품을 사 둔다든가,$w2\n"
.stringn "모두를 위해 물건을 사는 건 잘하는데 말이야.$K$P그런 점은$w2\n"
.stringn "점점 에르나를 닮아가네.$K\n"
.stringn "$F3$P$FS엄마를?$K\n"
.stringn "$F1$P그래.$K\n"
.stringn "너는 성실한 것도\n"
.stringn "에르나를 닮았어.$K$P그래도 미스트, $w2너는 좀 더\n"
.stringn "누군가에게 응석을 부려도 괜찮다고 생각해.$K$P곁에 있는 게 나라서\n"
.stringn "미덥지 않을지도 모르겠지만$MC……$MD$K\n"
.stringn "$F3$P그렇지 않아.$K\n"
.stringn "난 $w2티아마트씨를\n"
.stringn "언니라고 생각하고 있는걸.$K\n"
.stringn "$F1$P고마워, $w2미스트.$K"
db 0
.align 4
//MYELL_MIST_TIAMAT_B

//0x3B0A4
Text_3B084:
.stringn ""
db 0
.align 4
//MYELL_MIST_TIAMAT_C

//0x3B0A8
Text_3B088:
.stringn "$R背景会話|$B支援背景|$<$F3$FS$F3$FCL_MIST|$F1$FS$F1$FCL_TIAMAT|$F1$P어머 미스트, $w2빨래하니?$w4\n"
.stringn "나도 도와줄게.$K\n"
.stringn "$F3$P응?$w4 괜찮아$MC!$MD$w4\n"
.stringn "티아마트씨는\n"
.stringn "전투로 지쳤을 테니까.$K\n"
.stringn "$F1$P그건 너도 마찬가지잖니?$w4\n"
.stringn "괜찮으니까 $w2도와줄게.$K$P그건 그렇고 $w2굉장한 양인걸.$K\n"
.stringn "$F3$P응. $w4겸사겸사\n"
.stringn "다른 사람들 몫도 $w2맡고 있어.$K$P항상 오빠를\n"
.stringn "도와주는 답례로.$K\n"
.stringn "$F1$P후후,$w2 친절한 것도 좋지만$w2\n"
.stringn "피곤하지 않은 범위 내에서 해야지.$w4\n"
.stringn "$MC…$MD어머, $w2이거 $w2찢어졌네.$K\n"
.stringn "$F3$P아, $w2오빠 거다.$w4\n"
.stringn "$MC……$MD계속 싸워서 그런지$w2\n"
.stringn "꽤 낡아졌나 보네.$K$P다음에 $w2마을에서 새 걸로 사야겠다.$w4\n"
.stringn "단장이 너덜너덜한 옷을 입고 있으면\n"
.stringn "멋이 안 사니까.$K\n"
.stringn "$F1$P그러는 미스트도$MC…$MD$w4\n"
.stringn "여기, $w2잠깐 봐봐.$K$P네 옷도\n"
.stringn "소매 쪽이 $w2찢어졌어.$K\n"
.stringn "$F3$P아.$w4\n"
.stringn "진짜네.$K\n"
.stringn "$F1$P정말, $w2어쩔 수 없다니까.$w4\n"
.stringn "그래, $w4다음에 같이 마을에 가지 않을래?$w4\n"
.stringn "새 옷들을 좀 사야겠어.$K\n"
.stringn "$F3$P$FA응? $w2그래도 $w2돼?$w4\n"
.stringn "할 일이 이렇게나 많은데.$K\n"
.stringn "$F1$P미스트도 그럴 나이니까$w2\n"
.stringn "그런 쪽에도 신경을 쓰라고\n"
.stringn "항상 말했잖니.$K\n"
.stringn "$F3$P응.$w4\n"
.stringn "내 나름대로 $w2신경을 쓰고 있다고\n"
.stringn "생각했는데$MC…$MD$K\n"
.stringn "$F1$P말만 해서는 안 돼.$w4\n"
.stringn "행동을 해야지.$w4\n"
.stringn "그럼 $w2다음에 $w2같이 가는 거다.$K\n"
.stringn "$F3$P$FS네~에.$K"
db 0
.align 4
//MYELL_MIST_TIAMAT_C_a

