.stringn "$R背景会話|$B支援背景|$<$F3$FS$F3$FCL_MIST|$F1$FS$F1$FCL_TIAMAT|$F1$P어머 미스트, $w2빨래하니?$w4\n"
.stringn "나도 도와줄게.$K\n"
.stringn "$F3$P응?$w4 괜찮아$MC!$MD$w4\n"
.stringn "티아마트씨는\n"
.stringn "전투로 지쳤을 테니까.$K\n"
.stringn "$F1$P그건 너도 마찬가지잖니?$w4\n"
.stringn "괜찮으니까 $w2도와줄게.$K$P그건 그렇고 $w2굉장한 양인걸.$K\n"
.stringn "$F3$P군 모두의 몫$MC…$MD$w4은 무리지만,$w2\n"
.stringn "용병단과 다른 몇몇 사람들 몫을\n"
.stringn "맡고 있어.$K$P항상 오빠를\n"
.stringn "도와주는 답례로.$K\n"
.stringn "$F1$P후후,$w2 친절한 것도 좋지만$w2\n"
.stringn "피곤하지 않은 범위 내에서 해야지.$w4\n"
.stringn "$MC…$MD어머, $w2이거 $w2찢어졌네.$K\n"
.stringn "$F3$P아, $w2오빠 거다.$w4\n"
.stringn "$MC……$MD계속 싸워서 그런지$w2\n"
.stringn "꽤 낡아졌나 보네.$K$P다음에 $w2마을에서 새 걸로 사야겠다.$w4\n"
.stringn "장군이 너덜너덜한 옷을 입고 있으면\n"
.stringn "멋이 안 사니까.$K\n"
.stringn "$F1$P그러는 미스트도$MC…$MD$w4\n"
.stringn "여기, $w2잠깐 봐봐.$K$P네 옷도\n"
.stringn "소매 쪽이 $w2흐트러졌어.$K\n"
.stringn "$F3$P아.$w4\n"
.stringn "진짜네.$K\n"
.stringn "$F1$P정말, $w2어쩔 수 없다니까.$w4\n"
.stringn "그래. $w4다음에 같이 마을에 가지 않을래?$w4\n"
.stringn "새 옷들을 좀 사야겠어.$K\n"
.stringn "$F3$P$FA응? $w2그래도 $w2돼?$w4\n"
.stringn "할 일이 이렇게나 많은데.$K\n"
.stringn "$F1$P미스트도 그럴 나이니까$w2\n"
.stringn "그런 쪽에도 신경을 쓰라고\n"
.stringn "항상 말했잖니.$K\n"
.stringn "$F3$P응.$w4\n"
.stringn "내 나름대로 $w2신경을 쓰고 있다고\n"
.stringn "생각했는데$MC…$MD$K\n"
.stringn "$F1$P말만 해서는 안 돼.$w4\n"
.stringn "행동을 해야지.$w4\n"
.stringn "그럼 $w2다음에 $w2같이 가는 거다.$K\n"
.stringn "$F3$P$FS네~에.$K"
