//0x3C780
Text_3C760:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_MORDY|$F3$FS$F3$FCL_SOANVALCKE|$F1$P$MC…$MD손.$K\n"
.stringn "$F3$P$MC……$MD답을 찾은 건가?$K\n"
.stringn "$F1$P$MC………$MD【인붙이】$MC…$MD$w4\n"
.stringn "베오크는$MC……$MD$w4\n"
.stringn "라구즈와의$MC…$MD$w4 혼혈 아이를 그렇게 부른다.$K$P손은, $w2라구즈의 피를\n"
.stringn "가지고 있는 건가?$K\n"
.stringn "$F3$P그래.$w4\n"
.stringn "$MC…$MD그 증거로 인이, $w2왼쪽 관자놀이에\n"
.stringn "나타나 있다.$K\n"
.stringn "$F1$P$MC…………$MD$K\n"
.stringn "$F3$P무리하지 않아도 된다.$w4\n"
.stringn "나랑 더는 얘기하고 싶지 않지?$K\n"
.stringn "$F1$P$MC…$MD모우디는$MC…$MD$w4 잘 모르겠다.$w4\n"
.stringn "갈리아의 전설에는$MC…$MD$w4\n"
.stringn "【무부모】가 불길하다고$MC…$MD$w4 나와 있다.$K$P【무부모】가 태어나면$MC……$MD$w4\n"
.stringn "대지의 파멸이 100년 가까워진다고$MC…$MD$K\n"
.stringn "$F3$P그래. $w4나는$MC…$MD$w4 라구즈들에게\n"
.stringn "【무부모】라고 불리는 자.$w4\n"
.stringn "결코 태어나는 게 가능할 리 없는 아이.$K$P그래서 【무부모】지$MC…$MD$w4 잘들 지껄이더군.$K$P라구즈는$MC…$MD$w4 그렇게$w2\n"
.stringn "우리들 혼혈의 인을 가진 자들을$MC……$MD$w4\n"
.stringn "처음부터 없었던 것처럼 취급하고 있다.$K$P베오크도 【인붙이】라며\n"
.stringn "우리를 박해하고 있지만$MC……$MD$w4\n"
.stringn "존재의 부정까지는 하지 않는다.$K$P그래서 $w2우리들은$MC…$MD$w4\n"
.stringn "베오크 이상으로 라구즈를 혐오하지.$K\n"
.stringn "$F1$P왜?$w4\n"
.stringn "왜, $w2【무부모】가 태어나나?$K$P다른 종족끼리는 $w2아이가 생길 리 없을 터다.$w4\n"
.stringn "그건, $w2이 세계를 창조한\n"
.stringn "여신 아스타르테의 결정이니까.$K\n"
.stringn "$F3$P내가 알기로는$MC…$MD$w4\n"
.stringn "야수·새·용$MC…$MD$w4 어느 종족이라도$w2\n"
.stringn "확실히 $w2그들 안에서만 자식을 가질 수 있다.$K$P하지만$MC…$MD$w4 베오크와 다른 종족 사이에서는\n"
.stringn "극히 드물게$MC……$MD$w4 아이가 태어나기도 하지.$K$P꺼림칙하게도 $w2혼혈의 인은$MC…$MD$w4\n"
.stringn "한 번이라도 연관된 혈족에게$MC……$MD$w4\n"
.stringn "은밀하게 내려져 오고 있다는 거다.$K$P여신의 결정을 어긴 것은, $w2나인가?$w4\n"
.stringn "아니지. $w4내 조상 중 누군가가 한 짓이다.$K$P양친도 조부모도\n"
.stringn "일족 모두가 베오크라고?$w4\n"
.stringn "아주 오래 전$MC…$MD$w4 누군가가 $w2라구즈의 피를 가져왔고,$K$P그 죄가$MC…$MD$w4 수많은 대를 지나며$w2\n"
.stringn "나에게도 나타났지. $w4나는 그저 태어난 것뿐인데.$w4\n"
.stringn "처음부터 『부정』의 낙인이 찍혀 있었다.$K\n"
.stringn "$F1$P$MC……$MD$K\n"
.stringn "$F3$P라구즈의 피는, $w2내게\n"
.stringn "특별한 힘을 주었다.$K$P이 힘을 써서$MC…$MD$w4 편안하게 살고 있는 놈들을\n"
.stringn "없애 버릴까 생각도 했지만$MC…$MD$w4 관뒀다.$K$P내게도 동료가 있었으니까.$w4\n"
.stringn "나처럼 혼혈의 인을 숨기기 위해$MC…$MD$w4\n"
.stringn "세상으로부터 쫓겨난 자들이$MC……$MD$K\n"
.stringn "$F1$P손은, $w2왜\n"
.stringn "모우디에게 다가온 건가?$K$P갈리아에 흥미가$MC…$MD$w4 있다고\n"
.stringn "한 건 어째서인가?$K\n"
.stringn "$F3$P갈리아의 수아족에게 흥미가 있었다.$w4\n"
.stringn "베그니온에 사는 녀석들이랑은\n"
.stringn "털색이 달라 보여서 말이지.$K$P내 동료들 사이에선$MC…$MD$w4\n"
.stringn "베오크와 손을 잡을 정도로\n"
.stringn "개방적인 나라라면,$K$P우리 같은 자들에 대해서도\n"
.stringn "관용적일 거라는 주장이 있었다.$K$P갈리아와 크리미아$MC…$MD$K$P그 중 한쪽이라면$w2\n"
.stringn "우리들을 받아 줄\n"
.stringn "장소가 되지 않을까 했었지$MC……$MD$K$P$MC……$MD물론, $w2그런\n"
.stringn "형편 좋은 일은 없었던 것 같군.$K\n"
.stringn "$F1$P손$MC…$MD$K\n"
.stringn "$F3$P자 그럼, $w2너와 어울리는 것도\n"
.stringn "여기까지인가.$K$P잠시 동안$MC…$MD$w4 이 싸움이 끝날 때까지는\n"
.stringn "네 눈앞을 서성거리게 되겠지만\n"
.stringn "그 정도는 참아 줘.$K\n"
.stringn "두 번 다시 말을 안 걸 테니$MC…$MD$K\n"
.stringn "$F1$P싫다$MC!$MD$w4\n"
.stringn "눈앞에 있는 손을\n"
.stringn "안 본 척할 수는 없다.$K\n"
.stringn "$F3$P$FA모우디$MC…$MD$w4\n"
.stringn "여신의 결정은 어쩔 거냐?$K$P베오크보다 자연에 가까운 라구즈는$MC…$MD$w4\n"
.stringn "그 이치를 중요하게 여기는 존재일 텐데?$K\n"
.stringn "$F1$P모우디는 여신을 만난 적이 없다.$w4\n"
.stringn "만약$MC…$MD$w4 만난다면 불평하겠다.$K$P손을 괴롭히지 말라고.$w4\n"
.stringn "모우디의 소중한 친구라고.$K\n"
.stringn "$F3$P$Fc$FS훗,$w4 여신에게 불평한다라$MC…$MD$w4\n"
.stringn "반대로 나는 $w2태어나서 처음으로\n"
.stringn "그녀에게 감사하고 싶군.$K\n"
.stringn "$F1$P왜?$K\n"
.stringn "$F3$P$Fd모우디를 만날 수 있었으니까.$w4\n"
.stringn "이런 운명이라면 나쁘지 않지.$K"
db 0
.align 4
//MYELL_MORDY_SOANVALCKE_A

//0x3C4E8
Text_3C4C8:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_SOANVALCKE|$F3$FCL_MORDY|$F3$P손$MC!!$MD$K\n"
.stringn "$F1$P뭐냐, $w2모우디.$w4\n"
.stringn "그렇게나 숨을 헐떡이면서.$K\n"
.stringn "$F3$P혐오는 『엄청 싫다』,$w2\n"
.stringn "무지는 『머리가 나쁘다』라고 들었다.$K$P왜, $w2손은\n"
.stringn "자기 나라를 싫어하나?$w4\n"
.stringn "모우디를 멍청이 취급하나?$K\n"
.stringn "$F1$P$MC…$MD조사한 건가.$w4\n"
.stringn "생각보다 머리는 잘 돌아가는 듯하군.$w4\n"
.stringn "그럼 “무지”하다는 건 철회하지.$K\n"
.stringn "$F3$P손$MC!$MD$w4\n"
.stringn "모우디의 질문에 대답해라.$K\n"
.stringn "$F1$P$MC……$MD모처럼이니\n"
.stringn "더 조사해 봐.$K$P나는 【인붙이】다.$w4\n"
.stringn "그래서 나라를 혐오하고,$w2\n"
.stringn "무지한 라구즈들을 증오하지.$K\n"
.stringn "$F3$P$MC…$MD라구즈를$MC…$MD$w4 증오해?$w4\n"
.stringn "『인부치』니까$MC…?$MD$w4\n"
.stringn "$MC……$MD손은$MC…$MD$w4 뭐 하는 사람이지?$K"
db 0
.align 4
//MYELL_MORDY_SOANVALCKE_B

//0x3C244
Text_3C224:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_SOANVALCKE|$F3$FS$F3$FCL_MORDY|$F3$P손$MC!$MD$w4\n"
.stringn "여기에 있었구나.$K\n"
.stringn "$F1$P$MC…$MD그래.$K\n"
.stringn "$F3$P갈리아 얘기는 $w2이제 됐나?$w4\n"
.stringn "모우디는 아직도\n"
.stringn "해 줄 이야기가 $w2많이 있다.$K\n"
.stringn "$F1$P$MC……$MD모우디는$w2\n"
.stringn "자기 나라를 좋아하나?$K\n"
.stringn "$F3$P그렇다. $w4갈리아는 좋은 나라다.$w4\n"
.stringn "모우디한테는,$w2\n"
.stringn "세계 제일로 $w2굉장한 나라다.$K\n"
.stringn "$F1$P그런가.$K\n"
.stringn "$F3$P손은 어떤가?$w4\n"
.stringn "베그니온이 좋나?$K\n"
.stringn "$F1$P$MC…$MD혐오하고 있다.$K\n"
.stringn "$F3$P『혀모』?$w4\n"
.stringn "그건 무슨 의미인가?$K\n"
.stringn "$F1$P너는 몰라도 돼.$w4\n"
.stringn "무지한 채로 있는 편이 행복하니까.$K\n"
.stringn "$F3$P$FA『무디』$MC……$MD$w4\n"
.stringn "$MC……$MD으음$MC…$MD$w4 모우디는\n"
.stringn "현대어를 잘 모르겠다$MC……$MD$K"
db 0
.align 4
//MYELL_MORDY_SOANVALCKE_C

//0x3DCEC
Text_3DCCC:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_VULCI|$F3$FS$F3$FCL_MORDY|$F3$P우르키, $w2좋은 생각이 났다.$K\n"
.stringn "$F1$P뭐지?$K\n"
.stringn "$F3$P모우디가 눈이 되겠다.$w4\n"
.stringn "보이는 것이 있으면 너한테 주겠다.$K$P그러니까, $w2모우디를 태우고\n"
.stringn "같이 숲으로 가면 된다$MC!$MD$K\n"
.stringn "$F1$P$MC………………$MD$w4\n"
.stringn "아니$MC……$MD$w2 그건 못 한다$MC…$MD$K$P너는 너무 무거워.$w4\n"
.stringn "내 힘으로는 너를 태울 수 없다.$K\n"
.stringn "$F3$P$FA으으$MC……$MD$w4 그렇구나. $w4미안.$K$P모우디는 밤에도 보인다,$w2\n"
.stringn "너는 날 수 있다,$w2\n"
.stringn "그래서 좋은 생각인 줄 알았다$MC……$MD$K\n"
.stringn "$F1$P$MC…………$MD$K\n"
.stringn "$F3$P모우디, $w2열심히 생각했는데$MC……$MD$w4\n"
.stringn "$MC……$MD미안, $w2우르키.$K\n"
.stringn "$F1$P아니$MC……$MD$w4\n"
.stringn "$MC……$MD뭐어, $w2만약의 이야기지만.$K$P내가 좀 더 힘을 기르고,$w2\n"
.stringn "네가 좀 더 가벼워진다면$MC……$MD$w4\n"
.stringn "가능할지도 모르겠군.$K\n"
.stringn "$F3$P$FS그렇구나$MC!$MD$w3 그러면 우르키가 사는\n"
.stringn "페니키스에도 가 볼 수 있겠다$MC!$MD$w4\n"
.stringn "모우디, $w2힘내겠다$MC!$MD$K$P$FA그렇구나$MC…$MD$w3 모우디는 가벼워지는 역할이다.$w4\n"
.stringn "$MC……$MD으으$MC……$MD$w4 잘 생각해 보니 어렵다$MC……$MD$K$P좋다, $w2내일부터 먹는 것을 줄여 보겠다$MC!$MD$K$F3$FD\n"
.stringn "$F1$P아니$MC……$MD 만약이라고$MC…………$MD$w4\n"
.stringn "$MC……………………$MD$w4\n"
.stringn "$MC………………………………$MD$K$P$MC………$MD$w3적당히 말한 것이었다$w2만$MC……$MD$K"
db 0
.align 4
//MYELL_MORDY_VULCI_A

//0x3D8CC
Text_3D8AC:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_VULCI|$F3$FCL_MORDY|$F1$P$MC……$MD모우디.$K\n"
.stringn "$F3$P왜 그러나, $w2우르키?$K\n"
.stringn "$F1$P네게 물어보고 싶은 게 있다.$K\n"
.stringn "$F3$P$FS응?$w4 뭔가?$K\n"
.stringn "$F1$P너희 수아족은 밤에도\n"
.stringn "시력에 문제가 없는 것 같더군$K$P$MC……$MD우리들은 밤에 눈이 안 보인다.$w4\n"
.stringn "어둠 속에서 $w2눈을 뜨고 있어도\n"
.stringn "아무것도 안 보이지.$K\n"
.stringn "$F3$P$FA으음, $w2그거 불편하겠다.$w4\n"
.stringn "확실히 어두우면 잘 보기 힘들지만,$w2\n"
.stringn "약간의 불빛이 있으면 잘 보인다.$K$P$FS너도 모우디처럼$w2\n"
.stringn "달빛으로 보면 된다.$K\n"
.stringn "$F1$P$MC……$MD그렇게 할 수 있다면 좋겠지만.$w4\n"
.stringn "조익족에게는 아무래도 무리다.$K\n"
.stringn "$F3$P$FA그렇구나.$K\n"
.stringn "$F1$P$MC……$MD나는 밤의 풍경을 본 적이 없다.$w4\n"
.stringn "동포들 중 누구도 밤의 세계를 모르지.$K$P나는 한 번이라도 $w2밤의 숲을 보고 싶다.$K$P밤이 되면 숲의 나무들은 어떻게 보일까?$w4\n"
.stringn "왜 비가 오지 않아도 아침이 되면\n"
.stringn "잎사귀에 물방울이 맺혀 있는 거지?$K$P밤의 숲은 $w2알 수 없는 것들뿐이다.$w4\n"
.stringn "도대체 $w2어떤 느낌이지?$K\n"
.stringn "$F3$P$FS밤의 숲은 고요하지만,$w2\n"
.stringn "낮에는 생물의 숨결이 $w2살아 있다.$w4\n"
.stringn "낮과 밤은 전혀 다른 숲이다.$K\n"
.stringn "$F1$P$MC……$MD그런가.$K\n"
.stringn "한번 $w2보고 싶군.$K"
db 0
.align 4
//MYELL_MORDY_VULCI_B

//0x3D524
Text_3D504:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_VULCI|$F3$FCL_MORDY|$F3$P우르키, $w2뭐 물어봐도 되나?$K\n"
.stringn "$F1$P$MC……$MD그래.$w4\n"
.stringn "뭐지?$K\n"
.stringn "$F3$P조익족은 하늘을 난다.$w4\n"
.stringn "하늘을 난다는 건 어떤 기분인가?$K\n"
.stringn "$F1$P$MC……$MD$w4\n"
.stringn "$MC……$MD딱히 어떤 기분이 드는 건 아니다.$K\n"
.stringn "$F3$P으음$MC……$MD$w4 그런가.$w4\n"
.stringn "$w4그런 거구나.$K$P모우디는 아직,$w2\n"
.stringn "하늘을 날아 본 적이 없어서$w4\n"
.stringn "물어보고 싶었다.$K\n"
.stringn "$F1$P$MC……$MD그래, $w2그렇겠지.$K\n"
.stringn "$F3$P우르키가 사는 페니키스는\n"
.stringn "어떤 곳인가?$w4\n"
.stringn "역시, $w2날 수 없으면 못 가는 건가?$K\n"
.stringn "$F1$P그래$MC……$MD$K$P배로 찾아온다 한들\n"
.stringn "페니키스에는 항구가 없다. $w4필요가 없으니까.$w4\n"
.stringn "우리의 도움 없이는 $w2상륙하기 어렵겠지.$K\n"
.stringn "$F3$P그렇구나$MC……$MD$w4\n"
.stringn "아쉽다$MC……$MD$K\n"
.stringn "$F1$P$MC……$MD너는 페니키스에 $w2가 보고 싶나?$K\n"
.stringn "$F3$P$FS그렇다$MC!$MD$w4 가 보고 싶다$MC!$MD$w4\n"
.stringn "이 전쟁에서 $w2여러 베오크와 라구즈와 만났다$MC!$MD$K$P모두가 살던 곳으로$w2\n"
.stringn "모우디는 가 보고 싶다$MC!$MD$K\n"
.stringn "$F1$P$MC……$MD그런가.$K"
db 0
.align 4
//MYELL_MORDY_VULCI_C

