//0x3EA00
Text_3E9E0:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_MWARIM|$F3$FS$F3$FCL_ZIHARK|$F3$P무와림.$K\n"
.stringn "$F1$P뭐야, $w2지하크.$K\n"
.stringn "$F3$P네게 주려고 $w2이걸 가져왔어.$K\n"
.stringn "$F1$P$MC……$MD이건?$K\n"
.stringn "$F3$P수아족은 $w2이 풀의 향기를\n"
.stringn "엄청 좋아하지?$K$P좀처럼 나지 않는 풀이지만,$w2\n"
.stringn "향기를 맡는 것만으로도$w2\n"
.stringn "차분한 기분이 된다고 들었어.$K\n"
.stringn "$F1$P$MC……$MD$K\n"
.stringn "$F3$P$FA혹시,$w2\n"
.stringn "풀을 착각했나?$K\n"
.stringn "$F1$P$MC……$MD아니.$w4\n"
.stringn "하지만 $w2그 풀을 좋아하는 건\n"
.stringn "수아족들 중에서도 고양이들뿐이다.$K$P우리들 호랑이한테는$MC…$MD$w3\n"
.stringn "그런 습성이 없어.$K\n"
.stringn "$F3$P$FS뭐야$MC…$MD$w2 그런 거였구나.$K$P미안해. $w4옛날에$w2\n"
.stringn "연인이 그랬으니까$MC…$MD$K$P틀림없이 다 그럴 거라고$w2\n"
.stringn "생각했었어.$K\n"
.stringn "$F1$P$MC……$MD연인?$K\n"
.stringn "네 연인은$w2\n"
.stringn "수아족이었나?$K\n"
.stringn "$F3$P그래.$K\n"
.stringn "$F1$P$MC……$MD그렇군.$w4\n"
.stringn "베오크와 맺어지는 라구즈도 있다고$MC…$MD$w3\n"
.stringn "이야기로는 들은 적이 있었지만$MC……$MD$K$P그$MC…$MD$w2 힘들었겠구나.$K\n"
.stringn "$F3$P그렇지$MC…$MD$w4\n"
.stringn "결국 $w2맺어지지는\n"
.stringn "못했지만$MC……$MD$K$P나는 지금도$MC…$MD$w3\n"
.stringn "그녀 이외의 여자를 $w2사랑한 적이 없어.$K\n"
.stringn "$F1$P$FS$MC……$MD그 풀을,$w2\n"
.stringn "받을 수 있을까.$K\n"
.stringn "$F3$P$FA어?$w4 하지만$MC……$MD$K\n"
.stringn "$F1$P상관없어.$w4\n"
.stringn "이걸 가져와 준\n"
.stringn "네 마음을 받고 싶다.$K\n"
.stringn "$F3$P$FS그렇구나$MC…$MD$w4\n"
.stringn "고마워.$K\n"
.stringn "너는 상냥한 라구즈구나.$K"
db 0
.align 4
//MYELL_MWARIM_ZIHARK_A

//0x3E540
Text_3E520:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_MWARIM|$F3$FCL_ZIHARK|$F1$P$MC……$MD지하크.$K\n"
.stringn "$F3$P$FS안녕, $w2무와림.$w4\n"
.stringn "또 만났네.$K\n"
.stringn "$F1$P$MC……$MD숫돌 가루는 찾았나?$K\n"
.stringn "$F3$P아니, $w2공교롭게도 못 찾았어.$K\n"
.stringn "누군가한테 $w2다시 빌리는 것도 그러니까$w2\n"
.stringn "이제부터 새로운 걸\n"
.stringn "사러 가려고 하던 참이야.$K\n"
.stringn "$F1$P$MC……$MD이건 쓸 수 있나?$K\n"
.stringn "$F3$P$FA응?$w4 이건$MC…$MD$w4\n"
.stringn "아주 좋은 숫돌 가루인걸.$K$P라구즈인 네가$w2\n"
.stringn "왜 이런 걸 가지고 있어?$K\n"
.stringn "$F1$P$MC……$MD옛날 버릇이다.$K\n"
.stringn "$F3$P옛날$MC…?$MD$K\n"
.stringn "$F1$P귀족의 노예였던 시절$MC……$MD$w4\n"
.stringn "주인은 $w2자주 검을 연마했다.$K$P언제나 $w2갑자기 가지고 오는데,$w2\n"
.stringn "그 자리에서 바로 닦지 않으면$w2\n"
.stringn "호되게 매질을 당했지.$K$P그래서$MC…$MD$w4다.$K\n"
.stringn "$F3$P$MC……$MD$w4미안해.$w4\n"
.stringn "싫은 일을\n"
.stringn "생각나게 해 버렸네.$K\n"
.stringn "$F1$P상관없다.$w4$FS\n"
.stringn "괜찮다면$w2\n"
.stringn "그 검도 닦아 줄까?$K\n"
.stringn "$F3$P$FS아니, $w2진정한 검사라면$w3\n"
.stringn "자신의 검은 자기가 손질하는 법이야.$w4\n"
.stringn "마음만으로도 기뻐.$K\n"
.stringn "$F1$P그럼, $w2이 가루만이라도\n"
.stringn "써 줘.$w4\n"
.stringn "나에겐 이제 $w2필요 없는 거니까.$K\n"
.stringn "$F3$P무와림$MC…$MD$K$P고마워, $w2도움이 됐어.$w4\n"
.stringn "사례라고 하긴 좀 그렇지만$MC…$MD$w4\n"
.stringn "같이 식사라도 어때?$K\n"
.stringn "$F1$P$MC…$MD그렇군. $w4너와 함께라면$MC…$MD$w3\n"
.stringn "즐거운 식사를 할 수 있을 것 같다.$K"
db 0
.align 4
//MYELL_MWARIM_ZIHARK_B

//0x3E1C4
Text_3E1A4:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_ZIHARK|$F3$P이상하네.$w4\n"
.stringn "방금 전까진 있었는데$w2\n"
.stringn "대체 어디로 간 거야$MC……$MD$K\n"
.stringn "$F1$FCL_MWARIM|$F1$P$MC…$MD무슨 일 있나?$K\n"
.stringn "$F3$P$FS아, $w2무와림.$w4\n"
.stringn "“숫돌 가루”가 $w2보이질 않아서.$K\n"
.stringn "$F1$P숫돌 가루?$K\n"
.stringn "$F3$P검을 손질하는 데 쓰는 도구야.$K\n"
.stringn "칼날은 그냥 두면 녹슬게 되니까.$w4\n"
.stringn "기름으로 닦거나, $w2숫돌 가루를 치거나$MC……$MD$K\n"
.stringn "$F1$P$MC……$MD고운 돌가루를 넣은 $w2주머니 말인가?$K\n"
.stringn "$F3$P그래, $w2그거.$w4\n"
.stringn "혹시 주웠어?$K\n"
.stringn "$F1$P$MC……$MD아니.$K\n"
.stringn "옛날에 $w2본 적이 있었을 뿐이다.$w4\n"
.stringn "숫돌 가루라고 불리는 줄은 몰랐는데.$K\n"
.stringn "$F3$P$FA근처에서 떨어뜨리진 않았고,$w2\n"
.stringn "행군 도중에\n"
.stringn "잃어버린 건가$MC……$MD$K$FS$P어쩔 수 없지, $w2아이크 단장한테서\n"
.stringn "조금 빌려야겠다.$K\n"
.stringn "$F1$P$MC……$MD베오크는 불편하겠군.$K\n"
.stringn "$F3$P그러게나 말이야.$K$P우리는 무기가 없으면 아무것도 할 수 없지.$w4\n"
.stringn "이럴 때는 항상$w2\n"
.stringn "라구즈가 부럽다는 생각이 들어.$K\n"
.stringn "$F1$P$MC…………$MD$K"
db 0
.align 4
//MYELL_MWARIM_ZIHARK_C

