//0x3F998
Text_3F978:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_OSCAR|$F3$FCL_TANIS|$F3$P오스카.$w4\n"
.stringn "?$w4 어디 가는 거지?$K\n"
.stringn "$F1$P네, $w2지금부터 식사 준비를 하러$MC……$MD$w4\n"
.stringn "뭔가 용무가 있으신가요?$K\n"
.stringn "$F3$P아니, $w2별일은 아니다만$MC……$MD$w4\n"
.stringn "네게 고맙다는 말을 해 두고 싶었다.$K$P네 보좌 덕분에$w2\n"
.stringn "충분히 내 힘을 발휘할 수 있었지.$K$P이렇게 편안하게 싸울 수 있었던 적은 없다.$w4\n"
.stringn "가능하다면 $w2너를\n"
.stringn "베그니온으로 데려가고 싶을 정도군.$K\n"
.stringn "$F1$P감사합니다.$K\n"
.stringn "$F3$P그나저나$MC……$MD$w4\n"
.stringn "오스카가 요리를 하는 건가?$K\n"
.stringn "$F1$P네. $w4용병단끼리 행동할 때는 자주 했지만,$w4\n"
.stringn "지금은 가끔씩 이렇게 도우러 갑니다.$K\n"
.stringn "$F3$P호오, $w2재주가 좋군.$K\n"
.stringn "$F1$P$FA그런가요?$K\n"
.stringn "$F3$P한심한 이야기지만,$w2\n"
.stringn "난 달걀 껍데기 하나도 제대로 못 깐다.$K$P야영지에서 $w2딱 한 번 요리한 적이 있었는데$MC…$MD$w4\n"
.stringn "계란이 아니라 $w2껍데기를 먹이고 싶은 거냐는$w2\n"
.stringn "말을 들은 적이 있었지.$K\n"
.stringn "$F1$P$MC……$MD그렇군요$MC…$MD$K\n"
.stringn "$F3$P$FS어처구니없지?$K\n"
.stringn "$F1$P$FS아뇨, $w4그 정도로 현란하게 검을\n"
.stringn "잘 다루시는데 의외라고 생각했을 뿐입니다.$K$P혹시, $w2실례가 되지 않는다면$MC……$MD$w4\n"
.stringn "제가 가르쳐 드려도 괜찮을까요?$K\n"
.stringn "$F3$P$FA네가 요리를?$K\n"
.stringn "$F1$P싫지 않으시다면요.$K\n"
.stringn "$F3$P흠, $w2너라면 가르치는 일도 잘 하겠지.$w4\n"
.stringn "$FS좋아, $w2교습을 부탁하마.$K"
db 0
.align 4
//MYELL_OSCAR_TANIS_A

//0x3F284
Text_3F264:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_OSCAR|$F3$FCL_TANIS|$F1$P타니스님. $w4지난번의 용맹한 돌격$MC……$MD$w4\n"
.stringn "훌륭했습니다.$K\n"
.stringn "$F3$P물론이다. $w4우리는 베그니온 기사.$w4\n"
.stringn "조국과 신사님의 이름으로$w2\n"
.stringn "불명예스러운 싸움을 할 수는 없지.$K\n"
.stringn "$F1$P타니스님의 무예는\n"
.stringn "저도 소문으로 들은 적이 있습니다.$K$P최대 속도로는$w2\n"
.stringn "빛의 속도에도 비유된다는\n"
.stringn "천마 기사대의 총돌격$MC……$MD$K\n"
.stringn "$F3$P호오, $w2알고 있었나.$K\n"
.stringn "$F1$P$FA그러나 타니스님.$K$P실례를 무릅쓰고 말씀드립니다만,$w2\n"
.stringn "그 전술은 병사의 수가 우위일 때\n"
.stringn "성립된다고 할 수 있지 않을까요?$K\n"
.stringn "$F3$P음$MC……$MD$K$P확실히 그건 인정하지.$w4\n"
.stringn "이번 전투에서는 베그니온군의 전술을\n"
.stringn "그대로 쓸 수 없겠지.$K\n"
.stringn "$F1$P네.$w4\n"
.stringn "우리 군은 항상 병력이 적고,$w2\n"
.stringn "장비마저 충분히 갖추지 못한 자도 간혹 있죠.$K$P베그니온과 같은 윤택한 자금과 병력은\n"
.stringn "도저히 바랄 수 없는 것이 현실입니다.$K\n"
.stringn "$F3$P그렇지.$w4\n"
.stringn "그럼 어떻게 하면 되지?$w4\n"
.stringn "네 의견을 듣고 싶군.$K\n"
.stringn "$F1$P우리가 계속해 온 것은$w2\n"
.stringn "개개인을 살리는 싸움이었습니다.$K$P이런 연전에서는 $w2우선 죽지 않는 것을\n"
.stringn "첫 번째로 생각해야 합니다.$K$P비록 전투에서 이기더라도 $w2희생이 크다면$w2\n"
.stringn "다음 전투에서는 이길 수 없으니까요.$K$P설령 불명예스러운 비난을 받는 한이 있어도$w2\n"
.stringn "부상을 당했을 때는 곧바로 이탈하고,$w2\n"
.stringn "다른 동료에게 맡기는 겁니다$MC……$MD$K\n"
.stringn "$F3$P과연$MC……$MD$w4\n"
.stringn "개인적으로는 약간 불만이지만$w4\n"
.stringn "유효하다는 점은 인정하지 않을 수 없군.$K\n"
.stringn "$F1$P가능하다면 타니스님께서도\n"
.stringn "항상 아군과 연계하여 싸우시도록\n"
.stringn "부탁하고 싶습니다.$K\n"
.stringn "$F3$P하지만 $w2이 군에서 나와 연계를 취할\n"
.stringn "천마 기사는 좀처럼 없다.$w4\n"
.stringn "누가 나를 보좌하지?$K\n"
.stringn "$F1$P$FS그럼, $w2제가 그 역할을 맡겠습니다.$K\n"
.stringn "$F3$P네가?$K\n"
.stringn "$F1$P네, $w2아직 미숙하지만요.$K\n"
.stringn "$F3$P$FS$MC……$MD아니, $w2너라면 좋다.$K$P너에 대한 것은 조금이나마 알고 있지.$w4\n"
.stringn "다른 정체를 알 수 없는 용병들과는 달리\n"
.stringn "믿을 수 있을 것 같군.$K\n"
.stringn "$F1$P영광입니다.$K\n"
.stringn "$F3$P$FA하지만 $w2내게 네가 탄 말을 기다릴 여유는 없다.$w4\n"
.stringn "나를 보좌한다면$w2\n"
.stringn "나를 따라올 수 있어야겠지.$K\n"
.stringn "$F1$P$FA넵, $w2노력하겠습니다.$K"
db 0
.align 4
//MYELL_OSCAR_TANIS_B

//0x3EF04
Text_3EEE4:
.stringn "$R背景会話|$B支援背景|$<$F3$FCL_TANIS|$F3$P음?$w4 잠깐 기다리도록.$K\n"
.stringn "$F1$FCL_OSCAR|$F1$P네?$K\n"
.stringn "$F3$P지금 이 천을 떨어뜨린 건\n"
.stringn "너인가?$K\n"
.stringn "$F1$P이건$MC……$MD$w4 죄송합니다.$w4\n"
.stringn "타니스님께서\n"
.stringn "직접 주워 주시다니.$K\n"
.stringn "$F3$P네 이름은?$K\n"
.stringn "$F1$P네, $w2인사가 늦었군요.$w4\n"
.stringn "처음 뵙겠습니다.$K$P저는 그레일 용병단의\n"
.stringn "오스카라고 합니다.$K\n"
.stringn "$F3$P흠, $w2너도 아이크 장군이\n"
.stringn "이끌고 있는 용병단의 일원인가.$w4\n"
.stringn "알았다.$K$P내 부하들은 $w2최소한만 데리고 왔지만$w4\n"
.stringn "우리 베그니온 기사는 비록 수가 적더라도\n"
.stringn "남 못지 않지. $w4전장에서 보여 주겠다.$K\n"
.stringn "$F1$P$FS유명한 베그니온 천마 기사의 힘은\n"
.stringn "잘 알고 있습니다.$w4\n"
.stringn "앞으로 잘 부탁드립니다.$K\n"
.stringn "$F3$P그래.$K\n"
.stringn "$F1$P그럼, $w2실례하겠습니다.$w4\n"
.stringn "정말 감사했습니다.$K\n"
.stringn "$F1$FD$P$w5$F3$P$FS흠$MC……$MD$w4\n"
.stringn "제법 예의가 바른 청년인걸.$K$P용병이라 하면 천박하고 저속한\n"
.stringn "남자들밖에 없다고 단정짓고 있었다만$MC……$MD$w4\n"
.stringn "과연 아이크 장군의 부하로군.$K"
db 0
.align 4
//MYELL_OSCAR_TANIS_C

//0x40678
Text_40658:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_RIEUSION|$F3$FCL_TANIS|$F3$P뤼시온 왕자님.$w4\n"
.stringn "지난번에는$MC…$MD$w2 위험했습니다.\n"
.stringn "도와주셔서 감사합니다.$K\n"
.stringn "$F1$P$MC…$MD어쨌든$w2\n"
.stringn "무사히 끝나서 다행이다.$K$P언제나 날렵하게 움직이던 네가$MC…$MD$w4\n"
.stringn "적을 눈앞에 두고$w2\n"
.stringn "갑자기$MC…$MD$w2 움직임을 멈춰서 놀랐거든.$K\n"
.stringn "$F3$P자신도 모르는 사이에$MC…$MD$w3\n"
.stringn "피로가 쌓였던 것 같습니다.$K$P그때 $w2뤼시온 왕자님께서\n"
.stringn "【주가】를 불러 주시지 않았다면$MC…$MD$w3\n"
.stringn "상당히 위험한 상황에 빠졌을 겁니다.$K$P재차 감사드립니다.$K\n"
.stringn "$F1$P$MC……$MD이런데도, $w2내가$w3\n"
.stringn "전장에서 쓸모없다고 생각하는 건가?$K\n"
.stringn "$F3$P아니요, $w2전부 제 자만이었습니다.$K$P지키라는 명령을 받았으면서$w2\n"
.stringn "역으로 보호받다니$MC…$MD$w4\n"
.stringn "이만큼 한심한 일도 없습니다.$K\n"
.stringn "$F1$P$FS알았다면$w2\n"
.stringn "그걸로 됐어.$K\n"
.stringn "$F3$P하지만$MC…$MD$w3 이렇게 된 이상,$w4\n"
.stringn "이 군에 있어도 폐가 될 뿐$MC……$MD$K$P이 발로 베그니온에 돌아가$w3\n"
.stringn "신사님께 야단을 맞으려고 합니다.$K\n"
.stringn "$F1$P$FA자, $w2잠깐만$MC!$MD$w4\n"
.stringn "단 한 번 실패했다고$MC…$MD$w3\n"
.stringn "그렇게까지 할 필요는 없지 않나.$K\n"
.stringn "$F3$P아뇨$MC…$MD$w3 임무에 모두\n"
.stringn "실패한 제게는$MC……$MD$w4\n"
.stringn "이제 제대의 길밖에 남아 있지 않습니다.$K\n"
.stringn "$F1$P그럼$MC…$MD$MC!$MD$K$P내 호위를 맡기겠다.$w4\n"
.stringn "그렇게 하면$w2\n"
.stringn "신사의 임무를 하나 완수할 수 있겠지.$K\n"
.stringn "$F3$P그런$MC…$MD$w3 저 따위가 호위라니,$w2\n"
.stringn "왕자님께 짐이 될 뿐입니다.$K\n"
.stringn "$F1$P$FS내가 너를 지키겠다.$w4\n"
.stringn "이름뿐인 호위라도 좋으니까,$w2\n"
.stringn "여기 남아서 임무를 완수해 다오.$K\n"
.stringn "$F3$P뤼시온 왕자님$MC…$MD$w4\n"
.stringn "그럼 $w2삼가 호위 임무를 맡겠습니다.$K$FS$P부족하지만 $w3앞으로도\n"
.stringn "잘 부탁드립니다.$K"
db 0
.align 4
//MYELL_RIEUSION_TANIS_A

//0x402B8
Text_40298:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_RIEUSION|$F3$FS$F3$FCL_TANIS|$F3$P뤼시온 왕자님.$K\n"
.stringn "$F1$P$MC…$MD너인가.$K\n"
.stringn "$F3$P보아하니$MC…$MD$w3\n"
.stringn "지난번의 부상도 순조롭게 회복된 것 같아$w2\n"
.stringn "다행입니다.$K\n"
.stringn "$F1$P$MC……$MD$K\n"
.stringn "$F3$P$FA무례를 무릅쓰고 말씀드리겠습니다.$K$P역시, $w3당신 같은 분께서\n"
.stringn "전장에 나서는 것은$w2\n"
.stringn "무모하지 않습니까?$K$P당신을 지키기 위해서는$w2\n"
.stringn "여러 병사들의 손을 빌려야 합니다.$K$P적어도 제게 $w2전속 호위를\n"
.stringn "맡겨 주신다면$MC…$MD$w3\n"
.stringn "조금은 상태가 나아$MC……$MD$K\n"
.stringn "$F1$P$MC…$MD아이크가$w2\n"
.stringn "내 힘이 필요 없다고 말하지 않는 한$MC…$MD$w3\n"
.stringn "전장에 나갈 거다.$K$P그 외에는 $w2누구의 지시도 받지 않겠어.$K\n"
.stringn "$F3$P뤼시온 왕자님$MC!$MD$K\n"
.stringn "$F1$P$MC…$MD지난번 전투에서$MC……$MD$w3 네가$w2\n"
.stringn "도와준 것에 대해서는 $w2감사하고 있다.$K$P하지만 $w3몇 번이고 말하는데$MC…$MD$w2 호위는 필요 없다.$w4\n"
.stringn "날 따라다니는 건 $w2그만해 줘.$K\n"
.stringn "$F1$FD$P$w5$F3$P$MC…$MD흐음. $w4칙명이 아니라면$w2\n"
.stringn "나도 억지로 하고 싶은 건 아니다만$MC…$MD$w3\n"
.stringn "꽤$MC…$MD$w2 곤란하게 됐군.$K"
db 0
.align 4
//MYELL_RIEUSION_TANIS_B

//0x3FE48
Text_3FE28:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_RIEUSION|$F3$FCL_TANIS|$F3$P뤼시온 왕자님,$w4\n"
.stringn "잠깐 $w2괜찮으십니까.$K\n"
.stringn "$F1$P너는 확실히$MC……$MD$w3\n"
.stringn "신사의$MC…?$MD$K\n"
.stringn "$F3$P네.$w4\n"
.stringn "신사 친위대 $w2부대장을 맡고 있는$w4\n"
.stringn "타니스라고 합니다.$K\n"
.stringn "$F1$P$MC…$MD$w2나한테 무슨 볼일이지?$K\n"
.stringn "$F3$P신사님께 $w2가능한 만큼$w2\n"
.stringn "왕자님을 지켜드리라는 명령을 받았습니다.$w4\n"
.stringn "앞으로 $w2잘 부탁드립니다.$K\n"
.stringn "$F1$P20년 전의 속죄$MC…$MD$w4라는 건가.$w4\n"
.stringn "안타깝게 됐지만 $w2필요 없어.$w4\n"
.stringn "내 몸 정도는 스스로 지킬 수 있다.$K\n"
.stringn "$F3$P하지만 $w2왕자님.$w4\n"
.stringn "백로 민족이 $w2일체 싸울 수 있는 기술을\n"
.stringn "가지고 있지 않다는 것은$MC…$MD$K$P베그니온에선$w2\n"
.stringn "어린아이들도 아는 사실입니다.$K$P전장에서$MC…$MD$w4 싸우지도 않고$w2\n"
.stringn "어떻게 자신을\n"
.stringn "지키실 생각이십니까?$K\n"
.stringn "$F1$P그런 건$w2\n"
.stringn "너하고 관계없다.$K\n"
.stringn "$F3$P$MC…$MD저는 칙명을 받고 있습니다.$w4\n"
.stringn "확실한 이유도 듣지 못한 채$w2\n"
.stringn "명령을 포기할 수는 없습니다.$K\n"
.stringn "$F1$P베오크의 방식에$w2\n"
.stringn "내가 따를 이유는 없어.$w4\n"
.stringn "$MC…$MD얘기는 이걸로 끝이다. $w4실례하지.$K$F1$FD$P$w5\n"
.stringn "$F3$P$MC……$MD$w2이거야 원, $w2보기와는 다르게\n"
.stringn "기가 센 왕자님이로군.$w4\n"
.stringn "쉽게 지키게 해 주진 않을 것 같은데.$K$P그럼, $w2어떻게 하면 좋을까$MC…$MD$K"
db 0
.align 4
//MYELL_RIEUSION_TANIS_C

//0x414FC
Text_414DC:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_TOPUCK|$F3$FCL_RIEUSION|$F1$P저기 있잖아$MC…$MD$w4 안 되는 거야?$K\n"
.stringn "$F3$P$MC………$MD$K\n"
.stringn "$F1$P사실은 할 수 있는 거지?$w4\n"
.stringn "부탁이야, $w2해 주라.$w4\n"
.stringn "지금 당장이 아니더라도 괜찮으니까.$K\n"
.stringn "$F3$P$MC…$MD무리다.$K\n"
.stringn "$F1$P$MC…$MD우리들이\n"
.stringn "아무것도 가진 게 없어서 그러는 거야?$w4\n"
.stringn "그래서 안 도와주는 거야?$K\n"
.stringn "$F3$P내가 $w2대가를 바라고\n"
.stringn "행동한다고 말할 셈이냐$MC!?$MD$K\n"
.stringn "$F1$P그, $w2그치만$MC…$MD$MC!$MD$w4\n"
.stringn "신사를 용서했을 때는$MC…$MD$w4\n"
.stringn "그렇게 대단한 일도 할 수 있었잖아$MC!!$MD$K\n"
.stringn "$F3$P그건$MC…$MD$w4\n"
.stringn "그런 조건 아래였으니 가능했던 일이다.$K\n"
.stringn "$F1$P?$w4 $MC…$MD잘 모르겠는데.$K\n"
.stringn "$F3$P$MC…$MD우선, $w2그곳은 셀리노스의 숲이었다.$w4\n"
.stringn "성스러운 제단 위에서$w2\n"
.stringn "가문의 정식 의식으로서 거행했지.$K$P그리고 무엇보다도$MC…$MD$w4\n"
.stringn "그때는 리아네가 있었다.$K$P【재생】의 주가는$w2\n"
.stringn "혼자서 노래한다면 큰 효력을 발휘할 수 없어.$K\n"
.stringn "$F1$P$MC………$MD그럼,$w2\n"
.stringn "그럼 그 공주님이 있으면 되는 거 아냐?$K\n"
.stringn "$F3$P이해력이 나쁘군$MC…$MD$K$P만약 리아네와 내가\n"
.stringn "쓰러질 때까지 노래한다고 해도,$w2\n"
.stringn "모래를 흙으로 바꿀 수는 없다.$K$P그 사막이 $w2아주 먼 옛날\n"
.stringn "풍요로운 흙이었다고 해도$MC…$MD$w4\n"
.stringn "몇백 년 전으로 되돌릴 만한 힘은 없어.$K$P알겠나?$K\n"
.stringn "$F1$P$MC………$MD쳇$K\n"
.stringn "$F3$P어째서 $w2내 주가가 필요하지?$K$P아이크에게$MC…$MD$w4\n"
.stringn "너희의 일은\n"
.stringn "신사가 맡아 주게 되었다고 들었다.$K\n"
.stringn "$F1$P신사는$MC…$MD$w4 라구즈 노예와 관한 일은\n"
.stringn "어떻게든 해 준다고 했지만$MC…$MD$K$P만약, $w2그게 베오크랑\n"
.stringn "같은 마을에 살게 해 준다는 얘기라면$MC…$MD$w4\n"
.stringn "곤란하다고 생각하거든.$K$P그야 그렇잖아?$K$P아무리 신사가 허락한다 해도,$w2\n"
.stringn "다른 베오크들은$MC…$MD$w4 역시\n"
.stringn "라구즈를 싫어하고$MC……$MD$K$P나도$MC…$MD$w4 동료들이 힘들어하는 건\n"
.stringn "역시, $w2싫고$MC……$MD$K\n"
.stringn "$F3$P그건$MC…$MD$w4 확실히\n"
.stringn "무리인 이야기군.$K\n"
.stringn "$F1$P그래서$MC…$MD$w4\n"
.stringn "사막을 어떻게든 되살리고 싶었어.$K$P라구즈끼리 살 수 있는 마을을\n"
.stringn "만들 수는 없을까 $w2생각한 거지.$K\n"
.stringn "$F3$P$MC………$MD아직은 미래의 일이지만,$w2\n"
.stringn "만약 $w2셀리노스의 숲이\n"
.stringn "다시 우리 손으로 돌아온다면$MC…$MD$w4 같이 살겠나?$K\n"
.stringn "$F1$P그, $w2그래도 돼$MC!?$MD$K\n"
.stringn "$F3$P$FS물론이다.$K\n"
.stringn "$F1$P$FS고마워$MC!$MD$w4\n"
.stringn "모두 기뻐할 거야$MC!!$MD$K\n"
.stringn "$F3$P단, $w2숲속의 동물들을\n"
.stringn "포식하는 건 금지다.$K\n"
.stringn "$F1$P$FA응$MC…?$MD$w4 그럼, $w2밥은\n"
.stringn "어떻게 먹어?$K\n"
.stringn "$F3$P물과 나무 열매가 풍족하다.$K\n"
.stringn "$F1$P내 동료들은\n"
.stringn "수아족들이 많다고,$w2\n"
.stringn "걔네는 육식이란 말이야$MC!$MD$K\n"
.stringn "$F3$P익숙해져라.$K\n"
.stringn "$F1$P$MC……$MD일단, $w2모두와 상담해 볼게.$K$P근데 $w2다들$MC…$MD$w4\n"
.stringn "고기를 전혀 먹지 못하니까\n"
.stringn "사막이 더 좋다고 말하지 않을까$MC…$MD$K"
db 0
.align 4
//MYELL_RIEUSION_TOPUCK_A

//0x411E4
Text_411C4:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_TOPUCK|$F3$FCL_RIEUSION|$F1$P백로 민족의 왕자$MC!$MD$K\n"
.stringn "$F3$P$MC…$MD뤼시온이다.$K\n"
.stringn "$F1$P그럼, $w2뤼시온 왕자$MC!$MD$w4\n"
.stringn "지금 시간 $w2있어?$K\n"
.stringn "$F3$P뭐어$MC…$MD$w4 상관없다.$w4\n"
.stringn "지난번에 했던 라구즈를 위해\n"
.stringn "주가를 불러달라는 얘기지?$K\n"
.stringn "$F1$P맞아. $w4기억해 줬구나.$w4\n"
.stringn "너 좋은 녀석인걸.$K\n"
.stringn "$F3$P$MC……$MD내용은?$K\n"
.stringn "$F1$P저기, $w2네 노래로$MC…$MD$w4\n"
.stringn "사막의 모래를,$w2\n"
.stringn "흙으로 바꿔 줬으면 좋겠어.$K\n"
.stringn "$F3$P모래를 흙$MC…$MD$w4으로?$K\n"
.stringn "$F1$P응. $w4싱싱한\n"
.stringn "작물이 잔뜩 자라는 흙.$K$P그러면 $w2거기에\n"
.stringn "우리들의 마을을 만들려고.$K\n"
.stringn "$F3$P$MC………$MD말도 안 되는 소리.$w4\n"
.stringn "주가는 $w2그렇게 만능한 것이 아니다$MC!$MD$K$F3$FD\n"
.stringn "$F1$P$FA앗, $w2야$MC!$MD$K$P$MC…$MD가 버렸잖아.$w4\n"
.stringn "백로 민족은 화를 잘 내네.$w4\n"
.stringn "저렇게나 착하게 생겼는데.$K"
db 0
.align 4
//MYELL_RIEUSION_TOPUCK_B

//0x40C8C
Text_40C6C:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_RIEUSION|$F3$FS$F3$FCL_TOPUCK|$F3$P아, $w2백로 민족의 왕자다$MC!$MD$K\n"
.stringn "$F1$P누구냐, $w2넌?$K\n"
.stringn "$F3$P난 토팍이야.$w4\n"
.stringn "나, $w2당신한테\n"
.stringn "물어보고 싶은 게 있어서.$K\n"
.stringn "$F1$P당돌한 녀석이군.$w4\n"
.stringn "물어볼 게 뭐지?$K\n"
.stringn "$F3$P그 노래의 효과는 $w2아무 데나 통하는 거야?$K\n"
.stringn "$F1$P주가 말인가?$K\n"
.stringn "$F3$P색이 없었던 숲을\n"
.stringn "한 방에 바꿔 버렸던 노래.$K\n"
.stringn "$F1$P【재생】의 주가로군.$w4\n"
.stringn "$MC………$MD그래서?$K\n"
.stringn "$F3$P저기, $w2그거$MC…$MD$w4\n"
.stringn "우리들을 위해서도$w2\n"
.stringn "불러 주면 안 될까?$K\n"
.stringn "$F1$P우리들?$K\n"
.stringn "$F3$P응. $w4나랑\n"
.stringn "그라느 사막에서 기다리고 있는$MC…$MD$w4\n"
.stringn "라구즈 동료들에게.$K\n"
.stringn "$F1$P그럼, $w2네가$MC…$MD$w4\n"
.stringn "라구즈 노예 해방군의 두목$MC…$MD$w4\n"
.stringn "이런 어린아이였을 줄은.$K\n"
.stringn "$F3$P$FA$MC…$MD어린애면 안 되는 거냐구.$K\n"
.stringn "$F1$P그런 뜻은 아니지만$MC…$MD$K$P그 베그니온에서$w2\n"
.stringn "라구즈를 돕기 위해 힘쓰는\n"
.stringn "베오크가 있다고 들어서$K$P어떤 자인가 했는데$MC…$MD$w4\n"
.stringn "상상과는 많이 다르군.$K\n"
.stringn "$F3$P그것보다, $w2저기,$w2\n"
.stringn "어떻게 할 거야.$w4\n"
.stringn "도와주지 않을래?$K\n"
.stringn "$F1$P라구즈를 위한 일이니\n"
.stringn "힘을 아낄 생각은 없다만$MC…$MD$w4\n"
.stringn "대체 $w2뭘 하면 되는 거지?$K\n"
.stringn "$F3$P$FS앗싸$MC!$MD$w4 그러니까 말이지$MC…$MD$K$FA$P아, $w2$w4근데 어떡하지?$K\n"
.stringn "$F1$P?$K\n"
.stringn "$F3$P나 아직$w2\n"
.stringn "전투 준비를 안 했었어.$K$FS$P제대로 얘기하고 싶으니까$w2\n"
.stringn "시간 날 때 올게.$w5\n"
.stringn "그럼, $w2또 보자$MC!$MD$K$F3$FD\n"
.stringn "$F1$P$MC…$MD베오크 아이는$w2\n"
.stringn "꽤나 침착하지 못하군.$K"
db 0
.align 4
//MYELL_RIEUSION_TOPUCK_C

