//0x42264
Text_42244:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_SOANVALCKE|$F6$FCL_SENERIO|$F1$P머지않아 전쟁이 끝나겠군.$K$P너는$MC…$MD$w4\n"
.stringn "앞으로도 베오크들 사이에서\n"
.stringn "자신을 속이면서 살아갈 건가?$K\n"
.stringn "$F6$P$MC………$MD저는,$w2\n"
.stringn "역시$MC…$MD$w4 【인붙이】인 걸까요?$K\n"
.stringn "$F1$P틀림없다.$w4\n"
.stringn "우리들은 동족을 알아볼 수 있어.$K\n"
.stringn "$F6$P$MC………$MD$K\n"
.stringn "$F1$P숨기는 동안에는 괜찮겠지.$w4\n"
.stringn "그 인이 【정령의 부적】이 아닌 것을\n"
.stringn "알아보는 자는 거의 없다.$K$P하지만$MC…$MD$w4 시간 문제야.$K\n"
.stringn "$F6$P$MC………$MD$K\n"
.stringn "$F1$P어렴풋이 느끼고 있겠지만,$w2\n"
.stringn "우리들은$MC…$MD$w4 나이를 먹는 속도가\n"
.stringn "베오크들과는 다르다.$K$P이어받은 라구즈의 피에 의해서인지$MC…$MD$w4\n"
.stringn "대체로 성장이 느려지지.$K\n"
.stringn "$F6$P$MC…$MD3년 정도 전까지는\n"
.stringn "평범하게 자라고 있다고$MC……$MD$w4\n"
.stringn "$MC……$MD생각하고 있었는데.$K\n"
.stringn "$F1$P더 이상 같은 장소에서 지낼 순 없다.$w4\n"
.stringn "베오크들도 언젠가 알아차릴 테니까.$K\n"
.stringn "$F6$P그래도$MC…$MD$w4\n"
.stringn "저는 $Fc아이크의 곁에 있고 싶습니다.$K\n"
.stringn "$F1$P$FA$MC………$MD$w4\n"
.stringn "어쩔 수 없는 상황이 되었을 땐,$w2\n"
.stringn "그라느 사막으로 와라.$K$P그곳에 $w2너의 동료들이 있다는 걸$w2\n"
.stringn "$MC……$MD잊지 마라.$K$F1$FD\n"
.stringn "$F6$P$MC……………$MD$K"
db 0
.align 4
//MYELL_SENERIO_SOANVALCKE_A

//0x4201C
Text_41FFC:
.stringn "$R背景会話|$B支援背景|$<$F5$FCL_SENERIO|$F5$P$MC………$MD$K\n"
.stringn "$F3$FS$F3$FCL_SOANVALCKE|$F3$P베오크 무리에서 지내면서도\n"
.stringn "잘 적응하지 못한 모양이군.$K\n"
.stringn "$F5$FD$F1$FCL_SENERIO|$F1$P$MC!!$MD$w4\n"
.stringn "또$MC…$MD$w4 당신입니까.$K\n"
.stringn "$F3$P그라느 사막에 있는\n"
.stringn "숨겨진 마을로 오지 않겠나?$K$P너와 같은$MC…$MD$w4 인을 가진 자들끼리\n"
.stringn "서로 기대며 살아가고 있다.$K\n"
.stringn "$F1$P당신은$MC…$MD$w4 뭔가 착각을\n"
.stringn "하고 있는 것 같습니다만$MC……$MD$w4\n"
.stringn "어쨌든, $w2괜한 참견입니다.$K$P$MC…$MD제가 있을 곳은$MC……$MD$w4\n"
.stringn "$MC……$MD여기뿐이니까요.$K\n"
.stringn "$F3$P그런가$MC…$MD$w4\n"
.stringn "그럼, $w2강요하진 않겠다.$K$F3$FD\n"
.stringn "$F1$P$MC…………$MD$K"
db 0
.align 4
//MYELL_SENERIO_SOANVALCKE_B

//0x41E54
Text_41E34:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_SENERIO|$F3$FCL_SOANVALCKE|$F3$P$MC………$MD$K\n"
.stringn "$F1$P$MC……$MD뭔가 용건이라도?$K\n"
.stringn "$F3$P$FS그렇게 경계하지 마라.$w4\n"
.stringn "나는$MC…$MD$w4 네 동료니까.$K\n"
.stringn "$F1$P$MC!!$MD$K\n"
.stringn "$F3$P$MC……$MD그 모습$MC…$MD$w4 자신을 속이며\n"
.stringn "이방 안에서 살아온 것 같군.$K\n"
.stringn "$F1$P$MC…………$MD$w4\n"
.stringn "저, $w2저는$MC……$MD$K\n"
.stringn "$F3$P느닷없이\n"
.stringn "말을 꺼냈으니 그야 당황했겠지.$K$P일단 $w2물러나겠다.$w4\n"
.stringn "$MC…$MD나중에 천천히 얘기하자고.$K$F3$FD\n"
.stringn "$F1$P$MC………………$MD$K"
db 0
.align 4
//MYELL_SENERIO_SOANVALCKE_C

