//0x4308C
Text_4306C:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_STELLA|$F3$FCL_SOTHE|$F1$P아$MC……$MD$w4 소더씨.$w4\n"
.stringn "$FS지난번에는$w2\n"
.stringn "정말로 감사했습니다.$K\n"
.stringn "$F3$P$MC……$MD별로,$w2\n"
.stringn "몇 번이고 고맙다고 하지 마.$K\n"
.stringn "$F1$P$FA그렇지만$MC……$MD$K\n"
.stringn "$F3$P너희들 귀족은 간단히$w2\n"
.stringn "고맙다는 말을 안 할 줄 알았는데$K$P$MC……$MD너는 다르구나.$K\n"
.stringn "$F1$P그런가요?$K\n"
.stringn "$F3$P그래.$w4\n"
.stringn "귀족들은 $w2우리들 평민을 짓밟고$w2\n"
.stringn "자기들만 $w2태평하게 잘 살고 있잖아.$K$P태어날 때부터 그걸\n"
.stringn "당연하게 생각하고 있고$MC…$MD$K$P죽을 때까지 $w2먹을 것과 잘 곳을\n"
.stringn "고민할 필요도 없지$MC……$MD$w4\n"
.stringn "정말이지, $w3부러운 신분이야.$K\n"
.stringn "$F1$P그렇지만, $w2자유는 없습니다$MC……$MD$K$P제 오빠들은 군인으로서 집안의 자랑이\n"
.stringn "되어 빛나는 삶을 살고 있어요.$K$P하지만 언니들은 모두 $w2얼굴도 모르는\n"
.stringn "상대의 집에 시집을 갑니다$MC……$MD$K$P거기에 사랑은 없고, $w2울며 지낸다는 편지를\n"
.stringn "몇 년마다 한 번씩 받을 뿐이죠$MC……$MD$w4\n"
.stringn "여자는 가문의 권력을 잇는 도구에 불과합니다.$K\n"
.stringn "$F3$P$MC…………$MD$w4\n"
.stringn "너도$MC……$MD$w4\n"
.stringn "그렇게 될 운명이었다는 거고$MC……$MD$K\n"
.stringn "$F1$P네$MC……$MD$w4 하지만 그게 $w2자신의 운명이라며$w2\n"
.stringn "포기하고 싶지는 않았어요.$K$P그러니까 저는$MC……$MD$w2 이 싸움이 끝날 때까지\n"
.stringn "이곳을 떠날 생각이 없습니다.$K\n"
.stringn "$F3$P$MC……$MD그렇구나.$K$P넌 내가 아는 귀족과는 전혀 다르네.$w4\n"
.stringn "요즘 계속 $w2네가 노력하는 걸 보고\n"
.stringn "그런 생각이 들었어.$K$P열심히 노력하면 살려고 하는 게\n"
.stringn "우리랑 똑같아. $w4아무것도 다르지 않아.$w4\n"
.stringn "귀족의 변덕이라고 생각해서 미안했다.$K\n"
.stringn "$F1$P가$MC……$MD$w4감사합니다$MC……$MD$K\n"
.stringn "$F3$P$FS앞으로도 힘내 줘.$w4\n"
.stringn "스스로 자신의 인생을 쟁취하기 위해서.$K\n"
.stringn "$F1$P$FS$MC……$MD네$MC!$MD$K"
db 0
.align 4
//MYELL_SOTHE_STELLA_A

//0x42A88
Text_42A68:
.stringn "$R背景会話|$B支援背景|$<$F1$Fc$F1$FCL_STELLA|$F3$FCL_SOTHE|$F1$P$Fd아$MC……$MD$w2 여기는$MC……?$MD$K\n"
.stringn "$F3$P$MC…………$MD$K\n"
.stringn "$F1$P저, $w2어떻게 된 거죠$MC……?$MD$K\n"
.stringn "$F3$P너, $w2쓰러져 있었어.$w4\n"
.stringn "그냥 놔두려고 했는데$MC……$MD$w4\n"
.stringn "왠지 신경 쓰여서.$K\n"
.stringn "$F1$P죄송합니다$MC……$MD$K\n"
.stringn "$F3$P내 알 바는 아니지만$MC……$MD$w4\n"
.stringn "너, $w2무리하는 거 아니야?$K$P행군을 따라가는 것도 힘든 것 같고,$w2\n"
.stringn "그 상태로는 몸이 망가질걸.$K\n"
.stringn "$F1$P죄송합니다$MC……$MD$K\n"
.stringn "싸움은$MC……$MD$w4\n"
.stringn "이렇게나 가혹하군요.$K$P매일 힘든 행군이 계속되고$MC……$MD$w4\n"
.stringn "적의 습격에 겁을 먹어서\n"
.stringn "밤에 안심하고 잘 수도 없어요$MC…$MD$K$P자신의 나약함을 뼈저리게 느끼고 있습니다$MC…$MD$K\n"
.stringn "$F3$P$MC……$MD아가씨 주제에 무리하니까 그런 거야.$K\n"
.stringn "여기에 $w2너를\n"
.stringn "모시는 집사나 시녀는 없어.$K$P집으로 돌아가면 지금까지처럼$w2\n"
.stringn "아무 불편 없이 살 수 있을걸.$K\n"
.stringn "$F1$P$MC……$MD아무 불편 없이, $w2인가요.$K\n"
.stringn "하지만 저택으로 돌아가면$MC……$MD$w4\n"
.stringn "제게 자유는 없습니다.$K\n"
.stringn "$F3$P$MC……?$MD$K\n"
.stringn "$F1$P제게는 부모님이 정해 주신 약혼자가 있습니다.$K\n"
.stringn "상대는 저보다 30살이나 연상이죠$MC……$MD$w4\n"
.stringn "제 아버지보다 연세가 많으신 분이에요.$K\n"
.stringn "$F3$P$MC……$MD$K\n"
.stringn "$F1$P저는$MC……$MD$w4 자신의 의지로 살고 싶어서\n"
.stringn "베그니온 기사단에 지원했습니다$MC……$MD$K\n"
.stringn "가족들에게 격렬하게 반대받았습니다만$MC……$MD$w4\n"
.stringn "오래 갈 리가 없다고 생각하셨나 봐요.$K$P곤란해하면서 $w2집으로\n"
.stringn "돌아올 것이 틀림없다고$MC……$MD$w4\n"
.stringn "그러니까$MC……$MD$w3 아직, $w2돌아갈 수는 없습니다.$K\n"
.stringn "$F3$P$MC…………$MD$K\n"
.stringn "$MC……$MD나랑은 $w2관계없어.$K$P그러니까 $w2네 마음대로 하면 돼.$K\n"
.stringn "$F1$P$FS네$MC……$MD$w4 감사합니다.$K"
db 0
.align 4
//MYELL_SOTHE_STELLA_B

//0x4266C
Text_4264C:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_STELLA|$F3$FCL_SOTHE|$F1$P소더씨.$w4\n"
.stringn "무기 손질 중이신가요?$K\n"
.stringn "$F3$P어, $w2그렇긴 한데.$K\n"
.stringn "$F1$P저기$MC……$MD$w4\n"
.stringn "잠깐 $w2괜찮으신가요?$K\n"
.stringn "$F3$P?$w4 나한테 무슨 볼일 있어?$K\n"
.stringn "$F1$P소더씨는 단검을 사용하시죠?$w4\n"
.stringn "확실히$MC……$MD$w2 검은 도끼에 강한 무기죠.$K$P그럼$MC…$MD$w2 도끼는 대체 $w2어떤 무기에\n"
.stringn "유효한가요?$K\n"
.stringn "$F3$P$MC……$MD너, 그런 것도 모르면서\n"
.stringn "용병을 하고 있는 거야?$K\n"
.stringn "$F1$P$FA네, $w2네에$MC……$MD$w2 죄송합니다.$w4\n"
.stringn "용병이 된 지 아직 얼마 안 됐고$MC……$MD$w3\n"
.stringn "저는 활을 사용하니까요$MC……$MD$K\n"
.stringn "$F3$P흐~음$MC……$MD$w4\n"
.stringn "너, $w2용병이 되기 전에는 뭘 했었는데?$K\n"
.stringn "$F1$P아, $w2아무것도$MC……$MD$w4 하지 않았습니다.$K\n"
.stringn "$F3$P아무것도?$w4 아무것도 안 하고\n"
.stringn "먹고살 수 있을 리가 없잖아.$K$P$MC…………$MD$w2혹시$MC……$MD$w3\n"
.stringn "너, $w2귀족이야?$K$P그 말투도 그렇고, $w2무지한 것도 그렇고$MC…$MD$w3\n"
.stringn "$MC……$MD잘나신 귀족님께서 왜 이런 싸움에?$K\n"
.stringn "$F1$P$MC………………$MD$K\n"
.stringn "$F3$P$MC……$MD하긴, $w2내가 물을 게 아닌가.$w4\n"
.stringn "뭐$MC……$MD$w2 괜찮겠지.$w4\n"
.stringn "귀족의 취미로는.$K"
db 0
.align 4
//MYELL_SOTHE_STELLA_C

//0x43B30
Text_43B10:
.stringn ""
db 0
.align 4
//MYELL_SOTHE_TOPUCK_A

//0x43B34
Text_43B14:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_TOPUCK|$F3$FCL_SOTHE|$F1$P아.$K\n"
.stringn "$F3$P아직도 포기 안 한 거야?$w4\n"
.stringn "끈질겨$MC…$MD$K\n"
.stringn "$F1$P그렇게 싫으면$w2\n"
.stringn "이제 부탁 안 할 거야$MC!$MD$w4\n"
.stringn "너 따윈 됐어, $w2저리로 가 버려$MC!!$MD$K\n"
.stringn "$F3$P$MC……$MD뭔데.$w4\n"
.stringn "왜 그렇게$w2\n"
.stringn "친구에 집착하는 거야?$K\n"
.stringn "$F1$P무와림이 걱정한단 말이야$MC…$MD$K\n"
.stringn "$F3$P무와림?$w4\n"
.stringn "아아$MC…$MD$w2 그 호랑이.$K\n"
.stringn "$F1$P나한테$MC…$MD$w4\n"
.stringn "베오크 친구가 없는 게$K\n"
.stringn "자기 탓이라면서\n"
.stringn "괴로운 얼굴을 하고 있으니까$MC…$MD$K$P그래서, $w2너랑 친구가 돼서\n"
.stringn "기쁘게 해 주고 싶었어.$K\n"
.stringn "$F3$P그런 거였구만.$w4\n"
.stringn "그렇다면 $w2처음부터 그렇게 말하라고.$K\n"
.stringn "$F1$P그럼 $w2친구해 주는 거지$MC!?$MD$K\n"
.stringn "$F3$P그래.$K\n"
.stringn "$F1$P$MC…$MD갑자기 왜?$K\n"
.stringn "$F3$P키워 준 부모 같은 존재잖아?$w4\n"
.stringn "걱정시키고 싶지 않은 마음이라면$w2\n"
.stringn "잘 아니까.$K$P나도$MC…$MD$w2 부모 대신\n"
.stringn "굉장히 소중한 사람이 있고$MC……$MD$K\n"
.stringn "$F1$P그렇구나$MC!$MD$w4\n"
.stringn "너도 그런 거구나$MC!?$MD$w4$FS\n"
.stringn "헤헤,$w3 뭔가 친근한걸.$K\n"
.stringn "$F3$P협력은 하겠지만,$w2\n"
.stringn "진짜 친구가 되는 건 아니니까$K$P그럴 상황이 $w2아닐 땐$w3\n"
.stringn "끈적대지 마라?$K\n"
.stringn "$F1$P뭐야.$w4\n"
.stringn "어차피 $w2하는 거\n"
.stringn "제대로 친구하자고!$K\n"
.stringn "$F3$P싫어.$K"
db 0
.align 4
//MYELL_SOTHE_TOPUCK_A_a

//0x43F84
Text_43F64:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_TOPUCK|$F3$FCL_SOTHE|$F1$P아.$K\n"
.stringn "$F3$P아직도 포기 안 한 거야?$w4\n"
.stringn "끈질겨$MC…$MD$K\n"
.stringn "$F1$P그렇게 싫으면$w2\n"
.stringn "이제 부탁 안 할 거야$MC!$MD$w4\n"
.stringn "너 따윈 됐어, $w2저리로 가 버려$MC!!$MD$K\n"
.stringn "$F3$P$MC……$MD뭔데.$w4\n"
.stringn "왜 그렇게$w2\n"
.stringn "친구에 집착하는 거야?$K\n"
.stringn "$F1$P무와림이 걱정한단 말이야$MC…$MD$K\n"
.stringn "$F3$P무와림?$w4\n"
.stringn "아아$MC…$MD$w2 그 호랑이.$K\n"
.stringn "$F1$P아직, $w2살아 있었을 때$MC……$MD$w4\n"
.stringn "나한테$MC…$MD$w2 베오크 친구가 없는 게\n"
.stringn "자기 탓이라면서 $w2엄청 걱정했거든.$K$P그러니까 $w2만약, $w2너하고 친구가 된다면$MC…$MD$w4\n"
.stringn "그 녀석도 안심할 것 같아서.$K\n"
.stringn "$F3$P그런 거였구만.$w4\n"
.stringn "그렇다면 $w2처음부터 그렇게 말하라고.$K\n"
.stringn "$F1$P그럼 $w2친구해 주는 거지$MC!?$MD$K\n"
.stringn "$F3$P그래.$K\n"
.stringn "$F1$P$MC…$MD갑자기 왜?$K\n"
.stringn "$F3$P키워 준 부모 같은 존재잖아?$w4\n"
.stringn "걱정시키고 싶지 않은 마음이라면$w2\n"
.stringn "잘 아니까.$K$P나도$MC…$MD$w2 부모 대신\n"
.stringn "굉장히 소중한 사람이 있고$MC……$MD$K\n"
.stringn "$F1$P그렇구나$MC!$MD$w4\n"
.stringn "너도 그런 거구나$MC!?$MD$w4$FS\n"
.stringn "헤헤,$w3 뭔가 친근한걸.$K\n"
.stringn "$F3$P협력은 하겠지만,$w2\n"
.stringn "진짜 친구가 되는 건 아니니까$K$P그럴 상황이 $w2아닐 땐$w3\n"
.stringn "끈적대지 마라?$K\n"
.stringn "$F1$P뭐야.$w4\n"
.stringn "어차피 $w2하는 거\n"
.stringn "제대로 친구하자고!$K\n"
.stringn "$F3$P싫어.$K"
