//0x4399C
Text_4397C:
.stringn "$R背景会話|$B支援背景|$<$F5$FCL_SOTHE|$F3$FCL_TOPUCK|$F3$P야.$K\n"
.stringn "$F5$P$MC……$MD$K\n"
.stringn "$F3$P우리$w2\n"
.stringn "나이도 비슷하잖아~$w4\n"
.stringn "모처럼이니까 $w2사이좋게 지내자고.$K\n"
.stringn "$F5$P친분을 쌓는 건 좋아하지 않아.$K\n"
.stringn "$F3$P너는 그렇겠지만 말이야~$w3\n"
.stringn "나는 $w2너랑$w2\n"
.stringn "친구가 되고 싶다구.$K\n"
.stringn "$F5$P$MC……$MD내 알 바 아니야.$K$F5$FD\n"
.stringn "$F3$P뭐야$MC!$MD$w4\n"
.stringn "적당히 해야 될 거 아니야,$w2\n"
.stringn "닳는 것도 아닌데$MC!!$MD$K"
db 0
.align 4
//MYELL_SOTHE_TOPUCK_B

//0x436D8
Text_436B8:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_SOTHE|$F3$FS$F3$FCL_TOPUCK|$F3$P앗, $w2너.$K$P야, $w2저번에\n"
.stringn "나랑 임무 같이 했었지?$K\n"
.stringn "$F1$P$MC……$MD기억 안 나.$K\n"
.stringn "$F3$P$FA뭐야$MC……$MD$w4\n"
.stringn "난 $w2기억하고 있었는데.$K$P그렇게 작은 무기로$w2\n"
.stringn "적이랑 대등하게 싸웠잖아?$K$FS$P나랑 나이가 비슷해 보이는데\n"
.stringn "굉장하다고 생각했어.$K$P아, $w2난 토팍이라고 해.$w4\n"
.stringn "이래 봬도$w2\n"
.stringn "남 못지 않은 마법사라구.$K\n"
.stringn "$F1$P$MC……$MD$K\n"
.stringn "$F3$P네 이름은?$K\n"
.stringn "$F1$P$MC……$MD소더.$K\n"
.stringn "$F3$P소더구나$MC!$MD$w4 잘 부탁해$MC!$MD$K$P근데 $w3소더는\n"
.stringn "왜 여기서 용병 일을 하고 있는 거야?$K\n"
.stringn "$F1$P$MC……$MD말 안 하고 싶은데.$K$F1$FD\n"
.stringn "$F3$P$FA야, $w2야$MC!$MD$w4\n"
.stringn "뭐야 저 녀석.$w4\n"
.stringn "완전 $w2재수 없잖아$MC!!$MD$K"
db 0
.align 4
//MYELL_SOTHE_TOPUCK_C

