//0x44AA0
Text_44A80:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_ULYSSES|$F3$FCL_VOKE|$F3$P무슨 일이지$MC…$MD$w3\n"
.stringn "아직도 내게 볼일이 있는 건가?$K\n"
.stringn "$F1$P아이크 장군과의\n"
.stringn "계약이 종료되는 것은 언제지?$K\n"
.stringn "$F3$P왜 그걸 묻는 거냐.$K\n"
.stringn "$F1$P의뢰하고 싶은 일이 생겼다네.$w4\n"
.stringn "$MC…$MD자네밖에 할 수 없는 일이야.$K\n"
.stringn "$F3$P당신을 잘 안다고 생각했는데$MC…$MD$w4\n"
.stringn "그렇게 다급한 듯한 표정은$MC…$MD$w3\n"
.stringn "처음 보는군.$K\n"
.stringn "$F1$P20만이다.$K\n"
.stringn "$F3$P?$K\n"
.stringn "$F1$P20만을 준비하지.$w4\n"
.stringn "즉시 일에 들어가 주게.$K\n"
.stringn "$F3$P공교롭게도$MC…$MD$w4\n"
.stringn "나는 겸업을 할 생각은 없다.$K$P물론, $w3지금 맡고 있는 일을\n"
.stringn "중간에 관둘 생각도 없지.$K\n"
.stringn "$F1$P$MC……$MD$K\n"
.stringn "$F3$P$MC…$MD얼마 남지 않았다.$w4\n"
.stringn "이 싸움이 마무리되면$MC…$MD$w3\n"
.stringn "나와 아이크의 계약은 끝나지.$K$P어떤 식으로든$MC…$MD$w2 말이다.$K$P그렇게 자유로운 몸이 된다면$MC…$MD$w3\n"
.stringn "이 발로 직접 $w2당신이 있는 곳에\n"
.stringn "용건을 들으러 가 주마.$K\n"
.stringn "$F1$P$MC…$MD무슨 바람이 분 건가?$K\n"
.stringn "$F3$P페일 백작,$w2\n"
.stringn "나는 당신이 마음에 든다.$K$FS$P당신의 일을 끝내고 돈을\n"
.stringn "제때 받지 못한 적은 단 한 번도 없었지.$K\n"
.stringn "$F1$P$FS내가 $w2우수한 고용주란 말인가.$w4\n"
.stringn "칭찬을 받으니 영광이군.$K$FA$P그럼, $w2어쨌든\n"
.stringn "이 싸움을 끝내는 수밖에 없겠군.$K$P자네를 기다리고 있는 다음 일도$MC…$MD$w3\n"
.stringn "매우 시급한 일이니 말일세.$K"
db 0
.align 4
//MYELL_ULYSSES_VOKE_A

//0x44798
Text_44778:
.stringn "$R背景会話|$B支援背景|$<$F1$FS$F1$FCL_VOKE|$F3$FS$F3$FCL_ULYSSES|$F1$P$MC…$MD빠르군.$K\n"
.stringn "$F3$P여러 가지 유익한 정보를 얻을 수 있었네.$K$P대부분은 $w2지난번에\n"
.stringn "공주님께서 아이크 장군에게\n"
.stringn "들으셨다고 하는 정보와 일치하지만$MC…$MD$K$P듣지도 못했던 세세한 사실들까지\n"
.stringn "어느 것이나 참$MC…$MD$w4 흥미롭군.$K\n"
.stringn "$F1$P당신에게는$MC…$MD$w4\n"
.stringn "눈에 불을 켜고 달려들 만한 것들뿐인가.$K\n"
.stringn "$F3$P아무튼, $w2이걸로 자네와\n"
.stringn "아이크 장군에 대한 의심은$MC…$MD$w4\n"
.stringn "일단 거두었다고 해 두지.$K\n"
.stringn "$F1$P그것참 $w2고맙군.$K\n"
.stringn "$F3$P할 이야기는 그것뿐이네.$K\n"
.stringn "$F1$P$MC…$MD페일 백작.$K\n"
.stringn "$F3$P뭔가?$K\n"
.stringn "$F1$P아무래도 당신에게는$MC…$MD$w4\n"
.stringn "지금 있는 곳보다는 어둠의 세계가\n"
.stringn "어울리는 것 같은데.$K$P이번 기회에$w2\n"
.stringn "이쪽으로 오지 않겠나?$K\n"
.stringn "$F3$P내 충성과 헌신은\n"
.stringn "언제나 크리미아 왕가와 함께할 것이네.$K$F3$FD\n"
.stringn "$F1$P$MC………$MD$K"
db 0
.align 4
//MYELL_ULYSSES_VOKE_B

//0x44434
Text_44414:
.stringn "$R背景会話|$B支援背景|$<$F1$FCL_VOKE|$F1$P$MC…………$MD$w4\n"
.stringn "거기 숨어 있는 남자.$w4\n"
.stringn "다섯을 다 세기 전에 나와라.$K$P5, $w34, $w33$MC…$MD$K\n"
.stringn "$F3$FCL_ULYSSES|$F3$P$MC…$MD대단하군.$w4\n"
.stringn "과연 【불 끄는 자】.$w4\n"
.stringn "이 거리에서 나를 알아차릴 줄이야.$K\n"
.stringn "$F1$P페일 백작$MC…$MD$w3\n"
.stringn "당신이었나.$K\n"
.stringn "$F3$P이런 곳에서$w2\n"
.stringn "자네의 모습을 보게 되다니\n"
.stringn "생각도 못 했다네.$K$P$MC…$MD누구 밑에서 움직이고 있는 거지?$K\n"
.stringn "$F1$P당신이라면$w2\n"
.stringn "이미 조사를 끝냈을 텐데.$K$P그걸 믿으면 된다.$K\n"
.stringn "$F3$P진실이라$MC…$MD$w3 아이크 장군 밑에서$w2\n"
.stringn "크리미아를 위해\n"
.stringn "일하고 있다는 건가?$K\n"
.stringn "$F1$P정확히는,$w2\n"
.stringn "아이크 개인의 아래서다.$K\n"
.stringn "$F3$P어째서지?$K\n"
.stringn "$F1$P$FS10만이다.$K\n"
.stringn "$F3$P10만?$K\n"
.stringn "$F1$P대답의 대가다.$K\n"
.stringn "$F3$P$FS훗,$w4\n"
.stringn "그 액수를 제시한 시점에서$w2\n"
.stringn "대답할 생각은 없는 것이로군.$K\n"
.stringn "$F1$P$MC……$MD$K$F1$FD\n"
.stringn "$F3$P$FA아이크 장군$MC…$MD$K$P저 남자를 그림자로 삼아$w2\n"
.stringn "무슨 일을 꾸미고 있는 건지$MC……$MD$w4\n"
.stringn "시급히 $w2조사할 필요가 있겠어.$K"
db 0
.align 4
//MYELL_ULYSSES_VOKE_C

